import React from "react";
import { useTranslation } from "react-i18next";
import { getLockedCloudHost } from "#/api/agent-server-config";
import { useActiveBackend } from "#/contexts/active-backend-context";
import type { Backend } from "#/api/backend-registry/types";
import { useSaveSettings } from "#/hooks/mutation/use-save-settings";
import { useBackendsHealth } from "#/hooks/query/use-backends-health";
import { useSettings } from "#/hooks/query/use-settings";
import { I18nKey } from "#/i18n/declaration";
import { OPENHANDS_I18N_NAMESPACE } from "#/i18n";
import { ModalBackdrop } from "#/components/shared/modals/modal-backdrop";
import { ModalBody } from "#/components/shared/modals/modal-body";
import {
  BaseModalTitle,
  BaseModalDescription,
} from "#/components/shared/modals/confirmation-modals/base-modal";
import { BrandButton } from "#/components/features/settings/brand-button";
import { setTelemetryConsent } from "#/services/telemetry";

interface TelemetryConsentBannerProps {
  onChoice?: (granted: boolean) => void;
}

function LocalTelemetryConsentBanner({
  backend,
  onChoice,
}: TelemetryConsentBannerProps & {
  backend: Backend;
}) {
  const { t, ready } = useTranslation(OPENHANDS_I18N_NAMESPACE);
  const health = useBackendsHealth([backend]);
  const isBackendConnected = health[backend.id]?.isConnected === true;
  const { data: settings, isSuccess: hasLoadedSettings } = useSettings();
  const { mutateAsync: saveSettings, isPending: isSavingSettings } =
    useSaveSettings();
  const [isReady, setIsReady] = React.useState(false);
  const [hasSubmittedChoice, setHasSubmittedChoice] = React.useState(false);

  React.useEffect(() => {
    setHasSubmittedChoice(false);
  }, [backend.id]);

  const shouldShow =
    isBackendConnected &&
    hasLoadedSettings &&
    settings?.user_consents_to_analytics === null &&
    !hasSubmittedChoice;

  React.useEffect(() => {
    if (ready && shouldShow) {
      const timer = setTimeout(() => setIsReady(true), 50);
      return () => clearTimeout(timer);
    }
    setIsReady(false);
    return undefined;
  }, [ready, shouldShow]);

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const granted = formData.get("analytics") === "on";

    try {
      await saveSettings({ user_consents_to_analytics: granted });
    } catch {
      return;
    }

    setHasSubmittedChoice(true);
    await setTelemetryConsent(granted ? "granted" : "denied");
    onChoice?.(granted);
  };

  if (!shouldShow || !isReady) return null;

  return (
    <ModalBackdrop elevated aria-label={t(I18nKey.TELEMETRY$CONSENT_TITLE)}>
      <form
        data-testid="telemetry-consent-form"
        onSubmit={handleSubmit}
        className="flex flex-col gap-2"
      >
        <ModalBody className="border border-border">
          <BaseModalTitle title={t(I18nKey.TELEMETRY$CONSENT_TITLE)} />
          <BaseModalDescription>
            {t(I18nKey.TELEMETRY$CONSENT_DESCRIPTION)}
          </BaseModalDescription>
          <p className="text-xs text-neutral-400">
            {t(I18nKey.TELEMETRY$BACKEND_SCOPE, {
              name: backend.name,
              host: backend.host,
            })}
          </p>

          <label className="flex gap-2 items-center self-start text-sm cursor-pointer">
            <input
              name="analytics"
              type="checkbox"
              defaultChecked
              className="w-4 h-4 cursor-pointer"
            />
            {t(I18nKey.TELEMETRY$SEND_ANONYMOUS_DATA)}
          </label>

          <BrandButton
            testId="confirm-telemetry-preferences"
            type="submit"
            variant="primary"
            className="w-full"
            isDisabled={isSavingSettings}
          >
            {t(I18nKey.TELEMETRY$CONFIRM_PREFERENCES)}
          </BrandButton>
        </ModalBody>
      </form>
    </ModalBackdrop>
  );
}

export function TelemetryConsentBanner({
  onChoice,
}: TelemetryConsentBannerProps) {
  const { backend } = useActiveBackend();

  if (getLockedCloudHost() !== null || backend.kind !== "local") return null;

  return <LocalTelemetryConsentBanner backend={backend} onChoice={onChoice} />;
}

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import ReactDOM from "react-dom";
import { ChevronDown, FileUp, Plus } from "lucide-react";
import { useTranslation } from "react-i18next";
import { ContextMenuListItem } from "#/components/features/context-menu/context-menu-list-item";
import { BrandButton } from "#/components/features/settings/brand-button";
import { I18nKey } from "#/i18n/declaration";
import { ContextMenu } from "#/ui/context-menu";
import { KebabMenuItemContent } from "./kebab-menu-item-content";

interface AddAutomationMenuProps {
  onAdd: () => void;
  onImport: () => void;
  isAddDisabled?: boolean;
}

export function AddAutomationMenu({
  onAdd,
  onImport,
  isAddDisabled = false,
}: AddAutomationMenuProps) {
  const { t } = useTranslation("openhands");
  const [open, setOpen] = useState(false);
  const [portalStyle, setPortalStyle] = useState<React.CSSProperties>();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLUListElement>(null);

  useLayoutEffect(() => {
    if (!open || !triggerRef.current) return undefined;

    const updatePosition = () => {
      const rect = triggerRef.current?.getBoundingClientRect();
      if (!rect) return;

      setPortalStyle({
        position: "fixed",
        zIndex: 9999,
        top: rect.bottom + 2,
        right: window.innerWidth - rect.right,
      });
    };

    updatePosition();
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [open]);

  useEffect(() => {
    if (!open) return undefined;

    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node;
      if (
        triggerRef.current?.contains(target) ||
        menuRef.current?.contains(target)
      ) {
        return;
      }
      setOpen(false);
    };

    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("keydown", handleEscape);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("keydown", handleEscape);
    };
  }, [open]);

  const closeAnd = (action: () => void) => {
    action();
    setOpen(false);
  };

  const menu =
    open && portalStyle ? (
      <ContextMenu
        ref={menuRef}
        testId="automations-add-automation-menu"
        theme="popover"
        position="none"
        alignment="none"
        spacing="none"
        className="min-w-[10rem]"
      >
        <li>
          <ContextMenuListItem
            testId="automations-add-automation-create"
            isDisabled={isAddDisabled}
            className="group"
            onClick={() => {
              if (isAddDisabled) return;
              closeAnd(onAdd);
            }}
          >
            <KebabMenuItemContent
              icon={<Plus className="size-4" aria-hidden />}
              label={t(I18nKey.AUTOMATIONS$CREATE_AUTOMATION_BUTTON)}
            />
          </ContextMenuListItem>
        </li>
        <li>
          <ContextMenuListItem
            testId="automations-import-automation"
            className="group"
            onClick={() => closeAnd(onImport)}
          >
            <KebabMenuItemContent
              icon={<FileUp className="size-4" aria-hidden />}
              label={t(I18nKey.AUTOMATIONS$IMPORT)}
            />
          </ContextMenuListItem>
        </li>
      </ContextMenu>
    ) : null;

  return (
    <>
      <BrandButton
        ref={triggerRef}
        type="button"
        variant="secondary"
        testId="automations-add-automation"
        className="whitespace-nowrap"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((current) => !current)}
      >
        {t(I18nKey.AUTOMATIONS$ADD_AUTOMATION)}
        <ChevronDown className="size-4 shrink-0" aria-hidden />
      </BrandButton>

      {open && portalStyle && typeof document !== "undefined"
        ? ReactDOM.createPortal(
            <div style={portalStyle}>{menu}</div>,
            document.body,
          )
        : null}
    </>
  );
}

import {
  HEALTH_LABEL_KEYS,
  type AutomationHealth,
} from "#/manifests/automation-insights";
