interface AutomationListRowProps {
  automation: Automation;
  onToggle: (id: string, enabled: boolean) => void;
  onRunNow: (id: string) => void;
  isRunPending?: boolean;
  onDelete: (id: string) => void;
  onExport: (automation: Automation) => void;
  onEdit?: (id: string) => void;
  insights?: AutomationInsightsProps;
}

export function AutomationListRow({
  automation,
  onToggle,
  onRunNow,
  isRunPending = false,
  onDelete,
  onExport,
  onEdit,
  insights,
}: AutomationListRowProps) {
  const { navigate } = useNavigation();
  const { t, i18n } = useTranslation("openhands");
  const { canManage: hasManagePermission } = useAutomationPermissions();
  const isOwner = useIsAutomationOwner(automation);
  // Write actions on a specific automation: manage OR creator (escape hatch).
  const canManage = hasManagePermission || isOwner;
  const isDraft = isDraftAutomation(automation);
  // Non-creators may turn an automation off but not back on. Draft test
  // artifacts are finalized through the draft setup flow, not this toggle.
  const canToggle = isDraft ? false : automation.enabled ? canManage : isOwner;

  const handleView = () => {
    navigate?.(`/automations/${automation.id}`);
  };

  const menuItems = buildAutomationMenuItems({
    automation,
    t,
    canManage,
    canToggle,
    onRunNow,
    isRunPending,
    onView: handleView,
    onExport,
    onEdit,
    onToggle,
    onDelete,
  });

  const isEventTrigger = automation.trigger.type === "event";
  const TriggerIcon = isEventTrigger ? Zap : ClockIcon;
  const triggerEventLabel = getTriggerEventLabel(automation);
  const triggerScheduleLabel = getTriggerScheduleLabel(automation);
  const triggerSource = getTriggerSource(automation);
  const hasTriggerMeta = Boolean(
    triggerEventLabel || triggerScheduleLabel || triggerSource,
  );

  const runState = toLatestRunState(insights?.state);
  const health = deriveRunHealth(runState);
  const impactStatement = resolveAutomationImpactStatement(
    automation,
    insights?.state?.summary?.completedTotal ?? null,
  );
  const latestRun = runState.latestRun;
  const display = latestRun ? getAutomationRunDisplay(latestRun) : null;
  const lastRunAt = latestRun
    ? getLastRunTimestamp(latestRun)
    : automation.last_triggered_at;
  const whenLabel = lastRunAt
    ? formatRelativeTime(lastRunAt, i18n.language, t)
    : null;
  const hasMeta =
    hasTriggerMeta || Boolean(whenLabel) || Boolean(latestRun?.status);
  const detailHref = `/automations/${encodeURIComponent(automation.id)}`;
  const statusLabelKey = getRunStatusLabelKey(runState);
  const disableAnimation = import.meta.env.MODE === "test";
  const showDraftBadge = isDraft;

  return (
    <li
      data-testid={`automation-list-row-${automation.id}`}
      className={automationActivityRowClassName}
    >
      <Tooltip
        content={
          <HomeAutomationRunTooltip
            automation={automation}
            runState={runState}
          />
        }
        placement="top-start"
        closeDelay={100}
        disableAnimation={disableAnimation}
        className="rounded-xl border border-border bg-base-secondary p-0 text-contrast shadow-xl"
      >
        <NavigationLink
          to={detailHref}
          aria-label={`${automation.name} ${t(statusLabelKey)}`}
          className="flex min-w-0 flex-1 items-center justify-between gap-3 px-3 py-2.5 focus:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-focus"
        >
          <div className="grid min-w-0 flex-1 grid-cols-[auto_minmax(0,1fr)] gap-x-2">
            <span
              data-testid={`automation-health-${automation.id}`}
              className="inline-flex h-5 w-2.5 shrink-0 items-center justify-center"
            >
              <AutomationHealthIndicator health={health} />
            </span>
            <span className="flex min-w-0 items-center gap-2">
              <span className="truncate text-sm font-medium leading-5 text-foreground">
                {automation.name}
              </span>
              {showDraftBadge ? (
                <ActiveStatusBadge automation={automation} compact />
              ) : null}
            </span>
            {hasMeta ? (
              <span className="col-start-2 mt-0.5 flex min-w-0 items-center gap-1.5 text-xs leading-4 text-text-secondary">
                <TriggerIcon className="size-3 shrink-0" aria-hidden="true" />
                {triggerEventLabel ? (
                  <span className="truncate">{triggerEventLabel}</span>
                ) : null}
                {triggerScheduleLabel ? (
                  <span className="truncate">{triggerScheduleLabel}</span>
                ) : null}
                {triggerSource ? (
                  <span
                    className={cn(
                      extensionModuleCardPillClassName,
                      "shrink-0 px-1.5 py-0 text-text-secondary",
                    )}
                  >
                    {formatTriggerSourceLabel(triggerSource)}
                  </span>
                ) : null}
                {whenLabel ? (
                  <>
                    {hasTriggerMeta ? (
                      <span className="shrink-0" aria-hidden="true">
                        ·
                      </span>
                    ) : null}
                    <span
                      data-testid={`automation-last-run-${automation.id}`}
                      className="truncate"
                    >
                      {whenLabel}
                    </span>
                  </>
                ) : null}
                {latestRun ? (
                  <>
                    {hasTriggerMeta || whenLabel ? (
                      <span className="shrink-0" aria-hidden="true">
                        ·
                      </span>
                    ) : null}
                    <RunStatusBadge
                      status={display?.badgeStatus ?? latestRun.status}
                      compact
                    />
                  </>
                ) : null}
                {impactStatement ? (
                  <>
                    {hasTriggerMeta || whenLabel || latestRun ? (
                      <span className="shrink-0" aria-hidden="true">
                        ·
                      </span>
                    ) : null}
                    <span
                      data-testid={`automation-impact-${automation.id}`}
                      className="truncate"
                    >
                      {impactStatement}
                    </span>
                  </>
                ) : null}
              </span>
            ) : null}
            <span className="sr-only">{t(statusLabelKey)}</span>
          </div>
        </NavigationLink>
      </Tooltip>

      <div className="flex shrink-0 items-center gap-1.5 pr-1.5">
        {insights ? (
          <AutomationRunActivitySparkline
            automationId={automation.id}
            runs={runState.recentRuns}
            testId={`automation-activity-${automation.id}`}
          />
        ) : null}
        {canManage ? (
          <StyledTooltip
            content={t(I18nKey.AUTOMATIONS$RUN_NOW)}
            placement="top"
          >
            <button
              type="button"
              data-testid={`automation-run-now-${automation.id}`}
              aria-label={t(I18nKey.AUTOMATIONS$RUN_NOW)}
              aria-busy={isRunPending}
              disabled={isRunPending || !automation.enabled}
              onClick={(event) => {
                event.stopPropagation();
                onRunNow(automation.id);
              }}
              className={automationIconActionButtonClassName}
            >
              <PlayIcon className="size-4 shrink-0" aria-hidden />
            </button>
          </StyledTooltip>
        ) : null}
        <KebabMenu
          items={menuItems}
          triggerClassName="opacity-70 group-hover:opacity-100"
        />
      </div>
    </li>
  );
}

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import ReactDOM from "react-dom";
import { Grid2x2, Rows3 } from "lucide-react";
import { useTranslation } from "react-i18next";
import { ContextMenuListItem } from "#/components/features/context-menu/context-menu-list-item";
import { I18nKey } from "#/i18n/declaration";
import { ContextMenu } from "#/ui/context-menu";
import { cn } from "#/utils/utils";
import type { AutomationViewMode } from "./automation-view-mode";
import { ViewMenuItemContent } from "./view-menu-item-content";

interface AutomationViewToggleProps {
  view: AutomationViewMode;
  onChange: (view: AutomationViewMode) => void;
  disabled?: boolean;
}

const VIEW_OPTIONS: {
  value: AutomationViewMode;
  icon: typeof Grid2x2;
  labelKey: I18nKey;
  testId: string;
}[] = [
  {
    value: "grid",
    icon: Grid2x2,
    labelKey: I18nKey.AUTOMATIONS$VIEW_GRID,
    testId: "automations-view-toggle-grid",
  },
  {
    value: "list",
    icon: Rows3,
    labelKey: I18nKey.AUTOMATIONS$VIEW_LIST,
    testId: "automations-view-toggle-list",
  },
];

export function AutomationViewToggle({
  view,
  onChange,
  disabled = false,
}: AutomationViewToggleProps) {
  const { t } = useTranslation("openhands");
  const [open, setOpen] = useState(false);
  const [portalStyle, setPortalStyle] = useState<React.CSSProperties>();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLUListElement>(null);

  const activeOption =
    VIEW_OPTIONS.find((option) => option.value === view) ?? VIEW_OPTIONS[0]!;
  const ActiveIcon = activeOption.icon;

  useLayoutEffect(() => {
    if (!open || !triggerRef.current) return undefined;

    const updatePosition = () => {
      const rect = triggerRef.current?.getBoundingClientRect();
      if (!rect) return;

      const gap = 4;
      setPortalStyle({
        position: "fixed",
        zIndex: 9999,
        top: rect.bottom + gap,
        right: window.innerWidth - rect.right,
      });
    };

    updatePosition();
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [open]);

  useEffect(() => {
    if (!open) return undefined;

    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node;
      if (
        triggerRef.current?.contains(target) ||
        menuRef.current?.contains(target)
      ) {
        return;
      }
      setOpen(false);
    };

    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("keydown", handleEscape);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("keydown", handleEscape);
    };
  }, [open]);

  const menu =
    open && portalStyle ? (
      <ContextMenu ref={menuRef} theme="popover" className="min-w-[10rem]">
        {VIEW_OPTIONS.map((option) => (
          <li key={option.value}>
            <ContextMenuListItem
              testId={option.testId}
              onClick={() => {
                onChange(option.value);
                setOpen(false);
              }}
              className="group"
            >
              <ViewMenuItemContent
                icon={option.icon}
                label={t(option.labelKey)}
                isSelected={view === option.value}
              />
            </ContextMenuListItem>
          </li>
        ))}
      </ContextMenu>
    ) : null;

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        data-testid="automations-view-toggle"
        aria-label={t(I18nKey.AUTOMATIONS$VIEW_MODE)}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-disabled={disabled}
        disabled={disabled}
        onClick={() => {
          if (disabled) return;
          setOpen((current) => !current);
        }}
        className={cn(
          "inline-flex size-9 shrink-0 cursor-pointer items-center justify-center rounded-lg border border-border bg-base-secondary text-contrast transition-colors hover:bg-interactive-hover focus-visible:border-contrast/40 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-contrast/20",
          "disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:bg-base-secondary",
        )}
      >
        <ActiveIcon className="size-4" aria-hidden />
      </button>

      {open && portalStyle && typeof document !== "undefined"
        ? ReactDOM.createPortal(
            <div style={portalStyle}>{menu}</div>,
            document.body,
          )
        : null}
    </>
  );
}

