  /** The run these logs belong to; enables the debug action for failed runs. */
  run?: AutomationRun;
  /** The parent automation, used to add context to the debug prompt. */
  automation?: Automation;
}

function concatStream(outputs: BashOutput[], key: "stdout" | "stderr"): string {
  // Outputs come back from the API sorted by timestamp, but pages can
  // arrive out-of-order, so re-sort by (timestamp, order) before
  // concatenating to keep the stream chronological.
  return [...outputs]
    .sort((a, b) => {
      const ts = a.timestamp.localeCompare(b.timestamp);
      if (ts !== 0) return ts;
      return (a.order ?? 0) - (b.order ?? 0);
    })
    .map((output) => output[key] ?? "")
    .join("");
}

function stringifyDetailValue(value: unknown): string | null {
  if (typeof value === "string") return value.trim() || null;
  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }
  return null;
}

function formatStatusDetail(
  statusDetail: AutomationRunStatusDetail | null | undefined,
): string | null {
  if (!statusDetail) return null;
  const primary =
    stringifyDetailValue(statusDetail.formatted_detail) ??
    stringifyDetailValue(statusDetail.detail);
  const context = [
    stringifyDetailValue(statusDetail.phase),
    stringifyDetailValue(statusDetail.kind),
    stringifyDetailValue(statusDetail.source),
    stringifyDetailValue(statusDetail.operation),
    stringifyDetailValue(statusDetail.code),
    stringifyDetailValue(statusDetail.status_code),
  ].filter(Boolean);

  if (primary && context.length > 0) {
    return `${primary} (${context.join(" · ")})`;
  }
  if (primary) return primary;
  if (context.length > 0) return context.join(" · ");
  return JSON.stringify(statusDetail);
}

function RunInspectionSummary({ run }: { run: AutomationRun | undefined }) {
  const { t } = useTranslation("openhands");
  if (!run) return null;

  const display = getAutomationRunDisplay(run);
  const taskSummary =
    run.status === AutomationRunStatus.COMPLETED
      ? display.summary
      : getAutomationRunTaskSummary(run);
  const taskMetadataText = display.customTaskMetadataText;
  const taskStatus =
    run.status === AutomationRunStatus.COMPLETED || display.taskOutcome
      ? display.badgeStatus
      : null;
  const systemError = run.error_detail?.trim() || null;
  const statusDetail = formatStatusDetail(run.status_detail);
  const hasSystemDetails = systemError || statusDetail;

  return (
    <dl className="mt-4 grid gap-3 rounded-lg border border-border bg-black/20 p-3 text-xs">
      <div className="grid gap-1 sm:grid-cols-[5rem_minmax(0,1fr)] sm:items-center">
        <dt className="text-muted">
          {t(I18nKey.AUTOMATIONS$DETAIL$RUN_LABEL)}
        </dt>
        <dd>
          <span className="inline-flex rounded-md bg-surface-raised px-2 py-0.5 font-mono text-[10px] font-medium text-muted">
            {run.status}
          </span>
        </dd>
      </div>
      <div className="grid gap-1 sm:grid-cols-[5rem_minmax(0,1fr)] sm:items-start">
        <dt className="pt-0.5 text-muted">
          {t(I18nKey.AUTOMATIONS$DETAIL$TASK_LABEL)}
        </dt>
        <dd className="min-w-0 space-y-2">
          {taskStatus ? <RunStatusBadge status={taskStatus} compact /> : null}
          {taskSummary ? (
            <p className="break-words text-content">{taskSummary}</p>
          ) : taskMetadataText ? (
            <p className="text-muted">
              {t(I18nKey.AUTOMATIONS$DETAIL$CUSTOM_TASK_METADATA)}
            </p>
          ) : (
            <p className="text-muted">
              {t(I18nKey.AUTOMATIONS$DETAIL$NO_TASK_OUTCOME)}
            </p>
          )}
          {taskMetadataText ? (
            <div className="min-w-0 space-y-1">
              <p className="text-muted">
                {t(I18nKey.AUTOMATIONS$DETAIL$TASK_METADATA)}
              </p>
              <pre
                data-testid="automation-task-metadata"
                className="max-h-48 overflow-auto whitespace-pre-wrap break-words rounded-md border border-border bg-black/30 p-2 font-mono text-[11px] leading-4 text-content"
              >
                {taskMetadataText}
              </pre>
            </div>
          ) : null}
        </dd>
      </div>
      <div className="grid gap-1 sm:grid-cols-[5rem_minmax(0,1fr)] sm:items-start">
        <dt className="pt-0.5 text-muted">
          {t(I18nKey.AUTOMATIONS$DETAIL$SYSTEM_LABEL)}
        </dt>
        <dd className="min-w-0 space-y-1 break-words text-content">
          {hasSystemDetails ? (
            <>
              {systemError ? (
                <p>
                  <span className="text-muted">
                    {t(I18nKey.COMMON$ERROR)}:{" "}
                  </span>
                  {systemError}
                </p>
              ) : null}
              {statusDetail ? (
                <p>
                  <span className="text-muted">
                    {t(I18nKey.AUTOMATIONS$DETAIL$STATUS_DETAIL)}:{" "}
                  </span>
                  {statusDetail}
                </p>
              ) : null}
            </>
          ) : (
            <p className="text-muted">
              {t(I18nKey.AUTOMATIONS$DETAIL$NO_SYSTEM_ISSUES)}
            </p>
          )}
        </dd>
      </div>
    </dl>
  );
}

export function RunLogsModal({
  conversationId,
  sandboxId,
  bashCommandId,
  isOpen,
  onClose,
  run,
  automation,
}: RunLogsModalProps) {
  const { t } = useTranslation("openhands");
  const [activeTab, setActiveTab] = useState<LogTab>("stdout");

  const {
    data: outputs,
    isFetching,
    isResolvingConversation,
    sandboxIssue,
    conversationMissing,
    error,
  } = useBashCommandLogs({
    conversationId,
    sandboxId,
    bashCommandId,
    enabled: isOpen,
  });

  // Reset to the default tab whenever the modal opens for a different run.
  useEffect(() => {
    if (isOpen) setActiveTab("stdout");
  }, [isOpen, bashCommandId]);

  // Close on Escape.
  useEffect(() => {
    if (!isOpen) return undefined;
    const handler = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [isOpen, onClose]);

  const { stdout, stderr } = useMemo(() => {
    if (!outputs) return { stdout: "", stderr: "" };
    return {
      stdout: concatStream(outputs, "stdout"),
      stderr: concatStream(outputs, "stderr"),
    };
  }, [outputs]);

  if (!isOpen) return null;

  const loading = isResolvingConversation || (isFetching && !outputs);
  const noBashCommand = !bashCommandId;
  const activeBody = activeTab === "stdout" ? stdout : stderr;

  const tabBaseClass =
    "border-b-2 px-3 py-2 text-sm font-normal transition-colors focus:outline-none";
  const tabActiveClass = "border-[var(--oh-primary)] text-contrast";
  const tabInactiveClass = "border-transparent text-muted hover:text-content";

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4"
      role="dialog"
      aria-modal="true"
      aria-label={t(I18nKey.AUTOMATIONS$DETAIL$LOGS_TITLE)}
    >
      <div
        className="absolute inset-0 bg-black/60"
        onClick={onClose}
        onKeyDown={(e) => {
          if (e.key === "Escape") onClose();
        }}
        role="presentation"
      />
      <div
        data-testid="run-logs-body"
        className="relative flex max-h-[80vh] w-full max-w-3xl flex-col overflow-y-auto overscroll-contain rounded-xl border border-border bg-surface"
      >
        <div className="sticky top-0 z-10 flex shrink-0 items-center justify-between gap-4 bg-surface px-6 pb-4 pt-6">
          <h2 className={modalTitleLgMediumClassName}>
            {t(I18nKey.AUTOMATIONS$DETAIL$LOGS_TITLE)}
          </h2>
          <button
            type="button"
            onClick={onClose}
            className="text-muted hover:text-foreground"
            aria-label={t(I18nKey.AUTOMATIONS$CANCEL)}
          >
            <XMarkIcon className="size-5" />
          </button>
        </div>

        <div className="px-6 pb-6">
          <RunInspectionSummary run={run} />

          <div
            role="tablist"
            aria-label={t(I18nKey.AUTOMATIONS$DETAIL$LOGS_TITLE)}
            className="mt-4 flex gap-1 border-b border-border"
          >
            <button
              type="button"
              role="tab"
              aria-selected={activeTab === "stdout"}
              aria-controls="run-logs-panel-stdout"
              id="run-logs-tab-stdout"
              tabIndex={activeTab === "stdout" ? 0 : -1}
              onClick={() => setActiveTab("stdout")}
              className={`${tabBaseClass} ${
                activeTab === "stdout" ? tabActiveClass : tabInactiveClass
              }`}
            >
              {t(I18nKey.AUTOMATIONS$DETAIL$LOGS_TAB_OUTPUT)}
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={activeTab === "stderr"}
              aria-controls="run-logs-panel-stderr"
              id="run-logs-tab-stderr"
              tabIndex={activeTab === "stderr" ? 0 : -1}
              onClick={() => setActiveTab("stderr")}
              className={`${tabBaseClass} ${
                activeTab === "stderr" ? tabActiveClass : tabInactiveClass
              }`}
            >
              {t(I18nKey.AUTOMATIONS$DETAIL$LOGS_TAB_ERROR)}
            </button>
          </div>

          <div
            role="tabpanel"
            id={`run-logs-panel-${activeTab}`}
            aria-labelledby={`run-logs-tab-${activeTab}`}
            className="mt-3 min-h-[12rem] rounded-lg border border-border bg-black/40 p-4 font-mono text-xs"
          >
            {noBashCommand && (
              <p className="text-muted italic">
                {t(I18nKey.AUTOMATIONS$DETAIL$LOGS_NO_COMMAND)}
              </p>
            )}

            {!noBashCommand && conversationMissing && (
              <p className="text-muted italic">
                {t(I18nKey.AUTOMATIONS$DETAIL$LOGS_CONVERSATION_MISSING)}
              </p>
            )}

            {!noBashCommand && !conversationMissing && sandboxIssue && (
              <p
                data-testid={`run-logs-sandbox-issue-${sandboxIssue}`}
                className="text-muted italic"
              >
                {t(SANDBOX_ISSUE_I18N[sandboxIssue])}
              </p>
            )}

            {!noBashCommand &&
              !conversationMissing &&
              !sandboxIssue &&
              loading && (
                <p className="text-muted italic">
                  {t(I18nKey.AUTOMATIONS$DETAIL$LOGS_LOADING)}
                </p>
              )}

            {!noBashCommand &&
              !conversationMissing &&
              !sandboxIssue &&
              !loading &&
              error &&
              !outputs && (
                <p className="text-danger">
                  {t(I18nKey.AUTOMATIONS$DETAIL$LOGS_ERROR)}: {String(error)}
                </p>
              )}

            {!loading && !sandboxIssue && outputs && (
              <pre
                data-testid={`run-logs-output-${activeTab}`}
                className={`whitespace-pre-wrap break-words ${
                  activeTab === "stderr" ? "text-danger" : "text-content"
                }`}
              >
                {activeBody.length > 0 ? (
                  activeBody
                ) : (
                  <span className="text-muted italic">
                    {t(I18nKey.AUTOMATIONS$DETAIL$LOGS_EMPTY)}
                  </span>
                )}
              </pre>
            )}
          </div>

          {run?.status === AutomationRunStatus.FAILED && (
            <div className="mt-4 flex justify-end">
              <DebugAutomationButton
                run={run}
                automation={automation}
                stderr={stderr}
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { Tooltip } from "@heroui/react";
import { useTranslation } from "react-i18next";
import { I18nKey } from "#/i18n/declaration";
import { AutomationRunStatus } from "#/types/automation";
import {
  formatRelativeTime,
  isInvalidTimestamp,
} from "#/utils/format-relative-time";
import { cn } from "#/utils/utils";

/**
 * Whether a run's phase is worth showing at all: it answers "what is it doing
 * now" or "where did it stop", so a finished, cancelled or skipped run has
 * nothing to add. Shared by every surface, so one run cannot show a phase on
 * one screen and hide it on another.
 */
export function shouldShowRunPhase(
  status: AutomationRunStatus | null | undefined,
): boolean {
  return (
    status === AutomationRunStatus.FAILED ||
    status === AutomationRunStatus.PENDING ||
    status === AutomationRunStatus.RUNNING
  );
}

/**
 * Whether the phase's age is worth showing. Only for a run still in flight:
 * the age exists to separate a moving run from a stalled one, and a run that
 * has failed is neither — its phase is the place it stopped. Left in, the age
 * of an old failure degrades to an absolute date (`formatRelativeTime` gives
 * up past a week), which reads as a second timestamp beside the one the row
 * already shows.
 */
export function shouldShowRunPhaseAge(
  status: AutomationRunStatus | null | undefined,
): boolean {
  return (
    status === AutomationRunStatus.PENDING ||
    status === AutomationRunStatus.RUNNING
  );
}

interface RunPhaseFields {
  /** `AutomationRun.status` — decides whether the age is meaningful. */
  status: AutomationRunStatus | null | undefined;
  /** `AutomationRun.phase_code` — `null`/absent means no phase reported. */
  code: string | null | undefined;
  /** `AutomationRun.phase_label` — free-form author text, not interface copy. */
  label: string | null | undefined;
  /** `AutomationRun.phase_updated_at` — when this phase was last written. */
  updatedAt?: string | null;
}

interface RunPhaseProps extends RunPhaseFields {
  /** More width before clipping, for rows far wider than a card. */
  wide?: boolean;
}

/**
 * Codes the frontend can translate: the automation service's own milestones
 * and the preset templates'. Any other code is by design unknown — custom
 * automations emit their own — and falls back to `phase_label`.
 */
const KNOWN_PHASE_CODES: Record<string, I18nKey> = {
  queued: I18nKey.AUTOMATIONS$DETAIL$PHASE_QUEUED,
  sandbox_provisioning: I18nKey.AUTOMATIONS$DETAIL$PHASE_SANDBOX_PROVISIONING,
  bundle_upload: I18nKey.AUTOMATIONS$DETAIL$PHASE_BUNDLE_UPLOAD,
  entrypoint_start: I18nKey.AUTOMATIONS$DETAIL$PHASE_ENTRYPOINT_START,
  preparing: I18nKey.AUTOMATIONS$DETAIL$PHASE_PREPARING,
  running_agent: I18nKey.AUTOMATIONS$DETAIL$PHASE_RUNNING_AGENT,
};

/**
 * The one place a stored phase becomes text, so a run cannot read one way on
 * a card and another way in that card's own tooltip. An absent code counts as
 * unrecognized rather than as an absent phase: the service accepts a phase
 * carrying only a label, and dropping those would hide a real phase.
 *
 * `code` and `label` are independently optional in the service's contract, so
 * the last resort is the raw code — a code-only phase is a real phase and
 * must reach the screen. It is shown as stored rather than prettified: the
 * code is data like the label, and turning `poll_prs` into "Poll prs" would
 * invent English-shaped copy no automation author wrote.
 *
 * Both fields are author-supplied, which is why the lookup is an own-property
 * check and both are trimmed. A code of `toString` would otherwise resolve to
 * `Object.prototype.toString` and be handed to `t()`, and the service stores
 * a whitespace-only field as sent — it rejects only a phase blank on *both*.
 */
export function resolveRunPhaseText(
  t: (key: I18nKey) => string,
  code: string | null | undefined,
  label: string | null | undefined,
): string | null {
  const knownKey =
    code && Object.hasOwn(KNOWN_PHASE_CODES, code)
      ? KNOWN_PHASE_CODES[code]
      : undefined;
  if (knownKey) return t(knownKey);
  return label?.trim() || code?.trim() || null;
}

/**
 * How long the run has been in this phase, as localized relative time.
 *
 * This is the half of the phase that separates progress from a stall: the
 * phase text alone says a run is "Running agent", and only its age says
 * whether it entered that phase seconds ago or forty minutes ago. Returns
 * `null` when the service reported no usable timestamp — an older service
 * omits the field entirely, and an unset datetime arrives as the epoch — so
 * an age nobody can compute never surfaces as "Invalid Date" or "Jan 1, 1970".
 */
export function formatRunPhaseAge(
  updatedAt: string | null | undefined,
  locale: string,
  t: (key: I18nKey, options?: Record<string, unknown>) => string,
): string | null {
  if (!updatedAt || isInvalidTimestamp(updatedAt)) return null;
  return formatRelativeTime(updatedAt, locale, t);
}

/**
 * The resolved phase of a run, or `null` when it has none worth showing.
 * Every surface goes through this — the clipped row below, the home
 * hovercard's wrapping one — so they cannot drift into resolving a phase, or
 * deciding to show its age, on their own terms.
 */
export function useRunPhase({
  status,
  code,
  label,
  updatedAt,
}: RunPhaseFields): { text: string; age: string | null } | null {
  const { t, i18n } = useTranslation("openhands");

  const text = resolveRunPhaseText(t, code, label);
  if (!text) return null;

  const age = shouldShowRunPhaseAge(status)
    ? formatRunPhaseAge(updatedAt, i18n.language, t)
    : null;

  return { text, age };
}

/**
 * A run's current or last-known phase and how long it has held it, clipped to
 * the room the surface has with the full text one hover away — author-supplied
 * labels routinely outgrow any row. The label is data, not interface copy, so
 * it is rendered as-is: passing it through `t()` would be wrong, it is not a
 * key. The age sits outside the clipped text so a long label can never push it
 * out of sight — it is the part that stays legible when everything else is cut.
 *
 * The text stays in the accessibility tree rather than hiding behind an
 * accessible name on a focusable wrapper. Every surface nests this inside a
 * link — the activity log's `<a>`, the cards' `role="link"` — where a tab
 * stop is invalid interactive nesting, and Enter on it bubbled to the card
 * and navigated the user away from the text they were trying to read.
 * Truncation is CSS only, so the full label is already in the DOM and reads
 * in full; the tooltip is the sighted mouse user's route to it.
 */
export function RunPhase({
  status,
  code,
  label,
  updatedAt,
  wide = false,
}: RunPhaseProps) {
  const phase = useRunPhase({ status, code, label, updatedAt });
  if (!phase) return null;

  const { text, age } = phase;

  return (
    <Tooltip
      content={
        <>
          {text}
          {age ? <span className="mt-1 block text-muted">{age}</span> : null}
        </>
      }
      placement="top"
      closeDelay={100}
      disableAnimation={import.meta.env.MODE === "test"}
      classNames={{
        content:
          "max-w-xs whitespace-pre-wrap break-words rounded-xl border border-border bg-base-secondary px-3 py-2 text-left text-xs text-contrast shadow-xl",
      }}
    >
      <span className="flex min-w-0 cursor-default items-center gap-1">
        <span
          data-testid="run-phase"
          className={cn(
            "min-w-0 truncate text-xs text-muted",
            wide ? "max-w-[28rem]" : "max-w-[12rem]",
          )}
        >
          {text}
        </span>
        {age ? (
          <span
            data-testid="run-phase-age"
            className="shrink-0 whitespace-nowrap text-xs text-muted"
          >
            · {age}
          </span>
        ) : null}
      </span>
    </Tooltip>
  );
}

import { CircleAlert, CircleHelp, Loader2 } from "lucide-react";
import { useTranslation } from "react-i18next";
import { StyledTooltip } from "#/components/shared/buttons/styled-tooltip";
import CheckCircleIcon from "#/icons/check-circle.svg?react";
import XCircleIcon from "#/icons/x-circle.svg?react";
import ClockIcon from "#/icons/clock.svg?react";
import { AutomationRunStatus } from "#/types/automation";
import {
  getAutomationRunBadgeLabelKey,
  type AutomationRunBadgeStatus,
} from "#/utils/automation-run-display";
import { cn } from "#/utils/utils";

interface RunStatusBadgeProps {
  status: AutomationRunBadgeStatus;
  /**
   * Icon-only mark (no pill). Status text is available via hover tooltip and
   * `aria-label`, unless {@link showLabel} is also set.
   */
  iconOnly?: boolean;
  /** With `iconOnly`, render the status word next to the icon (still no pill). */
  showLabel?: boolean;
  /** Smaller pill for dense rows (e.g. home activity meta line). */
  compact?: boolean;
}

const statusConfig: Record<string, { style: string; iconTone: string }> = {
  [AutomationRunStatus.COMPLETED]: {
    style: "bg-semantic-success/10 text-semantic-success",
    iconTone: "text-semantic-success",
  },
  success: {
    style: "bg-semantic-success/10 text-semantic-success",
    iconTone: "text-semantic-success",
  },
  [AutomationRunStatus.FAILED]: {
    style: "bg-semantic-danger/10 text-danger",
    iconTone: "text-danger",
  },
  failed: {
    style: "bg-semantic-danger/10 text-danger",
    iconTone: "text-danger",
  },
  blocked: {
    style: "bg-warning/10 text-warning",
    iconTone: "text-warning",
  },
  partial_success: {
    style: "bg-warning/10 text-warning",
    iconTone: "text-warning",
  },
  unknown: {
    style: "bg-warning/10 text-warning",
    iconTone: "text-warning",
  },
  [AutomationRunStatus.PENDING]: {
    style: "bg-surface-raised text-muted",
    iconTone: "text-muted",
  },
  [AutomationRunStatus.RUNNING]: {
    style: "bg-surface-raised text-muted",
    iconTone: "text-muted",
  },
  [AutomationRunStatus.CANCELLED]: {
    style: "bg-surface-raised text-muted",
    iconTone: "text-muted",
  },
  [AutomationRunStatus.SKIPPED]: {
    style: "bg-surface-raised text-muted",
    iconTone: "text-muted",
  },
};

function StatusIcon({
  status,
  compact = false,
}: {
  status: AutomationRunBadgeStatus;
  compact?: boolean;
}) {
  const iconClass = compact ? "size-3" : "size-3.5";
  switch (status) {
    case AutomationRunStatus.COMPLETED:
    case "success":
      return (
        <CheckCircleIcon
          data-testid="run-status-icon-completed"
          className={iconClass}
        />
      );
    case AutomationRunStatus.FAILED:
    case "failed":
      return (
        <XCircleIcon
          data-testid="run-status-icon-failed"
          className={iconClass}
        />
      );
    case AutomationRunStatus.RUNNING:
      return (
        <Loader2
          data-testid="run-status-icon-running"
          className={cn(iconClass, "animate-spin motion-reduce:animate-none")}
          aria-hidden="true"
        />
      );
    case "blocked":
    case "partial_success":
      return (
        <CircleAlert
          data-testid="run-status-icon-warning"
          className={iconClass}
          aria-hidden="true"
        />
      );
    case "unknown":
      return (
        <CircleHelp
          data-testid="run-status-icon-needs-review"
          className={iconClass}
          aria-hidden="true"
        />
      );
    default:
      return (
        <ClockIcon
          data-testid="run-status-icon-pending"
          className={iconClass}
        />
      );
  }
}

export function RunStatusBadge({
  status,
  iconOnly = false,
  showLabel = false,
  compact = false,
}: RunStatusBadgeProps) {
  const { t } = useTranslation("openhands");
  // Degrade instead of crashing on a status the backend added after this enum.
  const config =
    statusConfig[status] ?? statusConfig[AutomationRunStatus.PENDING];
  const label = t(getAutomationRunBadgeLabelKey(status));

  if (iconOnly) {
    if (showLabel) {
      return (
        <span
          data-testid="run-status-badge-icon"
          className={cn(
            "inline-flex min-w-0 shrink-0 items-center gap-1.5 text-xs font-medium",
            config.iconTone,
          )}
        >
          <StatusIcon status={status} compact={compact} />
          <span className="truncate">{label}</span>
        </span>
      );
    }

    return (
      <StyledTooltip content={label} placement="top">
        <span
          role="img"
          aria-label={label}
          data-testid="run-status-badge-icon"
          className={cn(
            "inline-flex shrink-0 cursor-default items-center justify-center",
            config.iconTone,
          )}
        >
          <StatusIcon status={status} compact={compact} />
        </span>
      </StyledTooltip>
    );
  }

  return (
    <span
      className={cn(
        "inline-flex items-center rounded-full font-medium",
        compact
          ? "gap-1 pl-1 pr-1.5 py-0 text-[10px] leading-4"
          : "gap-1.5 pl-2 pr-2.5 py-1 text-xs",
        config.style,
      )}
    >
      <StatusIcon status={status} compact={compact} />
      {label}
    </span>
  );
}

import { useTranslation } from "react-i18next";
import { I18nKey } from "#/i18n/declaration";
import TerminalIcon from "#/icons/terminal.svg?react";
import { HighlightedSourceView } from "#/components/features/files-tab/highlighted-source-view";
import { useAutomationTarballFiles } from "#/hooks/query/use-automation-tarball-files";
import type { Automation } from "#/types/automation";
import type { TarEntry } from "#/utils/tar-unpack";
import { SectionCard } from "./section-card";

interface ScriptSectionProps {
  automation: Automation;
}

/**
 * The bundle member the entrypoint runs, if it names one: the first token
 * of the command that is a file in the archive (`python main.py` → `main.py`).
 */
function findEntrypointPath(
  entrypoint: string | undefined,
  entries: TarEntry[],
): string | null {
  if (!entrypoint) return null;
  const paths = new Set(entries.map((entry) => entry.path));
  for (const token of entrypoint.split(/\s+/)) {
    const candidate = token.replace(/^\.\//, "");
    if (paths.has(candidate)) return candidate;
  }
  return null;
}

/** Entrypoint first, then the rest by path. */
function orderEntries(
  entries: TarEntry[],
  entrypointPath: string | null,
): TarEntry[] {
  return [...entries].sort((a, b) => {
    if (a.path === entrypointPath) return -1;
    if (b.path === entrypointPath) return 1;
    return a.path.localeCompare(b.path);
  });
}

/**
 * What a script automation runs: the files of its uploaded bundle, read
 * back from the same tarball the kebab menu offers for download. Takes the
 * place of the prompt section for automations that have no prompt.
 */
export function ScriptSection({ automation }: ScriptSectionProps) {
  const { t } = useTranslation("openhands");
  const {
    data: entries,
    isPending,
    isError,
  } = useAutomationTarballFiles(automation);

  const entrypointPath = findEntrypointPath(
    automation.entrypoint,
    entries ?? [],
  );
  // A bundle the service can't hand back (external URL, deleted upload) or
  // that isn't an archive gets the same answer: download it instead.
  const unavailable = isError || entries?.length === 0;

  return (
    <SectionCard
      icon={<TerminalIcon className="size-4" />}
      title={t(I18nKey.AUTOMATIONS$DETAIL$SCRIPT)}
    >
      <div className="flex flex-col gap-4">
        {automation.entrypoint ? (
          <code
            data-testid="automation-script-entrypoint"
            className="self-start rounded-md bg-surface-raised px-2 py-1 font-mono text-xs text-content"
          >
            {automation.entrypoint}
          </code>
        ) : null}

        {isPending ? (
          <p className="text-sm italic text-muted">
            {t(I18nKey.AUTOMATIONS$DETAIL$SCRIPT_LOADING)}
          </p>
        ) : null}

        {unavailable ? (
          <p
            data-testid="automation-script-unavailable"
            className="text-sm text-muted"
          >
            {t(I18nKey.AUTOMATIONS$DETAIL$SCRIPT_UNAVAILABLE)}
          </p>
        ) : null}

        {entries && entries.length > 0
          ? orderEntries(entries, entrypointPath).map((entry) => (
              <div
                key={entry.path}
                data-testid="automation-script-file"
                className="overflow-hidden rounded-lg border border-[var(--oh-border)]"
              >
                <div className="flex items-center gap-2 border-b border-[var(--oh-border)] bg-black/20 px-3 py-2 font-mono text-xs text-content">
                  <span className="truncate">{entry.path}</span>
                  {entry.path === entrypointPath ? (
                    <span className="shrink-0 rounded-md bg-surface-raised px-2 py-0.5 text-[10px] font-medium text-muted">
                      {t(I18nKey.AUTOMATIONS$DETAIL$SCRIPT_ENTRYPOINT)}
                    </span>
                  ) : null}
                </div>
                {entry.text === null ? (
                  <p className="px-3 py-2 text-xs italic text-muted">
                    {t(I18nKey.AUTOMATIONS$DETAIL$SCRIPT_BINARY_FILE)}
                  </p>
                ) : (
                  <div className="max-h-96 overflow-auto">
                    <HighlightedSourceView
                      path={entry.path}
                      text={entry.text}
                    />
                  </div>
                )}
              </div>
            ))
          : null}
      </div>
    </SectionCard>
  );
}

import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { RefreshCw, Check, TriangleAlert } from "lucide-react";
import { I18nKey } from "#/i18n/declaration";
import { formatTimeDelta } from "#/utils/format-time-delta";
import { cn } from "#/utils/utils";

export type GitSyncActivityState = "idle" | "running" | "succeeded" | "failed";

interface GitSyncActivityRowProps {
  state: GitSyncActivityState;
  /** When the running cycle started, for the elapsed-time hint. */
  startedAt: string | null;
  /** Automations still waiting to be pushed, shown while a cycle runs. */
  pendingCount: number;
}

/**
 * Re-render every second while a cycle runs. The elapsed hint is derived from
 * the clock, not from props, and the status poll returns identical JSON for as
 * long as the cycle is in flight -- react-query's structural sharing then
 * hands back the same object, nothing re-renders, and the hint would sit at
 * whatever it read when the cycle started.
 */
function useSecondsTick(active: boolean) {
  const [, setTick] = useState(0);

  useEffect(() => {
    if (!active) return undefined;
    const timer = setInterval(() => setTick((count) => count + 1), 1_000);
    return () => clearInterval(timer);
  }, [active]);
}

/**
 * The page's own account of the sync cycle, in place of the fire-and-forget
 * success toast: the trigger returns as soon as the cycle is scheduled, so a
 * toast said "started" and then never came back with an outcome.
 */
export function GitSyncActivityRow({
  state,
  startedAt,
  pendingCount,
}: GitSyncActivityRowProps) {
  const { t } = useTranslation("openhands");
  const isRunning = state === "running";

  useSecondsTick(isRunning && startedAt !== null);

  if (state === "idle") return null;

  const isFailed = state === "failed";

  return (
    <div
      data-testid="git-sync-activity-row"
      data-state={state}
      className={cn(
        "mt-4 flex flex-wrap items-center gap-x-2 gap-y-1 rounded-md px-3 py-2 text-sm",
        isRunning && "bg-tertiary text-content",
        state === "succeeded" && "bg-green-500/10 text-green-300",
        isFailed && "bg-red-500/10 text-red-300",
      )}
    >
      {isRunning && <RefreshCw className="size-4 animate-spin" aria-hidden />}
      {state === "succeeded" && <Check className="size-4" aria-hidden />}
      {isFailed && <TriangleAlert className="size-4" aria-hidden />}

      <span className="font-medium">
        {isRunning && t(I18nKey.AUTOMATIONS$GIT_SYNC$SYNCING)}
        {state === "succeeded" &&
          t(I18nKey.AUTOMATIONS$GIT_SYNC$SYNC_COMPLETED)}
        {isFailed && t(I18nKey.AUTOMATIONS$GIT_SYNC$SYNC_FAILED)}
      </span>

      {isRunning && startedAt && (
        <span className="text-xs text-muted">
          {t(I18nKey.AUTOMATIONS$GIT_SYNC$SYNC_STARTED_AGO, {
            time: formatTimeDelta(startedAt),
          })}
        </span>
      )}
      {isRunning && pendingCount > 0 && (
        <span className="text-xs text-muted">
          {t(I18nKey.AUTOMATIONS$GIT_SYNC$SYNC_PENDING_COUNT, {
            count: pendingCount,
          })}
        </span>
      )}
    </div>
  );
}

import { useState, type FormEvent } from "react";
import { useTranslation } from "react-i18next";
import { I18nKey } from "#/i18n/declaration";
import { SettingsInput } from "#/components/features/settings/settings-input";
import { SettingsSwitch } from "#/components/features/settings/settings-switch";
import { BrandButton } from "#/components/features/settings/brand-button";
import { SectionCard } from "#/components/features/automations/detail/section-card";
import CogIcon from "#/icons/cog.svg?react";
import {
  displayErrorToast,
  displaySuccessToast,
} from "#/utils/custom-toast-handlers";
import { getApiErrorMessage } from "#/utils/api-error-message";
import {
  useCheckGitSyncConfig,
  useUpdateGitSyncConfig,
} from "#/hooks/query/use-git-sync";
import type {
  GitSyncConfigUpdateRequest,
  GitSyncStatus,
} from "#/types/git-sync";

/**
 * Identifies the save-and-sync button in the submit event. Read from the
 * event's `submitter` rather than tracked on click: native field validation
 * (the author email, the interval) can swallow a submit after the click has
 * already happened, and a flag set there would still be armed when Save is
 * pressed next -- syncing off a button that never asked for it.
 */
const SAVE_AND_SYNC = "git-sync-save-and-sync";

interface GitSyncConfigFormProps {
  status: GitSyncStatus;
  canManage: boolean;
  /**
   * Runs a sync cycle. The same handler the overview's Sync now button uses,
   * so a save-and-sync is followed by the one activity row rather than
   * starting a cycle nothing on the page is watching.
   */
  onSyncNow: () => void;
}

export function GitSyncConfigForm({
  status,
  canManage,
  onSyncNow,
}: GitSyncConfigFormProps) {
  const { t } = useTranslation("openhands");
  const { mutate: updateConfig, isPending } = useUpdateGitSyncConfig();
  const { mutateAsync: checkConfig, isPending: isChecking } =
    useCheckGitSyncConfig();

  // The settings that failed their reachability check, so the same submit
  // pressed a second time saves them anyway. Keyed by the values that were
  // checked rather than a plain flag: editing any of them changes the key,
  // which re-arms the check without the field handlers having to clear it.
  const [failedCheck, setFailedCheck] = useState<{
    key: string;
    detail: string;
  } | null>(null);

  const [intervalHasChanged, setIntervalHasChanged] = useState(false);
  const [repoUrlHasChanged, setRepoUrlHasChanged] = useState(false);
  const [branchHasChanged, setBranchHasChanged] = useState(false);
  const [pathHasChanged, setPathHasChanged] = useState(false);
  const [authorNameHasChanged, setAuthorNameHasChanged] = useState(false);
  const [authorEmailHasChanged, setAuthorEmailHasChanged] = useState(false);

  // `null` means untouched, so the switch keeps following the server state
  // (including a status refetch) until the operator actually flips it.
  const [enabledOverride, setEnabledOverride] = useState<boolean | null>(null);
  const enabled = enabledOverride ?? status.enabled;
  const enabledHasChanged =
    enabledOverride !== null && enabled !== status.enabled;

  const [tokenText, setTokenText] = useState("");
  const [clearToken, setClearToken] = useState(false);
  const [encryptionKeyText, setEncryptionKeyText] = useState("");
  const [clearEncryptionKey, setClearEncryptionKey] = useState(false);

  const tokenHasChanged = tokenText.trim().length > 0 || clearToken;
  const encryptionKeyHasChanged =
    encryptionKeyText.trim().length > 0 || clearEncryptionKey;

  const formIsClean =
    !enabledHasChanged &&
    !intervalHasChanged &&
    !repoUrlHasChanged &&
    !branchHasChanged &&
    !pathHasChanged &&
    !authorNameHasChanged &&
    !authorEmailHasChanged &&
    !tokenHasChanged &&
    !encryptionKeyHasChanged;

  const resetChangeFlags = () => {
    setEnabledOverride(null);
    setIntervalHasChanged(false);
    setRepoUrlHasChanged(false);
    setBranchHasChanged(false);
    setPathHasChanged(false);
    setAuthorNameHasChanged(false);
    setAuthorEmailHasChanged(false);
    setTokenText("");
    setClearToken(false);
    setEncryptionKeyText("");
    setClearEncryptionKey(false);
    setFailedCheck(null);
  };

  // The secret inputs are remounted -- and therefore emptied -- whenever the
  // matching clear switch flips, so drop the typed value with them. Keeping it
  // in state would leave the field marked dirty against an empty input and
  // submit `token: ""`, an override that fails every later push with
  // `fatal: Authentication failed`.
  const toggleClearToken = (isToggled: boolean) => {
    setClearToken(isToggled);
    setTokenText("");
  };

  const toggleClearEncryptionKey = (isToggled: boolean) => {
    setClearEncryptionKey(isToggled);
    setEncryptionKeyText("");
  };

  // A cleared field posts `null` -- clear the override and fall back to the
  // environment default -- rather than `""`, which the backend stored as a
  // literal empty override. An empty branch or path then made the next git
  // command fatal (`git checkout -B ""`, `git add -A -- ""`), wedging every
  // subsequent sync cycle with that error in the status banner.
  const clearedFieldAsNull = (formData: FormData, name: string) =>
    formData.get(name)?.toString().trim() || null;

  const save = (body: GitSyncConfigUpdateRequest, thenSync: boolean) => {
    updateConfig(body, {
      onSuccess: () => {
        displaySuccessToast(t(I18nKey.AUTOMATIONS$GIT_SYNC$CONFIG_SAVED));
        // Only on success: clearing the flags after a failure would disable
        // Save and silently un-toggle the clear switches, leaving no way to
        // retry the change that was just rejected.
        resetChangeFlags();
        // A cycle runs off the stored configuration, so it can only be
        // triggered once the save has landed -- and a rejected save leaves
        // nothing new to sync.
        if (thenSync) onSyncNow();
      },
      onError: (error) => {
        // The backend's detail is the message: a 409 means another
        // organization already syncs this repository, branch and path, and
        // it says so in words the operator can act on.
        displayErrorToast(getApiErrorMessage(error, t(I18nKey.ERROR$GENERIC)));
      },
    });
  };

  // What the reachability check actually depends on. A save that touches only
  // the interval or the author has nothing for the remote to reject, so it
  // shouldn't cost a round trip to the repo.
  const remoteFieldsOf = (body: GitSyncConfigUpdateRequest) =>
    (["repo_url", "branch", "token"] as const)
      .filter((field) => field in body)
      .map((field) => `${field}=${body[field]}`)
      .join("&");

  /** The reason these settings can't reach their repo, or null to go ahead. */
  const reachabilityFailure = async (body: GitSyncConfigUpdateRequest) => {
    try {
      const result = await checkConfig(body);
      return result.ok
        ? null
        : (result.detail ?? t(I18nKey.AUTOMATIONS$GIT_SYNC$CHECK_FAILED_TITLE));
    } catch {
      // A check that couldn't run says nothing about the configuration --
      // an automation backend that predates the endpoint answers 404 -- and
      // must never be what stands between an operator and saving.
      return null;
    }
  };

  // A plain submit handler rather than `<form action={...}>`: React resets an
  // uncontrolled form as soon as the action returns, which wiped every edit
  // while the save was still in flight -- so a rejected save left the operator
  // with the old values and nothing to retry.
  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const thenSync =
      (event.nativeEvent as SubmitEvent).submitter?.getAttribute("name") ===
      SAVE_AND_SYNC;
    const formData = new FormData(event.currentTarget);
    const body: GitSyncConfigUpdateRequest = {};

    if (enabledHasChanged) {
      body.enabled = enabled;
    }
    if (intervalHasChanged) {
      // Blank reads as manual-only rather than clearing the override, so an
      // emptied field can never be mistaken for "keep syncing on a timer".
      const raw = formData.get("git-sync-interval-input")?.toString().trim();
      const parsed = Number(raw);
      body.interval_seconds =
        raw && Number.isFinite(parsed) ? Math.max(0, Math.trunc(parsed)) : 0;
    }
    if (repoUrlHasChanged) {
      body.repo_url = clearedFieldAsNull(formData, "git-sync-repo-url-input");
    }
    if (branchHasChanged) {
      body.branch = clearedFieldAsNull(formData, "git-sync-branch-input");
    }
    if (pathHasChanged) {
      body.path = clearedFieldAsNull(formData, "git-sync-path-input");
    }
    if (authorNameHasChanged) {
      body.author_name = clearedFieldAsNull(
        formData,
        "git-sync-author-name-input",
      );
    }
    if (authorEmailHasChanged) {
      body.author_email = clearedFieldAsNull(
        formData,
        "git-sync-author-email-input",
      );
    }
    // The secrets come from state rather than FormData: the clear switch
    // remounts (and empties) their inputs, so the two disagree for a render
    // and only state knows what the operator actually typed.
    const token = tokenText.trim();
    const encryptionKey = encryptionKeyText.trim();
    if (clearToken) {
      body.token = null;
    } else if (token) {
      body.token = token;
    }
    if (clearEncryptionKey) {
      body.encryption_key = null;
    } else if (encryptionKey) {
      body.encryption_key = encryptionKey;
    }

    // Test the settings before storing them, so a mistyped repo URL or a
    // rejected token is caught here instead of by the next sync cycle. The
    // same values submitted twice save anyway: an operator who disagrees with
    // the check -- or whose remote refuses `ls-remote` but accepts a push --
    // must not be locked out of their own configuration.
    const remoteFields = remoteFieldsOf(body);
    if (remoteFields && failedCheck?.key !== remoteFields) {
      const detail = await reachabilityFailure(body);
      if (detail) {
        setFailedCheck({ key: remoteFields, detail });
        return;
      }
    }
    setFailedCheck(null);

    save(body, thenSync);
  };

  return (
    <SectionCard
      icon={<CogIcon className="size-4" />}
      title={t(I18nKey.AUTOMATIONS$GIT_SYNC$CONFIG_TITLE)}
    >
      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        <div className="flex flex-col gap-2">
          <SettingsSwitch
            testId="git-sync-enabled-switch"
            isToggled={enabled}
            isDisabled={!canManage}
            onToggle={setEnabledOverride}
          >
            {t(I18nKey.AUTOMATIONS$GIT_SYNC$FIELD_ENABLED)}
          </SettingsSwitch>
          <p className="text-xs text-muted">
            {t(I18nKey.AUTOMATIONS$GIT_SYNC$ENABLED_HELP)}
          </p>
        </div>

        <div className="flex flex-col gap-2">
          <SettingsInput
            testId="git-sync-interval-input"
            name="git-sync-interval-input"
            type="number"
            min={0}
            label={t(I18nKey.AUTOMATIONS$GIT_SYNC$FIELD_INTERVAL)}
            defaultValue={String(status.interval_seconds)}
            isDisabled={!canManage}
            onChange={(value) =>
              setIntervalHasChanged(
                value.trim() !== String(status.interval_seconds),
              )
            }
          />
          <p className="text-xs text-muted">
            {t(I18nKey.AUTOMATIONS$GIT_SYNC$INTERVAL_HELP)}
          </p>
        </div>

        <SettingsInput
          testId="git-sync-repo-url-input"
          name="git-sync-repo-url-input"
          type="text"
          label={t(I18nKey.AUTOMATIONS$GIT_SYNC$FIELD_REPO_URL)}
          defaultValue={status.repo_url}
          placeholder={t(I18nKey.AUTOMATIONS$GIT_SYNC$REPO_URL_PLACEHOLDER)}
          isDisabled={!canManage}
          onChange={(value) =>
            setRepoUrlHasChanged(value.trim() !== status.repo_url)
          }
        />

        <SettingsInput
          testId="git-sync-branch-input"
          name="git-sync-branch-input"
          type="text"
          label={t(I18nKey.AUTOMATIONS$GIT_SYNC$FIELD_BRANCH)}
          defaultValue={status.branch}
          placeholder={t(I18nKey.AUTOMATIONS$GIT_SYNC$BRANCH_PLACEHOLDER)}
          isDisabled={!canManage}
          onChange={(value) =>
            setBranchHasChanged(value.trim() !== status.branch)
          }
        />

        <SettingsInput
          testId="git-sync-path-input"
          name="git-sync-path-input"
          type="text"
          label={t(I18nKey.AUTOMATIONS$GIT_SYNC$FIELD_PATH)}
          defaultValue={status.path}
          placeholder={t(I18nKey.AUTOMATIONS$GIT_SYNC$PATH_PLACEHOLDER)}
          isDisabled={!canManage}
          onChange={(value) => setPathHasChanged(value.trim() !== status.path)}
        />

        <div className="flex flex-col gap-2">
          <SettingsInput
            testId="git-sync-author-name-input"
            name="git-sync-author-name-input"
            type="text"
            label={t(I18nKey.AUTOMATIONS$GIT_SYNC$FIELD_AUTHOR_NAME)}
            showOptionalTag
            defaultValue=""
            isDisabled={!canManage}
            // Dirty on any edit, not just a non-empty one: gating on the value
            // meant emptying the field never posted `author_name: null`, so a
            // wrong override could never be cleared back to the default.
            onChange={() => setAuthorNameHasChanged(true)}
          />

          <SettingsInput
            testId="git-sync-author-email-input"
            name="git-sync-author-email-input"
            type="email"
            label={t(I18nKey.AUTOMATIONS$GIT_SYNC$FIELD_AUTHOR_EMAIL)}
            showOptionalTag
            defaultValue=""
            isDisabled={!canManage}
            onChange={() => setAuthorEmailHasChanged(true)}
          />
          <p className="text-xs text-muted">
            {t(I18nKey.AUTOMATIONS$GIT_SYNC$AUTHOR_HELP)}
          </p>
        </div>

        <div className="flex flex-col gap-2">
          <SettingsInput
            key={clearToken ? "token-cleared" : "token-editable"}
            testId="git-sync-token-input"
            name="git-sync-token-input"
            type="password"
            label={t(I18nKey.AUTOMATIONS$GIT_SYNC$FIELD_TOKEN)}
            placeholder={t(I18nKey.AUTOMATIONS$GIT_SYNC$TOKEN_PLACEHOLDER)}
            isDisabled={!canManage || clearToken}
            onChange={setTokenText}
          />
          <p className="text-xs text-muted">
            {t(I18nKey.AUTOMATIONS$GIT_SYNC$TOKEN_HELP)}
          </p>
          <SettingsSwitch
            testId="git-sync-clear-token-switch"
            isToggled={clearToken}
            isDisabled={!canManage}
            onToggle={toggleClearToken}
          >
            {t(I18nKey.AUTOMATIONS$GIT_SYNC$CLEAR_TOKEN)}
          </SettingsSwitch>
        </div>

        <div className="flex flex-col gap-2">
          <SettingsInput
            key={clearEncryptionKey ? "key-cleared" : "key-editable"}
            testId="git-sync-encryption-key-input"
            name="git-sync-encryption-key-input"
            type="password"
            label={t(I18nKey.AUTOMATIONS$GIT_SYNC$FIELD_ENCRYPTION_KEY)}
            placeholder={t(
              status.encryption_enabled
                ? I18nKey.AUTOMATIONS$GIT_SYNC$KEY_SET_PLACEHOLDER
                : I18nKey.AUTOMATIONS$GIT_SYNC$KEY_UNSET_PLACEHOLDER,
            )}
            isDisabled={!canManage || clearEncryptionKey}
            onChange={setEncryptionKeyText}
          />
          <p className="text-xs text-muted">
            {t(I18nKey.AUTOMATIONS$GIT_SYNC$ENCRYPTION_KEY_HELP)}
          </p>
          <SettingsSwitch
            testId="git-sync-clear-encryption-key-switch"
            isToggled={clearEncryptionKey}
            isDisabled={!canManage}
            onToggle={toggleClearEncryptionKey}
          >
            {t(I18nKey.AUTOMATIONS$GIT_SYNC$CLEAR_ENCRYPTION_KEY)}
          </SettingsSwitch>
        </div>

        {failedCheck && (
          <div
            role="alert"
            data-testid="git-sync-check-failure"
            className="rounded-md border border-red-500/40 bg-red-500/10 p-3 text-sm text-red-300 whitespace-pre-wrap break-words"
          >
            <p className="font-medium">
              {t(I18nKey.AUTOMATIONS$GIT_SYNC$CHECK_FAILED_TITLE)}
            </p>
            <p className="mt-1">{failedCheck.detail}</p>
            <p className="mt-1 text-xs text-red-300/70">
              {t(I18nKey.AUTOMATIONS$GIT_SYNC$CHECK_FAILED_HINT)}
            </p>
          </div>
        )}

        <div className="flex justify-start gap-3">
          <BrandButton
            testId="git-sync-save-button"
            variant="primary"
            type="submit"
            isDisabled={!canManage || isPending || isChecking || formIsClean}
          >
            {!isPending && !isChecking && t(I18nKey.SETTINGS$SAVE_CHANGES)}
            {isChecking && t(I18nKey.AUTOMATIONS$GIT_SYNC$CHECKING)}
            {isPending && t(I18nKey.SETTINGS$SAVING)}
          </BrandButton>
          <BrandButton
            testId="git-sync-save-and-sync-button"
            name={SAVE_AND_SYNC}
            variant="secondary"
            type="submit"
            // Sync left off is a 503 from the trigger, so there is nothing to
            // offer -- but a save that turns it on can sync straight after.
            isDisabled={
              !canManage || isPending || isChecking || formIsClean || !enabled
