function Field({
  label,
  showLabel = true,
  labelClassName,
  suffix,
  horizontal = false,
  isStreaming = false,
  errorText,
  children,
}: {
  label: string;
  showLabel?: boolean;
  labelClassName?: string;
  suffix?: string;
  horizontal?: boolean;
  isStreaming?: boolean;
  errorText?: string;
  children: ReactNode;
}) {
  return (
    <label
      data-streaming-active={isStreaming ? "true" : undefined}
      className={cn(
        "flex gap-2",
        horizontal ? "items-center" : "flex-col",
        streamingHighlightClassName(isStreaming),
      )}
    >
      {showLabel ? (
        <span
          className={cn(
            "flex shrink-0 items-center gap-2 text-sm",
            labelClassName,
          )}
        >
          <span>{label}</span>
          {suffix && (
            <span className="font-normal text-[var(--oh-muted)]">{suffix}</span>
          )}
        </span>
      ) : null}
      <div className="min-w-0 flex-1">{children}</div>
      {errorText ? (
        <span
          role="alert"
          className="text-xs leading-5 text-[var(--oh-warning)]"
        >
          {errorText}
        </span>
      ) : null}
    </label>
  );
}

