          <h2 className={cn("pr-6", modalTitleLgClassName)}>{title}</h2>
        </header>
        <div className="flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-6 custom-scrollbar">
          <SettingsInput
            testId="automation-setup-repository-address"
