            type="text"
            value={address}
            onChange={setAddress}
            placeholder={t(I18nKey.SETUP$REPOSITORY_PLACEHOLDER)}
            showRequiredTag
          />
        </div>
        <footer className="flex flex-shrink-0 justify-end gap-2 px-6 pb-6 pt-4">
          <BrandButton
            type="button"
            variant="secondary"
            onClick={onClose}
            testId="automation-setup-add-repository-modal-dismiss"
          >
            {t(I18nKey.BUTTON$CLOSE)}
          </BrandButton>
          <BrandButton
            type="submit"
