/**
 * Modal wrapper. In **add** mode it renders a two-column layout
 * (manual connection | OR | Cloud login). In **edit** mode it wraps
 * the standard `BackendForm`.
 */
export function BackendFormModal({
  mode,
  backend,
  onClose,
  source = "add_backend_modal",
  hideCloseButton = false,
}: BackendFormModalProps) {
  const { t } = useTranslation("openhands");

  if (mode === "add") {
    return (
      <ModalBackdrop
        onClose={hideCloseButton ? undefined : onClose}
        closeOnEscape={false}
        closeOnBackdropClick={!hideCloseButton}
        aria-label={t(I18nKey.BACKEND$ADD_TITLE)}
      >
        <div
          data-testid={
            hideCloseButton ? "onboarding-modal" : "add-backend-modal"
          }
          className={cn(
            "relative max-h-[92vh] w-180 overflow-x-hidden overflow-y-auto rounded-xl border border-border bg-base-secondary p-6",
            MODAL_MAX_WIDTH_VIEWPORT,
          )}
        >
          {hideCloseButton ? null : (
            <ModalCloseButton onClose={onClose} testId="add-backend-close" />
          )}
          <AddBackendAddModeBody
            hideCloseButton={hideCloseButton}
            onClose={onClose}
            source={source}
          />
        </div>
      </ModalBackdrop>
    );
  }

  // Edit mode — keep the header visible while a tall form scrolls.
  const testIdRoot = "edit-backend";
  return (
    <ModalBackdrop
      onClose={onClose}
      closeOnEscape={false}
      aria-label={t(I18nKey.BACKEND$EDIT_TITLE)}
    >
      <div
        data-testid={`${testIdRoot}-modal`}
        className={cn(
          "relative max-h-[92dvh] bg-base-secondary p-6 rounded-xl flex flex-col gap-4 border border-border",
          modalWidthClassName("md"),
          MODAL_MAX_WIDTH_VIEWPORT,
        )}
      >
        <ModalCloseButton onClose={onClose} testId={`${testIdRoot}-close`} />
        <h2 className={cn("shrink-0 pr-6", modalTitleLgClassName)}>
          {t(I18nKey.BACKEND$EDIT_TITLE)}
        </h2>
        <div className="min-h-0 overflow-y-auto">
          <BackendForm
            mode="edit"
            backend={backend}
            onSubmitted={onClose}
            testIdRoot={testIdRoot}
          />
        </div>
      </div>
    </ModalBackdrop>
  );
}

import { useTranslation } from "react-i18next";
import { Pencil, RefreshCw, Trash2 } from "lucide-react";

import { type Backend } from "#/api/backend-registry/types";
import {
  isCloudBackendLoggedOutHealthError,
  isInvalidBackendApiKeyHealthError,
  type BackendHealth,
} from "#/hooks/query/use-backends-health";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import { BackendStatusDot } from "./backend-status-dot";
