interface ManageBackendsModalProps {
  onClose: () => void;
  /**
   * Recovery mode is used by the root unavailable-backend gate. There is no
   * app shell behind the modal, so dismiss controls would be misleading.
   */
  recoveryMode?: boolean;
  /** Open straight onto the DigitalOcean Managed Agents screen. */
  initialView?: ManageBackendsView;
}

export type ManageBackendsView = "backends" | "managed-agents";

interface PendingRemoval {
  id: string;
  name: string;
  marsSessionId?: string;
}

/**
 * Resolve the connected organization label for a backend row, mirroring the
 * per-org labelling used by the backend selector. Cloud API keys are bound to
 * a single org (legacy keys may expose several, joined here); local backends
 * and unresolved/errored lookups yield no label.
 */
function resolveBackendOrgLabel(
  backend: Backend,
  cloudOrgs: ReturnType<typeof useAllCloudOrganizations>,
  currentUserIds: ReturnType<typeof useCloudCurrentUserId>,
  personalWorkspaceLabel: string,
): string | undefined {
  if (backend.kind !== "cloud") return undefined;
  const entry = cloudOrgs[backend.id];
  if (!entry || entry.orgs.length === 0) return undefined;
  const userId = currentUserIds[backend.id]?.userId ?? null;
  return entry.orgs
    .map((org) =>
      !!userId && userId === org.id ? personalWorkspaceLabel : org.name,
    )
    .join(", ");
}

export function ManageBackendsModal({
  onClose,
  recoveryMode = false,
  initialView = "backends",
}: ManageBackendsModalProps) {
  const { t } = useTranslation("openhands");
  const { backends, active, removeBackend, setActive, updateBackend } =
    useActiveBackendContext();
  const healthByBackendId = useBackendsHealth(backends, {
    probeDisabledOnce: true,
  });
  const cloudOrgs = useAllCloudOrganizations();
  const currentUserIds = useCloudCurrentUserId();
  const personalWorkspaceLabel = t(I18nKey.BACKEND$PERSONAL_WORKSPACE);
  const lockedCloudHost = getLockedCloudHost();
  const isLockedToCloud = lockedCloudHost !== null;
  // Cookie-auth (OHE-hosted) backends have no API key to refresh — re-auth is
  // the main-app login, so the device-flow reconnect controls don't apply.
  const isCookieAuthBackend = active.backend.authMode === "cookie";
  const lockedCloudBackend =
    isLockedToCloud && !isCookieAuthBackend && active.backend.kind === "cloud"
      ? active.backend
      : null;
  const lockedCloudReconnectHost =
    lockedCloudHost ?? lockedCloudBackend?.host ?? "";
  const modalTitle =
    isLockedToCloud && !isCookieAuthBackend
      ? t(I18nKey.BACKEND$RECONNECT_CLOUD_TITLE)
      : t(I18nKey.BACKEND$MANAGE_TITLE);
  const [pendingRemoval, setPendingRemoval] =
    React.useState<PendingRemoval | null>(null);
  const [editingBackend, setEditingBackend] = React.useState<Backend | null>(
    null,
  );
  const [showAddForm, setShowAddForm] = React.useState(false);
  // The tunnel lives in the Electron main process, so the browser and library
  // builds have nothing to offer here.
  const showManagedAgents = getMarsBridge() !== null && !isLockedToCloud;
  const [view, setView] = React.useState<ManageBackendsView>(
    showManagedAgents ? initialView : "backends",
  );
  const handleConfirmRemoval = () => {
    if (!pendingRemoval) return;
    removeBackend(pendingRemoval.id);
    setPendingRemoval(null);
  };

  const redirectAfterSwitch = useBackendSwitchRedirect();

  const handleSelectBackend = React.useCallback(
    (backend: Backend) => {
      if (active.backend.id !== backend.id || active.orgId !== null) {
        // @spec BM-002 — Switching backends keeps the user on the same page
        redirectAfterSwitch();
        setActive(backend.id);
      }
      onClose();
    },
    [active.backend.id, active.orgId, onClose, redirectAfterSwitch, setActive],
  );

  const handleCloudLogin = React.useCallback(
    (backend: Backend, apiKey: string) => {
      updateBackend(backend.id, { apiKey });
    },
    [updateBackend],
  );

  const handleLockedCloudReconnect = React.useCallback(
    (apiKey: string) => {
      if (!lockedCloudBackend) return;
      updateBackend(lockedCloudBackend.id, { apiKey });
    },
    [lockedCloudBackend, updateBackend],
  );

  // A removal confirmation on top owns Escape and outside clicks; closing this
  // modal under it would unmount it mid-stop and swallow a refused destroy.
  const isClosable = !recoveryMode && pendingRemoval === null;

  return (
    <>
      <ModalBackdrop
        onClose={isClosable ? onClose : undefined}
        closeOnEscape={isClosable}
        closeOnBackdropClick={isClosable}
        aria-label={modalTitle}
      >
        <div
          data-testid="manage-backends-modal"
          className={cn(
            "relative flex flex-col bg-surface border border-border rounded-xl",
            modalWidthClassName(view === "managed-agents" ? "xl" : "lg"),
            MODAL_MAX_WIDTH_VIEWPORT,
            view === "managed-agents" ? "h-[80vh]" : "max-h-[70vh]",
          )}
        >
          {recoveryMode ? null : (
            <ModalCloseButton
              onClose={onClose}
              testId="close-manage-backends-modal"
            />
          )}
          {view === "managed-agents" ? (
            <ManagedAgentsView
              onBack={() => setView("backends")}
              onDone={onClose}
            />
          ) : (
            <>
              <div className={cn("p-5", !recoveryMode && "pr-12")}>
                <h2 className={modalTitleLgClassName}>{modalTitle}</h2>
              </div>

              <div className="flex min-h-0 flex-1 flex-col px-5">
                <div
                  className="flex-1 overflow-auto rounded-md border border-border bg-surface-raised custom-scrollbar-always"
                  data-testid="manage-backends-list"
                >
                  {backends.length === 0 ? (
                    <p className="px-3 py-6 text-center text-sm text-text-secondary">
                      {t(I18nKey.BACKEND$MANAGE_EMPTY)}
                    </p>
                  ) : (
                    <ul className="divide-y divide-border">
                      {backends.map((backend) => (
                        <BackendRow
                          key={backend.id}
                          backend={backend}
                          health={healthByBackendId[backend.id]}
                          orgLabel={resolveBackendOrgLabel(
                            backend,
                            cloudOrgs,
                            currentUserIds,
                            personalWorkspaceLabel,
                          )}
                          onSelect={() => handleSelectBackend(backend)}
                          onEdit={() => setEditingBackend(backend)}
                          onRemove={() =>
                            setPendingRemoval({
                              id: backend.id,
                              name: backend.name,
                              marsSessionId: backend.marsSessionId,
                            })
                          }
                          onLogin={
                            backend.authMode === "cookie"
                              ? undefined
                              : (apiKey) => handleCloudLogin(backend, apiKey)
                          }
                        />
                      ))}
                    </ul>
                  )}
                </div>
              </div>

              <div className="flex justify-end gap-2 p-5">
                {isLockedToCloud ? (
                  lockedCloudBackend ? (
                    <DeviceFlowAuth
                      host={lockedCloudReconnectHost}
                      onSuccess={handleLockedCloudReconnect}
                      testIdRoot="manage-backends-reconnect-cloud"
                      idleButtonLabel={t(I18nKey.BACKEND$RECONNECT_CLOUD)}
                      className="w-full sm:w-auto"
                      buttonClassName="w-full sm:w-auto"
                      statusDisplay="modal"
                    />
                  ) : null
                ) : (
                  <BrandButton
                    type="button"
                    variant={recoveryMode ? "primary" : "secondary"}
                    onClick={() => setShowAddForm(true)}
                    testId="manage-backends-add"
                    startContent={<Plus width={14} height={14} />}
                  >
                    {t(I18nKey.BACKEND$ADD)}
                  </BrandButton>
                )}
                {recoveryMode ? null : (
                  <BrandButton
                    type="button"
                    variant="primary"
                    onClick={onClose}
                    testId="manage-backends-done"
                  >
                    {t(I18nKey.HOME$DONE)}
                  </BrandButton>
                )}
              </div>
            </>
          )}
        </div>
      </ModalBackdrop>

      {showAddForm ? (
        <BackendFormModal
          mode="add"
          source="manage_backends_modal"
          onClose={() => setShowAddForm(false)}
        />
      ) : null}

      {editingBackend ? (
        <BackendFormModal
          mode="edit"
          backend={editingBackend}
          onClose={() => setEditingBackend(null)}
        />
      ) : null}

      {pendingRemoval?.marsSessionId ? (
        <MarsBackendRemovalModal
          name={pendingRemoval.name}
          sessionId={pendingRemoval.marsSessionId}
          onRemove={handleConfirmRemoval}
          onCancel={() => setPendingRemoval(null)}
        />
      ) : pendingRemoval ? (
        <ConfirmationModal
          text={t(I18nKey.BACKEND$REMOVE_CONFIRMATION, {
            name: pendingRemoval.name,
          })}
          onConfirm={handleConfirmRemoval}
          onCancel={() => setPendingRemoval(null)}
        />
      ) : null}
    </>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";
import { ChevronRight, Loader2, Plus, RefreshCw } from "lucide-react";

import {
  getMarsErrorMessage,
  getSessionPhase,
  isConnectableSession,
  type MarsAgentConfig,
  type MarsSession,
  type NewMarsAgentInput,
} from "#/api/mars/mars-tunnel-backend";
import {
  getUsableConnectionId,
  useMarsAgents,
  useMarsAuthState,
  type MarsAgentGroup,
} from "#/hooks/query/use-mars-agents";
import { useLaunchMarsSession } from "#/hooks/use-launch-mars-session";
import { useMarsSignIn } from "#/hooks/use-mars-sign-in";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import { DigitalOceanNewAgentForm } from "./digitalocean-new-agent-form";
import {
  agentLabel,
  SESSION_COUNT_I18N_KEY,
  STAGE_LABEL_KEY,
} from "./managed-agents-labels";
import { ManagedAgentsSignIn } from "./managed-agents-sign-in";
import { SessionStatusDot } from "./session-status-dot";
import {
  getConnectStage,
  useSessionActivityLabel,
  useSessionMeta,
} from "./use-session-meta";

const PANEL_CLASS =
  "flex min-h-[13.5rem] w-full flex-col rounded-xl border border-border";
const ICON_BUTTON_CLASS =
  "inline-flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-md text-muted hover:bg-interactive-hover hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-300 disabled:cursor-not-allowed disabled:opacity-40";

type Launcher = ReturnType<typeof useLaunchMarsSession>;

interface SessionChildRowProps {
  session: MarsSession;
  launcher: Launcher;
  onOpen: () => void;
}

function SessionChildRow({ session, launcher, onOpen }: SessionChildRowProps) {
  const { t } = useTranslation("openhands");
  const stage = getConnectStage(launcher.connecting, session);
  const { name, phase, meta, stageLabel } = useSessionMeta(session, stage);

  return (
    <li>
      <button
        type="button"
        onClick={onOpen}
        disabled={launcher.isBusy || !isConnectableSession(session)}
        aria-label={t(I18nKey.DO_AGENTS$OPEN_AGENT, { name })}
        data-testid={`digitalocean-session-${session.session_id}`}
        className="flex w-full min-w-0 cursor-pointer items-center gap-2.5 rounded-md px-2 py-1.5 text-left hover:bg-surface-raised focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-blue-300 disabled:cursor-not-allowed disabled:opacity-60"
      >
        <SessionStatusDot phase={phase} className="size-1.5" />
        <span className="min-w-0 flex-1 truncate text-xs text-white">
          {name}
        </span>
        <span className="shrink-0 truncate text-xs tabular-nums text-muted">
          {stageLabel ?? meta}
        </span>
        {stage ? (
          <Loader2
            className="size-3.5 shrink-0 animate-spin text-muted"
            aria-hidden
          />
        ) : null}
      </button>
    </li>
  );
}

interface AgentRowProps {
  group: MarsAgentGroup;
  launcher: Launcher;
  error: string | null;
  onOpen: () => void;
  onOpenSession: (session: MarsSession) => void;
  onNewSession: () => void;
}

/** An agent with its sessions nested beneath it, collapsed by default. */
function AgentRow({
  group,
  launcher,
  error,
  onOpen,
  onOpenSession,
  onNewSession,
}: AgentRowProps) {
  const { t } = useTranslation("openhands");
  const [isExpanded, setIsExpanded] = React.useState(false);
  const { config, sessions } = group;
  const name = agentLabel(config);
  const latest = sessions[0];
  const activity = useSessionActivityLabel(latest);
  const sessionIds = new Set(sessions.map((s) => s.session_id));
  const stage =
    launcher.connecting && sessionIds.has(launcher.connecting.sessionId)
      ? launcher.connecting.stage
      : null;
  const isLaunching = launcher.launchingConfigId === config.id;
  const isWorking = isLaunching || stage !== null;
  const sessionsId = `digitalocean-agent-sessions-${config.id}`;

  let meta: string;
  if (isLaunching) meta = t(I18nKey.BACKEND$DIGITALOCEAN_CREATING_SESSION);
  else if (stage) meta = t(STAGE_LABEL_KEY[stage]);
  else if (!latest) meta = t(I18nKey.DO_AGENTS$NO_SESSIONS_SHORT);
  else {
    meta = [t(SESSION_COUNT_I18N_KEY, { count: sessions.length }), activity]
      .filter(Boolean)
      .join(" · ");
  }

  return (
    <li data-testid={`digitalocean-agent-${config.id}`}>
      <div className="flex items-center gap-1 pl-1 pr-2">
        <button
          type="button"
          onClick={() => setIsExpanded((value) => !value)}
          aria-expanded={isExpanded}
          aria-controls={sessionsId}
          aria-label={t(
            isExpanded
              ? I18nKey.DO_AGENTS$HIDE_SESSIONS
              : I18nKey.DO_AGENTS$SHOW_SESSIONS,
            { name },
          )}
          data-testid={`digitalocean-agent-toggle-${config.id}`}
          className={cn(ICON_BUTTON_CLASS, "size-6")}
        >
          <ChevronRight
            className={cn(
              "size-4 transition-transform duration-150",
              isExpanded && "rotate-90",
            )}
            aria-hidden
          />
        </button>
        <button
          type="button"
          onClick={onOpen}
          disabled={launcher.isBusy}
          aria-label={t(I18nKey.DO_AGENTS$OPEN_AGENT, { name })}
          data-testid={`digitalocean-agent-open-${config.id}`}
          className="flex min-w-0 flex-1 cursor-pointer items-center gap-3 rounded-lg px-2 py-2.5 text-left hover:bg-surface-raised focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-blue-300 disabled:cursor-not-allowed"
        >
          <span
            aria-hidden
            className="relative flex size-8 shrink-0 items-center justify-center rounded-md bg-surface-raised text-sm font-medium text-white"
          >
            {name.charAt(0).toUpperCase()}
            {latest ? (
              <SessionStatusDot
                phase={getSessionPhase(latest.status)}
                className="absolute -bottom-0.5 -right-0.5 ring-2 ring-surface"
              />
            ) : null}
          </span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="truncate text-sm text-white">{name}</span>
            <span className="truncate text-xs tabular-nums text-muted">
              {meta}
            </span>
          </span>
          {isWorking ? (
            <Loader2
              className="size-4 shrink-0 animate-spin text-muted"
              aria-hidden
            />
          ) : null}
        </button>
        <button
          type="button"
          onClick={onNewSession}
          disabled={launcher.isBusy}
          aria-label={t(I18nKey.DO_AGENTS$NEW_SESSION_FOR, { name })}
          title={t(I18nKey.DO_AGENTS$NEW_SESSION)}
          data-testid={`digitalocean-agent-new-${config.id}`}
          className={ICON_BUTTON_CLASS}
        >
          <Plus className="size-4" aria-hidden />
        </button>
      </div>
      {error ? (
        <p
          role="alert"
          data-testid={`digitalocean-agent-error-${config.id}`}
          className="mx-3 mb-2 text-pretty text-xs text-status-error"
        >
          {error}
        </p>
      ) : null}
      {isExpanded ? (
        <ul
          id={sessionsId}
          className="mb-1 ml-14 mr-2 flex flex-col border-l border-border pl-2"
        >
          {sessions.length === 0 ? (
            <li className="px-2 py-1.5 text-xs text-muted">
              {t(I18nKey.DO_AGENTS$NO_SESSIONS_SHORT)}
            </li>
          ) : (
            sessions.map((session) => (
              <SessionChildRow
                key={session.session_id}
                session={session}
                launcher={launcher}
                onOpen={() => onOpenSession(session)}
              />
            ))
          )}
        </ul>
      ) : null}
    </li>
  );
}

interface DigitalOceanConnectPanelProps {
  /** A session is open and the user is now in its conversation. */
  onConnected: () => void;
}

/**
 * The "DigitalOcean" option in the connect chooser: sign in once, then pick
 * one of the team's OpenHands agents (or create one) to open. Each agent
 * lists its sessions beneath it; opening the agent itself resumes its latest
 * session (or starts its first).
 */
export function DigitalOceanConnectPanel({
  onConnected,
}: DigitalOceanConnectPanelProps) {
  const { t } = useTranslation("openhands");
  const authQuery = useMarsAuthState();
  const authState = authQuery.data;
  const connectionId = getUsableConnectionId(authState);
  const agentsQuery = useMarsAgents(connectionId);
  const signIn = useMarsSignIn();
  const launcher = useLaunchMarsSession();
  const [failure, setFailure] = React.useState<{
    configId: string;
    message: string;
  } | null>(null);
  const [isNewAgentOpen, setIsNewAgentOpen] = React.useState(false);
  const [newAgentError, setNewAgentError] = React.useState<string | null>(null);

  const run = async (configId: string, action: () => Promise<unknown>) => {
    setFailure(null);
    try {
      await action();
      onConnected();
    } catch (error) {
      setFailure({ configId, message: launcher.describeError(error) });
    }
  };

  const createAgent = async (input: NewMarsAgentInput) => {
    setNewAgentError(null);
    let config: MarsAgentConfig;
    try {
      config = await launcher.createAgent(input);
    } catch (error) {
      setNewAgentError(launcher.describeError(error));
      return;
    }
    setIsNewAgentOpen(false);
    await run(config.id, () => launcher.launch(config));
  };

  const closeNewAgent = () => {
    setIsNewAgentOpen(false);
    setNewAgentError(null);
  };

  if (authQuery.isPending) {
    return (
      <div className={cn(PANEL_CLASS, "items-center justify-center")}>
        <Loader2 className="size-5 animate-spin text-muted" aria-hidden />
      </div>
    );
  }

  if (!connectionId) {
    return (
      <div
        data-testid="digitalocean-connect-panel"
        className={cn(PANEL_CLASS, "items-center justify-center px-5")}
      >
        <ManagedAgentsSignIn
          showBranding={false}
          canUseOAuth={authState?.canUseOAuth ?? false}
          isExpired={authState?.active?.isExpired === true}
          isSigningIn={signIn.isSigningIn}
          isSavingToken={signIn.isSavingToken}
          error={signIn.error}
          onSignInWithOAuth={signIn.signInWithOAuth}
          onSaveToken={signIn.saveToken}
        />
      </div>
    );
  }

  const groups = agentsQuery.data?.groups ?? [];
  const active = authState?.active;

  return (
    <div data-testid="digitalocean-connect-panel" className={PANEL_CLASS}>
      <div className="flex items-center gap-2 px-4 pb-2 pt-3">
        <h3 className="min-w-0 flex-1 truncate text-sm font-medium text-white">
          {t(I18nKey.DO_AGENTS$AGENTS_HEADING)}
        </h3>
        <button
          type="button"
          onClick={() =>
            isNewAgentOpen ? closeNewAgent() : setIsNewAgentOpen(true)
          }
          disabled={launcher.isBusy}
          aria-expanded={isNewAgentOpen}
          data-testid="digitalocean-new-agent"
          className={cn(
            "inline-flex h-8 shrink-0 cursor-pointer items-center gap-1.5 rounded-md px-2.5 text-xs font-medium text-muted hover:bg-interactive-hover hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-300 disabled:cursor-not-allowed disabled:opacity-40",
            isNewAgentOpen && "bg-interactive-hover text-white",
          )}
        >
          <Plus className="size-4" aria-hidden />
          {t(I18nKey.DO_AGENTS$NEW_AGENT)}
        </button>
        <button
          type="button"
          onClick={() => void agentsQuery.refetch()}
          aria-label={t(I18nKey.BACKEND$DIGITALOCEAN_AGENTS_REFRESH)}
          title={t(I18nKey.BACKEND$DIGITALOCEAN_AGENTS_REFRESH)}
          data-testid="digitalocean-agents-refresh"
          className={ICON_BUTTON_CLASS}
        >
          <RefreshCw
            className={cn("size-4", agentsQuery.isFetching && "animate-spin")}
            aria-hidden
          />
        </button>
      </div>

      {isNewAgentOpen ? (
        <DigitalOceanNewAgentForm
          isCreating={launcher.isCreatingAgent}
          error={newAgentError}
          onSubmit={(input) => void createAgent(input)}
          onCancel={closeNewAgent}
        />
      ) : null}

      <div className="max-h-72 min-h-0 flex-1 overflow-y-auto px-1 custom-scrollbar-always">
        {agentsQuery.isPending ? (
          <p className="px-3 py-6 text-center text-sm text-muted">
            {t(I18nKey.BACKEND$DIGITALOCEAN_AGENTS_LOADING)}
          </p>
        ) : null}
        {agentsQuery.error ? (
          <p
            role="alert"
            className="mx-3 my-2 text-pretty text-sm text-status-error"
          >
            {getMarsErrorMessage(agentsQuery.error) ??
              t(I18nKey.BACKEND$DIGITALOCEAN_AGENTS_FAILED)}
          </p>
        ) : null}
        {agentsQuery.data && groups.length === 0 && !isNewAgentOpen ? (
          <p
            data-testid="digitalocean-agents-empty"
            className="mx-auto max-w-sm px-3 py-6 text-center text-pretty text-sm text-muted"
          >
            {t(I18nKey.DO_AGENTS$NO_OPENHANDS_AGENTS)}
          </p>
        ) : null}
        {groups.length > 0 ? (
          <ul className="flex flex-col">
            {groups.map((group) => (
              <AgentRow
                key={group.config.id}
                group={group}
                launcher={launcher}
                error={
                  failure?.configId === group.config.id ? failure.message : null
                }
                onOpen={() =>
                  void run(group.config.id, () => launcher.openAgent(group))
                }
                onOpenSession={(session) =>
                  void run(group.config.id, () =>
                    launcher.open(session, group.config),
                  )
                }
                onNewSession={() =>
                  void run(group.config.id, () => launcher.launch(group.config))
                }
              />
            ))}
          </ul>
        ) : null}
      </div>

      <div className="mt-2 flex items-center gap-3 border-t border-border px-4 py-2.5 text-xs">
        <span
          aria-hidden
          className="size-1.5 shrink-0 rounded-full bg-status-success"
        />
        <span
          data-testid="digitalocean-account"
          className="min-w-0 flex-1 truncate text-muted"
        >
          {active?.teamName ?? active?.label}
        </span>
        <button
          type="button"
          onClick={signIn.signOut}
          disabled={signIn.isSigningOut}
          data-testid="digitalocean-sign-out"
          className="shrink-0 cursor-pointer text-muted hover:text-white disabled:cursor-not-allowed"
        >
          {t(I18nKey.BACKEND$DIGITALOCEAN_SIGN_OUT)}
        </button>
      </div>
    </div>
  );
}

import { useTranslation } from "react-i18next";
import { Loader2, Pause, Square, Unplug } from "lucide-react";

import {
  isConnectableSession,
  type MarsSession,
} from "#/api/mars/mars-tunnel-backend";
import { BrandButton } from "#/components/features/settings/brand-button";
import type { MarsConnectStage } from "#/hooks/use-connect-mars-session";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import { shortSessionId } from "./managed-agents-labels";
import { SessionStatusDot } from "./session-status-dot";
import { useSessionMeta } from "./use-session-meta";

const ICON_BUTTON_CLASS =
  "inline-flex size-8 cursor-pointer items-center justify-center rounded-md text-muted transition-colors hover:bg-interactive-hover hover:text-white disabled:cursor-not-allowed disabled:opacity-40";

interface ManagedAgentsSessionRowProps {
  session: MarsSession;
  isConnected: boolean;
  /** Set while this row's connect flow is running. */
  connectStage: MarsConnectStage | null;
  /** Another row is connecting or this row has a pause or stop in flight. */
  isBusy: boolean;
  error: string | null;
  onConnect: () => void;
  onOpen: () => void;
  onDisconnect: () => void;
  onPause: () => void;
  /** Ends the session for good; the parent confirms before calling. */
  onStop: () => void;
}

export function ManagedAgentsSessionRow({
  session,
  isConnected,
  connectStage,
  isBusy,
  error,
  onConnect,
  onOpen,
  onDisconnect,
  onPause,
  onStop,
}: ManagedAgentsSessionRowProps) {
  const { t } = useTranslation("openhands");
  const { name, phase, meta, stageLabel } = useSessionMeta(
    session,
    connectStage,
  );
  const isConnecting = connectStage !== null;
  const canConnect = isConnectableSession(session);
  // Anything not already over can be stopped, including a failed or stuck
  // provisioning session whose sandbox still needs tearing down.
  const canStop = phase !== "ended";
  const stopButton = canStop ? (
    <button
      type="button"
      onClick={onStop}
      disabled={isBusy}
      aria-label={t(I18nKey.DO_AGENTS$STOP)}
      title={t(I18nKey.DO_AGENTS$STOP)}
      data-testid={`managed-agents-stop-${session.session_id}`}
      className={ICON_BUTTON_CLASS}
    >
      <Square className="size-4" aria-hidden />
    </button>
  ) : null;

  return (
    <li
      data-testid={`managed-agents-session-${session.session_id}`}
      className={cn(
        "flex flex-col gap-1 border-l-2 px-3 py-2.5",
        isConnected ? "border-l-primary" : "border-l-transparent",
      )}
    >
      <div className="flex items-center gap-3">
        <SessionStatusDot phase={phase} />
        <div className="flex min-w-0 flex-1 flex-col">
          <span className="truncate text-sm text-white" title={name}>
            {name}
          </span>
          <span
            className="truncate text-xs text-muted"
            data-testid={`managed-agents-session-status-${session.session_id}`}
          >
            {meta}
            <span className="ml-2 font-mono text-[11px] text-text-tertiary">
              {shortSessionId(session)}
            </span>
          </span>
        </div>

        <div className="flex shrink-0 items-center gap-1.5">
          {isConnecting ? (
            <span
              role="status"
              aria-live="polite"
              data-testid={`managed-agents-connecting-${session.session_id}`}
              className="flex items-center gap-2 text-xs text-muted"
            >
              <Loader2 className="size-4 animate-spin" aria-hidden />
              {stageLabel}
            </span>
          ) : null}

          {!isConnecting && isConnected ? (
            <>
              <span className="rounded-full border border-primary/40 px-2 py-0.5 text-[11px] uppercase tracking-wide text-primary">
                {t(I18nKey.DO_AGENTS$CONNECTED)}
              </span>
              <button
                type="button"
                onClick={onDisconnect}
                disabled={isBusy}
                aria-label={t(I18nKey.BUTTON$DISCONNECT)}
                title={t(I18nKey.BUTTON$DISCONNECT)}
                data-testid={`managed-agents-disconnect-${session.session_id}`}
                className={ICON_BUTTON_CLASS}
              >
                <Unplug className="size-4" aria-hidden />
              </button>
              {stopButton}
              <BrandButton
                type="button"
                variant="secondary"
                onClick={onOpen}
                testId={`managed-agents-open-${session.session_id}`}
                className="h-8"
              >
                {t(I18nKey.DO_AGENTS$OPEN)}
              </BrandButton>
            </>
          ) : null}

          {!isConnecting && !isConnected && canConnect ? (
            <>
              {phase === "ready" ? (
                <button
                  type="button"
                  onClick={onPause}
                  disabled={isBusy}
                  aria-label={t(I18nKey.DO_AGENTS$PAUSE)}
                  title={t(I18nKey.DO_AGENTS$PAUSE)}
                  data-testid={`managed-agents-pause-${session.session_id}`}
                  className={ICON_BUTTON_CLASS}
                >
                  <Pause className="size-4" aria-hidden />
                </button>
              ) : null}
              {stopButton}
              <BrandButton
                type="button"
                variant="primary"
                onClick={onConnect}
                isDisabled={isBusy}
                testId={`managed-agents-connect-${session.session_id}`}
                className="h-8"
              >
                {phase === "paused"
                  ? t(I18nKey.DO_AGENTS$RESUME_AND_CONNECT)
                  : t(I18nKey.BACKEND$CONNECT)}
              </BrandButton>
            </>
          ) : null}

          {/* The main action (Open / Connect) is always rightmost, with Stop
              just left of it (rendered above), so the destructive action is
              never mistaken for part of it. */}
          {!isConnecting && !isConnected && !canConnect ? stopButton : null}
        </div>
      </div>

      {error ? (
        <p
          role="alert"
          data-testid={`managed-agents-session-error-${session.session_id}`}
          className="pl-5 text-xs text-status-error whitespace-pre-wrap break-words"
        >
          {error}
        </p>
      ) : null}
    </li>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";
import { BrandButton } from "#/components/features/settings/brand-button";
import { SettingsInput } from "#/components/features/settings/settings-input";
import { ModalBackdrop } from "#/components/shared/modals/modal-backdrop";
import { ModalCloseButton } from "#/components/shared/modals/modal-close-button";
