import {
  ContextWindowRing,
  CONTEXT_WINDOW_TRACK_COLOR,
} from "./context-window-ring";

const TONE_BAR_CLASS = {
  neutral: "bg-foreground",
  warning: "bg-amber-500",
  danger: "bg-red-500",
} as const;

const TONE_LABEL_CLASS = {
  neutral: "text-muted",
  warning: "text-amber-500",
  danger: "text-red-500",
} as const;

export function ContextWindowMeter() {
  const { t } = useTranslation("openhands");
  const usage = useContextWindowUsage();
  const { navigateToTab } = useSelectConversationTab();
  const [isPopoverOpen, setIsPopoverOpen] = React.useState(false);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const popoverRef = useClickOutsideElement<HTMLDivElement>(
    () => setIsPopoverOpen(false),
    triggerRef,
  );
  useCloseOnEscape(isPopoverOpen, () => setIsPopoverOpen(false), triggerRef);
  const { handleCompact, isCompacting, isDisabled } = useCompactContextAction(
    usage?.perTurnToken ?? 0,
  );

  if (!usage) {
    return null;
  }

  const usagePercentage = getContextWindowUsagePercentage(
    usage.perTurnToken,
    usage.contextWindow,
  );
  const roundedPercentage = Math.round(usagePercentage);
  const remainingPercentage = Math.max(0, 100 - roundedPercentage);
  const usagePercentLabel = `${roundedPercentage}% ${t(I18nKey.CONVERSATION$USED)} (${remainingPercentage}% ${t(I18nKey.CONVERSATION$LEFT)})`;
  const usageTokenSummary = `${formatCompactTokenCount(usage.perTurnToken)} / ${formatCompactTokenCount(usage.contextWindow)}`;
  const tone = getContextFillTone(usagePercentage);

  const openUsagePanel = () => {
    setIsPopoverOpen(false);
    navigateToTab("usage");
  };

  return (
    <div className="relative shrink-0">
      <StyledTooltip
        content={t(I18nKey.CHAT_INTERFACE$SHOW_CONTEXT)}
        placement="top"
        // While the popover is open the hint is redundant, and an open
        // tooltip would swallow the Escape meant for the popover.
        isDisabled={isPopoverOpen}
      >
        <button
          ref={triggerRef}
          type="button"
          className={cn(chatInputIconButtonClassName, "size-8")}
          aria-label={`${t(I18nKey.CHAT_INTERFACE$CONTEXT_WINDOW_METER_LABEL)}: ${usagePercentLabel}`}
          aria-expanded={isPopoverOpen}
          aria-haspopup="dialog"
          data-testid="context-window-meter"
          onClick={(event) => {
            event.preventDefault();
            event.stopPropagation();
            setIsPopoverOpen((open) => !open);
          }}
        >
          <ContextWindowRing percentage={usagePercentage} />
        </button>
      </StyledTooltip>

      {isPopoverOpen && (
        <div
          ref={popoverRef}
          data-testid="context-window-meter-popover"
          className={cn(
            "absolute bottom-full right-0 z-[60] mb-2 w-70",
            "flex flex-col gap-0.5 rounded-md border border-border-subtle bg-tertiary px-1 py-1 shadow-lg",
          )}
        >
          <div className="flex flex-col gap-2 px-2 py-1.5">
            <div className="flex items-center justify-between gap-2 text-sm">
              <span className="font-semibold text-foreground">
                {t(I18nKey.CONVERSATION$CONTEXT_WINDOW)}
              </span>
              <span className={cn("shrink-0 text-xs", TONE_LABEL_CLASS[tone])}>
                {usagePercentLabel}
              </span>
            </div>

            <button
              type="button"
              data-testid="context-window-meter-bar-button"
              className="relative h-1.5 w-full rounded-full cursor-pointer"
              style={{ backgroundColor: CONTEXT_WINDOW_TRACK_COLOR }}
              aria-label={t(I18nKey.COMMON$USAGE)}
              onClick={(event) => {
                event.preventDefault();
                event.stopPropagation();
                openUsagePanel();
              }}
            >
              <span
                className={cn(
                  "absolute inset-y-0 left-0 rounded-full transition-all duration-300",
                  TONE_BAR_CLASS[tone],
                )}
                style={{ width: `${Math.min(100, usagePercentage)}%` }}
              />
            </button>

            <div className="flex items-center justify-between gap-2">
              <button
                type="button"
                data-testid="context-window-compact-button"
                disabled={isDisabled}
                aria-busy={isCompacting}
                aria-label={t(I18nKey.CONVERSATION$COMPACT_CONTEXT)}
                className={cn(
                  "inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-xs",
                  "text-muted hover:bg-interactive-hover hover:text-foreground",
                  "transition-colors disabled:cursor-not-allowed disabled:opacity-50",
                )}
                onClick={(event) => {
                  event.preventDefault();
                  event.stopPropagation();
                  handleCompact();
                }}
              >
                {isCompacting ? (
                  <Loader2 className="size-3 animate-spin" aria-hidden />
                ) : (
                  <Minimize className="size-3" aria-hidden />
                )}
                <span>{t(I18nKey.CONVERSATION$COMPACT_CONTEXT)}</span>
              </button>
              <span className="text-xs text-muted">{usageTokenSummary}</span>
            </div>
          </div>

          <Divider inset="menu" />

          <ContextMenuListItem
            testId="context-window-plan-usage"
            onClick={(event) => {
              event.preventDefault();
              event.stopPropagation();
              openUsagePanel();
            }}
          >
            <ConversationNameContextMenuIconText
              icon={<Gauge size={16} />}
              text={t(I18nKey.COMMON$USAGE)}
            />
          </ContextMenuListItem>
        </div>
      )}
    </div>
  );
}

import { cn } from "#/utils/utils";
import { getContextFillTone } from "#/components/features/conversation/usage-panel/context-meter";

const CONTEXT_WINDOW_RING_SIZE = 16;
const CONTEXT_WINDOW_RING_STROKE = 2;

/**
 * Default opacity of the ring's unfilled track on dark themes.
 *
 * The track is derived from the foreground rather than pinned to a scale stop.
 * It carries information (the arc's proportion is only readable against it), so
 * it is a foreground element, and every stop in the surface family sits close
 * to the surfaces it delimits. Drawing it with `--oh-border` put it in that
 * family: it was 1.57:1 against the composer at rest, and the trigger's hover
 * fill resolves to the same stop, taking it to 1.00:1. No stop in that family
 * fixes it, and no fixed stop holds across the three palettes in
 * `color-themes.ts`, whose scales differ.
 *
 * Light palettes override the foreground and weight tokens because a single
 * translucent mix cannot preserve 3:1 contrast on both dark and light
 * surfaces. `context-window-ring.test.tsx` asserts the effective values for
 * every shipped theme.
 */
/** Shared by the ring's track and the popover's usage bar, which had the same defect. */
export const CONTEXT_WINDOW_TRACK_COLOR =
  "color-mix(in srgb, var(--oh-context-window-foreground) var(--oh-context-window-track-weight), transparent)";

const TONE_STROKE = {
  neutral: "var(--oh-context-window-foreground)",
  warning: "#f59e0b", // amber-500
  danger: "#ef4444", // red-500
} as const;

interface ContextWindowRingProps {
  percentage: number;
  className?: string;
}

export function ContextWindowRing({
  percentage,
  className,
}: ContextWindowRingProps) {
  const radius = (CONTEXT_WINDOW_RING_SIZE - CONTEXT_WINDOW_RING_STROKE) / 2;
  const circumference = 2 * Math.PI * radius;
  const clampedPercentage = Math.min(100, Math.max(0, percentage));
  const dashOffset = circumference - (clampedPercentage / 100) * circumference;
  const tone = getContextFillTone(clampedPercentage);

  return (
    <svg
      width={CONTEXT_WINDOW_RING_SIZE}
      height={CONTEXT_WINDOW_RING_SIZE}
      viewBox={`0 0 ${CONTEXT_WINDOW_RING_SIZE} ${CONTEXT_WINDOW_RING_SIZE}`}
      className={cn("shrink-0", className)}
      aria-hidden
    >
      <circle
        cx={CONTEXT_WINDOW_RING_SIZE / 2}
        cy={CONTEXT_WINDOW_RING_SIZE / 2}
        r={radius}
        fill="none"
        style={{ stroke: CONTEXT_WINDOW_TRACK_COLOR }}
        strokeWidth={CONTEXT_WINDOW_RING_STROKE}
        data-testid="context-window-ring-track"
      />
      <circle
        cx={CONTEXT_WINDOW_RING_SIZE / 2}
        cy={CONTEXT_WINDOW_RING_SIZE / 2}
        r={radius}
        fill="none"
        stroke={TONE_STROKE[tone]}
        strokeWidth={CONTEXT_WINDOW_RING_STROKE}
        strokeLinecap="round"
        strokeDasharray={circumference}
        strokeDashoffset={dashOffset}
        transform={`rotate(-90 ${CONTEXT_WINDOW_RING_SIZE / 2} ${CONTEXT_WINDOW_RING_SIZE / 2})`}
        className="transition-[stroke-dashoffset,stroke] duration-300"
        data-testid="context-window-ring-arc"
      />
    </svg>
  );
}

