/**
 * Repository search + launch flow for cloud backends.
 * Shared by the sidebar "+ New conversation" control and the conversation
 * panel "new thread folder" opener.
 */
export function CloudNewConversationMenu({
  trigger,
  className,
  popoverClassName,
  popoverTestId = "new-conversation-popover",
  useFixedPlacement = false,
}: CloudNewConversationMenuProps) {
  const { t } = useTranslation("openhands");
  const { navigate } = useNavigation();

  const { providers } = useUserProviders();
  const { lastSelectedProvider, setLastSelectedProvider } = useHomeStore();

  const [open, setOpen] = React.useState(false);
  const popoverRef = React.useRef<HTMLDivElement>(null);
  const triggerWrapRef = React.useRef<HTMLSpanElement>(null);
  const fixedBox = usePopoverFixedPlacement(triggerWrapRef, {
    open,
    enabled: useFixedPlacement,
  });
  const [selectedProvider, setSelectedProvider] =
    React.useState<Provider | null>(lastSelectedProvider ?? null);
  const [query, setQuery] = React.useState("");
  const debouncedQuery = useDebounce(query, 300);

  React.useEffect(() => {
    if (providers.length === 0) {
      if (selectedProvider !== null) setSelectedProvider(null);
      return;
    }
    if (selectedProvider && providers.includes(selectedProvider)) return;
    const fallback =
      lastSelectedProvider && providers.includes(lastSelectedProvider)
        ? lastSelectedProvider
        : providers[0];
    setSelectedProvider(fallback);
  }, [providers, selectedProvider, lastSelectedProvider]);

  const repositoryQueriesEnabled = open && !!selectedProvider;
  const {
    data: repoPages,
    isLoading,
    isError,
    hasNextPage,
    isFetchingNextPage,
    fetchNextPage,
  } = useGitRepositories({
    provider: selectedProvider,
    enabled: repositoryQueriesEnabled,
  });

  const { data: searchResults, isLoading: isSearchLoading } =
    useSearchRepositories(
      debouncedQuery,
      selectedProvider,
      !repositoryQueriesEnabled,
    );

  const allRepositories = React.useMemo(
    () => repoPages?.pages.flatMap((page) => page.items) ?? [],
    [repoPages],
  );

  const repositories = debouncedQuery ? (searchResults ?? []) : allRepositories;

  const { mutate: createConversation, isPending } = useCreateConversation();
  const isCreatingElsewhere = useIsCreatingConversation();
  const isCreating = isPending || isCreatingElsewhere;

  React.useEffect(() => {
    if (!open) return undefined;
    const onDown = (e: MouseEvent) => {
      if (
        popoverRef.current &&
        !popoverRef.current.contains(e.target as Node)
      ) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", onDown);
    return () => document.removeEventListener("mousedown", onDown);
  }, [open]);

  React.useEffect(() => {
    if (!open) return undefined;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [open]);

  const launchRepository = (repo: GitRepository) => {
    if (isCreating) return;
    createConversation(
      {
        repository: {
          name: repo.full_name,
          gitProvider: repo.git_provider,
          branch: repo.main_branch ?? "main",
        },
        entryPoint: "sidebar_cloud_menu",
      },
      {
        onSuccess: (data) => {
          setOpen(false);
          navigate(`/conversations/${data.conversation_id}`);
        },
      },
    );
  };

  const handleProviderChange = (provider: Provider) => {
    setSelectedProvider(provider);
    setLastSelectedProvider(provider);
    setQuery("");
  };

  const itemClass = dropdownMenuRowClassName;

  React.useEffect(() => {
    if (!open) return;
    if (debouncedQuery) return;
    if (!hasNextPage || isFetchingNextPage || isLoading) return;
    if (repositories.length === 0 || repositories.length >= 10) return;
    fetchNextPage();
  }, [
    open,
    debouncedQuery,
    hasNextPage,
    isFetchingNextPage,
    isLoading,
    repositories.length,
    fetchNextPage,
  ]);

  const isListLoading = debouncedQuery ? isSearchLoading : isLoading;
  const showLoadMore =
    !debouncedQuery && hasNextPage && repositories.length > 0;

  const toggleOpen = React.useCallback(() => {
    setOpen((o) => !o);
  }, []);

  const showPopover = open && (!useFixedPlacement || fixedBox !== null);

  const fixedStyle: React.CSSProperties | undefined =
    useFixedPlacement && fixedBox
      ? {
          position: "fixed",
          top: fixedBox.top,
          left: fixedBox.left,
          width: fixedBox.width,
        }
      : undefined;

  return (
    <div
      className={cn(!useFixedPlacement && "relative", className)}
      ref={popoverRef}
    >
      <span ref={triggerWrapRef} className="inline-flex">
        {trigger({
          onClick: toggleOpen,
          "aria-expanded": open,
          "aria-haspopup": "menu",
          disabled: isCreating,
        })}
      </span>

      {showPopover && (
        <div
          data-testid={popoverTestId}
          className={cn(
            NEW_CONVERSATION_DROPDOWN_SURFACE,
            !useFixedPlacement &&
              cn("absolute top-full mt-0", popoverClassName),
          )}
          style={fixedStyle}
        >
          {providers.length > 1 && (
            <div
              className="flex items-center gap-1 px-1 py-1"
              data-testid="cloud-provider-tabs"
            >
              {providers.map((provider) => {
                const isActive = provider === selectedProvider;
                return (
                  <button
                    key={provider}
                    type="button"
                    data-testid={`cloud-provider-tab-${provider}`}
                    onClick={() => handleProviderChange(provider)}
                    className={cn(
                      "flex items-center gap-1 rounded border px-2 py-1 text-xs",
                      dropdownInstantColorClassName,
                      isActive
                        ? "border-border-subtle bg-interactive-hover text-contrast"
                        : "border-transparent text-text-secondary hover:text-contrast",
                    )}
                  >
                    <GitProviderIcon gitProvider={provider} />
                    <span className="capitalize">{provider}</span>
                  </button>
                );
              })}
            </div>
          )}

          <div className="px-2">
            <div className="relative">
              <SearchIcon
                width={16}
                height={16}
                aria-hidden
                className="pointer-events-none absolute left-0 top-1/2 -translate-y-1/2 text-muted"
              />
              <input
                type="text"
                data-testid="cloud-repo-search-input"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder={t(I18nKey.COMMON$SEARCH_REPOSITORIES)}
                disabled={!selectedProvider}
                className={cn(
                  "w-full border-0 bg-transparent py-1.5 pl-6 pr-0 text-sm text-contrast",
                  "outline-none placeholder:text-muted",
                  "focus:outline-none focus:ring-0",
                  "disabled:cursor-not-allowed disabled:opacity-60",
                )}
              />
            </div>
          </div>

          <Divider inset="menu" />

          <ul
            className={cn(
              "max-h-[40vh] overflow-y-auto custom-scrollbar-always sm:max-h-70",
              dropdownMenuListClassName,
            )}
          >
            {isListLoading && repositories.length === 0 && (
              <li
                className="px-2 py-2 text-sm text-muted italic"
                data-testid="cloud-repo-loading"
              >
                {t(I18nKey.HOME$LOADING_REPOSITORIES)}
              </li>
            )}
            {isError && (
              <li
                className="px-2 py-2 text-sm text-[#F87171]"
                data-testid="cloud-repo-error"
              >
                {t(I18nKey.HOME$FAILED_TO_LOAD_REPOSITORIES)}
              </li>
            )}
            {!isListLoading &&
              !isError &&
              repositories.length === 0 &&
              !!selectedProvider && (
                <li
                  className="px-2 py-2 text-sm text-muted italic"
                  data-testid="cloud-repo-empty"
                >
                  {t(I18nKey.GITHUB$NO_RESULTS)}
                </li>
              )}
            {repositories.map((repo) => (
              <RepoListItem
                key={`${repo.git_provider}:${repo.id}`}
                repo={repo}
                disabled={isCreating}
                onSelect={launchRepository}
                itemClass={itemClass}
              />
            ))}
            {showLoadMore && (
              <li>
                <button
                  type="button"
                  data-testid="cloud-repo-load-more"
                  disabled={isFetchingNextPage}
                  onClick={() => fetchNextPage()}
                  className={itemClass}
                >
                  <span className="text-text-secondary">
                    {isFetchingNextPage
                      ? t(I18nKey.HOME$LOADING_MORE_REPOSITORIES)
                      : t(I18nKey.CONVERSATION$LOAD_MORE)}
                  </span>
                </button>
              </li>
            )}
          </ul>
        </div>
      )}
    </div>
  );
}

import { Tag, Workflow, X } from "lucide-react";
import { useTranslation } from "react-i18next";
import { I18nKey } from "#/i18n/declaration";
import {
  formatTagFacetLabel,
  UNNAMED_AUTOMATION_FACET,
} from "./conversation-panel-list-helpers";

interface ConversationActiveTagFiltersProps {
  selectedFacets: readonly string[];
  onToggleFacet: (facet: string) => void;
  /** Automation names narrowing the list in `only-automations` mode. */
  selectedAutomationNames: readonly string[];
  onToggleAutomationName: (name: string) => void;
  onClearAll: () => void;
}

/**
 * Always-visible record of which facet selections are narrowing the list —
 * both families: user tags and automation names.
 *
 * The facet rows live two levels inside a menu (tag facets behind a toggle in
 * the layouts menu, automation names inside the advanced-options modal).
 * Without this strip a filter left switched on just makes conversations
 * disappear, with nothing on screen to say why or how to get them back — and
 * both selections are persisted, so a reload brings the narrowing back with
 * the explanation still buried.
 *
 * The automation *mode* deliberately has no chip here: it is a scope, not a
 * facet selection, and `onClearAll` leaves it alone for the same reason —
 * this strip must not silently switch a surface it doesn't show.
 *
 * Renders nothing when nothing is selected — an empty bar would cost a row
 * of a narrow sidebar to say "no news".
 */
export function ConversationActiveTagFilters({
  selectedFacets,
  onToggleFacet,
  selectedAutomationNames,
  onToggleAutomationName,
  onClearAll,
}: ConversationActiveTagFiltersProps) {
  const { t } = useTranslation("openhands");

  if (selectedFacets.length === 0 && selectedAutomationNames.length === 0) {
    return null;
  }

  const chipClassName =
    "flex min-w-0 max-w-full cursor-pointer items-center gap-1 rounded-full bg-surface px-2 py-0.5 text-[10px] leading-4 text-contrast hover:bg-contrast/10";

  return (
    <div
      data-testid="conversation-active-tag-filters"
      className="flex min-w-0 items-start gap-1.5 border-b border-border px-4 py-1.5"
    >
      <Tag className="mt-1 h-3 w-3 shrink-0 text-muted" aria-hidden />

      <div className="flex min-w-0 flex-1 flex-wrap items-center gap-1">
        {selectedFacets.map((facet) => (
          <button
            key={facet}
            type="button"
            data-testid={`active-tag-filter-${facet}`}
            onClick={() => onToggleFacet(facet)}
            className={chipClassName}
          >
            <span className="truncate">{formatTagFacetLabel(facet, t)}</span>
            <X className="h-3 w-3 shrink-0" aria-hidden />
          </button>
        ))}

        {selectedAutomationNames.map((name) => (
          <button
            key={name}
            type="button"
            data-testid={`active-automation-filter-${name}`}
            onClick={() => onToggleAutomationName(name)}
            className={chipClassName}
          >
            <Workflow className="h-3 w-3 shrink-0" aria-hidden />
            <span className="truncate">
              {name === UNNAMED_AUTOMATION_FACET
                ? t(I18nKey.CONVERSATION_PANEL$AUTOMATION_UNNAMED)
                : name}
            </span>
            <X className="h-3 w-3 shrink-0" aria-hidden />
          </button>
        ))}
      </div>

      <button
        type="button"
        data-testid="clear-tag-filters"
        onClick={onClearAll}
        className="shrink-0 cursor-pointer text-[10px] leading-5 text-muted hover:text-contrast"
      >
        {t(I18nKey.CONVERSATION_PANEL$CLEAR_FILTERS)}
      </button>
    </div>
  );
}

