import React, { useCallback } from "react";
import { useTranslation } from "react-i18next";
import { useActiveBackend } from "#/contexts/active-backend-context";
import { useClickOutsideElement } from "#/hooks/use-click-outside-element";
import { ContextMenu } from "#/ui/context-menu";
import { ContextMenuListItem } from "../../context-menu/context-menu-list-item";
import { I18nKey } from "#/i18n/declaration";
import { ConversationNameContextMenuIconText } from "../../conversation/conversation-name-context-menu-icon-text";

import { Archive, ArchiveRestore, Gauge, Tags } from "lucide-react";
import EditIcon from "#/icons/u-edit.svg?react";
import SkillsIcon from "#/icons/skills.svg?react";
import ToolsIcon from "#/icons/u-tools.svg?react";
import DownloadIcon from "#/icons/u-download.svg?react";
import CloseIcon from "#/icons/u-close.svg?react";
import DeleteIcon from "#/icons/u-delete.svg?react";
import { Divider } from "#/ui/divider";

interface ConversationCardContextMenuProps {
  onClose: () => void;
  onDelete?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onArchive?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onUnarchive?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onStop?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onEdit?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onEditTags?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onDisplayCost?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onShowAgentTools?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onShowSkills?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onDownloadViaVSCode?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onDownloadConversation?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  position?: "top" | "bottom";
  /**
   * Fixed coordinates for a portaled menu (conversation list overflow
   * stacking). When set, theme/position switch to non-absolute layout.
   */
  floatingStyle?: React.CSSProperties;
  ignoreOutsideClickRef?: React.RefObject<HTMLElement | null>;
}

export function ConversationCardContextMenu({
  onClose,
  onDelete,
  onArchive,
  onUnarchive,
  onStop,
  onEdit,
  onEditTags,
  onDisplayCost,
  onShowAgentTools,
  onShowSkills,
  onDownloadViaVSCode,
  onDownloadConversation,
  position = "bottom",
  floatingStyle,
  ignoreOutsideClickRef,
}: ConversationCardContextMenuProps) {
  const { t } = useTranslation("openhands");
  const { backend } = useActiveBackend();
  const ref = useClickOutsideElement<HTMLUListElement>(
    onClose,
    ignoreOutsideClickRef,
  );
  const stopLabelKey =
    backend.kind === "cloud"
      ? I18nKey.COMMON$CLOSE_CONVERSATION_STOP_RUNTIME
      : I18nKey.COMMON$STOP_CONVERSATION;

  const generateSection = useCallback(
    (items: React.ReactNode[], sectionKey: string, isLast?: boolean) => {
      const filteredItems = items.filter((i) => i != null);

      if (filteredItems.length > 0) {
        return !isLast ? (
          <React.Fragment key={sectionKey}>
            {filteredItems}
            <Divider inset="menu" />
          </React.Fragment>
        ) : (
          <React.Fragment key={sectionKey}>{filteredItems}</React.Fragment>
        );
      }
      return null;
    },
    [],
  );

  const isPortaled = floatingStyle != null;

  return (
    <ContextMenu
      ref={ref}
      testId="context-menu"
      style={isPortaled ? floatingStyle : undefined}
      theme={isPortaled ? "popover" : "default"}
      position={isPortaled ? "none" : position}
      alignment={isPortaled ? "none" : "right"}
      spacing={isPortaled ? "none" : "default"}
      className={
        isPortaled
          ? "mt-0 min-w-50 w-max max-w-[min(280px,100vw-16px)]"
          : "z-[200] mt-0"
      }
    >
      {generateSection(
        [
          onEdit && (
            <ContextMenuListItem
              key="edit-button"
              testId="edit-button"
              onClick={onEdit}
            >
              <ConversationNameContextMenuIconText
                icon={<EditIcon width={16} height={16} />}
                text={t(I18nKey.BUTTON$RENAME)}
              />
            </ContextMenuListItem>
          ),
          onEditTags && (
            <ContextMenuListItem
              key="edit-tags-button"
              testId="edit-tags-button"
              onClick={onEditTags}
            >
              <ConversationNameContextMenuIconText
                icon={<Tags className="h-4 w-4" aria-hidden />}
                text={t(I18nKey.CONVERSATION$EDIT_TAGS)}
              />
            </ContextMenuListItem>
          ),
        ],
        // eslint-disable-next-line i18next/no-literal-string -- internal section id, not user-facing
        "edit-section",
      )}
      {generateSection(
        [
          onShowAgentTools && (
            <ContextMenuListItem
              key="show-agent-tools-button"
              testId="show-agent-tools-button"
              onClick={onShowAgentTools}
            >
              <ConversationNameContextMenuIconText
                icon={<ToolsIcon width={16} height={16} />}
                text={t(I18nKey.BUTTON$SHOW_AGENT_TOOLS_AND_METADATA)}
              />
            </ContextMenuListItem>
          ),
          onShowSkills && (
            <ContextMenuListItem
              key="show-skills-button"
              testId="show-skills-button"
              onClick={onShowSkills}
            >
              <ConversationNameContextMenuIconText
                icon={
                  <SkillsIcon
                    width={16}
                    height={16}
                    className="stroke-[1.75]"
                    aria-hidden
                  />
                }
                text={t(I18nKey.CONVERSATION$SHOW_SKILLS)}
              />
            </ContextMenuListItem>
          ),
        ],
        // eslint-disable-next-line i18next/no-literal-string -- internal section id, not user-facing
        "tools-section",
      )}
      {generateSection(
        [
          onStop && (
            <ContextMenuListItem
              key="stop-button"
              testId="stop-button"
              onClick={onStop}
            >
              <ConversationNameContextMenuIconText
                icon={<CloseIcon width={16} height={16} />}
                text={t(stopLabelKey)}
              />
            </ContextMenuListItem>
          ),
          onDownloadViaVSCode && (
            <ContextMenuListItem
              key="download-vscode-button"
              testId="download-vscode-button"
              onClick={onDownloadViaVSCode}
            >
              <ConversationNameContextMenuIconText
                icon={<DownloadIcon width={16} height={16} />}
                text={t(I18nKey.BUTTON$DOWNLOAD_VIA_VSCODE)}
              />
            </ContextMenuListItem>
          ),
          onDownloadConversation && (
            <ContextMenuListItem
              key="download-trajectory-button"
              testId="download-trajectory-button"
              onClick={onDownloadConversation}
            >
              <ConversationNameContextMenuIconText
                icon={<DownloadIcon width={16} height={16} />}
                text={t(I18nKey.BUTTON$DOWNLOAD_CONVERSATION_DATA)}
              />
            </ContextMenuListItem>
          ),
        ],
        // eslint-disable-next-line i18next/no-literal-string -- internal section id, not user-facing
        "control-section",
      )}
      {generateSection(
        [
          onDisplayCost && (
            <ContextMenuListItem
              key="display-cost-button"
              testId="display-cost-button"
              onClick={onDisplayCost}
            >
              <ConversationNameContextMenuIconText
                icon={<Gauge size={16} />}
                text={t(I18nKey.BUTTON$DISPLAY_COST)}
              />
            </ContextMenuListItem>
          ),
          onArchive && (
            <ContextMenuListItem
              key="archive-button"
              testId="archive-button"
              onClick={onArchive}
            >
              <ConversationNameContextMenuIconText
                icon={<Archive className="h-4 w-4" aria-hidden />}
                text={t(I18nKey.COMMON$ARCHIVE_CONVERSATION)}
              />
            </ContextMenuListItem>
          ),
          onUnarchive && (
            <ContextMenuListItem
              key="unarchive-button"
              testId="unarchive-button"
              onClick={onUnarchive}
            >
              <ConversationNameContextMenuIconText
                icon={<ArchiveRestore className="h-4 w-4" aria-hidden />}
                text={t(I18nKey.COMMON$UNARCHIVE_CONVERSATION)}
              />
            </ContextMenuListItem>
          ),
          onDelete && (
            <ContextMenuListItem
              key="delete-button"
              testId="delete-button"
              onClick={onDelete}
            >
              <ConversationNameContextMenuIconText
                icon={<DeleteIcon width={16} height={16} />}
                text={t(I18nKey.COMMON$DELETE_CONVERSATION)}
              />
            </ContextMenuListItem>
          ),
        ],
        // eslint-disable-next-line i18next/no-literal-string -- internal section id, not user-facing
        "info-section",
        true,
      )}
    </ContextMenu>
  );
}

import type { ReactNode } from "react";
import { Folder } from "lucide-react";
import { FaBitbucket, FaGithub, FaGitlab } from "react-icons/fa6";
import { FaCodeBranch } from "react-icons/fa";
import type { IconType } from "react-icons/lib";
import { useTranslation } from "react-i18next";
import { I18nKey } from "#/i18n/declaration";
import type { RepositorySelection } from "#/api/open-hands.types";
import type { Provider } from "#/types/settings";
import type { ExecutionStatus } from "#/types/agent-server/core/base/common";
import type { SandboxStatus } from "#/api/conversation-service/agent-server-conversation-service.types";
import { getDisplayConversationTags } from "#/api/agent-server-adapter";
import { resolveAcpProviderIcon } from "#/constants/acp-providers";
import AzureDevOpsLogo from "#/assets/branding/azure-devops-logo.svg?react";
import { AgentBrandIcon } from "#/components/shared/agent-brand-icon";
import { ConversationStatusDot } from "../conversation-status-dot";
import { getConversationTagLabel } from "./conversation-tag-display";
import { getConversationTagIcon } from "./conversation-tag-icons";

interface ConversationCardPreviewProps {
  title: string;
  executionStatus?: ExecutionStatus | null;
  sandboxStatus?: SandboxStatus | null;
  selectedRepository: RepositorySelection | null;
  workspaceWorkingDir?: string | null;
  llmModel?: string | null;
  /**
   * High-level kind of the conversation's agent. Drives the model row's brand
   * mark exactly like the card chip does — without it an ACP conversation
   * would show the OpenHands wordmark next to a Claude Code / Codex / Gemini
   * model, contradicting the chip on the very card being hovered.
   */
  agentKind?: "openhands" | "acp" | null;
  /** Registry key of the ACP CLI server, resolved to its brand mark. */
  acpServer?: string | null;
  createdAt?: string;
  /**
   * Server-side conversation tags. Always shown in the hovercard when present
   * (except keys already covered by repository / branch / directory rows).
   * Sidebar card chips stay gated by the panel's Tags preference.
   */
  tags?: Record<string, string> | null;
}

const providerIcon: Partial<Record<Provider, IconType>> = {
  bitbucket: FaBitbucket,
  bitbucket_data_center: FaBitbucket,
  github: FaGithub,
  gitlab: FaGitlab,
};

interface PreviewRowProps {
  label: string;
  children: ReactNode;
}

function PreviewRow({ label, children }: PreviewRowProps) {
  return (
    <div className="flex items-start gap-2 text-xs leading-4">
      <span className="w-20 shrink-0 whitespace-normal break-words text-muted">
        {label}
      </span>
      <span className="min-w-0 flex-1 overflow-visible whitespace-normal break-words text-foreground">
        {children}
      </span>
    </div>
  );
}

/**
 * Icon + value for preview rows. The icon sits in a box matching the first
 * line's height (``leading-4``) so it stays optically centered when the value
 * wraps to multiple lines. The slot has a 12px *minimum* rather than a fixed
 * width so the wider OpenHands wordmark (18px at ``size={12}``) is not clipped,
 * while the square icons still share one column.
 */
function PreviewValueWithIcon({
  icon,
  children,
  testId,
  tagKey,
}: {
  icon?: ReactNode;
  children: ReactNode;
  testId?: string;
  tagKey?: string;
}) {
  return (
    <span
      data-testid={testId}
      data-tag-key={tagKey}
      className="inline-flex min-w-0 max-w-full items-start gap-1.5"
    >
      {icon ? (
        <span className="inline-flex h-4 min-w-3 shrink-0 items-center justify-center [&_svg]:block">
          {icon}
        </span>
      ) : null}
      <span className="min-w-0 flex-1 whitespace-normal break-all">
        {children}
      </span>
    </span>
  );
}

export function ConversationCardPreview({
  title,
  executionStatus,
  sandboxStatus,
  selectedRepository,
  workspaceWorkingDir,
  llmModel,
  agentKind = null,
  acpServer = null,
  createdAt,
  tags = null,
}: ConversationCardPreviewProps) {
  const { t } = useTranslation("openhands");

  const repository = selectedRepository?.selected_repository ?? null;
  const branch = selectedRepository?.selected_branch ?? null;
  const provider = selectedRepository?.git_provider ?? null;
  const ProviderIcon = provider ? providerIcon[provider] : null;

  const createdLabel = createdAt
    ? new Date(createdAt).toLocaleString(undefined, {
        dateStyle: "medium",
        timeStyle: "short",
      })
    : null;

  const previewTags = getDisplayConversationTags(tags);

  return (
    <div
      data-testid="conversation-card-preview"
      className="flex w-70 max-w-[min(280px,90vw)] flex-col gap-3 overflow-visible p-3"
    >
      <div className="flex items-start gap-2">
        {executionStatus !== undefined ? (
          <span className="inline-flex h-5 w-2.5 shrink-0 items-center justify-center">
            <ConversationStatusDot
              executionStatus={executionStatus}
              sandboxStatus={sandboxStatus}
              showTooltip={false}
            />
          </span>
        ) : null}
        <span className="break-words text-sm font-medium leading-5 text-contrast">
          {title}
        </span>
      </div>

      <dl className="flex flex-col gap-1.5">
        {repository ? (
          <>
            <PreviewRow label={t(I18nKey.CONVERSATION_PANEL$PREVIEW_REPO)}>
              <PreviewValueWithIcon
                icon={
                  ProviderIcon ? (
                    <ProviderIcon size={12} />
                  ) : provider === "azure_devops" ? (
                    <AzureDevOpsLogo className="h-3 w-3" />
                  ) : undefined
                }
              >
                {repository}
              </PreviewValueWithIcon>
            </PreviewRow>
            {branch ? (
              <PreviewRow label={t(I18nKey.CONVERSATION_PANEL$PREVIEW_BRANCH)}>
                <PreviewValueWithIcon icon={<FaCodeBranch size={11} />}>
                  {branch}
                </PreviewValueWithIcon>
              </PreviewRow>
            ) : null}
          </>
        ) : workspaceWorkingDir ? (
          <PreviewRow label={t(I18nKey.CONVERSATION_PANEL$PREVIEW_DIRECTORY)}>
            <PreviewValueWithIcon icon={<Folder size={12} />}>
              {workspaceWorkingDir}
            </PreviewValueWithIcon>
          </PreviewRow>
        ) : null}

        {llmModel ? (
          <PreviewRow label={t(I18nKey.CONVERSATION_PANEL$PREVIEW_MODEL)}>
            <PreviewValueWithIcon
              testId="conversation-card-preview-model"
              icon={
                <AgentBrandIcon
                  kind={
                    agentKind === "acp"
                      ? resolveAcpProviderIcon(acpServer)
                      : "openhands"
                  }
                  size={12}
                />
              }
            >
              {llmModel}
            </PreviewValueWithIcon>
          </PreviewRow>
        ) : null}

        {previewTags.map(([key, value]) => {
          const Icon = getConversationTagIcon(key, value);
          const label = getConversationTagLabel(key, t);

          return (
            <PreviewRow key={key} label={label}>
              <PreviewValueWithIcon
                testId="conversation-card-preview-tag-row"
                tagKey={key}
                icon={<Icon aria-hidden className="h-3 w-3" />}
              >
                {/* Bare tags (empty value) show an em dash — the row label
                    already carries the key, so repeating it would stutter. */}
                {value || "—"}
              </PreviewValueWithIcon>
            </PreviewRow>
          );
        })}

        {createdLabel ? (
          <PreviewRow label={t(I18nKey.CONVERSATION$CREATED)}>
            {createdLabel}
          </PreviewRow>
        ) : null}
      </dl>
    </div>
  );
}

import React from "react";
import { Pin } from "lucide-react";
import { useTranslation } from "react-i18next";
import type { ACPModelOption } from "#/constants/acp-providers";
import { useTracking } from "#/hooks/use-tracking";
import { cn } from "#/utils/utils";
import { I18nKey } from "#/i18n/declaration";
import { transformVSCodeUrl } from "#/utils/vscode-url-helper";
import ConversationService from "#/api/conversation-service/conversation-service.api";
import { getDisplayConversationTags } from "#/api/agent-server-adapter";
import { ExecutionStatus } from "#/types/agent-server/core/base/common";
import { SandboxStatus } from "#/api/conversation-service/agent-server-conversation-service.types";
import { RepositorySelection } from "#/api/open-hands.types";
import { formatTimeDelta } from "#/utils/format-time-delta";
import {
  hoverRevealActionClassName,
  hoverRevealPinnedTimestampClassName,
  hoverRevealReserveClassName,
  hoverRevealYieldClassName,
} from "#/utils/hover-reveal-classes";
import { ConversationCardHeader } from "./conversation-card-header";
import { ConversationCardActions } from "./conversation-card-actions";
import { ConversationCardFooter } from "./conversation-card-footer";
import { ConversationStatusBadges } from "./conversation-status-badges";
import { useDownloadConversation } from "#/hooks/use-download-conversation";

interface ConversationCardProps {
  onClick?: () => void;
  onDelete?: () => void;
  onArchive?: () => void;
  /**
   * Restores an archived conversation. The panel passes this instead of
   * `onArchive` for rows that are already archived, so the menu offers exactly
   * one of the two directions.
   */
  onUnarchive?: () => void;
  onStop?: () => void;
  onChangeTitle?: (title: string) => void;
  /**
   * Opens the tag editor for this conversation. Local agent-server backends
   * only — Cloud conversations don't carry server-side tags, so the panel
   * leaves this undefined there and the menu item disappears.
   */
  onEditTags?: () => void;
  showOptions?: boolean;
  title: string;
  selectedRepository: RepositorySelection | null;
  lastUpdatedAt: string;
  createdAt?: string;
  executionStatus?: ExecutionStatus | null;
  sandboxStatus?: SandboxStatus | null;
  conversationId?: string;
  contextMenuOpen?: boolean;
  onContextMenuToggle?: (isOpen: boolean) => void;
  isActive?: boolean;
  workspaceWorkingDir?: string | null;
  showRepositoryMetadata?: boolean;
  llmModel?: string | null;
  showLlmProfiles?: boolean;
  agentKind?: "openhands" | "acp" | null;
  acpServer?: string | null;
  acpModels?: readonly ACPModelOption[] | null;
  tags?: Record<string, string> | null;
  /** Gates the tag-chip row; wired to the panel's "Tags" metadata toggle. */
  showTags?: boolean;
  isArchived?: boolean;
  isPinned?: boolean;
  onTogglePin?: () => void;
  /** When true and pinned, keep the pin icon visible without hovering. */
  alwaysShowPinIcon?: boolean;
}

export function ConversationCard({
  onClick,
  onDelete,
  onArchive,
  onUnarchive,
  onStop,
  onChangeTitle,
  onEditTags,
  showOptions,
  title,
  selectedRepository,
  lastUpdatedAt,
  createdAt,
  conversationId,
  executionStatus,
  sandboxStatus,
  contextMenuOpen = false,
  onContextMenuToggle,
  isActive = false,
  workspaceWorkingDir,
  showRepositoryMetadata = true,
  llmModel = null,
  showLlmProfiles = false,
  agentKind = null,
  acpServer = null,
  acpModels = null,
  tags = null,
  showTags = false,
  isArchived = false,
  isPinned = false,
  onTogglePin,
  alwaysShowPinIcon = false,
}: ConversationCardProps) {
  const { t } = useTranslation("openhands");
  const { trackDownloadVsCodeButtonClicked } = useTracking();
  const [titleMode, setTitleMode] = React.useState<"view" | "edit">("view");
  const { mutateAsync: downloadConversation } = useDownloadConversation();

  const displayTags = getDisplayConversationTags(tags);
  const hasDisplayTags = displayTags.length > 0;
  const showTagChipRow = showTags && hasDisplayTags;

  const onTitleSave = (newTitle: string) => {
    if (newTitle !== "" && newTitle !== title) {
      onChangeTitle?.(newTitle);
    }
    setTitleMode("view");
  };

  const handleDelete = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    onDelete?.();
    onContextMenuToggle?.(false);
  };

  const handleArchive = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    onArchive?.();
    onContextMenuToggle?.(false);
  };

  const handleUnarchive = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    onUnarchive?.();
    onContextMenuToggle?.(false);
  };

  const handleStop = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    onStop?.();
    onContextMenuToggle?.(false);
  };

  const handleEdit = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    setTitleMode("edit");
    onContextMenuToggle?.(false);
  };

  const handleEditTags = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    onEditTags?.();
    onContextMenuToggle?.(false);
  };

  const handleDownloadViaVSCode = async (
    event: React.MouseEvent<HTMLButtonElement>,
  ) => {
    event.preventDefault();
    event.stopPropagation();
    trackDownloadVsCodeButtonClicked();

    // Fetch the VS Code URL from the API
    if (conversationId) {
      try {
        const data = await ConversationService.getVSCodeUrl(conversationId);
        if (data.vscode_url) {
          const transformedUrl = transformVSCodeUrl(data.vscode_url);
          if (transformedUrl) {
            window.open(transformedUrl, "_blank");
          }
        }
        // VS Code URL not available
      } catch {
        // Failed to fetch VS Code URL
      }
    }

    onContextMenuToggle?.(false);
  };

  const handleDownloadConversation = async (
    event: React.MouseEvent<HTMLButtonElement>,
  ) => {
    event.preventDefault();
    event.stopPropagation();

    if (conversationId) {
      try {
        await downloadConversation(conversationId);
      } catch {
        // useDownloadConversation already showed the error toast; close the
        // menu as on success instead of leaking the rejection.
      }
    }
    onContextMenuToggle?.(false);
  };

  const handleTogglePin = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    onTogglePin?.();
  };

  const renderPinButton = () => (
    <button
      type="button"
      data-testid={
        conversationId
          ? `conversation-pin-toggle-${conversationId}`
          : "conversation-pin-toggle"
      }
      aria-pressed={isPinned}
      aria-label={
        isPinned
          ? t(I18nKey.CONVERSATION_PANEL$UNPIN_CONVERSATION)
          : t(I18nKey.CONVERSATION_PANEL$PIN_CONVERSATION)
      }
      onClick={handleTogglePin}
      className={cn(
        "flex shrink-0 cursor-pointer items-center justify-center rounded-md p-1",
        "text-muted hover:bg-contrast/10 hover:text-contrast",
      )}
    >
      <Pin
        className={cn("h-3.5 w-3.5", isPinned && "fill-current")}
        aria-hidden
      />
    </button>
  );

  const hasContextMenu = !!(
    onDelete ||
    onArchive ||
    onUnarchive ||
    onChangeTitle ||
    onEditTags ||
    showOptions
  );
  const hasHoverActions = hasContextMenu || !!onTogglePin;
  const showPersistentPinIcon = alwaysShowPinIcon && isPinned && !!onTogglePin;
  const shouldRenderFooter =
    showRepositoryMetadata ||
    isArchived ||
    (showLlmProfiles && (agentKind === "acp" || !!llmModel)) ||
    (showTagChipRow && displayTags.length > 0);

  return (
    <div
      data-testid="conversation-card"
      data-context-menu-open={contextMenuOpen.toString()}
      data-active={isActive ? "true" : "false"}
      onClick={onClick}
      className={cn(
        "group relative h-auto w-full cursor-pointer rounded-md py-1 pl-2 pr-1 transition-colors",
        !contextMenuOpen && "hover:bg-surface",
        (isActive || contextMenuOpen) && "bg-surface",
      )}
    >
      <div className="flex items-center w-full min-w-0">
        <div className="flex items-center gap-2 flex-1 min-w-0 overflow-hidden">
          <ConversationCardHeader
            title={title}
            titleMode={titleMode}
            onTitleSave={onTitleSave}
            executionStatus={executionStatus}
            sandboxStatus={sandboxStatus}
          />
          {sandboxStatus === "ERROR" && <ConversationStatusBadges />}
        </div>

        <div
          data-testid="conversation-card-trailing-slot"
          className={cn(
            "relative ml-auto pl-2 flex items-center justify-end shrink-0",
            // The hover action overlay (pin + ellipsis) is absolutely
            // positioned, so reserve its width so the flex-1 title truncates
            // instead of colliding with the buttons. Pinned cards keep the pin
            // visible at rest, so reserve the width always for those. Touch /
            // coarse-pointer devices also keep the reserve so the ellipsis stays
            // clickable without a hover pass.
            showPersistentPinIcon
              ? "min-w-[3.75rem]"
              : hasHoverActions && hoverRevealReserveClassName(contextMenuOpen),
          )}
        >
          {!showPersistentPinIcon && (createdAt ?? lastUpdatedAt) && (
            <p
              className={cn(
                "text-xs text-muted text-right whitespace-nowrap transition-opacity -translate-x-1.5",
                hasHoverActions && hoverRevealYieldClassName(contextMenuOpen),
              )}
            >
              <time>{formatTimeDelta(lastUpdatedAt ?? createdAt)}</time>
            </p>
          )}

          {hasHoverActions ? (
            <div
              data-testid="conversation-card-hover-actions"
              className={cn(
                "absolute right-0 top-1/2 flex -translate-y-1/2 items-center gap-0.5 transition-opacity",
                showPersistentPinIcon
                  ? "pointer-events-auto visible opacity-100"
                  : hoverRevealActionClassName(contextMenuOpen),
              )}
            >
              {onTogglePin ? renderPinButton() : null}
              {showPersistentPinIcon &&
              (createdAt ?? lastUpdatedAt) &&
              hasContextMenu ? (
                <div className="relative shrink-0">
                  <div className={hoverRevealActionClassName(contextMenuOpen)}>
                    <ConversationCardActions
                      contextMenuOpen={contextMenuOpen}
                      onContextMenuToggle={onContextMenuToggle || (() => {})}
                      onDelete={onDelete && handleDelete}
                      onArchive={onArchive && handleArchive}
                      onUnarchive={onUnarchive && handleUnarchive}
                      onStop={onStop && handleStop}
                      onEdit={onChangeTitle && handleEdit}
                      onEditTags={onEditTags && handleEditTags}
                      onDownloadViaVSCode={handleDownloadViaVSCode}
                      onDownloadConversation={handleDownloadConversation}
                      executionStatus={executionStatus}
                      conversationId={conversationId}
                      showOptions={showOptions}
                    />
                  </div>
                  <p
                    className={cn(
                      "pointer-events-none absolute inset-0 items-center justify-end",
                      "text-xs text-muted whitespace-nowrap -translate-x-1.5",
                      hoverRevealPinnedTimestampClassName(contextMenuOpen),
                    )}
                  >
                    <time>{formatTimeDelta(lastUpdatedAt ?? createdAt)}</time>
                  </p>
                </div>
              ) : null}
              {!showPersistentPinIcon && hasContextMenu ? (
                <ConversationCardActions
                  contextMenuOpen={contextMenuOpen}
                  onContextMenuToggle={onContextMenuToggle || (() => {})}
                  onDelete={onDelete && handleDelete}
                  onArchive={onArchive && handleArchive}
                  onUnarchive={onUnarchive && handleUnarchive}
                  onStop={onStop && handleStop}
                  onEdit={onChangeTitle && handleEdit}
                  onEditTags={onEditTags && handleEditTags}
                  onDownloadViaVSCode={handleDownloadViaVSCode}
                  onDownloadConversation={handleDownloadConversation}
                  executionStatus={executionStatus}
                  conversationId={conversationId}
                  showOptions={showOptions}
                />
              ) : null}
            </div>
          ) : null}
        </div>
      </div>

      {shouldRenderFooter && (
        <ConversationCardFooter
          selectedRepository={selectedRepository}
          lastUpdatedAt={lastUpdatedAt}
          createdAt={createdAt}
          executionStatus={executionStatus}
          workspaceWorkingDir={workspaceWorkingDir}
          showRepositoryMetadata={showRepositoryMetadata}
          showTimestamp={false}
          llmModel={llmModel}
          showAgentChip={showLlmProfiles}
          agentKind={agentKind}
          acpServer={acpServer}
          acpModels={acpModels}
          tags={tags}
          showTags={showTagChipRow}
          isArchived={isArchived}
        />
      )}
    </div>
  );
}

import React from "react";
import { createPortal } from "react-dom";
import { useTranslation } from "react-i18next";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import {
  computeVisibleTagChipCount,
  formatConversationTagTooltip,
  getConversationTagLabel,
  getConversationTagValueLabel,
  truncateTagChipValue,
} from "./conversation-tag-display";
import {
  getConversationTagIcon,
  type ConversationTagIcon,
} from "./conversation-tag-icons";
import {
  CONVERSATION_CARD_META_CHIP_CLASSNAME,
  CONVERSATION_CARD_META_CHIP_ICON_CLASSNAME,
  CONVERSATION_CARD_META_CHIP_ICON_SLOT_CLASSNAME,
} from "./conversation-card-meta-chip";

interface ConversationTagChipsProps {
  tags: Array<[string, string]>;
}

/**
 * Fixed line-height slot so Lucide / react-icons / local SVGs share the same
 * optical center as the ``leading-4`` chip / overflow text (raw ``h-3 w-3``
 * SVGs sit on the baseline and look high or low depending on the glyph).
 */
function TagIconSlot({
  icon: Icon,
  keyName,
  testId,
}: {
  icon: ConversationTagIcon;
  keyName?: string;
  testId?: string;
}) {
  return (
    <span
      className={CONVERSATION_CARD_META_CHIP_ICON_SLOT_CLASSNAME}
      aria-hidden
    >
      <Icon
        data-testid={testId}
        data-tag-key={keyName}
        aria-hidden
        className={CONVERSATION_CARD_META_CHIP_ICON_CLASSNAME}
      />
    </span>
  );
}

function formatTagChipLabel(
  key: string,
  value: string,
  t: (key: I18nKey) => string,
): string {
  // Same string as the tooltip, with the value hard-truncated so long chips
  // still fit. Bare tags (empty value) show the humanized key once.
  return formatConversationTagTooltip(key, truncateTagChipValue(value), t);
}

function TagChipContent({
  icon,
  keyName,
  chipLabel,
  iconTestId,
}: {
  icon: ConversationTagIcon;
  keyName: string;
  chipLabel: string;
  /**
   * Only the visible row passes this. The off-screen measure row renders the
   * same chips, so tagging both would emit every chip test id twice and break
   * ``getByTestId`` (singular) for any card with tags.
   */
  iconTestId?: string;
}) {
  return (
    <>
      <TagIconSlot icon={icon} keyName={keyName} testId={iconTestId} />
      <span className="truncate leading-4">{chipLabel}</span>
    </>
  );
}

/**
 * Single-row tag chips for a conversation card. Chip labels show the same
 * humanized ``key: value`` pair as the tooltip (bare tags with an empty
 * value show the key once); chips that do not fit fold behind a ``+N``
 * button that opens a key/value popover.
 *
 * The overflow popover is portaled with ``position: fixed`` so it is not
 * clipped by the chip row's ``overflow-hidden`` or the sidebar scroller.
 */
export function ConversationTagChips({ tags }: ConversationTagChipsProps) {
  const { t, i18n } = useTranslation("openhands");
  const containerRef = React.useRef<HTMLDivElement>(null);
  const measureRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const popoverRef = React.useRef<HTMLDivElement>(null);
  const [visibleCount, setVisibleCount] = React.useState(tags.length);
  const [isOverflowOpen, setIsOverflowOpen] = React.useState(false);
  const [popoverBox, setPopoverBox] = React.useState<{
    top: number;
    left: number;
  } | null>(null);

  const recomputeVisibleCount = React.useCallback(() => {
    const container = containerRef.current;
    const measure = measureRef.current;
    if (!container || !measure) {
      return;
    }

    const widths = Array.from(measure.children).map(
      (child) => (child as HTMLElement).offsetWidth,
    );
    setVisibleCount(computeVisibleTagChipCount(widths, container.clientWidth));
  }, []);

  const measurePopover = React.useCallback(() => {
    const trigger = triggerRef.current;
    if (!trigger) {
      return;
    }
    const rect = trigger.getBoundingClientRect();
    const gutter = 8;
    const width = 16 * 16;
    let left = rect.left;
    if (left + width > window.innerWidth - gutter) {
      left = Math.max(gutter, window.innerWidth - gutter - width);
    }
    setPopoverBox({ top: rect.bottom + 4, left });
  }, []);

  // Callers build this array fresh on every render (``getDisplayConversationTags``
  // returns a new array), so keying the reset effect on ``tags`` identity would
  // fire on every parent render — closing an open ``+N`` popover and forcing a
  // layout read on each 10s panel refetch. Compare tag *content* instead.
  const tagsKey = tags.map(([key, value]) => `${key}=${value}`).join("\u001f");
  const lastTagsKeyRef = React.useRef<string | null>(null);

  React.useLayoutEffect(() => {
    if (lastTagsKeyRef.current === tagsKey) {
      return;
    }
    lastTagsKeyRef.current = tagsKey;
    setIsOverflowOpen(false);
    recomputeVisibleCount();
  }, [tagsKey, recomputeVisibleCount]);

  // Localized key labels change chip width (e.g. "Git" vs a longer
  // translation), so overflow must be remeasured when the language changes.
  const language = i18n.resolvedLanguage ?? i18n.language;
  React.useLayoutEffect(() => {
    recomputeVisibleCount();
  }, [language, recomputeVisibleCount]);

  React.useEffect(() => {
    const container = containerRef.current;
    if (!container || typeof ResizeObserver === "undefined") {
      return undefined;
    }

    const observer = new ResizeObserver(() => recomputeVisibleCount());
    observer.observe(container);
    return () => observer.disconnect();
  }, [recomputeVisibleCount]);

  React.useLayoutEffect(() => {
    if (!isOverflowOpen) {
      setPopoverBox(null);
      return undefined;
    }
    measurePopover();
    window.addEventListener("resize", measurePopover);
    window.addEventListener("scroll", measurePopover, true);
    return () => {
      window.removeEventListener("resize", measurePopover);
      window.removeEventListener("scroll", measurePopover, true);
    };
  }, [isOverflowOpen, measurePopover]);

  React.useEffect(() => {
    if (!isOverflowOpen) {
      return undefined;
    }
    const onPointerDown = (event: MouseEvent) => {
      const target = event.target as Node;
      if (triggerRef.current?.contains(target)) {
        return;
      }
      if (popoverRef.current?.contains(target)) {
        return;
      }
      setIsOverflowOpen(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsOverflowOpen(false);
      }
    };
    // mousedown (not click) so the opening click cannot race-close the panel,
    // and so NavigationLink activation is easier to cancel on the trigger.
    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [isOverflowOpen]);

  if (tags.length === 0) {
    return null;
  }

  const hiddenCount = Math.max(0, tags.length - visibleCount);
  const visibleTags = tags.slice(0, visibleCount);
  const overflowTags = tags.slice(visibleCount);

  const stopCardNavigation = (event: React.SyntheticEvent) => {
    // Don't preventDefault on mousedown — that suppresses the subsequent click
    // when the chip sits inside a conversation NavigationLink.
    event.stopPropagation();
  };

  const activateOverflow = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    setIsOverflowOpen((open) => !open);
  };

  return (
    <div
      data-testid="conversation-card-tag-chips"
      className="relative min-w-0 w-full"
    >
      <div
        ref={measureRef}
        aria-hidden
        className="pointer-events-none fixed top-0 -left-2500 z-[-1] flex flex-nowrap items-center gap-1 opacity-0"
      >
        {tags.map(([key, value]) => (
          <span key={key} className={CONVERSATION_CARD_META_CHIP_CLASSNAME}>
            <TagChipContent
              icon={getConversationTagIcon(key, value)}
              keyName={key}
              chipLabel={formatTagChipLabel(key, value, t)}
            />
          </span>
        ))}
      </div>

      <div
        ref={containerRef}
        data-testid="conversation-card-tag-row"
        className="flex w-full min-w-0 max-w-full flex-nowrap items-center gap-1 overflow-hidden"
      >
        {visibleTags.map(([key, value]) => (
          <span
            key={key}
            data-testid="conversation-card-tag-chip"
            title={formatConversationTagTooltip(key, value, t)}
            className={CONVERSATION_CARD_META_CHIP_CLASSNAME}
          >
            <TagChipContent
              icon={getConversationTagIcon(key, value)}
              keyName={key}
              chipLabel={formatTagChipLabel(key, value, t)}
              iconTestId="conversation-card-tag-chip-icon"
            />
          </span>
        ))}
        {hiddenCount > 0 ? (
          <button
            ref={triggerRef}
            type="button"
            data-testid="conversation-card-tag-overflow"
            aria-expanded={isOverflowOpen}
            aria-haspopup="dialog"
            aria-label={t(I18nKey.CONVERSATION$TAGS_OVERFLOW_ARIA, {
              count: hiddenCount,
            })}
            onMouseDown={stopCardNavigation}
            onClick={activateOverflow}
            className={cn(
              CONVERSATION_CARD_META_CHIP_CLASSNAME,
              "shrink-0 self-center hover:bg-interactive-hover hover:text-foreground",
            )}
          >
            {/* Match chip height (icon slot + label) so +N shares the same centerline. */}
            <span className="inline-flex h-4 w-0 shrink-0" aria-hidden />
            <span className="leading-4">{`+${hiddenCount}`}</span>
          </button>
        ) : null}
      </div>

      {isOverflowOpen &&
        popoverBox &&
        typeof document !== "undefined" &&
        createPortal(
          // Stop card-level click activation when interacting with the list.
          // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- dialog surface must swallow clicks
          <div
            ref={popoverRef}
            role="dialog"
            data-testid="conversation-card-tag-overflow-popover"
            className={cn(
              "z-[9999] min-w-[10rem] max-w-[16rem]",
              "rounded-md border border-border-subtle",
              "bg-surface p-2 shadow-lg",
            )}
            style={{
              position: "fixed",
              top: popoverBox.top,
              left: popoverBox.left,
            }}
            onMouseDown={stopCardNavigation}
            onClick={(event) => {
              event.preventDefault();
              event.stopPropagation();
            }}
          >
            <dl className="m-0 flex flex-col gap-1">
              {overflowTags.map(([key, value]) => (
                <div
                  key={key}
                  data-testid="conversation-card-tag-overflow-row"
                  className="grid grid-cols-[minmax(0,auto)_minmax(0,1fr)] gap-x-2 text-[10px] leading-4"
                >
                  <dt className="m-0 inline-flex min-w-0 items-center gap-1 whitespace-normal break-words text-muted">
                    <TagIconSlot icon={getConversationTagIcon(key, value)} />
                    <span className="min-w-0 whitespace-normal break-words leading-4">
                      {getConversationTagLabel(key, t)}
                    </span>
                  </dt>
                  <dd
                    className="m-0 whitespace-normal break-words text-left leading-4 text-foreground"
                    title={value}
                  >
                    {getConversationTagValueLabel(key, value, t)}
                  </dd>
                </div>
              ))}
            </dl>
          </div>,
          document.body,
        )}
    </div>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";
import {
  Clock3,
  Folder,
  ListFilter,
  Shrink,
  SlidersHorizontal,
  Star,
  Tag,
  Trash2,
} from "lucide-react";
import { I18nKey } from "#/i18n/declaration";
import type { BackendKind } from "#/api/backend-registry/types";
import { cn } from "#/utils/utils";
import {
  dropdownInstantColorClassName,
  dropdownMenuListClassName,
  dropdownMenuViewportScrollClassName,
} from "#/utils/dropdown-classes";
import {
  DEFAULT_LAYOUT_SETTINGS,
  useConversationPanelPreferencesStore,
  type LayoutSettingsSlice,
} from "#/stores/conversation-panel-preferences-store";
import { formatTagFacetLabel } from "./conversation-panel-list-helpers";
import { MenuHeading } from "./menu-heading";
import { MenuSeparator } from "./menu-separator";
import { MenuRow } from "./menu-row";
import { AdvancedConversationOptionsModal } from "./advanced-conversation-options-modal";

interface LayoutPreset {
  id: string;
  icon: React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>;
  /** Omitted for the backend-dependent first preset (workspace vs repo). */
  labelKey?: I18nKey;
  settings: LayoutSettingsSlice;
}

/**
 * Layout presets are complete preference bundles (design inference from the
 * 2026-08-14 PM walkthrough video; the video names the presets but not their
 * exact bundles). Applying one replaces every layout-controlled field so a
 * previous preset cannot leak into the next one. Any manual deviation reads
 * as "Custom".
 */
const LAYOUT_PRESETS: LayoutPreset[] = [
  {
    id: "by-workspace",
    icon: Folder,
    settings: {
      ...DEFAULT_LAYOUT_SETTINGS,
      organizeMode: "grouped",
    },
  },
  {
    id: "recent-activity",
    icon: Clock3,
    labelKey: I18nKey.CONVERSATION_PANEL$LAYOUT_RECENT_ACTIVITY,
    // Exactly the default bundle, so a profile that never changed a layout
    // preference reads as Recent rather than Custom.
    settings: DEFAULT_LAYOUT_SETTINGS,
  },
  {
    id: "focused",
    icon: Star,
    labelKey: I18nKey.CONVERSATION_PANEL$LAYOUT_FOCUSED,
    settings: {
      ...DEFAULT_LAYOUT_SETTINGS,
      threadScope: "relevant",
      showOlderConversations: false,
    },
  },
  {
    id: "minimal",
    icon: Shrink,
    labelKey: I18nKey.CONVERSATION_PANEL$LAYOUT_MINIMAL,
    settings: {
      ...DEFAULT_LAYOUT_SETTINGS,
      threadScope: "relevant",
      showOlderConversations: false,
      showRepoBranchMetadata: false,
      showLlmProfiles: false,
      showTagsMetadata: false,
      showHoverMetadata: false,
    },
  },
];

export function getActiveLayoutPreset(
  settings: LayoutSettingsSlice,
): LayoutPreset | null {
  return (
    LAYOUT_PRESETS.find((preset) =>
      Object.entries(preset.settings).every(
        ([key, value]) => settings[key as keyof LayoutSettingsSlice] === value,
      ),
    ) ?? null
  );
}

export interface ConversationLayoutsMenuProps {
  menuOpen: boolean;
  setMenuOpen: (open: boolean) => void;
  menuRef: React.RefObject<HTMLDivElement | null>;
  backendKind: BackendKind;
  /** Distinct user-facing `key=value` facets among the loaded conversations. */
  tagFacets: readonly string[];
  /** Distinct automation names; the advanced modal owns their facet rows. */
  automationNameFacets: readonly string[];
  totalConversationsCount: number;
  onRequestDeleteAll: () => void;
}

export function ConversationLayoutsMenu({
  menuOpen,
  setMenuOpen,
  menuRef,
  backendKind,
  tagFacets,
  automationNameFacets,
  totalConversationsCount,
  onRequestDeleteAll,
}: ConversationLayoutsMenuProps) {
  const { t } = useTranslation("openhands");
  const preferences = useConversationPanelPreferencesStore();
  const [tagSectionExpanded, setTagSectionExpanded] = React.useState(false);
  const [advancedOpen, setAdvancedOpen] = React.useState(false);

  const groupedLabel =
    backendKind === "local"
      ? t(I18nKey.CONVERSATION_PANEL$BY_WORKSPACE)
      : t(I18nKey.CONVERSATION_PANEL$BY_REPOSITORY);

  const activePreset = getActiveLayoutPreset(preferences);

  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const menuContentRef = React.useRef<HTMLDivElement>(null);

  // Mirror the filter menu's focus management: focus into the menu on open,
  // return focus to the trigger on close.
  const wasOpenRef = React.useRef(menuOpen);
  React.useEffect(() => {
    if (menuOpen) {
      const firstItem =
        menuContentRef.current?.querySelector<HTMLButtonElement>(
          '[role="menuitem"], [role="menuitemradio"], [role="menuitemcheckbox"]',
        );
      firstItem?.focus();
    } else if (wasOpenRef.current) {
      triggerRef.current?.focus();
    }
    wasOpenRef.current = menuOpen;
  }, [menuOpen]);

  const handleMenuKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") {
      event.preventDefault();
      setMenuOpen(false);
      return;
    }
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
    const container = menuContentRef.current;
    if (!container) return;
    const items = Array.from(
      container.querySelectorAll<HTMLButtonElement>(
        '[role="menuitem"], [role="menuitemradio"], [role="menuitemcheckbox"]',
      ),
    ).filter((el) => !el.disabled);
    if (items.length === 0) return;
    const currentIdx = items.indexOf(
      document.activeElement as HTMLButtonElement,
    );
    const delta = event.key === "ArrowDown" ? 1 : -1;
    const start = currentIdx === -1 ? 0 : currentIdx;
    const nextIdx = (start + delta + items.length) % items.length;
    event.preventDefault();
    items[nextIdx]?.focus();
  };

  return (
    <div ref={menuRef} className="relative shrink-0 pr-0.5">
      <button
        ref={triggerRef}
        type="button"
        data-testid="conversation-layouts-toggle"
        aria-label={t(I18nKey.CONVERSATION_PANEL$LAYOUTS_HEADING)}
        aria-haspopup="menu"
        aria-expanded={menuOpen}
        onClick={() => setMenuOpen(!menuOpen)}
        className={cn(
          "relative inline-flex h-7 w-7 items-center justify-center rounded-md text-muted hover:text-contrast hover:bg-surface-raised",
          dropdownInstantColorClassName,
        )}
      >
        <ListFilter
          className="shrink-0"
          size={14}
          strokeWidth={2}
          aria-hidden
        />
      </button>

      {menuOpen ? (
        <div
          ref={menuContentRef}
          role="menu"
          aria-orientation="vertical"
          aria-label={t(I18nKey.CONVERSATION_PANEL$LAYOUTS_HEADING)}
          tabIndex={-1}
          data-testid="conversation-layouts-menu"
          onKeyDown={handleMenuKeyDown}
          className={cn(
            "absolute right-0 top-full z-50 mt-0 w-64 rounded-md border border-border-subtle bg-tertiary px-1 py-1 text-foreground shadow-lg",
            dropdownMenuListClassName,
            dropdownMenuViewportScrollClassName,
          )}
        >
          <MenuHeading>
            {t(I18nKey.CONVERSATION_PANEL$LAYOUTS_HEADING)}
          </MenuHeading>
          {LAYOUT_PRESETS.map((preset) => (
            <MenuRow
              key={preset.id}
              icon={preset.icon}
              label={preset.labelKey ? t(preset.labelKey) : groupedLabel}
              selected={activePreset?.id === preset.id}
              testId={`layout-preset-${preset.id}`}
              onClick={() => {
                preferences.applyLayoutSettings(preset.settings);
                setMenuOpen(false);
              }}
            />
          ))}

          <MenuSeparator />
          <MenuRow
            icon={Tag}
            label={t(I18nKey.CONVERSATION_PANEL$TAG_FILTERS)}
            testId="tag-filters-section"
            onClick={() => setTagSectionExpanded(!tagSectionExpanded)}
          />
          {tagSectionExpanded ? (
            tagFacets.length > 0 ? (
              tagFacets.map((facet) => (
                <MenuRow
                  key={facet}
                  icon={Tag}
                  label={formatTagFacetLabel(facet, t)}
                  selected={preferences.selectedTagFacets.includes(facet)}
                  testId={`tag-facet-row-${facet}`}
                  onClick={() => preferences.toggleTagFacet(facet)}
                />
              ))
            ) : (
              <p
                data-testid="tag-filters-empty"
                className="px-2 py-1 text-[11px] text-muted/70"
              >
                {t(I18nKey.CONVERSATION_PANEL$NO_VISIBLE_TAGS)}
              </p>
            )
          ) : null}

          <MenuSeparator />
          <MenuRow
            icon={SlidersHorizontal}
            label={
              activePreset
                ? t(I18nKey.CONVERSATION_PANEL$ADVANCED_OPTIONS)
                : `${t(I18nKey.CONVERSATION_PANEL$ADVANCED_OPTIONS)} · ${t(
                    I18nKey.CONVERSATION_PANEL$ADVANCED_OPTIONS_CUSTOM,
                  )}`
            }
            testId="advanced-options-row"
            onClick={() => {
              setMenuOpen(false);
              setAdvancedOpen(true);
            }}
          />

          <MenuSeparator />
          <MenuRow
            testId="delete-all-conversations"
            icon={Trash2}
            label={capitalizeLabel(t(I18nKey.CONVERSATION$DELETE_ALL))}
            disabled={totalConversationsCount === 0}
            destructive
            onClick={() => {
              if (totalConversationsCount === 0) return;
              onRequestDeleteAll();
              setMenuOpen(false);
            }}
          />
        </div>
      ) : null}

      <AdvancedConversationOptionsModal
        open={advancedOpen}
        onClose={() => setAdvancedOpen(false)}
        backendKind={backendKind}
        automationNameFacets={automationNameFacets}
      />
    </div>
  );
}

const capitalizeLabel = (label: string) =>
  label.length > 0 ? label.charAt(0).toUpperCase() + label.slice(1) : label;

