interface HookEventItemProps {
  hookEvent: HookEvent;
  isExpanded: boolean;
  onToggle: (eventType: string) => void;
}

const EVENT_TYPE_I18N_KEYS: Record<string, I18nKey> = {
  pre_tool_use: I18nKey.HOOKS_MODAL$EVENT_PRE_TOOL_USE,
  post_tool_use: I18nKey.HOOKS_MODAL$EVENT_POST_TOOL_USE,
  user_prompt_submit: I18nKey.HOOKS_MODAL$EVENT_USER_PROMPT_SUBMIT,
  session_start: I18nKey.HOOKS_MODAL$EVENT_SESSION_START,
  session_end: I18nKey.HOOKS_MODAL$EVENT_SESSION_END,
  stop: I18nKey.HOOKS_MODAL$EVENT_STOP,
};

const HOOK_PILL_CLASS =
  "inline-flex shrink-0 items-center rounded-full px-2 py-0.5 text-[11px] font-medium leading-4 border border-border bg-surface text-tertiary-light";

const HOOK_COUNT_I18N_KEY = "HOOKS_MODAL$HOOK_COUNT";

export function HookEventItem({
  hookEvent,
  isExpanded,
  onToggle,
}: HookEventItemProps) {
  const { t } = useTranslation("openhands");
  const i18nKey = EVENT_TYPE_I18N_KEYS[hookEvent.event_type];
  const eventTypeLabel = i18nKey ? t(i18nKey) : hookEvent.event_type;

  const totalHooks = hookEvent.matchers.reduce(
    (sum, matcher) => sum + (matcher.hooks ?? []).length,
    0,
  );

  return (
    <div>
      <button
        type="button"
        onClick={() => onToggle(hookEvent.event_type)}
        className="w-full py-3 px-3 text-left flex items-center justify-between hover:bg-tertiary transition-colors"
      >
        <div className="flex items-center">
          <Typography.Text className="font-bold text-content-2">
            {eventTypeLabel}
          </Typography.Text>
        </div>
        <div className="flex items-center gap-2">
          <span className={HOOK_PILL_CLASS}>
            {t(HOOK_COUNT_I18N_KEY, { count: totalHooks })}
          </span>
          <Typography.Text className="text-text-tertiary">
            {isExpanded ? (
              <ChevronDown size={18} />
            ) : (
              <ChevronRight size={18} />
            )}
          </Typography.Text>
        </div>
      </button>

      {isExpanded && (
        <div className="border-t border-border px-3 pt-3 pb-3">
          <div className="divide-y divide-border">
            {hookEvent.matchers.map((matcher, index) => (
              <HookMatcherContent
                key={`${hookEvent.event_type}-${matcher.matcher}-${index}`}
                matcher={matcher}
              />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import { useTranslation } from "react-i18next";
import { I18nKey } from "#/i18n/declaration";
import { Typography } from "#/ui/typography";
import { Pre } from "#/ui/pre";
import { HookMatcher } from "#/api/conversation-service/agent-server-conversation-service.types";

interface HookMatcherContentProps {
  matcher: HookMatcher;
}

const HOOK_PILL_CLASS =
  "inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium leading-4 border border-border bg-surface text-tertiary-light";

export function HookMatcherContent({ matcher }: HookMatcherContentProps) {
  const { t } = useTranslation("openhands");

  return (
    <div className="py-3">
      <div className="mb-2">
        <Typography.Text className="text-sm font-semibold text-text-tertiary">
          {t(I18nKey.HOOKS_MODAL$MATCHER)}
        </Typography.Text>
        <span className={`ml-2 ${HOOK_PILL_CLASS}`}>{matcher.matcher}</span>
      </div>

      <div className="mt-2">
        <Typography.Text className="text-sm font-semibold text-text-tertiary mb-2">
          {t(I18nKey.HOOKS_MODAL$COMMANDS)}
        </Typography.Text>
        {(matcher.hooks ?? []).map((hook, index) => {
          // Pick the field each hook type runs with; an agent hook may also
          // carry a `prompt`, which it never reads.
          const text =
            hook.type === "agent"
              ? hook.system_prompt
              : hook.type === "prompt"
                ? hook.prompt
                : hook.command;
          return (
            <div key={`${text}-${index}`} className="mt-2">
              {text ? (
                <Pre
                  size="small"
                  font="mono"
                  lineHeight="relaxed"
                  padding="medium"
                  borderRadius="medium"
                  maxHeight="small"
                  overflow="auto"
                  className="border border-border bg-canvas-base text-text-tertiary"
                >
                  {text}
                </Pre>
              ) : null}
              <div className="mt-2 flex flex-wrap gap-2 text-xs text-muted">
                <span className={HOOK_PILL_CLASS}>
                  {t(I18nKey.HOOKS_MODAL$TYPE, { type: hook.type })}
                </span>
                {hook.timeout !== undefined ? (
                  <span className={HOOK_PILL_CLASS}>
                    {t(I18nKey.HOOKS_MODAL$TIMEOUT, { timeout: hook.timeout })}
                  </span>
                ) : null}
                {hook.async ? (
                  <span className={HOOK_PILL_CLASS}>
                    {t(I18nKey.HOOKS_MODAL$ASYNC)}
                  </span>
                ) : null}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState } from "react";
import { ModalBackdrop } from "#/components/shared/modals/modal-backdrop";
import {
  MODAL_MAX_WIDTH_VIEWPORT,
  ModalBody,
} from "#/components/shared/modals/modal-body";
import { useConversationHooks } from "#/hooks/query/use-conversation-hooks";
import { AgentState } from "#/types/agent-state";
import { HooksModalHeader } from "./hooks-modal-header";
import { HooksLoadingState } from "./hooks-loading-state";
import { HooksEmptyState } from "./hooks-empty-state";
import { HookEventItem } from "./hook-event-item";
import { RuntimeWaitingState } from "./runtime-waiting-state";
import { useAgentState } from "#/hooks/use-agent-state";
import { cn } from "#/utils/utils";

interface HooksModalProps {
  onClose: () => void;
}

export function HooksModal({ onClose }: HooksModalProps) {
  const { curAgentState } = useAgentState();
  const [expandedEvents, setExpandedEvents] = useState<Record<string, boolean>>(
    {},
  );
  const {
    data: hooks,
    isLoading,
    isError,
    refetch,
    isRefetching,
  } = useConversationHooks();

  const toggleEvent = (eventType: string) => {
    setExpandedEvents((prev) => ({
      ...prev,
      [eventType]: !prev[eventType],
    }));
  };

  const isAgentReady = ![AgentState.LOADING, AgentState.INIT].includes(
    curAgentState,
  );

  return (
    <ModalBackdrop onClose={onClose}>
      <ModalBody
        width="lg"
        className={cn(
          "relative max-h-[80vh] flex flex-col items-start border border-border",
          MODAL_MAX_WIDTH_VIEWPORT,
        )}
        testID="hooks-modal"
      >
        <HooksModalHeader
          isLoading={isLoading}
          isRefetching={isRefetching}
          onRefresh={refetch}
          onClose={onClose}
        />

        <div className="w-full h-[60vh] overflow-auto rounded-md border border-border bg-surface-raised custom-scrollbar-always">
          {!isAgentReady ? (
            <RuntimeWaitingState testId="hooks-runtime-waiting" />
          ) : isLoading ? (
            <HooksLoadingState />
          ) : isError || !hooks || hooks.length === 0 ? (
            <HooksEmptyState isError={isError} />
          ) : (
            <div className="divide-y divide-border">
              {hooks.map((hookEvent) => {
                const isExpanded =
                  expandedEvents[hookEvent.event_type] || false;

                return (
                  <HookEventItem
                    key={hookEvent.event_type}
                    hookEvent={hookEvent}
                    isExpanded={isExpanded}
                    onToggle={toggleEvent}
                  />
                );
              })}
            </div>
          )}
        </div>
      </ModalBody>
    </ModalBackdrop>
  );
}

