  const { t } = useTranslation("openhands");
  const menuRef = useClickOutsideElement<HTMLUListElement>(onClose);
  const setMessageToSend = useConversationStore(
    (state) => state.setMessageToSend,
  );
  const [portalStyle, setPortalStyle] = useState<React.CSSProperties>();

  useLayoutEffect(() => {
    const anchor = anchorRef.current;
    if (!anchor) {
      return undefined;
    }

    const updatePosition = () => {
      const rect = anchor.getBoundingClientRect();
      setPortalStyle({
        position: "fixed",
        top: rect.bottom + 4,
        right: window.innerWidth - rect.right,
        zIndex: 50,
      });
    };

    updatePosition();
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [anchorRef]);

  const handleCommit = () => {
    setMessageToSend(getGitCommitPrompt());
    onClose();
  };

  const handlePull = () => {
    setMessageToSend(getGitPullPrompt());
    onClose();
  };

  const handlePush = () => {
    setMessageToSend(getGitPushPrompt(gitProvider));
    onClose();
  };

  const handleCreatePr = () => {
    setMessageToSend(getCreatePRPrompt(gitProvider));
    onClose();
  };

  const handleCreateNewBranch = () => {
    setMessageToSend(getCreateNewBranchPrompt());
    onClose();
  };

  if (!portalStyle) {
    return null;
  }

  return ReactDOM.createPortal(
    <ContextMenu
      ref={menuRef}
      testId={`${testIdPrefix}-menu`}
      theme="popover"
      style={portalStyle}
      className="w-max min-w-[8rem]"
    >
      <ContextMenuListItem
        testId={`${testIdPrefix}-commit`}
        onClick={handleCommit}
        className={GIT_MENU_ITEM_CLASSNAME}
      >
        <ToolsContextMenuIconText
          icon={<GitCommitHorizontal className="size-4" aria-hidden />}
          text={t(I18nKey.DIFF_VIEWER$COMMITS)}
        />
      </ContextMenuListItem>
      <ContextMenuListItem
        testId={`${testIdPrefix}-pull`}
        onClick={handlePull}
        className={GIT_MENU_ITEM_CLASSNAME}
      >
        <ToolsContextMenuIconText
          icon={<ArrowDownIcon width={16} height={16} aria-hidden />}
          text={t(I18nKey.COMMON$PULL)}
        />
      </ContextMenuListItem>
      <ContextMenuListItem
        testId={`${testIdPrefix}-push`}
        onClick={handlePush}
        className={GIT_MENU_ITEM_CLASSNAME}
      >
        <ToolsContextMenuIconText
          icon={<ArrowUpIcon width={16} height={16} aria-hidden />}
          text={t(I18nKey.COMMON$PUSH)}
        />
      </ContextMenuListItem>
      <ContextMenuListItem
        testId={`${testIdPrefix}-create-pr`}
        onClick={handleCreatePr}
        className={GIT_MENU_ITEM_CLASSNAME}
      >
        <ToolsContextMenuIconText
          icon={<PrIcon width={16} height={16} aria-hidden />}
          text={t(I18nKey.COMMON$CREATE_PR)}
        />
      </ContextMenuListItem>
      <ContextMenuListItem
        testId={`${testIdPrefix}-create-new-branch`}
        onClick={handleCreateNewBranch}
        className={GIT_MENU_ITEM_CLASSNAME}
      >
        <ToolsContextMenuIconText
          icon={<CodeBranchIcon width={16} height={16} aria-hidden />}
          text={t(I18nKey.COMMON$CREATE_NEW_BRANCH)}
        />
      </ContextMenuListItem>
    </ContextMenu>,
    document.body,
  );
}

import { useRef } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ChatInterface } from "../../chat/chat-interface";
import { ConversationOverviewPanel } from "../conversation-overview-panel";
import { useConversationStore } from "#/stores/conversation-store";
import { useBreakpoint } from "#/hooks/use-breakpoint";
import { useConversationOverviewColumnSpace } from "#/hooks/use-conversation-overview-column-space";
import {
  CONVERSATION_OVERVIEW_COLUMN_WIDTH_PX,
  CONVERSATION_OVERVIEW_PANEL_TRANSITION,
} from "../conversation-overview-panel.constants";

interface ChatInterfaceWrapperProps {
  isRightPanelShown: boolean;
  showGitControlBar?: boolean;
  showEmptyStateSuggestions?: boolean;
  composerDockTarget?: HTMLElement | null;
  onDockedComposerSubmit?: () => void;
  minimalComposer?: boolean;
  composerPlaceholder?: string;
}

const THREAD_CLASSNAME =
  "w-full min-w-0 max-w-200 h-full flex flex-col min-h-0";

export function ChatInterfaceWrapper({
  isRightPanelShown: _isRightPanelShown,
  showGitControlBar = true,
  showEmptyStateSuggestions = true,
  composerDockTarget = null,
  onDockedComposerSubmit,
  minimalComposer = false,
  composerPlaceholder,
}: ChatInterfaceWrapperProps) {
  const isMobile = useBreakpoint();
  const reduceMotion = useReducedMotion();
  const enableOverviewMotion = !reduceMotion && import.meta.env.MODE !== "test";
  const isOverviewPanelShown = useConversationStore(
    (state) => state.isOverviewPanelShown,
  );
  const containerRef = useRef<HTMLDivElement>(null);
  const wantsOverviewPanel = !isMobile && isOverviewPanelShown;
  const hasOverviewColumnSpace = useConversationOverviewColumnSpace(
    containerRef,
    wantsOverviewPanel,
  );
  const showOverviewPanel = wantsOverviewPanel && hasOverviewColumnSpace;

  return (
    <div
      ref={containerRef}
      className="flex h-full min-h-0 w-full overflow-hidden"
    >
      <div className="flex min-h-0 min-w-0 flex-1 justify-center overflow-hidden">
        <div className={THREAD_CLASSNAME}>
          <ChatInterface
            showGitControlBar={showGitControlBar}
            showEmptyStateSuggestions={showEmptyStateSuggestions}
            composerDockTarget={composerDockTarget}
            onDockedComposerSubmit={onDockedComposerSubmit}
            minimalComposer={minimalComposer}
            composerPlaceholder={composerPlaceholder}
          />
        </div>
      </div>
      <AnimatePresence>
        {showOverviewPanel ? (
          <motion.div
            key="conversation-overview-column"
            data-testid="conversation-overview-column"
            initial={enableOverviewMotion ? { width: 0, opacity: 0 } : false}
            animate={{
              width: CONVERSATION_OVERVIEW_COLUMN_WIDTH_PX,
              opacity: 1,
            }}
            exit={
              enableOverviewMotion ? { width: 0, opacity: 0 } : { opacity: 0 }
            }
            transition={CONVERSATION_OVERVIEW_PANEL_TRANSITION}
            className="flex shrink-0 flex-col items-start overflow-hidden pt-4 pl-3 pr-4"
          >
            <div
              className="w-full shrink-0"
              style={{ width: CONVERSATION_OVERVIEW_COLUMN_WIDTH_PX }}
            >
              <ConversationOverviewPanel />
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

import { useEffect, useState } from "react";
import { FileText, MessageSquare } from "lucide-react";
