function PublicShareToggle({
  isPublic,
  onToggle,
  ariaLabel,
}: {
  isPublic: boolean;
  onToggle: (nextIsPublic: boolean) => void;
  ariaLabel: string;
}) {
  return (
    <label className="relative inline-flex shrink-0 cursor-pointer items-center">
      <input
        hidden
        type="checkbox"
        data-testid="share-publicly-button"
        checked={isPublic}
        aria-label={ariaLabel}
        onChange={(event) => onToggle(event.target.checked)}
      />
      <span
        aria-hidden
        className={cn(
          "inline-flex h-3.5 w-7 items-center rounded-full px-0.5 py-px transition-colors duration-200 ease-in-out",
          isPublic ? "bg-contrast" : "bg-base-secondary",
        )}
      >
        <span
          className={cn(
            "block h-2 w-2 shrink-0 rounded-full transition-transform duration-200 ease-in-out",
            isPublic
              ? "translate-x-[calc(1rem-1px)] bg-base-secondary"
              : "translate-x-px bg-tertiary-light",
          )}
        />
      </span>
    </label>
  );
}

export function ConversationNameContextMenu({
  onClose,
  onRename,
  onDelete,
  onStop,
  onDisplayCost,
  onShowAgentTools,
  onShowSkills,
  onShowHooks,
  onTogglePublic,
  onCopyShareLink,
  onExportTranscript,
  onDownloadConversation,
  shareUrl,
  position = "bottom",
  anchorRef,
}: ConversationNameContextMenuProps) {
  const isMobile = useBreakpoint();

  const { t } = useTranslation("openhands");
  const { backend } = useActiveBackend();
  const { data: conversation } = useActiveConversation();
  const isArchivedConversation = useIsArchivedConversation();
  const ref = useClickOutsideElement<HTMLUListElement>(onClose, anchorRef);

  const anchorElement = anchorRef?.current ?? null;
  const [portalStyle, setPortalStyle] = React.useState<React.CSSProperties>();
  // The menu's width is only measurable once it is in the portal, so placement
  // runs again right after the first positioned render, still before paint.
  const isMenuMounted = portalStyle !== undefined;
  React.useLayoutEffect(() => {
    if (!anchorElement) return undefined;

    const updatePosition = () => {
      const rect = anchorElement.getBoundingClientRect();
      if (!rect) return;
      const gap = 8;
      const style: React.CSSProperties = {
        position: "fixed",
        zIndex: 9999,
      };
      if (position === "top") {
        style.bottom = window.innerHeight - rect.top + gap;
      } else {
        style.top = rect.bottom + gap;
      }
      // At phone width the trigger sits near the right edge: keep the whole
      // menu, and every label, inside the viewport.
      const menuWidth = ref.current?.getBoundingClientRect().width ?? 0;
      style.left = clampLeftToViewport(rect.left, menuWidth);
      setPortalStyle(style);
    };

    updatePosition();
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [anchorElement, position, isMenuMounted, ref]);

  React.useEffect(() => {
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      onClose();
      anchorElement?.focus();
    };

    document.addEventListener("keydown", handleEscape);
    return () => document.removeEventListener("keydown", handleEscape);
  }, [onClose, anchorElement]);
  const hasTools = Boolean(onShowAgentTools || onShowSkills || onShowHooks);
  const hasInfo = Boolean(onDisplayCost);
  const hasControl = Boolean(onStop || onDelete);
  const stopLabelKey =
    backend.kind === "cloud"
      ? I18nKey.COMMON$CLOSE_CONVERSATION_STOP_RUNTIME
      : I18nKey.COMMON$STOP_CONVERSATION;
  const shouldShowPublicSharing =
    backend.kind === "cloud" && Boolean(onTogglePublic);
  const isPublic = conversation?.public || false;

  const isPortaled = Boolean(anchorElement);
  const portalClassName = isPortaled
    ? "!static !top-auto !bottom-auto !left-auto !right-auto !mt-0"
    : "";

  const menu = (
    <ContextMenu
      ref={ref}
      testId="conversation-name-context-menu"
      position={position}
      alignment="left"
      className={cn(
        // The mobile offset only applies to the inline, absolutely positioned
        // menu; the portaled menu gets its coordinates from `portalStyle`.
        !isPortaled && isMobile ? "right-0 translate-x-[34%] left-auto" : "",
        portalClassName,
      )}
    >
      {onRename && (
        <ContextMenuListItem testId="rename-button" onClick={onRename}>
          <ConversationNameContextMenuIconText
            icon={<EditIcon width={16} height={16} />}
            text={t(I18nKey.BUTTON$RENAME)}
          />
        </ContextMenuListItem>
      )}

      {hasTools && <Divider testId="separator-tools" inset="menu" />}

      {onShowSkills && (
        <ArchivedDisabledTooltip isDisabled={isArchivedConversation}>
          <ContextMenuListItem
            testId="show-skills-button"
            onClick={onShowSkills}
            isDisabled={isArchivedConversation}
          >
            <ConversationNameContextMenuIconText
              icon={
                <SkillsIcon
                  width={16}
                  height={16}
                  className="stroke-[1.75]"
                  aria-hidden
                />
              }
              text={t(I18nKey.CONVERSATION$SHOW_SKILLS)}
            />
          </ContextMenuListItem>
        </ArchivedDisabledTooltip>
      )}

      {onShowHooks && (
        <ArchivedDisabledTooltip isDisabled={isArchivedConversation}>
          <ContextMenuListItem
            testId="show-hooks-button"
            onClick={onShowHooks}
            isDisabled={isArchivedConversation}
          >
            <ConversationNameContextMenuIconText
              icon={<FishingHookIcon width={16} height={16} aria-hidden />}
              text={t(I18nKey.CONVERSATION$SHOW_HOOKS)}
            />
          </ContextMenuListItem>
        </ArchivedDisabledTooltip>
      )}

      {onShowAgentTools && (
        <ArchivedDisabledTooltip isDisabled={isArchivedConversation}>
          <ContextMenuListItem
            testId="show-agent-tools-button"
            onClick={onShowAgentTools}
            isDisabled={isArchivedConversation}
          >
            <ConversationNameContextMenuIconText
              icon={<ToolsIcon width={16} height={16} />}
              text={t(I18nKey.BUTTON$SHOW_AGENT_TOOLS_AND_METADATA)}
            />
          </ContextMenuListItem>
        </ArchivedDisabledTooltip>
      )}

      {onExportTranscript && (
        <ContextMenuListItem
          testId="export-transcript-button"
          onClick={onExportTranscript}
        >
          <ConversationNameContextMenuIconText
            icon={<DownloadIcon width={16} height={16} />}
            text={t(I18nKey.BUTTON$EXPORT_TRANSCRIPT)}
          />
        </ContextMenuListItem>
      )}

      {onDownloadConversation && (
        <ContextMenuListItem
          testId="download-trajectory-button"
          onClick={onDownloadConversation}
        >
          <ConversationNameContextMenuIconText
            icon={<DownloadIcon width={16} height={16} />}
            text={t(I18nKey.BUTTON$DOWNLOAD_CONVERSATION_DATA)}
          />
        </ContextMenuListItem>
      )}

      {(hasInfo || hasControl) && (
        <Divider testId="separator-info-control" inset="menu" />
      )}

      {onDisplayCost && (
        <ContextMenuListItem
          testId="display-cost-button"
          onClick={onDisplayCost}
        >
          <ConversationNameContextMenuIconText
            icon={<Gauge size={16} />}
            text={t(I18nKey.BUTTON$DISPLAY_COST)}
          />
        </ContextMenuListItem>
      )}

      {shouldShowPublicSharing && onTogglePublic && (
        <li className="flex w-full items-center gap-2 rounded px-2 py-2 hover:bg-interactive-hover">
          <span className="flex shrink-0 items-center text-muted" aria-hidden>
            <Share2 size={16} />
          </span>
          <span className="min-w-0 flex-1 truncate text-sm">
            {t(I18nKey.CONVERSATION$SHARE_PUBLICLY)}
          </span>
          <div className="flex shrink-0 items-center">
            {isPublic && shareUrl && onCopyShareLink && (
              <div className="mr-2 flex items-center gap-0.5">
                <button
                  type="button"
                  data-testid="copy-share-link-button"
                  onClick={onCopyShareLink}
                  className="rounded p-0.5 text-muted hover:bg-interactive-selected hover:text-foreground cursor-pointer [&_svg]:text-current"
                  title={t(I18nKey.BUTTON$COPY_TO_CLIPBOARD)}
                >
                  <CopyIcon width={14} height={14} />
                </button>
                <a
                  data-testid="open-share-link-button"
                  href={shareUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  onClick={(event) => event.stopPropagation()}
                  className="rounded p-0.5 text-muted no-underline visited:text-muted hover:bg-interactive-selected hover:text-foreground cursor-pointer [&_svg]:text-current"
                  title={t(I18nKey.BUTTON$OPEN_IN_NEW_TAB)}
                >
                  <ExternalLink size={14} aria-hidden />
                </a>
              </div>
            )}
            <PublicShareToggle
              isPublic={isPublic}
              onToggle={onTogglePublic}
              ariaLabel={t(I18nKey.CONVERSATION$SHARE_PUBLICLY)}
            />
          </div>
        </li>
      )}

      {onStop && (
        <ArchivedDisabledTooltip isDisabled={isArchivedConversation}>
          <ContextMenuListItem
            testId="stop-button"
            onClick={onStop}
            isDisabled={isArchivedConversation}
          >
            <ConversationNameContextMenuIconText
              icon={<CloseIcon width={16} height={16} />}
              text={t(stopLabelKey)}
            />
          </ContextMenuListItem>
        </ArchivedDisabledTooltip>
      )}

      {onDelete && (
        <ContextMenuListItem testId="delete-button" onClick={onDelete}>
          <ConversationNameContextMenuIconText
            icon={<DeleteIcon width={16} height={16} />}
            text={t(I18nKey.COMMON$DELETE_CONVERSATION)}
          />
        </ContextMenuListItem>
      )}
    </ContextMenu>
  );

  if (isPortaled) {
    if (typeof document === "undefined" || !portalStyle) {
      return null;
    }
    return ReactDOM.createPortal(
      <div style={portalStyle}>{menu}</div>,
      document.body,
    );
  }

  return menu;
}

import React from "react";
import { useTranslation } from "react-i18next";
import { useAgentState } from "#/hooks/use-agent-state";
import { useTaskPolling } from "#/hooks/query/use-task-polling";
import { useActiveConversation } from "#/hooks/query/use-active-conversation";
import { useUnifiedPauseConversation } from "#/hooks/mutation/use-unified-stop-conversation";
import { useUnifiedResumeConversation } from "#/hooks/mutation/use-unified-start-conversation";
import { useConversationId } from "#/hooks/use-conversation-id";
import { useCloseOnEscape } from "#/hooks/use-close-on-escape";
import { useUserProviders } from "#/hooks/use-user-providers";
import { getStatusColor, cn } from "#/utils/utils";
import { AgentState } from "#/types/agent-state";
import DebugStackframeDot from "#/icons/debug-stackframe-dot.svg?react";
import { ServerStatusContextMenu } from "../controls/server-status-context-menu";
import { ConversationName } from "./conversation-name";
import { ConversationGitActionsToggle } from "./conversation-git-actions-toggle";
import { ConversationOverviewToggle } from "./conversation-overview-toggle";
import { RightPanelToggle } from "./right-panel-toggle";
import {
  isExecutionActive,
  isExecutionErrored,
  isExecutionPaused,
} from "#/utils/status";
import { I18nKey } from "#/i18n/declaration";

export function ConversationNameWithStatus() {
  const { t } = useTranslation("openhands");
  const { conversationId } = useConversationId();
  const { data: conversation } = useActiveConversation();
  const { curAgentState } = useAgentState();
  const { isTask, taskStatus } = useTaskPolling();
  const { mutate: pauseConversation } = useUnifiedPauseConversation();
  const { mutate: resumeConversation } = useUnifiedResumeConversation();
  const { providers } = useUserProviders();
  const [menuOpen, setMenuOpen] = React.useState(false);
  const [hoveredOpen, setHoveredOpen] = React.useState(false);
  const triggerRef = React.useRef<HTMLButtonElement>(null);

  const executionStatus = conversation?.execution_status ?? null;
  const isStartingStatus =
    curAgentState === AgentState.LOADING || curAgentState === AgentState.INIT;
  const isStopStatus = isExecutionErrored(executionStatus);

  const statusColor = getStatusColor({
    isPausing: false,
    isTask,
    taskStatus,
    isStartingStatus,
    isStopStatus,
    curAgentState,
  });

  const isMenuVisible = menuOpen || hoveredOpen;

  const closeMenu = () => {
    setMenuOpen(false);
    setHoveredOpen(false);
  };

  // A menu opened by click or Enter returns focus to the dot; one opened by
  // hover closes without moving focus.
  useCloseOnEscape(isMenuVisible, closeMenu, menuOpen ? triggerRef : undefined);

  const handleStopServer = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    if (conversationId) {
      pauseConversation({ conversationId });
    }
    closeMenu();
  };

  const handleStartServer = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    if (conversationId) {
      resumeConversation({ conversationId, providers });
    }
    closeMenu();
  };

  const handleStatusClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    // Click toggles for touch; on desktop it also dismisses a hover-opened menu
    // instead of "pinning" it open under the cursor.
    if (isMenuVisible) {
      closeMenu();
      return;
    }
    setMenuOpen(true);
  };

  return (
    <div className="flex items-center justify-between w-full">
      <div className="flex items-center min-w-0">
        <div
          className="relative shrink-0"
          onPointerEnter={(event) => {
            // Gate on this event's pointer, not device-primary matchMedia — hybrid
            // laptops can emit compatibility mouseenter for touchscreen taps.
            if (event.pointerType === "mouse") {
              setHoveredOpen(true);
            }
          }}
          onPointerLeave={(event) => {
            if (event.pointerType === "mouse") {
              setHoveredOpen(false);
            }
          }}
        >
          <button
            ref={triggerRef}
            type="button"
            data-testid="server-status-menu-trigger"
            aria-label={t(I18nKey.COMMON$SERVER_STATUS)}
            aria-expanded={isMenuVisible}
            aria-haspopup="menu"
            onClick={handleStatusClick}
            className={cn(
              "flex items-center justify-center rounded-md",
              "text-muted hover:bg-contrast/10",
            )}
          >
            <DebugStackframeDot
              className="ml-[3.5px] w-6 h-6 cursor-pointer"
              color={statusColor}
              aria-hidden
            />
          </button>
          {isMenuVisible ? (
            <ServerStatusContextMenu
              onClose={closeMenu}
              ignoreOutsideClickRef={triggerRef}
              onStopServer={
                isExecutionActive(executionStatus)
                  ? handleStopServer
                  : undefined
              }
              onStartServer={
                isExecutionPaused(executionStatus)
                  ? handleStartServer
                  : undefined
              }
              executionStatus={executionStatus}
              position="bottom"
              className="bottom-full left-0 mt-0 min-h-fit"
              isPausing={false}
            />
          ) : null}
        </div>
        <ConversationName />
      </div>
      <div className="mr-2 flex shrink-0 items-center gap-1">
        <ConversationGitActionsToggle />
        <ConversationOverviewToggle />
        <RightPanelToggle />
      </div>
    </div>
  );
}

