export function ConversationOverviewContextMenu({
  isOpen,
  onClose,
  ignoreOutsideClickRef,
  anchorRef,
}: ConversationOverviewContextMenuProps) {
  const ref = useClickOutsideElement<HTMLUListElement>(
    onClose,
    ignoreOutsideClickRef,
  );
  const [portalStyle, setPortalStyle] = useState<React.CSSProperties>();
  const { t } = useTranslation("openhands");
  const { conversationId } = useConversationId();
  const { state, setUnpinnedOverviewSections, setUnpinnedOverviewGitParts } =
    useConversationLocalStorageState(conversationId);
  const { navigateToChanges, navigateToCommits } = useSelectConversationTab();
  const overviewDrawer = useConversationOverviewDrawerOptional();

  useLayoutEffect(() => {
    if (!isOpen || !anchorRef?.current) {
      setPortalStyle(undefined);
      return undefined;
    }

    const updatePosition = () => {
      const rect = anchorRef.current?.getBoundingClientRect();
      if (!rect) return;

      const gap = 8;
      setPortalStyle({
        position: "fixed",
        zIndex: 9999,
        top: rect.bottom + gap,
        right: window.innerWidth - rect.right,
      });
    };

    updatePosition();
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [isOpen, anchorRef]);

  const handleOpenGitPart = (item: GitPartMenuItem) => {
    if (item.opensChanges) {
      overviewDrawer?.closeDrawer();
      navigateToChanges();
      onClose();
      return;
    }

    if (item.opensCommits) {
      overviewDrawer?.closeDrawer();
      navigateToCommits();
      onClose();
      return;
    }

    if (!item.drawerSection) return;
    overviewDrawer?.openSection(item.drawerSection);
    onClose();
  };

  const handlePinToggle = (
    section: ConversationOverviewSection,
    event: React.MouseEvent,
  ) => {
    event.preventDefault();
    event.stopPropagation();

    const unpinnedSections = state.unpinnedOverviewSections ?? [];
    if (unpinnedSections.includes(section)) {
      setUnpinnedOverviewSections?.(
        unpinnedSections.filter((item) => item !== section),
      );
      return;
    }

    setUnpinnedOverviewSections?.([...unpinnedSections, section]);
  };

  const handleGitPartPinToggle = (
    part: ConversationOverviewGitPart,
    event: React.MouseEvent,
  ) => {
    event.preventDefault();
    event.stopPropagation();

    const unpinnedGitParts = state.unpinnedOverviewGitParts ?? [];
    if (unpinnedGitParts.includes(part)) {
      setUnpinnedOverviewGitParts?.(
        unpinnedGitParts.filter((item) => item !== part),
      );
      return;
    }

    setUnpinnedOverviewGitParts?.([...unpinnedGitParts, part]);
  };

  if (!isOpen) return null;

  const isPortaled = Boolean(anchorRef?.current && portalStyle);
  const gitPinned = isOverviewSectionPinned(
    CONVERSATION_OVERVIEW_SECTION.git,
    state.unpinnedOverviewSections ?? [],
  );
  const pinnedLabel = t(I18nKey.CONVERSATION$UNPIN_OVERVIEW_SECTION);
  const unpinnedLabel = t(I18nKey.CONVERSATION$PIN_OVERVIEW_SECTION);

  const renderMenuRow = ({
    key,
    testIdOpen,
    testIdPin,
    icon: Icon,
    label,
    pinned,
    isActionable,
    indent = false,
    onOpen,
    onPinToggle,
  }: {
    key: string;
    testIdOpen: string;
    testIdPin: string;
    icon: React.ComponentType<{ className?: string }>;
    label: string;
    pinned: boolean;
    isActionable: boolean;
    indent?: boolean;
    onOpen?: () => void;
    onPinToggle: (event: React.MouseEvent) => void;
  }) => {
    const labelContent = (
      <>
        <span className={dropdownMenuRowIconWrapperClassName} aria-hidden>
          <Icon className="h-4 w-4" />
        </span>
        <span className="text-sm">{label}</span>
      </>
    );

    return (
      <li key={key} className="list-none">
        <div
          className={cn(
            "group flex h-7.5 w-full min-w-0 items-stretch rounded hover:bg-interactive-hover",
            indent && "pl-4",
          )}
        >
          {isActionable ? (
            <button
              type="button"
              data-testid={testIdOpen}
              className={cn(
                "flex min-w-0 flex-1 cursor-pointer items-center gap-2 rounded-l p-2 text-start text-contrast",
                dropdownInstantColorClassName,
              )}
              onClick={onOpen}
            >
              {labelContent}
            </button>
          ) : (
            <div
              data-testid={testIdOpen}
              className={cn(
                "flex min-w-0 flex-1 items-center gap-2 rounded-l p-2 text-start text-contrast",
                dropdownInstantColorClassName,
              )}
            >
              {labelContent}
            </div>
          )}
          <OverviewPinButton
            testId={testIdPin}
            pinned={pinned}
            pinnedLabel={pinnedLabel}
            unpinnedLabel={unpinnedLabel}
            onClick={onPinToggle}
          />
        </div>
      </li>
    );
  };

  const renderSectionRow = (section: ConversationOverviewSection) => {
    if (section === CONVERSATION_OVERVIEW_SECTION.git) return null;
    const item = OVERVIEW_MENU_ITEMS_BY_SECTION[section];
    return renderMenuRow({
      key: section,
      testIdOpen: `conversation-overview-menu-open-${section}`,
      testIdPin: `conversation-overview-menu-pin-${section}`,
      icon: item.icon,
      label: t(item.i18nKey),
      pinned: isOverviewSectionPinned(
        section,
        state.unpinnedOverviewSections ?? [],
      ),
      isActionable: false,
      onPinToggle: (event) => handlePinToggle(section, event),
    });
  };

  const menu = (
    <ContextMenu
      ref={ref}
      testId="conversation-overview-context-menu"
      theme={isPortaled ? "popover" : "default"}
      position={isPortaled ? "none" : "bottom"}
      alignment={isPortaled ? "none" : "right"}
      spacing={isPortaled ? "none" : "default"}
      className={cn("z-[9999] w-fit", isPortaled ? "mt-0" : "mt-2")}
    >
      {CONVERSATION_OVERVIEW_SECTION_GROUPS.map((group, groupIndex) => (
        <React.Fragment key={group.sections.join("-")}>
          {groupIndex > 0 ? (
            <Divider
              testId={`conversation-overview-menu-divider-${groupIndex}`}
              inset="menu"
            />
          ) : null}
          {group.sections.map((section) => renderSectionRow(section))}
        </React.Fragment>
      ))}

      <Divider testId="conversation-overview-menu-divider-git" inset="menu" />

      {renderMenuRow({
        key: CONVERSATION_OVERVIEW_SECTION.git,
        testIdOpen: `conversation-overview-menu-open-${CONVERSATION_OVERVIEW_SECTION.git}`,
        testIdPin: `conversation-overview-menu-pin-${CONVERSATION_OVERVIEW_SECTION.git}`,
        icon: GitBranch,
        label: t(I18nKey.CONVERSATION$OVERVIEW_GIT),
        pinned: gitPinned,
        isActionable: false,
        onPinToggle: (event) =>
          handlePinToggle(CONVERSATION_OVERVIEW_SECTION.git, event),
      })}

      {GIT_PART_MENU_ITEMS.map((item) =>
        renderMenuRow({
          key: item.part,
          testIdOpen: `conversation-overview-menu-open-git-${item.part}`,
          testIdPin: `conversation-overview-menu-pin-git-${item.part}`,
          icon: item.icon,
          label: t(item.i18nKey),
          pinned: isOverviewGitPartPinned(
            item.part,
            state.unpinnedOverviewGitParts ?? [],
          ),
          isActionable: Boolean(
            item.drawerSection || item.opensCommits || item.opensChanges,
          ),
          indent: true,
          onOpen: () => handleOpenGitPart(item),
          onPinToggle: (event) => handleGitPartPinToggle(item.part, event),
        }),
      )}
    </ContextMenu>
  );

  if (isPortaled && portalStyle && typeof document !== "undefined") {
    return ReactDOM.createPortal(
      <div style={portalStyle}>{menu}</div>,
      document.body,
    );
  }

  return menu;
}

import React, { useEffect, useRef, useState } from "react";
import { GitCommitHorizontal } from "lucide-react";
import { LuFileDiff } from "react-icons/lu";
import { useTranslation } from "react-i18next";
import { useActiveConversation } from "#/hooks/query/use-active-conversation";
import { useConversationOverviewGitDiffStats } from "#/hooks/use-conversation-overview-git-diff-stats";
import { useSelectConversationTab } from "#/hooks/use-select-conversation-tab";
import { I18nKey } from "#/i18n/declaration";
import {
  OH_STATUS_ERROR_COLOR,
  OH_STATUS_SUCCESS_COLOR,
} from "#/constants/status-colors";
import { cn } from "#/utils/utils";
import { Provider } from "#/types/settings";
import { useConversationOverviewDrawerOptional } from "./conversation-overview-drawer-context";
import { ConversationGitActionsMenu } from "./conversation-git-actions-menu";

const CHANGES_BUTTON_CLASSNAME = cn(
  "flex min-w-0 flex-1 items-center gap-2 rounded-md px-2 py-1.5",
  "cursor-pointer border-0 bg-transparent text-left",
);

const ROW_ICON_CLASSNAME = "size-4 shrink-0 text-muted";

const GIT_ACTION_HOVER_TARGET_CLASSNAME =
  "conversation-overview-diffs-git-action";

const GIT_ACTION_BUTTON_CLASSNAME = cn(
  GIT_ACTION_HOVER_TARGET_CLASSNAME,
  "absolute inset-0 inline-flex items-center justify-center",
  "rounded-md text-muted transition-opacity",
  "hover:bg-contrast/10 hover:text-foreground",
);

/** Full-row hover, cleared while the git commit control itself is hovered. */
const DIFFS_ROW_CLASSNAME = cn(
  "flex items-center rounded-md transition-colors",
  "hover:bg-contrast/5",
  `has-[.${GIT_ACTION_HOVER_TARGET_CLASSNAME}:hover]:bg-transparent`,
);

const GIT_ACTION_OVERLAY_CLASSNAME = cn(
  "pointer-events-none invisible opacity-0",
  "group-hover/diffstats:pointer-events-auto group-hover/diffstats:visible group-hover/diffstats:opacity-100",
  "group-focus-within/diffstats:pointer-events-auto group-focus-within/diffstats:visible group-focus-within/diffstats:opacity-100",
);

export function ConversationOverviewDiffsRow() {
  const { t } = useTranslation("openhands");
  const { navigateToChanges } = useSelectConversationTab();
  const overviewDrawer = useConversationOverviewDrawerOptional();
  const { data: conversation } = useActiveConversation();
  const { additions, deletions, isLoading } =
    useConversationOverviewGitDiffStats();
  const gitProvider =
    (conversation?.git_provider as Provider | undefined) ?? "github";
  const [isGitMenuOpen, setIsGitMenuOpen] = useState(false);
  const gitActionButtonRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!isGitMenuOpen) {
      return undefined;
    }

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsGitMenuOpen(false);
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [isGitMenuOpen]);

  const handleOpenChanges = () => {
    overviewDrawer?.closeDrawer();
    navigateToChanges();
  };

  return (
    <li className={DIFFS_ROW_CLASSNAME}>
      <button
        type="button"
        data-testid="conversation-overview-diffs"
        aria-label={t(I18nKey.CONVERSATION$OVERVIEW_OPEN_CHANGES)}
        onClick={handleOpenChanges}
        className={CHANGES_BUTTON_CLASSNAME}
      >
        <LuFileDiff className={ROW_ICON_CLASSNAME} aria-hidden />
        <span className="min-w-0 flex-1 truncate text-sm text-foreground">
          {t(I18nKey.COMMON$CHANGES)}
        </span>
      </button>

      <div className="group/diffstats relative mr-2 flex h-6 min-w-6 shrink-0 items-center justify-center">
        {isLoading ? (
          <span className="text-sm tabular-nums text-muted">…</span>
        ) : (
          <>
            <span
              className={cn(
                "flex items-center gap-1.5 text-sm tabular-nums transition-opacity",
                isGitMenuOpen
                  ? "opacity-0"
                  : "group-hover/diffstats:opacity-0 group-focus-within/diffstats:opacity-0",
              )}
            >
              <span
                data-testid="conversation-overview-diffs-additions"
                style={{ color: OH_STATUS_SUCCESS_COLOR }}
              >
                {t(I18nKey.CONVERSATION$OVERVIEW_DIFF_ADDITIONS, {
                  count: additions.toLocaleString(),
                })}
              </span>
              <span
                data-testid="conversation-overview-diffs-deletions"
                style={{ color: OH_STATUS_ERROR_COLOR }}
              >
                {t(I18nKey.CONVERSATION$OVERVIEW_DIFF_DELETIONS, {
                  count: deletions.toLocaleString(),
                })}
              </span>
            </span>
            <button
              ref={gitActionButtonRef}
              type="button"
              data-testid="conversation-overview-diffs-git-action"
              aria-label={t(I18nKey.CONVERSATION$OVERVIEW_DIFF_GIT_ACTIONS)}
              aria-expanded={isGitMenuOpen}
              aria-haspopup="menu"
              onClick={(event) => {
                event.stopPropagation();
                setIsGitMenuOpen((open) => !open);
              }}
              className={cn(
                GIT_ACTION_BUTTON_CLASSNAME,
                !isGitMenuOpen && GIT_ACTION_OVERLAY_CLASSNAME,
                isGitMenuOpen &&
                  "pointer-events-auto visible opacity-100 text-foreground",
              )}
            >
              <GitCommitHorizontal className="size-4" aria-hidden />
            </button>
            {isGitMenuOpen ? (
              <ConversationGitActionsMenu
                anchorRef={gitActionButtonRef}
                gitProvider={gitProvider}
                testIdPrefix="conversation-overview-diffs-git"
                onClose={() => setIsGitMenuOpen(false)}
              />
            ) : null}
          </>
        )}
      </div>
    </li>
  );
}

import type { RefObject } from "react";
import { ResizeHandle } from "#/components/ui/resize-handle";
import { useResizableDrawerWidth } from "#/hooks/use-resizable-drawer-width";
import { cn } from "#/utils/utils";
import { ConversationOverviewDrawerContent } from "./conversation-overview-drawer-content";
import { useConversationOverviewDrawerOptional } from "./conversation-overview-drawer-context";
import {
  CONVERSATION_OVERVIEW_DRAWER_DEFAULT_WIDTH_PX,
  CONVERSATION_OVERVIEW_DRAWER_MAX_WIDTH_PX,
  CONVERSATION_OVERVIEW_DRAWER_MIN_WIDTH_PX,
  CONVERSATION_OVERVIEW_DRAWER_RESIZE_HANDLE_TEST_ID,
  CONVERSATION_OVERVIEW_DRAWER_TEST_ID,
  CONVERSATION_OVERVIEW_DRAWER_WIDTH_STORAGE_KEY,
} from "./conversation-overview-drawer.constants";

function getOverviewDrawerClass(isOpen: boolean) {
  return isOpen
    ? "translate-x-0 opacity-100"
    : "w-0 translate-x-full opacity-0";
}

interface ConversationOverviewDrawerProps {
  isMobile: boolean;
  resizeContainerRef?: RefObject<HTMLElement | null>;
}

export function ConversationOverviewDrawer({
  isMobile,
  resizeContainerRef,
}: ConversationOverviewDrawerProps) {
  const overviewDrawer = useConversationOverviewDrawerOptional();
  const isOpen = Boolean(overviewDrawer?.section);

  const { drawerWidth, isDragging, handleMouseDown } = useResizableDrawerWidth({
    containerRef: resizeContainerRef ?? { current: null },
    defaultWidth: CONVERSATION_OVERVIEW_DRAWER_DEFAULT_WIDTH_PX,
    minWidth: CONVERSATION_OVERVIEW_DRAWER_MIN_WIDTH_PX,
    maxWidth: CONVERSATION_OVERVIEW_DRAWER_MAX_WIDTH_PX,
    storageKey: CONVERSATION_OVERVIEW_DRAWER_WIDTH_STORAGE_KEY,
    enabled: isOpen && !isMobile && resizeContainerRef != null,
  });

  if (!overviewDrawer) {
    return null;
  }

  if (isMobile) {
    if (!isOpen) {
      return null;
    }

    return (
      <ConversationOverviewDrawerContent className="max-h-[min(50vh,420px)] w-full border-t border-border" />
    );
  }

  return (
    <>
      {isOpen && resizeContainerRef ? (
        <div data-testid={CONVERSATION_OVERVIEW_DRAWER_RESIZE_HANDLE_TEST_ID}>
          <ResizeHandle onMouseDown={handleMouseDown} isDragging={isDragging} />
        </div>
      ) : null}
      <div
        data-testid={CONVERSATION_OVERVIEW_DRAWER_TEST_ID}
        aria-hidden={!isOpen}
        className={cn(
          "shrink-0 overflow-hidden ease-in-out",
          isDragging
            ? "transition-[transform,opacity] duration-300"
            : "transition-all duration-300",
          getOverviewDrawerClass(isOpen),
        )}
        style={{
          width: isOpen ? `${drawerWidth}px` : "0px",
          transitionProperty: isDragging
            ? "transform, opacity"
            : "width, transform, opacity",
        }}
      >
        <div
          className="flex h-full flex-col overflow-hidden border-l border-border bg-base-secondary"
          style={{ width: `${drawerWidth}px` }}
        >
          {isOpen ? (
            <ConversationOverviewDrawerContent className="h-full" />
          ) : null}
        </div>
      </div>
    </>
  );
}

