type OverviewPanelBlock =
  | {
      kind: "sections";
      key: string;
      sections: ConversationOverviewSection[];
    }
  | { kind: "git"; key: "git" };

export function ConversationOverviewPanel() {
  const { t } = useTranslation("openhands");
  const stats = useConversationOverviewStats();
  const { conversationId } = useConversationId();
  const { state } = useConversationLocalStorageState(conversationId);
  const { isConnected: isGitConnected } = useConversationPrimaryRepository();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const menuAnchorRef = useRef<HTMLButtonElement>(null);
  useCloseOnEscape(isMenuOpen, () => setIsMenuOpen(false), menuAnchorRef);

  const isPinned = (section: ConversationOverviewSection) =>
    isOverviewSectionPinned(section, state.unpinnedOverviewSections ?? []);

  const showChanges = isOverviewGitPartPinned(
    CONVERSATION_OVERVIEW_GIT_PART.changes,
    state.unpinnedOverviewGitParts ?? [],
  );

  const showGitBlock =
    isPinned(CONVERSATION_OVERVIEW_SECTION.git) &&
    (showChanges || isGitConnected);

  const workspaceSections = CONVERSATION_OVERVIEW_SECTION_GROUPS.flatMap(
    (group) => group.sections.filter((section) => isPinned(section)),
  );

  // Git content first (untitled); Workspace sits below it.
  const panelBlocks: OverviewPanelBlock[] = [];
  if (showGitBlock) {
    panelBlocks.push({ kind: "git", key: "git" });
  }
  if (workspaceSections.length > 0) {
    panelBlocks.push({
      kind: "sections",
      key: workspaceSections.join("-"),
      sections: workspaceSections,
    });
  }

  const renderSection = (section: ConversationOverviewSection) => {
    switch (section) {
      case CONVERSATION_OVERVIEW_SECTION.workspace:
        return (
          <OverviewRow
            key={section}
            testId="conversation-overview-workspace"
            icon={<Laptop className={ROW_ICON_CLASSNAME} />}
            label={t(I18nKey.CONVERSATION$OVERVIEW_WORKSPACE)}
            value={stats.workspaceName ?? t(I18nKey.CONVERSATION$OVERVIEW_NONE)}
          />
        );
      case CONVERSATION_OVERVIEW_SECTION.git:
        // Rendered as its own panel block (not a group row).
        return null;
      default: {
        const _exhaustive: never = section;
        return _exhaustive;
      }
    }
  };

  return (
    <aside
      data-testid="conversation-overview-panel"
      aria-label={t(I18nKey.CONVERSATION$OVERVIEW)}
      className={PANEL_CLASSNAME}
    >
      <div className="flex items-center justify-between px-4 pb-0.5 pt-2.5">
        <span className="text-xs font-medium text-muted">
          {t(I18nKey.CONVERSATION$OVERVIEW)}
        </span>
        <div className="relative shrink-0">
          <EllipsisButton
            ref={menuAnchorRef}
            testId="conversation-overview-ellipsis"
            onClick={() => setIsMenuOpen((open) => !open)}
            ariaLabel={t(I18nKey.COMMON$MORE_OPTIONS)}
          />
          <ConversationOverviewContextMenu
            isOpen={isMenuOpen}
            onClose={() => setIsMenuOpen(false)}
            ignoreOutsideClickRef={menuAnchorRef}
            anchorRef={menuAnchorRef}
          />
        </div>
      </div>

      {panelBlocks.map((block, blockIndex) => (
        <React.Fragment key={block.key}>
          {blockIndex > 0 ? <OverviewSectionDivider /> : null}
          {block.kind === "git" ? (
            <div data-testid="conversation-overview-git-block">
              {showChanges ? (
                <ul className="px-2">
                  <ConversationOverviewDiffsRow />
                </ul>
              ) : null}
              {isGitConnected ? <ConversationOverviewGitSection /> : null}
            </div>
          ) : (
            <ul className="px-2">
              {block.sections.map((section) => renderSection(section))}
            </ul>
          )}
        </React.Fragment>
      ))}
    </aside>
  );
}

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import ReactDOM from "react-dom";
import { Info } from "lucide-react";
import { useTranslation } from "react-i18next";
import { useConversationStore } from "#/stores/conversation-store";
import {
  openConversationOverviewPanelPeek,
  scheduleCloseConversationOverviewPanelPeek,
  useSyncConversationOverviewPanelPeek,
} from "#/hooks/use-conversation-overview-panel-peek";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import { mobileTopBarIconButtonClassName } from "#/utils/mobile-top-bar-icon-button-classes";
import { ChatActionTooltip } from "../chat/chat-action-tooltip";
import { useIsArchivedConversation } from "#/hooks/use-is-archived-conversation";
import { useOptionalConversationId } from "#/hooks/use-conversation-id";
import { setConversationState } from "#/utils/conversation-local-storage";
import { ConversationOverviewPanel } from "./conversation-overview-panel";
import { CONVERSATION_OVERVIEW_PANEL_WIDTH_PX } from "./conversation-overview-panel.constants";

interface ConversationOverviewToggleProps {
  className?: string;
}

/**
 * Info toggle for the session-only overview panel beside the chat thread.
 * Opening overview closes the files/diffs drawer; the panel also auto-hides
 * when that drawer opens from elsewhere. While the drawer is open, hovering
 * this control peeks the overview as a portaled overlay.
 */
export function ConversationOverviewToggle({
  className,
}: ConversationOverviewToggleProps) {
  const { t } = useTranslation("openhands");
  const isArchivedConversation = useIsArchivedConversation();
  const { conversationId } = useOptionalConversationId();
  const triggerRef = useRef<HTMLDivElement>(null);
  const [peekPosition, setPeekPosition] = useState<{
    top: number;
    left: number;
  } | null>(null);
  const {
    isOverviewPanelShown,
    isOverviewPanelPeeked,
    isRightPanelShown,
    setIsOverviewPanelShown,
    setHasRightPanelToggled,
    setIsRightPanelShown,
  } = useConversationStore();

  useSyncConversationOverviewPanelPeek();

  useEffect(() => {
    if (isRightPanelShown && isOverviewPanelShown) {
      setIsOverviewPanelShown(false);
    }
  }, [isOverviewPanelShown, isRightPanelShown, setIsOverviewPanelShown]);

  const canPeekOnHover =
    !isArchivedConversation && isRightPanelShown && !isOverviewPanelShown;
  const showPeek = canPeekOnHover && isOverviewPanelPeeked;

  useLayoutEffect(() => {
    if (!showPeek) {
      setPeekPosition(null);
      return undefined;
    }

    const updatePosition = () => {
      const rect = triggerRef.current?.getBoundingClientRect();
      if (!rect) {
        return;
      }

      setPeekPosition({
        top: rect.bottom + 4,
        left: Math.max(8, rect.right - CONVERSATION_OVERVIEW_PANEL_WIDTH_PX),
      });
    };

    updatePosition();
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [showPeek]);

  const handleToggle = () => {
    if (isArchivedConversation) {
      return;
    }

    // Reveal overview by closing the files/diffs drawer first; otherwise the
    // mutual-exclusion effect above would immediately hide overview again.
    if (isRightPanelShown) {
      setHasRightPanelToggled(false);
      setIsRightPanelShown(false);
      if (conversationId) {
        setConversationState(conversationId, { rightPanelShown: false });
      }
      setIsOverviewPanelShown(true);
      return;
    }

    setIsOverviewPanelShown(!isOverviewPanelShown);
  };

  const isOverviewVisible = isOverviewPanelShown || showPeek;

  const tooltipText = isArchivedConversation
    ? t(I18nKey.CONVERSATION$UNAVAILABLE_FOR_ARCHIVES)
    : isOverviewPanelShown
      ? t(I18nKey.CONVERSATION$HIDE_OVERVIEW)
      : t(I18nKey.CONVERSATION$SHOW_OVERVIEW);

  const peek =
    showPeek && peekPosition
      ? ReactDOM.createPortal(
          <div
            data-testid="conversation-overview-peek"
            className="fixed z-50"
            style={{
              top: peekPosition.top,
              left: peekPosition.left,
              width: CONVERSATION_OVERVIEW_PANEL_WIDTH_PX,
            }}
            onMouseEnter={openConversationOverviewPanelPeek}
            onMouseLeave={scheduleCloseConversationOverviewPanelPeek}
          >
            <div className="shadow-lg">
              <ConversationOverviewPanel />
            </div>
          </div>,
          document.body,
        )
      : null;

  return (
    <>
      <div
        ref={triggerRef}
        className="relative inline-flex items-center self-center"
        onMouseEnter={() => {
          if (canPeekOnHover) {
            openConversationOverviewPanelPeek();
          }
        }}
        onMouseLeave={() => {
          if (canPeekOnHover || isOverviewPanelPeeked) {
            scheduleCloseConversationOverviewPanelPeek();
          }
        }}
      >
        <ChatActionTooltip tooltip={tooltipText} ariaLabel={tooltipText}>
          <button
            type="button"
            onClick={handleToggle}
            disabled={isArchivedConversation}
            className={cn(
              // Match RightPanelToggle hit target (p-1 + size-5 = 28px) while
              // keeping the smaller Info glyph.
              mobileTopBarIconButtonClassName,
              "size-7",
              isOverviewVisible && "bg-contrast/10 text-foreground",
              isArchivedConversation &&
                "cursor-not-allowed opacity-50 hover:bg-transparent hover:text-muted",
              className,
            )}
            aria-label={tooltipText}
            aria-pressed={isOverviewPanelShown}
            aria-disabled={isArchivedConversation}
            data-testid="conversation-overview-toggle"
          >
            <Info className="h-4 w-4 shrink-0" size={16} aria-hidden />
          </button>
        </ChatActionTooltip>
      </div>
      {peek}
    </>
  );
}

import { useTranslation } from "react-i18next";
import { cn } from "#/utils/utils";
import { I18nKey } from "#/i18n/declaration";
import { useConversationStore } from "#/stores/conversation-store";
import { useSelectConversationTab } from "#/hooks/use-select-conversation-tab";
import { useHandleBuildPlanClick } from "#/hooks/use-handle-build-plan-click";
import { useAgentState, usePlanningAgentState } from "#/hooks/use-agent-state";
import { AgentState } from "#/types/agent-state";
import { Typography } from "#/ui/typography";

/**
 * The Planner tab's Build row, shown below the drawer tab row while the
 * Planner tab is open. Rendered by the desktop drawer header and, at phone
 * width, below the panel page's fixed-height top bar.
 */
export function ConversationPlannerBuildBar({
  className,
}: {
  className?: string;
}) {
  const { t } = useTranslation("openhands");
  const planContent = useConversationStore((state) => state.planContent);
  const { isTabActive } = useSelectConversationTab();
  const { handleBuildPlanClick } = useHandleBuildPlanClick();
  const { curAgentState } = useAgentState();
  const { isPlanningAgentRunning } = usePlanningAgentState();

  if (!isTabActive("planner")) return null;

  const isAgentRunning =
    curAgentState === AgentState.RUNNING ||
    curAgentState === AgentState.LOADING ||
    isPlanningAgentRunning;
  const isBuildDisabled = isAgentRunning || !planContent;

  return (
    <div
      className={cn(
        "flex h-10 min-h-10 shrink-0 items-center border-t border-border pl-2.5 pr-1",
        className,
      )}
    >
      <button
        type="button"
        onClick={handleBuildPlanClick}
        disabled={isBuildDisabled}
        className={cn(
          "flex h-5 min-w-17 items-center justify-center rounded bg-contrast px-2 transition-opacity",
          isBuildDisabled
            ? "cursor-not-allowed opacity-50"
            : "cursor-pointer hover:opacity-90",
        )}
        data-testid="planner-tab-build-button"
      >
        <Typography.Text className="text-[11px] font-normal leading-5 text-contrast-foreground">
          {/* eslint-disable-next-line i18next/no-literal-string */}
          {t(I18nKey.COMMON$BUILD)} ⌘↩
        </Typography.Text>
      </button>
    </div>
  );
}

import React, { useLayoutEffect, useState } from "react";
import ReactDOM from "react-dom";
import { useTranslation } from "react-i18next";
import { ContextMenu } from "#/ui/context-menu";
import { useClickOutsideElement } from "#/hooks/use-click-outside-element";
import { useCloseOnEscape } from "#/hooks/use-close-on-escape";
import { clampLeftToViewport } from "#/hooks/use-popover-fixed-placement";
import { useConversationId } from "#/hooks/use-conversation-id";
import { useConversationLocalStorageState } from "#/utils/conversation-local-storage";
import {
  useConversationStore,
  type ConversationTab,
} from "#/stores/conversation-store";
import { I18nKey } from "#/i18n/declaration";
import { Gauge, Globe, ListTodo, SquareChevronRight } from "lucide-react";
import { LuFileDiff } from "react-icons/lu";
import DocumentIcon from "#/icons/document.svg?react";
import PillIcon from "#/icons/pill.svg?react";
import PillFillIcon from "#/icons/pill-fill.svg?react";
import DoubleCheckIcon from "#/icons/double-check.svg?react";
import { useTaskList } from "#/hooks/use-task-list";
import { useSelectConversationTab } from "#/hooks/use-select-conversation-tab";
import { useIsArchivedConversation } from "#/hooks/use-is-archived-conversation";
import { ArchivedDisabledTooltip } from "../../context-menu/archived-disabled-tooltip";
import { cn } from "#/utils/utils";
import {
  dropdownInstantColorClassName,
  dropdownMenuRowIconWrapperClassName,
} from "#/utils/dropdown-classes";

/** Space between the trigger and the portaled menu. */
const MENU_GAP_PX = 8;

interface ConversationTabsContextMenuProps {
  isOpen: boolean;
  onClose: () => void;
  ignoreOutsideClickRef?: React.RefObject<HTMLElement | null>;
  /** Portal anchor so the menu is not clipped by drawer overflow. */
  anchorRef?: React.RefObject<HTMLElement | null>;
}

export function ConversationTabsContextMenu({
  isOpen,
  onClose,
  ignoreOutsideClickRef,
  anchorRef,
}: ConversationTabsContextMenuProps) {
  const ref = useClickOutsideElement<HTMLUListElement>(
    onClose,
    ignoreOutsideClickRef,
  );
  useCloseOnEscape(isOpen, onClose, anchorRef);
  const [portalStyle, setPortalStyle] = useState<React.CSSProperties>();

  useLayoutEffect(() => {
    if (!isOpen || !anchorRef?.current) {
      setPortalStyle(undefined);
      return undefined;
    }

    const updatePosition = () => {
      const rect = anchorRef.current?.getBoundingClientRect();
      if (!rect) return;

      // The menu's own box is only measurable once it has painted; the first
      // pass falls back to anchoring on the trigger, and the frame below
      // re-runs with real dimensions.
      const menuRect = ref.current?.getBoundingClientRect();

      const overflowsBelow =
        rect.bottom + MENU_GAP_PX + (menuRect?.height ?? 0) >
        window.innerHeight;

      setPortalStyle({
        position: "fixed",
        zIndex: 9999,
        // Flip above the trigger rather than clipping at the viewport bottom.
        ...(overflowsBelow
          ? { bottom: window.innerHeight - rect.top + MENU_GAP_PX }
          : { top: rect.bottom + MENU_GAP_PX }),
        // An embedded canvas can sit hard against the viewport's right edge,
        // where left-aligning on the trigger clips the labels and pin controls.
        left: clampLeftToViewport(rect.left, menuRect?.width ?? 0),
      });
    };

    updatePosition();
    const frame = window.requestAnimationFrame(updatePosition);
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.cancelAnimationFrame(frame);
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [isOpen, anchorRef, ref]);
  const { t } = useTranslation("openhands");
  const { conversationId } = useConversationId();
  const {
    state,
    setUnpinnedTabs,
    setSelectedTab: setPersistedSelectedTab,
  } = useConversationLocalStorageState(conversationId);
  const { selectedTab, isRightPanelShown, setSelectedTab } =
    useConversationStore();

  const { navigateToTab } = useSelectConversationTab();

  const { hasTaskList } = useTaskList();
  const isArchivedConversation = useIsArchivedConversation();

  const tabConfig = [
    {
      tab: "planner",
      icon: ListTodo,
      i18nKey: I18nKey.COMMON$PLANNER,
    },
    { tab: "files", icon: DocumentIcon, i18nKey: I18nKey.COMMON$FILES },
    {
      tab: "commits",
      icon: LuFileDiff,
      i18nKey: I18nKey.DIFF_VIEWER$COMMITS,
    },
    {
      tab: "terminal",
      icon: SquareChevronRight,
      i18nKey: I18nKey.COMMON$TERMINAL,
    },
    { tab: "browser", icon: Globe, i18nKey: I18nKey.COMMON$BROWSER },
    { tab: "usage", icon: Gauge, i18nKey: I18nKey.COMMON$USAGE },
  ];

  if (hasTaskList) {
    tabConfig.unshift({
      tab: "tasklist",
      icon: DoubleCheckIcon,
      i18nKey: I18nKey.COMMON$TASK_LIST,
    });
  }

  const handleOpenTab = (tab: string) => {
    if (isArchivedConversation) {
      return;
    }
    navigateToTab(tab as ConversationTab);
    onClose();
  };

  const handlePinToggle = (tab: string, e: React.MouseEvent) => {
    if (isArchivedConversation) {
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    e.preventDefault();
    e.stopPropagation();
    if (state.unpinnedTabs.includes(tab)) {
      setUnpinnedTabs(state.unpinnedTabs.filter((item) => item !== tab));
    } else {
      const newUnpinnedTabs = [...state.unpinnedTabs, tab];
      setUnpinnedTabs(newUnpinnedTabs);

      if (selectedTab === tab && isRightPanelShown) {
        const nextPinnedTab = tabConfig.find(
          ({ tab: tabKey }) =>
            tabKey !== tab && !newUnpinnedTabs.includes(tabKey),
        );

        if (nextPinnedTab) {
          setSelectedTab(nextPinnedTab.tab as ConversationTab);
          setPersistedSelectedTab(nextPinnedTab.tab as ConversationTab);
        }
      }
    }
  };

  if (!isOpen) return null;

  const isPortaled = Boolean(anchorRef?.current && portalStyle);

  const menu = (
    <ContextMenu
      ref={ref}
      theme={isPortaled ? "popover" : "default"}
      position={isPortaled ? "none" : "bottom"}
      alignment={isPortaled ? "none" : "left"}
      spacing={isPortaled ? "none" : "default"}
      className={cn("z-[9999] w-fit", isPortaled ? "mt-0" : "mt-2")}
    >
      {tabConfig.map(({ tab, icon: Icon, i18nKey }) => {
        const pinned = !state.unpinnedTabs.includes(tab);
        return (
          <li key={tab} className="list-none">
            <ArchivedDisabledTooltip isDisabled={isArchivedConversation}>
              <div
                className={cn(
                  "group flex h-7.5 w-full min-w-0 items-stretch rounded",
                  !isArchivedConversation && "hover:bg-interactive-hover",
                  isArchivedConversation && "opacity-50",
                )}
              >
                <button
                  type="button"
                  data-testid={`conversation-tabs-menu-open-${tab}`}
                  disabled={isArchivedConversation}
                  className={cn(
                    "flex min-w-0 flex-1 items-center gap-2 rounded-l p-2 text-start text-contrast",
                    dropdownInstantColorClassName,
                    isArchivedConversation
                      ? "cursor-not-allowed"
                      : "cursor-pointer",
                  )}
                  onClick={() => handleOpenTab(tab)}
                >
                  <span
                    className={dropdownMenuRowIconWrapperClassName}
                    aria-hidden
                  >
                    <Icon className="h-4 w-4" />
                  </span>
                  <span className="text-sm">{t(i18nKey)}</span>
                </button>
                <button
                  type="button"
                  data-testid={`conversation-tabs-menu-pin-${tab}`}
                  disabled={isArchivedConversation}
                  className={cn(
                    "flex shrink-0 items-center justify-center rounded-r px-2 text-contrast",
                    dropdownInstantColorClassName,
                    isArchivedConversation
                      ? "cursor-not-allowed"
                      : "cursor-pointer hover:bg-contrast/10",
                  )}
                  aria-pressed={pinned}
                  aria-label={
                    pinned
                      ? t(I18nKey.CONVERSATION$UNPIN_TAB)
                      : t(I18nKey.CONVERSATION$PIN_TAB)
                  }
                  onClick={(e) => handlePinToggle(tab, e)}
                >
                  {pinned ? (
                    <span
                      className={cn(
                        "-mr-1.25 ml-auto",
                        dropdownMenuRowIconWrapperClassName,
                      )}
                      aria-hidden
                    >
                      <PillFillIcon className="h-7 w-7" />
                    </span>
                  ) : (
                    <span
                      className={cn(
                        "ml-auto",
                        dropdownMenuRowIconWrapperClassName,
                      )}
                      aria-hidden
                    >
                      <PillIcon className="h-4.5 w-4.5" />
                    </span>
                  )}
                </button>
              </div>
            </ArchivedDisabledTooltip>
          </li>
        );
      })}
    </ContextMenu>
  );

  if (isPortaled && portalStyle && typeof document !== "undefined") {
    return ReactDOM.createPortal(
      <div style={portalStyle}>{menu}</div>,
      document.body,
    );
  }

  return menu;
}

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
} from "react";
import { useTranslation } from "react-i18next";
import { LayoutGroup } from "framer-motion";
import { Gauge, Globe, ListTodo, SquareChevronRight } from "lucide-react";
import { LuFileDiff } from "react-icons/lu";
import DocumentIcon from "#/icons/document.svg?react";
import DoubleCheckIcon from "#/icons/double-check.svg?react";
import { EllipsisButton } from "#/components/features/conversation-panel/ellipsis-button";
import { cn } from "#/utils/utils";
import { useConversationLocalStorageState } from "#/utils/conversation-local-storage";
import { CONVERSATION_TAB_LABEL_KEYS } from "./conversation-tab-ids";
import { ConversationTabNav } from "./conversation-tab-nav";
import { DrawerVSCodeLink } from "./drawer-vscode-link";
import { ChatActionTooltip } from "../../chat/chat-action-tooltip";
import { I18nKey } from "#/i18n/declaration";
import { useConversationStore } from "#/stores/conversation-store";
import { ConversationTabsContextMenu } from "./conversation-tabs-context-menu";
import { useConversationId } from "#/hooks/use-conversation-id";
import { useSelectConversationTab } from "#/hooks/use-select-conversation-tab";
import { useTaskList } from "#/hooks/use-task-list";
import { useActiveBackend } from "#/contexts/active-backend-context";
import { useHandleBuildPlanClick } from "#/hooks/use-handle-build-plan-click";
import { useAgentState, usePlanningAgentState } from "#/hooks/use-agent-state";
import { AgentState } from "#/types/agent-state";
import { Typography } from "#/ui/typography";
import { mobileTopBarIconClassName } from "#/utils/mobile-top-bar-icon-button-classes";

export function ConversationTabs({
  variant = "default",
  isPanelResizing = false,
}: {
  variant?: "default" | "compact";
  /** True while the desktop drawer gripper is being dragged. */
  isPanelResizing?: boolean;
}) {
  const { conversationId } = useConversationId();
  const { setSelectedTab, planContent } = useConversationStore();

  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const { state: persistedState } =
    useConversationLocalStorageState(conversationId);

  const { hasTaskList } = useTaskList();
  const { backend } = useActiveBackend();

  const { handleBuildPlanClick } = useHandleBuildPlanClick();
  const { curAgentState } = useAgentState();
  const { isPlanningAgentRunning } = usePlanningAgentState();

  const {
    selectTab,
    isTabActive,
    onTabChange,
    selectedTab,
    isRightPanelShown,
  } = useSelectConversationTab();

  // Restore the most-recently-used tab from localStorage so users don't
  // lose their tab selection across reloads.
  //
  // Note: we deliberately do NOT mirror `rightPanelShown` from
  // localStorage. The drawer's open/closed state is session-only — see
  // the comment in `useConversationStore` and the schema note in
  // `conversation-local-storage.ts` for the rationale.
  useEffect(() => {
    setSelectedTab(persistedState.selectedTab);
  }, [setSelectedTab, persistedState.selectedTab]);

  useEffect(() => {
    const handlePanelVisibilityChange = () => {
      if (isRightPanelShown) {
        // If no tab is selected, default to files tab
        if (!selectedTab) {
          onTabChange("files");
        }
      }
    };

    handlePanelVisibilityChange();
  }, [isRightPanelShown, selectedTab, onTabChange]);

  const { t, i18n } = useTranslation("openhands");

  // `files` is intentionally the leftmost tab — it's the primary entry
  // point for inspecting agent output (workspace files + git diff).
  const tabs = [
    {
      tabValue: "files",
      isActive: isTabActive("files"),
      icon: DocumentIcon,
      onClick: () => selectTab("files"),
      tooltipContent: t(CONVERSATION_TAB_LABEL_KEYS.files),
      tooltipAriaLabel: t(CONVERSATION_TAB_LABEL_KEYS.files),
      label: t(CONVERSATION_TAB_LABEL_KEYS.files),
    },
    {
      tabValue: "commits",
      isActive: isTabActive("commits"),
      icon: LuFileDiff,
      onClick: () => selectTab("commits"),
      tooltipContent: t(CONVERSATION_TAB_LABEL_KEYS.commits),
      tooltipAriaLabel: t(CONVERSATION_TAB_LABEL_KEYS.commits),
      label: t(CONVERSATION_TAB_LABEL_KEYS.commits),
    },
    {
      tabValue: "planner",
      isActive: isTabActive("planner"),
      icon: ListTodo,
      onClick: () => selectTab("planner"),
      tooltipContent: t(CONVERSATION_TAB_LABEL_KEYS.planner),
      tooltipAriaLabel: t(CONVERSATION_TAB_LABEL_KEYS.planner),
      label: t(CONVERSATION_TAB_LABEL_KEYS.planner),
    },
    {
      tabValue: "terminal",
      isActive: isTabActive("terminal"),
      icon: SquareChevronRight,
      onClick: () => selectTab("terminal"),
      tooltipContent: t(CONVERSATION_TAB_LABEL_KEYS.terminal),
      tooltipAriaLabel: t(CONVERSATION_TAB_LABEL_KEYS.terminal),
      label: t(CONVERSATION_TAB_LABEL_KEYS.terminal),
      className: "pl-2",
    },
    {
      tabValue: "browser",
      isActive: isTabActive("browser"),
      icon: Globe,
      onClick: () => selectTab("browser"),
      tooltipContent: t(CONVERSATION_TAB_LABEL_KEYS.browser),
      tooltipAriaLabel: t(CONVERSATION_TAB_LABEL_KEYS.browser),
      label: t(CONVERSATION_TAB_LABEL_KEYS.browser),
    },
    {
      tabValue: "usage",
      isActive: isTabActive("usage"),
      icon: Gauge,
      onClick: () => selectTab("usage"),
      tooltipContent: t(CONVERSATION_TAB_LABEL_KEYS.usage),
      tooltipAriaLabel: t(CONVERSATION_TAB_LABEL_KEYS.usage),
      label: t(CONVERSATION_TAB_LABEL_KEYS.usage),
    },
  ];

  if (hasTaskList) {
    // Insert after the file-related tabs.
    tabs.splice(2, 0, {
      tabValue: "tasklist",
      isActive: isTabActive("tasklist"),
      icon: DoubleCheckIcon,
      onClick: () => selectTab("tasklist"),
      tooltipContent: t(CONVERSATION_TAB_LABEL_KEYS.tasklist),
      tooltipAriaLabel: t(CONVERSATION_TAB_LABEL_KEYS.tasklist),
      label: t(CONVERSATION_TAB_LABEL_KEYS.tasklist),
    });
  }

  // Pinned tabs always show in the bar. Unpinned tabs stay hidden unless the
  // user has that tab selected — then it appears while active so the bar
  // matches the open panel.
  const visibleTabs = tabs.filter((tab) => {
    if (!persistedState.unpinnedTabs.includes(tab.tabValue)) return true;
    return selectedTab === tab.tabValue;
  });

  const unpinnedSignature = persistedState.unpinnedTabs.join(",");

  const isAgentRunning =
    curAgentState === AgentState.RUNNING ||
    curAgentState === AgentState.LOADING ||
    isPlanningAgentRunning;
  const isBuildDisabled = isAgentRunning || !planContent;

  const tabsRowInnerRef = useRef<HTMLDivElement>(null);
  const measureRowRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const vscodeButtonRef = useRef<HTMLDivElement>(null);
  const anchorRef = useRef<HTMLButtonElement>(null);
  const [inlineTabCount, setInlineTabCount] = useState(visibleTabs.length);

  useLayoutEffect(() => {
    const rowInner = tabsRowInnerRef.current;
    const measureRow = measureRowRef.current;
    const menuEl = menuRef.current;
    const vscodeEl = vscodeButtonRef.current;
    if (!rowInner || !measureRow || !menuEl || !vscodeEl) return undefined;

    const measure = () => {
      const measureButtons = measureRow.querySelectorAll<HTMLButtonElement>(
        '[data-tab-measure="true"]',
      );
      const tabCount = measureButtons.length;

      const rowWidth = rowInner.getBoundingClientRect().width;
      if (rowWidth === 0) {
        setInlineTabCount(tabCount);
        return;
      }

      const widths = Array.from(measureButtons).map(
        (button) => button.getBoundingClientRect().width,
      );

      if (widths.length !== tabCount || tabCount === 0) {
        setInlineTabCount(Math.max(0, tabCount));
        return;
      }

      const menuWidth = menuEl.getBoundingClientRect().width;
      const vscodeWidth = vscodeEl.getBoundingClientRect().width;
      const gapCss =
        getComputedStyle(rowInner).columnGap || getComputedStyle(rowInner).gap;
      const gapPx = parseFloat(gapCss) || 6;

      let nextCount = 0;
      for (let k = tabCount; k >= 0; k -= 1) {
        let total = menuWidth + vscodeWidth;
        for (let i = 0; i < k; i += 1) {
          total += widths[i] ?? 0;
        }
        if (k > 0) {
          total += k * gapPx;
        }
        if (total <= rowWidth + 0.5) {
          nextCount = k;
          break;
        }
      }

      setInlineTabCount((prev) => (prev === nextCount ? prev : nextCount));
    };

    measure();
    if (typeof ResizeObserver === "undefined") return undefined;
    const ro = new ResizeObserver(measure);
    ro.observe(rowInner);
    // The editor button's presence is resolved asynchronously (the hook probes
    // /api/vscode/status), and it sits inside an `ml-auto shrink-0` wrapper, so
    // it appearing or disappearing does not change `rowInner`'s own box and
    // would not otherwise re-measure. Its width is folded into the fit
    // calculation above, so a stale value permanently costs an inline tab.
    ro.observe(vscodeEl);
    return () => ro.disconnect();
  }, [
    unpinnedSignature,
    visibleTabs.length,
    hasTaskList,
    backend.kind,
    selectedTab,
    isRightPanelShown,
    i18n.language,
  ]);

  const safeInlineTabCount = Math.min(inlineTabCount, visibleTabs.length);
  const inlineTabs = visibleTabs.slice(0, safeInlineTabCount);

  // Roving tabindex: the strip is a single tab stop. It sits on the selected
  // tab — drawer open or not, since the strip stays in the accessibility tree
  // while the drawer is collapsed — until the user arrows elsewhere.
  const selectedTabIndex = inlineTabs.findIndex(
    (tab) => tab.tabValue === selectedTab,
  );
  const [rovingTabIndex, setRovingTabIndex] = useState(0);
  const tabRefs = useRef<(HTMLButtonElement | null)[]>([]);

  useEffect(() => {
    if (selectedTabIndex >= 0) setRovingTabIndex(selectedTabIndex);
  }, [selectedTabIndex]);

  const tabStopIndex = Math.min(
    rovingTabIndex,
    Math.max(inlineTabs.length - 1, 0),
  );

  // Arrow keys move focus only; Enter/Space still activate, which keeps the
  // drawer from thrashing through tabs as the user scans the strip.
  const handleTabKeyDown = (
    event: KeyboardEvent<HTMLButtonElement>,
    index: number,
  ) => {
    const lastIndex = inlineTabs.length - 1;
    if (lastIndex < 0) return;

    let nextIndex: number;
    if (event.key === "ArrowRight") {
      nextIndex = index === lastIndex ? 0 : index + 1;
    } else if (event.key === "ArrowLeft") {
      nextIndex = index === 0 ? lastIndex : index - 1;
    } else if (event.key === "Home") {
      nextIndex = 0;
    } else if (event.key === "End") {
      nextIndex = lastIndex;
    } else {
      return;
    }

    event.preventDefault();
    setRovingTabIndex(nextIndex);
    tabRefs.current[nextIndex]?.focus();
  };

  return (
    <>
      <div
        className={cn(
          "relative w-full min-w-0",
          variant === "compact"
            ? "flex h-full min-h-0 items-center py-0 pl-0 pr-1"
            : "min-h-10 p-1",
        )}
      >
        <div
          ref={measureRowRef}
          aria-hidden
          className="pointer-events-none absolute top-0 left-[-10000px] flex flex-nowrap items-center gap-1.5"
        >
          {visibleTabs.map(
            (
              {
                tabValue,
                icon,
                isActive,
                tooltipContent,
                tooltipAriaLabel,
                label,
                className: tabClassName,
              },
              index,
            ) => (
              <ChatActionTooltip
                key={`measure-${tabValue}-${index}`}
                tooltip={tooltipContent}
                ariaLabel={tooltipAriaLabel}
              >
                <ConversationTabNav
                  tabValue={tabValue}
                  icon={icon}
                  onClick={() => {}}
                  isActive={isActive}
                  label={label}
                  className={cn(tabClassName, "shrink-0")}
                  measureOnly
                />
              </ChatActionTooltip>
            ),
          )}
        </div>
        <div
          ref={tabsRowInnerRef}
          className="flex w-full min-w-0 flex-nowrap items-center justify-start"
        >
          <div className="flex min-w-0 flex-1 items-center justify-start overflow-hidden">
            <div className="flex w-fit max-w-full min-w-0 items-center gap-1.5">
              <LayoutGroup id="conversation-drawer-tabs">
                <div
                  // A narrow drawer can push every tab into the overflow menu,
                  // and a tablist owning no tabs is not a tablist.
                  role={inlineTabs.length > 0 ? "tablist" : undefined}
                  aria-label={t(I18nKey.CONVERSATION$TABS_LABEL)}
                  className="flex w-fit max-w-full min-w-0 flex-nowrap items-center gap-1.5 overflow-x-hidden"
                >
                  {inlineTabs.map(
                    (
                      {
                        tabValue,
                        icon,
                        onClick,
                        isActive,
                        tooltipContent,
                        tooltipAriaLabel,
                        label,
                        className: tabClassName,
                      },
                      index,
                    ) => (
                      <ChatActionTooltip
                        key={`${tabValue}-${index}`}
                        tooltip={tooltipContent}
                        ariaLabel={tooltipAriaLabel}
                      >
                        <ConversationTabNav
                          tabValue={tabValue}
                          icon={icon}
                          onClick={onClick}
                          isActive={isActive}
                          isSelected={selectedTab === tabValue}
                          label={label}
                          className={cn(tabClassName, "shrink-0")}
                          suppressLayoutAnimation={isPanelResizing}
                          tabIndex={index === tabStopIndex ? 0 : -1}
                          onKeyDown={(event) => handleTabKeyDown(event, index)}
                          buttonRef={(node) => {
                            tabRefs.current[index] = node;
                          }}
                        />
                      </ChatActionTooltip>
                    ),
                  )}
                </div>
              </LayoutGroup>
