interface CompactContextButtonProps {
  /** Current context fill percentage; past the warning threshold the button becomes a prominent CTA. */
  fillPercent: number;
  /** Optional live per-turn token count used as a fallback snapshot before compaction. */
  perTurnToken?: number;
}

/**
 * "Compact context" action: POSTs `/api/conversations/{id}/condense` with a
 * spinner while in flight and toasts for start, completion (with tokens
 * freed), and failure. Disabled while the agent is actively running (the
 * server would race the active step) and promoted to a primary
 * call-to-action once the context fill passes
 * {@link CONTEXT_FILL_WARNING_PERCENT}.
 */
export function CompactContextButton({
  fillPercent,
  perTurnToken = 0,
}: CompactContextButtonProps) {
  const { t } = useTranslation("openhands");
  const { handleCompact, isCompacting, isDisabled, description } =
    useCompactContextAction(perTurnToken);
  const isHighFill = fillPercent > CONTEXT_FILL_WARNING_PERCENT;

  return (
    <div
      data-testid="compact-context-section"
      className="flex flex-col gap-2 border-t border-border-subtle pt-3"
    >
      {isHighFill && (
        <span className="text-xs text-amber-500">
          {t(I18nKey.CONVERSATION$CONTEXT_FILLING_UP)}
        </span>
      )}
      <div className="flex items-center gap-2">
        <BrandButton
          testId="compact-context-button"
          type="button"
          variant={isHighFill ? "primary" : "secondary"}
          isDisabled={isDisabled}
          aria-busy={isCompacting}
          onClick={handleCompact}
          startContent={
            isCompacting ? (
              <Loader2 className="h-4 w-4 animate-spin" aria-hidden />
            ) : (
              <Minimize className="h-4 w-4" aria-hidden />
            )
          }
          className="w-fit"
        >
          {t(I18nKey.CONVERSATION$COMPACT_CONTEXT)}
        </BrandButton>
        <StyledTooltip
          content={description}
          placement="top"
          tooltipClassName="max-w-55 text-xs font-normal leading-relaxed whitespace-normal"
        >
          <button
            type="button"
            data-testid="compact-context-info"
            aria-label={description}
            className="flex size-5 shrink-0 items-center justify-center rounded-full text-muted hover:text-foreground transition-colors cursor-help"
          >
            <Info className="size-3.5" aria-hidden />
          </button>
        </StyledTooltip>
      </div>
    </div>
  );
}

import { useTranslation } from "react-i18next";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import { getContextWindowUsagePercentage } from "#/utils/format-token-count";

/** Context fill percentage above which the meter warns and the compact CTA becomes prominent. */
export const CONTEXT_FILL_WARNING_PERCENT = 70;
/** Context fill percentage above which the meter signals danger. */
export const CONTEXT_FILL_DANGER_PERCENT = 90;

export type ContextFillTone = "neutral" | "warning" | "danger";

export function getContextFillTone(usagePercentage: number): ContextFillTone {
  if (usagePercentage > CONTEXT_FILL_DANGER_PERCENT) {
    return "danger";
  }
  if (usagePercentage > CONTEXT_FILL_WARNING_PERCENT) {
    return "warning";
  }
  return "neutral";
}

interface ContextMeterProps {
  /** Tokens currently held in the agent's context (`per_turn_token`). */
  perTurnToken: number;
  /** Model context window size in tokens. */
  contextWindow: number;
}

/**
 * Context-fill progress bar: neutral below
 * {@link CONTEXT_FILL_WARNING_PERCENT}, amber above it, red above
 * {@link CONTEXT_FILL_DANGER_PERCENT}. Shows the raw token numbers underneath.
 */
export function ContextMeter({
  perTurnToken,
  contextWindow,
}: ContextMeterProps) {
  const { t } = useTranslation("openhands");

  // Some models (e.g. via OpenRouter) report no context window size; show the
  // raw token count without a misleading "x / 0" or "0.0% used" readout.
  const isWindowUnknown = contextWindow <= 0;

  // Capped at 100 by getContextWindowUsagePercentage, so the bar width and
  // the label never read above a full window.
  const usagePercentage = getContextWindowUsagePercentage(
    perTurnToken,
    contextWindow,
  );
  const tone = getContextFillTone(usagePercentage);
  const isWarning = tone === "warning";
  const isDanger = tone === "danger";
  const roundedPercentage = Math.round(usagePercentage);
  const remainingPercentage = Math.max(0, 100 - roundedPercentage);
  const usagePercentLabel = isWindowUnknown
    ? t(I18nKey.CONVERSATION$CONTEXT_WINDOW_UNKNOWN)
    : `${roundedPercentage}% ${t(I18nKey.CONVERSATION$USED)} (${remainingPercentage}% ${t(I18nKey.CONVERSATION$LEFT)})`;

  return (
    <div data-testid="context-meter" className="flex flex-col gap-2">
      <div className="flex items-center justify-between gap-2">
        <span className="font-semibold">
          {t(I18nKey.CONVERSATION$CONTEXT_WINDOW)}
        </span>
        <span
          className={cn(
            "shrink-0 text-xs",
            isDanger
              ? "text-red-500"
              : isWarning
                ? "text-amber-500"
                : "text-muted",
          )}
        >
          {usagePercentLabel}
        </span>
      </div>
      <div className="relative h-1.5 w-full rounded-full bg-tertiary">
        <div
          data-testid="context-meter-bar"
          className={cn(
            "absolute inset-y-0 left-0 rounded-full transition-all duration-300",
            isDanger
              ? "bg-red-500"
              : isWarning
                ? "bg-amber-500"
                : "bg-foreground",
          )}
          // runtime usage-percentage width
          style={{ width: `${usagePercentage}%` }}
        />
      </div>
      <div className="flex justify-end">
        <span className="text-xs text-muted">
          {isWindowUnknown
            ? perTurnToken.toLocaleString()
            : `${perTurnToken.toLocaleString()} / ${contextWindow.toLocaleString()}`}
        </span>
      </div>
    </div>
  );
}

