import { useTranslation } from "react-i18next";

import { I18nKey } from "#/i18n/declaration";
import { useColorTheme } from "#/hooks/use-color-theme";
import { useWorkspaceFileContent } from "#/hooks/query/use-workspace-file-content";
import {
  useWorkspaceMutationCounter,
  withWorkspaceCacheBuster,
} from "#/stores/use-workspace-mutation-counter";
import { MarkdownRenderer } from "#/components/features/markdown/markdown-renderer";
import { isMarkdownFilePath } from "#/utils/is-markdown-file-path";
import { COLOR_THEMES } from "#/themes/color-themes";
import { cn } from "#/utils/utils";
import { HighlightedSourceView } from "./highlighted-source-view";
import type { ViewMode } from "./view-mode";

interface FileContentViewerProps {
  path: string;
  viewMode: ViewMode;
}

const HTML_LIKE_EXTS = new Set(["html", "htm", "svg"]);

// Office/document formats we can't preview inline. The label doubles as the
// allow-list (a present entry => Office doc) and feeds a clear, format-named
// "no preview" message instead of the generic binary fallback.
const OFFICE_DOCUMENT_LABELS: Record<string, string> = {
  pptx: "PowerPoint",
  ppt: "PowerPoint",
  docx: "Word",
  doc: "Word",
  xlsx: "Excel",
  xls: "Excel",
};

function getExtension(path: string): string {
  const idx = path.lastIndexOf(".");
  return idx === -1 ? "" : path.slice(idx + 1).toLowerCase();
}

/**
 * Fallback shown when a file's bytes aren't previewable. Office documents
 * (.pptx / .docx / .xlsx …) get a clear, format-named message; every other
 * binary keeps the generic "binary file" string so the pane is never blank.
 */
function UnpreviewableFallback({ path }: { path: string }) {
  const { t } = useTranslation("openhands");
  const documentLabel = OFFICE_DOCUMENT_LABELS[getExtension(path)];
  return (
    <div
      className="flex h-full w-full items-center justify-center text-sm text-muted"
      data-testid={
        documentLabel
          ? "file-content-viewer-unsupported-document"
          : "file-content-viewer-binary-fallback"
      }
    >
      {documentLabel
        ? t(I18nKey.FILES$UNSUPPORTED_DOCUMENT, { type: documentLabel })
        : t(I18nKey.FILES$BINARY_FALLBACK)}
    </div>
  );
}

/**
 * Renders the contents of a single workspace file. In `rich` mode we point
 * an iframe / <img> straight at the agent server's static workspace
 * fileserver for HTML / SVG / images / PDFs, so relative asset references
 * load naturally. In `plain` mode we always show the raw bytes as text (or
 * a fallback message for binaries).
 */
export function FileContentViewer({ path, viewMode }: FileContentViewerProps) {
  const { t } = useTranslation("openhands");
  const colorTheme = useColorTheme();
  const isLightTheme = COLOR_THEMES[colorTheme].appearance === "light";
  const query = useWorkspaceFileContent(path);
  // Subscribe to the workspace mutation counter so the iframe / <img> src
  // changes after every agent file-editor edit and every Files tab Refresh,
  // forcing a fresh fetch of the displayed file even when the *path* hasn't
  // moved. Assets it references (e.g. a `style.css` used by `index.html`)
  // keep their own URLs, so they are not cache-busted by this.
  const mutationCounter = useWorkspaceMutationCounter((state) => state.count);

  if (query.isLoading) {
    return (
      <div className="flex h-full w-full items-center justify-center text-sm text-muted">
        {t(I18nKey.FILES$LOADING_FILES)}
      </div>
    );
  }

  if (query.isError || !query.data) {
    // Show a load-error message rather than the binary-fallback string —
    // these are completely different failure modes (couldn't even fetch
    // the file vs. fetched fine but the bytes aren't previewable) and
    // mixing them up hides real backend failures behind a misleading
    // "Binary file" label. Prefer the underlying error's own message when
    // we have one; fall back to the generic translated string otherwise.
    return (
      <div
        className="flex h-full w-full items-center justify-center text-sm text-muted"
        data-testid="file-content-viewer-error"
      >
        {(query.error as Error | undefined)?.message ??
          t(I18nKey.FILES$LOAD_ERROR)}
      </div>
    );
  }

  const { kind, text, staticUrl, mimeType } = query.data;
  const bustedStaticUrl = withWorkspaceCacheBuster(staticUrl, mutationCounter);

  // ----- Plain mode: raw source bytes, syntax-highlighted when we can
  // recognize the grammar (falls through to a `<pre>` otherwise). This
  // includes "plain" view of markdown / HTML, where the point is to see
  // the markup behind the rich preview.
  if (viewMode === "plain") {
    if (kind === "text" && text !== null) {
      return (
        <HighlightedSourceView
          path={path}
          text={text}
          mimeType={mimeType ?? undefined}
        />
      );
    }
    return <UnpreviewableFallback path={path} />;
  }

  // ----- Rich mode: render HTML, markdown, images, PDFs from staticUrl. ----
  if (kind === "image") {
    return (
      <div
        className="flex h-full w-full items-center justify-center bg-surface p-4"
        data-testid="file-content-viewer-image"
      >
        <img
          src={bustedStaticUrl}
          alt={path}
          className="max-h-full max-w-full object-contain"
        />
      </div>
    );
  }

  if (kind === "pdf") {
    // Deliberately NOT sandboxed: Chromium refuses to instantiate its
    // built-in PDF viewer inside any sandboxed frame (the `sandbox`
    // attribute disables plugins unconditionally — no token re-enables
    // them), rendering "This page has been blocked by Chrome" instead of
    // the document. Unsandboxed is safe here: the fileserver declares
    // `Content-Type: application/pdf`, which browsers never sniff into
    // HTML, so the frame can only host the PDF viewer — and PDF-embedded
    // JS (AcroForm, OpenAction…) runs in the viewer's own sandboxed
    // engine with no access to this page's DOM.
    return (
      <iframe
        title={path}
        src={bustedStaticUrl}
        data-testid="file-content-viewer-iframe"
        className="h-full w-full bg-white"
      />
    );
  }

  if (kind === "binary") {
    return <UnpreviewableFallback path={path} />;
  }

  // Text-like content.
  if (mimeType === "text/html" || HTML_LIKE_EXTS.has(getExtension(path))) {
    // Sandbox the preview iframe: `allow-same-origin` keeps the frame on
    // the workspace fileserver's origin so relative `<link href="…">`,
    // `<img src="…">`, etc. continue to resolve, while the absence of
    // `allow-scripts` means any `<script>` (or `onerror=…`, inline event
    // handler, …) inside the previewed file is inert. This is exactly
    // the safe-preview posture we want — users can look at their HTML
    // without it executing in the canvas's context.
    return (
      <iframe
        title={path}
        src={bustedStaticUrl}
        sandbox="allow-same-origin"
        data-testid="file-content-viewer-iframe"
        className="h-full w-full bg-white"
      />
    );
  }

  if (kind === "text" && isMarkdownFilePath(path)) {
    // Match the right-pane chrome color so the rich-rendered markdown
    // blends with the surrounding files tab instead of painting a stark
    // white card. `--oh-scroll-fade-from` keeps wide-table edge fades on
    // the same surface (otherwise they default to `--oh-color-base`).
    return (
      <div
        data-testid="file-content-viewer-markdown"
        className="h-full w-full overflow-auto bg-surface text-foreground custom-scrollbar-always [--oh-scroll-fade-from:var(--oh-surface)]"
      >
        <div
          className={cn(
            "prose prose-sm max-w-none p-6",
            "[--tw-prose-body:var(--oh-foreground)] [--tw-prose-bold:var(--oh-foreground)] [--tw-prose-headings:var(--oh-foreground)] [--tw-prose-lead:var(--oh-text-secondary)] [--tw-prose-counters:var(--oh-text-secondary)] [--tw-prose-quotes:var(--oh-foreground)] [--tw-prose-quote-borders:var(--oh-border-subtle)] [--tw-prose-bullets:var(--oh-muted)] [--tw-prose-hr:var(--oh-border-subtle)] [--tw-prose-captions:var(--oh-muted)] [--tw-prose-kbd:var(--oh-foreground)]",
            !isLightTheme && "prose-invert",
          )}
        >
          <MarkdownRenderer
            content={text ?? ""}
            includeStandard
            includeHeadings
          />
        </div>
      </div>
    );
  }

  // Rich mode for actual source code (.ts, .py, .yaml, .css, …): there
  // is no other "rich" rendering to fall back to, so highlighted source
  // IS the rich view. Identical to the plain-mode treatment — keeping
  // both branches reuse `HighlightedSourceView` means the toggle has the
  // same visual identity for source files in both modes (which is the
  // honest answer: source IS rendered code).
  if (kind === "text" && text !== null) {
    return (
      <HighlightedSourceView
        path={path}
        text={text}
        mimeType={mimeType ?? undefined}
      />
    );
  }

  // Truly unknown / empty payload — show a fallback so the pane is never
  // blank.
  return <UnpreviewableFallback path={path} />;
}

import { ListTree } from "lucide-react";
import type { ReactNode } from "react";
import { useTranslation } from "react-i18next";
import CloseIcon from "#/icons/u-close.svg?react";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";

interface FileQuickRowProps {
  /** Open file tabs only (paths the user or agent has opened). */
  openPaths: string[];
  selectedPath: string | null;
  onSelectFile: (path: string) => void;
  onCloseFile: (path: string) => void;
  /** Whether the left-hand file tree is currently visible. */
  isTreeVisible: boolean;
  /** Toggle the visibility of the left-hand file tree. */
  onToggleTree: () => void;
  /** Trailing actions (e.g. refresh), pinned to the right. */
  actions?: ReactNode;
}

const HIDDEN_SCROLLBAR_CLASSNAME =
  "[scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden";

/**
 * Horizontal strip of open-file tabs. A path only appears after the user or
 * agent opens it. Overflow scrolls horizontally without a visible scrollbar.
 */
export function FileQuickRow({
  openPaths,
  selectedPath,
  onSelectFile,
  onCloseFile,
  isTreeVisible,
  onToggleTree,
  actions,
}: FileQuickRowProps) {
  const { t } = useTranslation("openhands");

  return (
    <div
      className="flex h-8.5 shrink-0 items-stretch gap-1.5 overflow-y-hidden border-b border-border px-2"
      data-testid="file-quick-row"
    >
      <button
        type="button"
        onClick={onToggleTree}
        data-testid="file-quick-row-tree-toggle"
        aria-pressed={isTreeVisible}
        aria-label={t(
          isTreeVisible
            ? I18nKey.FILES$HIDE_FILE_TREE
            : I18nKey.FILES$SHOW_FILE_TREE,
        )}
        title={t(
          isTreeVisible
            ? I18nKey.FILES$HIDE_FILE_TREE
            : I18nKey.FILES$SHOW_FILE_TREE,
        )}
        className={cn(
          "shrink-0 self-center inline-flex items-center justify-center w-6 h-6 rounded-md cursor-pointer",
          "text-text-tertiary hover:bg-tertiary",
          isTreeVisible && "bg-surface-raised",
        )}
      >
        <ListTree className="w-3 h-3" aria-hidden strokeWidth={2} />
      </button>

      {openPaths.length > 0 ? (
        <div
          role="tablist"
          aria-label={t(I18nKey.COMMON$FILES)}
          className={cn(
            "flex min-h-0 min-w-0 flex-1 flex-nowrap items-stretch overflow-x-auto overflow-y-hidden overscroll-y-none",
            HIDDEN_SCROLLBAR_CLASSNAME,
          )}
        >
          {openPaths.map((path, index) => {
            const isSelected = selectedPath === path;
            const fileName = path.split("/").pop() || path;
            return (
              <div
                key={path}
                className={cn(
                  "group/file-tab relative flex shrink-0 items-stretch",
                  // Vertical edges on every tab (left on the first, right on all).
                  "border-r border-r-border",
                  index === 0 && "border-l border-l-border",
                  "border-b-2 -mb-px transition-colors",
                  isSelected
                    ? "border-b-contrast text-contrast"
                    : "border-b-transparent text-muted hover:text-contrast hover:border-b-contrast/25",
                )}
              >
                <button
                  type="button"
                  role="tab"
                  aria-selected={isSelected}
                  onClick={() => onSelectFile(path)}
                  title={path}
                  data-testid={`file-quick-row-item-${path}`}
                  className="flex min-w-0 max-w-40 items-center pl-2.5 pr-1 text-xs cursor-pointer text-inherit"
                >
                  <span className="truncate">{fileName}</span>
                </button>
                <button
                  type="button"
                  data-testid={`file-quick-row-close-${path}`}
                  aria-label={t(I18nKey.FILES$CLOSE_TAB, { path })}
                  title={t(I18nKey.FILES$CLOSE_TAB, { path })}
                  className={cn(
                    "inline-flex items-center justify-center size-5 self-center mr-1 rounded-sm shrink-0 cursor-pointer",
                    "text-inherit hover:bg-contrast/10",
                    // Always visible on small / touch-first viewports; hover to
                    // reveal on fine pointers (desktop).
                    "opacity-100 transition-opacity",
                    "md:opacity-0 md:group-hover/file-tab:opacity-100 md:group-focus-within/file-tab:opacity-100",
                  )}
                  onClick={() => onCloseFile(path)}
                >
                  <CloseIcon width={10} height={10} aria-hidden />
                </button>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="flex-1 min-w-0" />
      )}

      {actions ? (
        <div className="ml-auto shrink-0 self-center flex items-center gap-1">
          {actions}
        </div>
      ) : null}
    </div>
  );
}

import { SyntaxHighlighter } from "#/components/features/markdown/syntax-highlighter";
import { useColorTheme } from "#/hooks/use-color-theme";
import { getSyntaxHighlighterTheme } from "#/themes/syntax-highlighter-themes";
import { getPrismLanguageForFile } from "#/utils/file-language";

interface HighlightedSourceViewProps {
  path: string;
  text: string;
  mimeType?: string;
}

/**
 * Renders the raw bytes of a workspace text file with Prism syntax
 * highlighting. Used both in:
 *   - Rich mode for actual source files (.ts, .py, .yaml, …) — there is
 *     no "rich" rendering of source code, so highlighted source IS the
 *     rich view.
 *   - Plain mode for source code AND for the source form of markdown /
 *     HTML files (so users can inspect the markup behind a rich preview).
 *
 * When we don't have a Prism grammar for the file we fall through to a
 * plain `<pre>` so the bytes still show. The wrapper styling matches the
 * right-pane background so the highlighted block reads as part of the
 * surrounding chrome instead of a floating card.
 */
export function HighlightedSourceView({
  path,
  text,
  mimeType,
}: HighlightedSourceViewProps) {
  const colorTheme = useColorTheme();
  const language = getPrismLanguageForFile(path, mimeType);

  if (!language) {
    return (
      <pre
        data-testid="file-content-viewer-plain"
        className="h-full w-full overflow-auto whitespace-pre-wrap break-words bg-surface p-4 text-xs leading-5 text-contrast custom-scrollbar-always"
      >
        {text}
      </pre>
    );
  }

  return (
    <div
      data-testid="file-content-viewer-highlighted"
      data-language={language}
      className="h-full w-full overflow-auto bg-surface custom-scrollbar-always"
    >
      <SyntaxHighlighter
        language={language}
        style={getSyntaxHighlighterTheme(colorTheme)}
        showLineNumbers
        wrapLongLines={false}
        // Override the theme's hard-coded background so the highlighter
        // blends with the right-pane chrome instead of painting a slab
        // of a slightly-different dark color.
        customStyle={{
          margin: 0,
          padding: "1rem",
          background: "transparent",
          fontSize: "0.75rem",
          lineHeight: "1.25rem",
          minHeight: "100%",
        }}
        codeTagProps={{
          style: { background: "transparent", fontFamily: "inherit" },
        }}
        lineNumberStyle={{
          color: "var(--oh-border)",
          minWidth: "2.5em",
          paddingRight: "1em",
          userSelect: "none",
        }}
      >
        {text}
      </SyntaxHighlighter>
    </div>
  );
}

import { useState } from "react";
import { ChevronDown, ChevronRight } from "lucide-react";

import FileIcon from "#/icons/file.svg?react";
import FolderIcon from "#/icons/folder.svg?react";
import { FileTreeNode } from "#/utils/file-tree";
import { cn } from "#/utils/utils";

interface TreeNodeProps {
  node: FileTreeNode;
  depth: number;
  selectedPath: string | null;
  onSelectFile: (path: string) => void;
}

export function TreeNode({
  node,
  depth,
  selectedPath,
  onSelectFile,
}: TreeNodeProps) {
  const [isOpen, setIsOpen] = useState(false);
  const indentPx = 8 + depth * 12;

  if (node.isDirectory) {
    return (
      <li>
        <button
          type="button"
          onClick={() => setIsOpen((prev) => !prev)}
          aria-expanded={isOpen}
          data-testid={`file-tree-dir-${node.path}`}
          className={cn(
            "flex w-full items-center gap-1.5 py-1 pr-2 text-left text-sm text-contrast",
            "hover:bg-tertiary cursor-pointer",
          )}
          // per-row indentation computed from tree depth at runtime
          style={{ paddingLeft: `${indentPx}px` }}
        >
          <span
            aria-hidden
            className="inline-flex w-3.5 shrink-0 items-center justify-center text-muted"
          >
            {isOpen ? (
              <ChevronDown className="w-3.5 h-3.5" />
            ) : (
              <ChevronRight className="w-3.5 h-3.5" />
            )}
          </span>
          <FolderIcon className="w-3.5 h-3.5 shrink-0" />
          <span className="truncate">{node.name}</span>
        </button>
        {isOpen && node.children.length > 0 && (
          <ul>
            {node.children.map((child) => (
              <TreeNode
                key={child.path}
                node={child}
                depth={depth + 1}
                selectedPath={selectedPath}
                onSelectFile={onSelectFile}
              />
            ))}
          </ul>
        )}
      </li>
    );
  }

  const isSelected = selectedPath === node.path;
  return (
    <li>
      <button
        type="button"
        onClick={() => onSelectFile(node.path)}
        data-testid={`file-tree-file-${node.path}`}
        className={cn(
          "flex w-full items-center gap-1.5 py-1 pr-2 text-left text-sm",
          "hover:bg-tertiary cursor-pointer",
          isSelected
            ? "bg-interactive-hover text-contrast"
            : "text-text-tertiary",
        )}
        // per-row indentation computed from tree depth at runtime
