function getParentPath(path: string): string | null {
  const trimmed = trimTrailingSeparators(path);
  if (!trimmed || trimmed === "/" || isWindowsDriveRoot(trimmed)) return null;

  const idx = Math.max(trimmed.lastIndexOf("/"), trimmed.lastIndexOf("\\"));
  if (idx < 0) return null;
  if (idx === 0) return "/";

  const parent = trimmed.slice(0, idx);
  if (/^[A-Za-z]:$/.test(parent)) {
    return `${parent}${trimmed[idx]}`;
  }

  return parent;
}

function isWindowsDriveRoot(path: string): boolean {
  return /^[A-Za-z]:[\\/]?$/.test(path);
}

function trimTrailingSeparators(path: string): string {
  const trimmed = path.replace(/[\\/]+$/, "");
  if (/^[A-Za-z]:$/.test(trimmed)) {
    const separator = path.includes("/") && !path.includes("\\") ? "/" : "\\";
    return `${trimmed}${separator}`;
  }
  return trimmed;
}

function shouldDefaultToProjectsPath(
  homeData: HomeDirectoryResponse | undefined,
): boolean {
  return homeData?.home === "/home/openhands";
}

export function FolderBrowserModal({
  isOpen,
  onClose,
  onAdd,
  onAddParent,
}: FolderBrowserModalProps) {
  const { t } = useTranslation("openhands");
  const [currentPath, setCurrentPath] = useState<string | null>(null);
  const active = useActiveBackend();

  const { data: homeData } = useHomeDirectory();

  // Initialize / reset to home each time the modal is opened
  useEffect(() => {
    if (isOpen && homeData?.home && currentPath === null) {
      setCurrentPath(
        shouldDefaultToProjectsPath(homeData) ? PROJECTS_PATH : homeData.home,
      );
    }
    if (!isOpen) {
      setCurrentPath(null);
    }
  }, [isOpen, homeData?.home, currentPath]);

  // A backend switch invalidates the previous path — clear it so the
  // open/close effect can re-seed from the new backend's homeData.home.
  useEffect(() => {
    setCurrentPath(null);
  }, [active.backend.id, active.orgId]);

  const {
    data: listing,
    isLoading,
    isError,
    error,
  } = useSearchSubdirs(isOpen ? currentPath : null);

  const favorites: SidebarEntry[] = useMemo(() => {
    if (!homeData?.home) return [];
    const trimmed = trimTrailingSeparators(homeData.home) || homeData.home;
    const backendFavorites = [
      { label: "Home", path: trimmed },
      ...(homeData.favorites ?? []),
    ];
    if (
      shouldDefaultToProjectsPath(homeData) &&
      !backendFavorites.some((entry) => entry.path === PROJECTS_PATH)
    ) {
      backendFavorites.push({
        label: PROJECTS_PATH,
        path: PROJECTS_PATH,
      });
    }

    return backendFavorites;
  }, [homeData]);

  const locations: SidebarEntry[] = homeData?.locations ?? [];

  if (!isOpen) return null;

  const subdirs = listing?.items ?? [];
  const parent = currentPath ? getParentPath(currentPath) : null;

  // Signal that we're inside a container environment without the host
  // home mounted: the agent server reports `/home/openhands` as home and
  // returns no favorites (the only contents are hidden credential dirs).
  // In that case there's nothing useful for the user to browse, so we
  // surface a hint instead of the generic empty state.
  const showHostHomeHint =
    homeData?.home === "/home/openhands" &&
    (homeData?.favorites?.length ?? 0) === 0 &&
    currentPath === homeData?.home &&
    !isLoading &&
    !isError &&
    subdirs.length === 0;

  const getBasename = (path: string): string => {
    const trimmed = trimTrailingSeparators(path);
    if (!trimmed) return "/";
    if (trimmed === "/" || isWindowsDriveRoot(trimmed)) return trimmed;
    const idx = Math.max(trimmed.lastIndexOf("/"), trimmed.lastIndexOf("\\"));
    return idx >= 0 ? trimmed.slice(idx + 1) || trimmed : trimmed;
  };

  const handleAddDirectory = () => {
    if (!currentPath) return;
    const item: LocalWorkspace = {
      id: currentPath,
      name: getBasename(currentPath),
      path: currentPath,
    };
    onAdd([item]);
    onClose();
  };

  const handleAddAllSubdirectories = () => {
    if (!currentPath || !onAddParent) return;
    onAddParent([
      {
        id: currentPath,
        name: getBasename(currentPath),
        path: currentPath,
      },
    ]);
    onClose();
  };

  return (
    <ModalBackdrop
      onClose={onClose}
      aria-label={t(I18nKey.HOME$ADD_WORKSPACES_TITLE)}
    >
      <div
        data-testid="folder-browser-modal"
        className={cn(
          "flex flex-col bg-surface border border-border-input rounded-xl",
          modalWidthClassName("xl"),
          MODAL_MAX_WIDTH_VIEWPORT,
          "h-120",
        )}
      >
        {/* Title bar */}
        <div className="flex items-center justify-between px-5 py-3 border-b border-border-input">
          <BaseModalTitle
            className={modalTitleSmClassName}
            title={t(I18nKey.HOME$ADD_WORKSPACES_TITLE)}
          />
        </div>

        {/* Body: sidebar + main */}
        <div className="flex flex-1 min-h-0">
          {/* Sidebar */}
          <aside
            data-testid="folder-browser-sidebar"
            className="w-28 md:w-45 shrink-0 border-r border-border-input bg-surface py-3 overflow-y-auto"
          >
            <SidebarSection
              label={t(I18nKey.HOME$FAVORITES)}
              entries={favorites}
              currentPath={currentPath}
              onPick={setCurrentPath}
            />
            <SidebarSection
              label={t(I18nKey.HOME$LOCATIONS)}
              entries={locations}
              currentPath={currentPath}
              onPick={setCurrentPath}
            />
          </aside>

          {/* Main */}
          <div className="flex-1 flex flex-col min-w-0">
            {/* Nav row */}
            <div className="flex items-center gap-2 px-4 py-2 border-b border-border-input">
              <button
                type="button"
                data-testid="folder-browser-up"
                onClick={() => parent && setCurrentPath(parent)}
                disabled={!parent}
                aria-label={t(I18nKey.COMMON$UP)}
                className="p-1 rounded hover:bg-interactive-hover text-contrast disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
              >
                <ChevronLeft width={16} height={16} />
              </button>
              <span
                className="text-xs text-muted truncate"
                data-testid="folder-browser-current-path"
              >
                {currentPath ?? ""}
              </span>
            </div>

            {/* Column headers */}
            <div
              data-testid="folder-browser-column-headers"
              className={cn(
                FOLDER_BROWSER_COLUMNS_CLASS_NAME,
                "px-4 py-1 border-b border-border-input text-xs text-text-secondary font-semibold",
              )}
            >
              <span>{t(I18nKey.HOME$NAME)}</span>
              <span>{t(I18nKey.HOME$KIND)}</span>
            </div>

            {/* List */}
            <ul
              className="flex-1 overflow-auto custom-scrollbar-always"
              data-testid="folder-browser-list"
            >
              {isLoading && (
                <li className="px-4 py-2 text-sm text-text-secondary">
                  {t(I18nKey.HOME$LOADING)}
                </li>
              )}
              {isError && (
                <li
                  className="px-4 py-2 text-sm text-red-400"
                  data-testid="folder-browser-error"
                >
                  {(error as Error | undefined)?.message ??
                    t(I18nKey.COMMON$FAILED_TO_LOAD)}
                </li>
              )}
              {!isLoading && !isError && subdirs.length === 0 && (
                <li
                  className="px-4 py-2 text-sm text-text-secondary"
                  data-testid={
                    showHostHomeHint
                      ? "folder-browser-host-home-hint"
                      : "folder-browser-empty"
                  }
                >
                  {showHostHomeHint
                    ? t(I18nKey.HOME$HOST_HOME_NOT_MOUNTED_HINT)
                    : t(I18nKey.HOME$NO_WORKSPACES)}
                </li>
              )}
              {subdirs.map((entry) => (
                <li key={entry.path}>
                  <button
                    type="button"
                    onClick={() => setCurrentPath(entry.path)}
                    className={cn(
                      FOLDER_BROWSER_COLUMNS_CLASS_NAME,
                      "items-center w-full text-left px-4 py-1.5 text-sm text-contrast hover:bg-interactive-hover cursor-pointer",
                    )}
                    data-testid={`folder-browser-entry-${entry.name}`}
                  >
                    <span className="flex items-center gap-2 min-w-0">
                      <FolderIcon width={16} height={16} className="shrink-0" />
                      <span className="truncate">{entry.name}</span>
                    </span>
                    <span className="text-text-secondary text-xs">
                      {t(I18nKey.HOME$FOLDER)}
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-2 px-5 py-3 border-t border-border-input">
          <BrandButton
            type="button"
            variant="secondary"
            onClick={onClose}
            testId="folder-browser-cancel"
          >
            {t(I18nKey.HOME$CANCEL)}
          </BrandButton>
          {onAddParent && (
            <BrandButton
              type="button"
              variant="secondary"
              onClick={handleAddAllSubdirectories}
              isDisabled={!currentPath || isLoading}
              testId="folder-browser-add-all-subdirs"
            >
              {t(I18nKey.HOME$ADD_ALL_SUBDIRECTORIES)}
            </BrandButton>
          )}
          <BrandButton
            type="button"
            variant="primary"
            onClick={handleAddDirectory}
            isDisabled={!currentPath || isLoading}
            testId="folder-browser-use"
          >
            {t(I18nKey.HOME$ADD_THIS_DIRECTORY)}
          </BrandButton>
        </div>
      </div>
    </ModalBackdrop>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";

import { BaseModalTitle } from "#/components/shared/modals/confirmation-modals/base-modal";
import { ModalBackdrop } from "#/components/shared/modals/modal-backdrop";
import {
  MODAL_MAX_WIDTH_VIEWPORT,
  modalWidthClassName,
} from "#/components/shared/modals/modal-body";
import { ConfirmationModal } from "#/components/shared/modals/confirmation-modal";
import { BrandButton } from "#/components/features/settings/brand-button";
import { I18nKey } from "#/i18n/declaration";
import { LocalWorkspace, LocalWorkspaceParent } from "#/types/workspace";
import { cn } from "#/utils/utils";
import { modalTitleSmClassName } from "#/utils/modal-classes";
import FolderIcon from "#/icons/folder.svg?react";
import CloseIcon from "#/icons/close.svg?react";

interface ManageWorkspacesModalProps {
  isOpen: boolean;
  workspaces: LocalWorkspace[];
  workspaceParents?: LocalWorkspaceParent[];
  onClose: () => void;
  onRemove: (path: string) => void;
  onRemoveParent?: (path: string) => void;
}

type PendingRemoval =
  | { type: "workspace"; path: string; text: string }
  | { type: "parent"; path: string; text: string };

export function ManageWorkspacesModal({
  isOpen,
  workspaces,
  workspaceParents = [],
  onClose,
  onRemove,
  onRemoveParent,
}: ManageWorkspacesModalProps) {
  const { t } = useTranslation("openhands");
  const [pendingRemoval, setPendingRemoval] =
    React.useState<PendingRemoval | null>(null);

  if (!isOpen) return null;

  // Workspaces from a parent are read-only here; users remove the parent.
  const staticWorkspaces = workspaces.filter((w) => !w.parentPath);
  const dynamicWorkspacesByParent = new Map<string, LocalWorkspace[]>();
  workspaces.forEach((w) => {
    if (!w.parentPath) return;
    const list = dynamicWorkspacesByParent.get(w.parentPath) ?? [];
    list.push(w);
    dynamicWorkspacesByParent.set(w.parentPath, list);
  });

  const hasContent = staticWorkspaces.length > 0 || workspaceParents.length > 0;

  const handleConfirmRemoval = () => {
    if (!pendingRemoval) return;

    if (pendingRemoval.type === "workspace") {
      onRemove(pendingRemoval.path);
    } else {
      onRemoveParent?.(pendingRemoval.path);
    }

    setPendingRemoval(null);
  };

  return (
    <>
      <ModalBackdrop
        onClose={onClose}
        aria-label={t(I18nKey.HOME$MANAGE_WORKSPACES)}
      >
        <div
          data-testid="manage-workspaces-modal"
          className={cn(
            "flex flex-col bg-surface border border-border-input rounded-xl",
            modalWidthClassName("lg"),
            MODAL_MAX_WIDTH_VIEWPORT,
            "max-h-[70vh]",
          )}
        >
          <div className="flex items-center justify-between px-5 py-3 border-b border-border-input">
            <BaseModalTitle
              className={modalTitleSmClassName}
              title={t(I18nKey.HOME$MANAGE_WORKSPACES)}
            />
          </div>

          <div
            className="flex-1 overflow-auto custom-scrollbar-always"
            data-testid="manage-workspaces-list"
          >
            {!hasContent && (
              <p className="px-5 py-6 text-sm text-text-secondary text-center">
                {t(I18nKey.HOME$MANAGE_WORKSPACES_EMPTY)}
              </p>
            )}

            {staticWorkspaces.length > 0 && (
              <ul>
                {staticWorkspaces.map((workspace) => (
                  <li
                    key={workspace.id}
                    className="flex items-center gap-3 px-5 py-2 border-b border-border-subtle last:border-b-0"
                    data-testid={`manage-workspaces-row-${workspace.name}`}
                  >
                    <FolderIcon width={16} height={16} className="shrink-0" />
                    <div className="flex flex-col min-w-0 flex-1">
                      <span className="text-sm text-contrast truncate">
                        {workspace.name}
                      </span>
                      <span className="text-xs text-muted truncate">
                        {workspace.path}
                      </span>
                    </div>
                    <button
                      type="button"
                      onClick={() =>
                        setPendingRemoval({
                          type: "workspace",
                          path: workspace.path,
                          text: t(I18nKey.HOME$REMOVE_WORKSPACE_CONFIRMATION, {
                            name: workspace.name,
                          }),
                        })
                      }
                      aria-label={t(I18nKey.HOME$REMOVE_WORKSPACE)}
                      data-testid={`manage-workspaces-remove-${workspace.name}`}
                      className="flex items-center gap-1 px-2 py-1 rounded text-xs text-text-tertiary hover:bg-interactive-hover hover:text-contrast cursor-pointer"
                    >
                      <CloseIcon width={12} height={12} />
                      <span>{t(I18nKey.HOME$REMOVE_WORKSPACE)}</span>
                    </button>
                  </li>
                ))}
              </ul>
            )}

            {workspaceParents.length > 0 && (
              <div data-testid="manage-workspaces-parents-section">
                <div className="px-5 pt-3 pb-1 text-[11px] uppercase tracking-wide text-muted font-semibold">
                  {t(I18nKey.HOME$WORKSPACE_PARENTS)}
                </div>
                <ul>
                  {workspaceParents.map((parent) => {
                    const children =
                      dynamicWorkspacesByParent.get(parent.path) ?? [];
                    return (
                      <li
                        key={parent.id}
                        className="border-b border-border-subtle last:border-b-0"
                        data-testid={`manage-workspaces-parent-row-${parent.name}`}
                      >
                        <div className="flex items-center gap-3 px-5 py-2">
                          <FolderIcon
                            width={16}
                            height={16}
                            className="shrink-0"
                          />
                          <div className="flex flex-col min-w-0 flex-1">
                            <span className="text-sm text-contrast truncate">
                              {parent.name}
                            </span>
                            <span className="text-xs text-muted truncate">
                              {parent.path}
                            </span>
                          </div>
                          {onRemoveParent && (
                            <button
                              type="button"
                              onClick={() =>
                                setPendingRemoval({
                                  type: "parent",
                                  path: parent.path,
                                  text: t(
                                    I18nKey.HOME$REMOVE_WORKSPACE_PARENT_CONFIRMATION,
                                    {
                                      name: parent.name,
                                      count: children.length,
                                    },
                                  ),
                                })
                              }
                              aria-label={t(
                                I18nKey.HOME$REMOVE_WORKSPACE_PARENT,
                              )}
                              data-testid={`manage-workspaces-remove-parent-${parent.name}`}
                              className="flex items-center gap-1 px-2 py-1 rounded text-xs text-text-tertiary hover:bg-interactive-hover hover:text-contrast cursor-pointer"
                            >
                              <CloseIcon width={12} height={12} />
                              <span>
                                {t(I18nKey.HOME$REMOVE_WORKSPACE_PARENT)}
                              </span>
                            </button>
                          )}
                        </div>
                        {children.length > 0 && (
                          <ul className="pb-2">
                            {children.map((child) => (
                              <li
                                key={child.id}
                                className="flex items-center gap-3 px-5 pl-10 py-1 text-xs text-text-secondary"
                                data-testid={`manage-workspaces-child-${child.name}`}
                              >
                                <FolderIcon
                                  width={12}
                                  height={12}
                                  className="shrink-0 opacity-70"
                                />
                                <span className="truncate">{child.name}</span>
                              </li>
                            ))}
                          </ul>
                        )}
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}
          </div>

          <div className="flex justify-end gap-2 px-5 py-3 border-t border-border-input">
            <BrandButton
              type="button"
              variant="primary"
              onClick={onClose}
              testId="manage-workspaces-done"
            >
              {t(I18nKey.HOME$DONE)}
            </BrandButton>
          </div>
        </div>
      </ModalBackdrop>

      {pendingRemoval && (
        <ConfirmationModal
          text={pendingRemoval.text}
          onConfirm={handleConfirmRemoval}
          onCancel={() => setPendingRemoval(null)}
        />
      )}
    </>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";
import { ModalBackdrop } from "#/components/shared/modals/modal-backdrop";
import { ModalCloseButton } from "#/components/shared/modals/modal-close-button";
import { I18nKey } from "#/i18n/declaration";

interface ImageLightboxProps {
  src: string;
  onClose: () => void;
}

/**
 * Full-size overlay for an image attachment. The thumbnail is a CSS downscale
 * of the same source, so no refetch is needed.
 */
export function ImageLightbox({ src, onClose }: ImageLightboxProps) {
  const { t } = useTranslation("openhands");

  // HeroUI consumes Escape on a document capture listener, so it never reaches
  // ModalBackdrop's window listener. Capture it here instead.
  React.useEffect(() => {
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.stopPropagation();
      onClose();
    };

    document.addEventListener("keydown", handleEscape, true);
    return () => document.removeEventListener("keydown", handleEscape, true);
  }, [onClose]);

  return (
    <ModalBackdrop
      onClose={onClose}
      closeOnEscape={false}
      aria-label={t(I18nKey.IMAGE$FULL_SIZE_PREVIEW)}
    >
      <div data-testid="image-lightbox" className="relative">
        <ModalCloseButton
          onClose={onClose}
          testId="image-lightbox-close"
          className="bg-black/60 text-white hover:bg-black/80"
        />
        <img
          src={src}
          alt={t(I18nKey.IMAGE$FULL_SIZE_PREVIEW)}
          className="max-h-[90vh] max-w-[90vw] rounded-lg object-contain"
        />
      </div>
    </ModalBackdrop>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";
import { ModalBackdrop } from "#/components/shared/modals/modal-backdrop";
import {
  MODAL_MAX_WIDTH_VIEWPORT,
  modalWidthClassName,
} from "#/components/shared/modals/modal-body";
import { ModalCloseButton } from "#/components/shared/modals/modal-close-button";
import { BrandButton } from "#/components/features/settings/brand-button";
import { I18nKey } from "#/i18n/declaration";
import { PluginSpec } from "#/api/conversation-service/agent-server-conversation-service.types";
import { Typography } from "#/ui/typography";
import { cn } from "#/utils/utils";
import { PluginLaunchPluginSection } from "./plugin-launch-plugin-section";

interface PluginLaunchModalProps {
  plugins: PluginSpec[];
  message?: string;
  isLoading?: boolean;
  onStartConversation: (plugins: PluginSpec[], initialMessage?: string) => void;
  onClose: () => void;
}

interface ExpandedState {
  [key: number]: boolean;
}

export function PluginLaunchModal({
  plugins,
  message,
  isLoading = false,
  onStartConversation,
  onClose,
}: PluginLaunchModalProps) {
  const { t } = useTranslation("openhands");
  const [pluginConfigs, setPluginConfigs] =
    React.useState<PluginSpec[]>(plugins);
  const [expandedSections, setExpandedSections] = React.useState<ExpandedState>(
    () => {
      // Initially expand plugins that have parameters
      const initial: ExpandedState = {};
      plugins.forEach((plugin, index) => {
        if (plugin.parameters && Object.keys(plugin.parameters).length > 0) {
          initial[index] = true;
        }
      });
      return initial;
    },
  );
  const [trustConfirmed, setTrustConfirmed] = React.useState(false);

  const pluginsWithParams = pluginConfigs.filter(
    (p) => p.parameters && Object.keys(p.parameters).length > 0,
  );
  const pluginsWithoutParams = pluginConfigs.filter(
    (p) => !p.parameters || Object.keys(p.parameters).length === 0,
  );

  const toggleSection = (index: number) => {
    setExpandedSections((prev) => ({
      ...prev,
      [index]: !prev[index],
    }));
  };

  const updateParameter = (
    pluginIndex: number,
    paramKey: string,
    value: unknown,
  ) => {
    setPluginConfigs((prev) => {
      const updated = [...prev];
      const plugin = { ...updated[pluginIndex] };
      plugin.parameters = {
        ...plugin.parameters,
        [paramKey]: value,
      };
      updated[pluginIndex] = plugin;
      return updated;
    });
  };

  const getPluginDisplayName = (plugin: PluginSpec): string => {
    const { source, repo_path: repoPath } = plugin;

    // If repo_path is specified, show the plugin name from the path
    if (repoPath) {
      const pathParts = repoPath.split("/");
      const pluginName = pathParts[pathParts.length - 1];
      return pluginName;
    }

    // Otherwise show the repo name
    if (source.startsWith("github:")) {
      return source.replace("github:", "");
    }
    if (source.includes("/")) {
      const parts = source.split("/");
      return parts[parts.length - 1].replace(".git", "");
    }
    return source;
  };

  const getPluginSourceInfo = (plugin: PluginSpec): string => {
    const { source } = plugin;
    if (source.startsWith("github:")) {
      return source.replace("github:", "");
    }
    if (source.includes("github.com/")) {
      return source.split("github.com/")[1]?.replace(".git", "") || source;
    }
    return source;
  };

  const getUniqueSources = (): string[] => {
    const sources = pluginConfigs.map((plugin) => getPluginSourceInfo(plugin));
    return [...new Set(sources)];
  };

  const handleStartConversation = () => {
    onStartConversation(pluginConfigs, message);
  };

  // The generic title already includes the verb ("Launch Plugin"), so only a
  // single plugin's display name is prefixed with "Launch".
  const modalTitle =
    pluginConfigs.length === 1
      ? `${t(I18nKey.LAUNCH$MODAL_TITLE)} ${getPluginDisplayName(pluginConfigs[0])}`
      : t(I18nKey.LAUNCH$MODAL_TITLE_GENERIC);

  return (
    <ModalBackdrop onClose={onClose}>
      <div
        data-testid="plugin-launch-modal"
        className={cn(
          "relative bg-base-secondary p-6 rounded-xl flex flex-col gap-4 border border-border max-h-[80vh]",
          modalWidthClassName("md"),
          MODAL_MAX_WIDTH_VIEWPORT,
        )}
      >
        <ModalCloseButton onClose={onClose} testId="close-button" />
        <Typography.H2 className="pr-6">{modalTitle}</Typography.H2>

        {message && <p className="text-sm text-contrast">{message}</p>}

        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {pluginsWithParams.length > 0 && (
            <div className="space-y-3">
              {pluginConfigs.map((plugin, index) => (
                <PluginLaunchPluginSection
                  key={`plugin-${index}`}
                  plugin={plugin}
                  originalIndex={index}
                  isExpanded={!!expandedSections[index]}
                  onToggle={() => toggleSection(index)}
                  getPluginDisplayName={getPluginDisplayName}
                  onParameterChange={updateParameter}
                />
              ))}
            </div>
          )}

          {pluginsWithoutParams.length > 0 && (
            <div className={cn(pluginsWithParams.length > 0 && "mt-4")}>
              <Typography.H3 className="mb-2 text-contrast">
                {pluginsWithParams.length > 0
                  ? t(I18nKey.LAUNCH$ADDITIONAL_PLUGINS)
                  : t(I18nKey.LAUNCH$PLUGINS)}
              </Typography.H3>
              <div className="space-y-2">
                {pluginsWithoutParams.map((plugin, index) => (
                  <div
                    key={`simple-plugin-${index}`}
                    className="rounded-md bg-tertiary px-3 py-2 text-sm"
                  >
                    <div className="font-medium">
                      {getPluginDisplayName(plugin)}
                    </div>
                    <div className="text-xs text-contrast mt-1">
                      {getPluginSourceInfo(plugin)}
                      {plugin.repo_path && (
                        <span className="ml-1">/ {plugin.repo_path}</span>
                      )}
                      {plugin.ref && (
                        <span className="ml-2">@ {plugin.ref}</span>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="pt-4 border-t border-border-subtle">
          <div className="flex items-start gap-3 mb-4">
            <input
              id="trust-checkbox"
              data-testid="trust-checkbox"
              type="checkbox"
              checked={trustConfirmed}
              onChange={(e) => setTrustConfirmed(e.target.checked)}
              className="mt-1 h-4 w-4 flex-shrink-0"
            />
            <label htmlFor="trust-checkbox" className="text-sm text-contrast">
              {t(I18nKey.LAUNCH$TRUST_PLUGIN_CHECKBOX, {
                sources: getUniqueSources().join(", "),
                interpolation: { escapeValue: false },
              })}
            </label>
          </div>
          <div className="flex w-full justify-end mt-8">
            <BrandButton
              testId="start-conversation-button"
              type="button"
              variant="primary"
              onClick={handleStartConversation}
              isDisabled={isLoading || !trustConfirmed}
              className="px-4"
            >
              {isLoading
                ? t(I18nKey.LAUNCH$STARTING)
                : t(I18nKey.LAUNCH$START_CONVERSATION)}
            </BrandButton>
          </div>
        </div>
      </div>
    </ModalBackdrop>
  );
}

import { useTranslation } from "react-i18next";
import { SettingsInput } from "#/components/features/settings/settings-input";
import { SettingsDropdownInput } from "#/components/features/settings/settings-dropdown-input";
import { GitRepoDropdown } from "#/components/features/home/git-repo-dropdown";
import { useActiveBackend } from "#/contexts/active-backend-context";
import { useUserProviders } from "#/hooks/use-user-providers";
import { I18nKey } from "#/i18n/declaration";
import {
  formControlMultilineFieldClassName,
  formControlSettingsFieldClassName,
} from "#/utils/form-control-classes";
import { cn } from "#/utils/utils";
import type { GitRepository } from "#/types/git";
import { fieldText, fieldValues } from "#/manifests/manifest-local-validation";
import { SetupRepositoryList } from "./manifest-repository-list";
import type {
  SetupFieldOption,
  SetupFormField as SetupFormFieldDefinition,
  SetupFormValue,
} from "#/manifests/types";

export interface SetupFormFieldProps {
  /** The record key the field is declared under, and what `{{form.x}}` reads. */
  name: string;
  field: SetupFormFieldDefinition;
  /** A list for a field collecting several values, a string for the rest. */
  value: SetupFormValue;
  /** Already-resolved copy: local checks and service errors look the same here. */
  error?: string;
  /** Declared options, or the ones the deployment supplied. */
  options: SetupFieldOption[];
  /** Whether dynamic options for this field are still loading. */
  isOptionsLoading?: boolean;
  /** The picked repository, kept so the picker can show what is selected. */
  repository: GitRepository | null;
  disabled: boolean;
  onChange: (value: SetupFormValue) => void;
  onRepositoryChange: (repository: GitRepository | null) => void;
  onBlur: () => void;
}

/**
 * Render one manifest-declared field.
 *
 * The host knows how to render a field *type*; what any field means is the
 * manifest's business. Every field's own copy comes from the manifest and is
 * never translated by the host; the only host string is the format hint the
 * repository fallback below needs, because no manifest declares it.
 */
export function SetupFormField({
  name,
  field,
  value,
  error,
  options,
  isOptionsLoading = false,
  repository,
  disabled,
  onChange,
  onRepositoryChange,
  onBlur,
}: SetupFormFieldProps) {
  const { t } = useTranslation("openhands");
  const { backend } = useActiveBackend();
  const { providers: connectedProviders } = useUserProviders();
  const testId = `setup-field-${name}`;
  const help = <p className="text-xs text-muted">{field.help}</p>;

  // Listing a user's repositories is a cloud-backend capability: `GitService`
  // answers with an empty page on any other backend, so the picker would offer
  // a source that can never respond. On a cloud backend it lists through the
  // instance's native integration for the field's provider, which a user who
  // connected that provider through an MCP server instead does not have.
  const canListRepositories =
    backend.kind === "cloud" &&
    connectedProviders.includes(field.provider ?? "github");

  // The format hint is host copy: a manifest states the format of everything it
  // declares except a repository, whose shape the host derives.
  const repositoryPlaceholder =
    field.placeholder ?? t(I18nKey.SETUP$REPOSITORY_PLACEHOLDER);

  if (field.type === "repo-picker" && field.multiple) {
    return (
      <div className="flex w-full flex-col gap-2.5">
        <FieldLabel field={field} />
        <SetupRepositoryList
          name={name}
          field={field}
          values={fieldValues(value)}
          canListRepositories={canListRepositories}
          placeholder={repositoryPlaceholder}
          disabled={disabled}
          onChange={onChange}
          onBlur={onBlur}
        />
        <FieldError testId={testId} error={error} />
        {help}
      </div>
    );
  }

  if (field.type === "repo-picker" && canListRepositories) {
    return (
      <div className="flex w-full flex-col gap-2.5">
        <FieldLabel field={field} />
        <GitRepoDropdown
          provider={field.provider ?? "github"}
          value={repository?.id ?? null}
          repositoryName={repository?.full_name ?? fieldText(value) ?? null}
          placeholder={field.placeholder}
          disabled={disabled}
          onChange={(selected) => {
            onRepositoryChange(selected ?? null);
            onChange(selected?.full_name ?? "");
            onBlur();
          }}
        />
        <FieldError testId={testId} error={error} />
        {help}
      </div>
    );
  }

  // A timezone or event field declares no options of its own: the accepted
  // values are the deployment's, so it renders as a list once they are known and
  // as a plain input when they are not. LLM profiles are different: they are a
  // semantic closed set owned by the current backend, so an unavailable list is
  // still shown as a disabled dropdown rather than an unrestricted text input.
  const shouldRenderDropdown =
    field.type === "select" ||
    field.type === "llm-profile" ||
    (["timezone", "event-source", "event-type"].includes(field.type) &&
      options.length > 0);
  if (shouldRenderDropdown) {
    const hasOptions = options.length > 0;
    const profileOptionsUnavailable =
      field.type === "llm-profile" && !isOptionsLoading && !hasOptions;
    return (
      <div className="flex w-full flex-col gap-2.5">
        <SettingsDropdownInput
          testId={testId}
          name={name}
          label={<FieldLabelText field={field} />}
          items={options.map((option) => ({
            key: option.value,
            label: option.label,
          }))}
          selectedKey={fieldText(value) || undefined}
          placeholder={
            profileOptionsUnavailable
              ? t(I18nKey.MODEL$NO_SAVED_PROFILES)
              : field.placeholder
          }
          isDisabled={disabled || profileOptionsUnavailable}
          isLoading={isOptionsLoading}
          required={field.required}
          onSelectionChange={(key) => {
            onChange(key === null ? "" : String(key));
            onBlur();
          }}
        />
        <FieldError testId={testId} error={error} />
        {help}
      </div>
    );
  }

  if (field.type === "plugin-sources") {
    return (
      <label className="flex w-full flex-col gap-2.5">
        <FieldLabelText field={field} />
        <textarea
          data-testid={testId}
          name={name}
          rows={4}
          value={fieldText(value)}
          placeholder={field.placeholder}
          disabled={disabled}
          aria-invalid={!!error}
          onChange={(event) => onChange(event.target.value)}
          onBlur={onBlur}
          className={cn(
            formControlMultilineFieldClassName,
            error && "border-red-500",
          )}
        />
        <FieldError testId={testId} error={error} />
        {help}
      </label>
    );
  }

  if (field.type === "tarball-upload") {
    return (
      <div className="flex w-full flex-col gap-2.5">
        <FieldLabel field={field} />
        <input
          data-testid={testId}
          name={name}
          type="file"
          accept=".tar,.tar.gz,.tgz,application/gzip,application/x-tar"
          disabled={disabled}
          aria-invalid={!!error}
          onChange={(event) => {
            onChange(event.target.files?.[0] ?? "");
            onBlur();
          }}
          className={cn(
            formControlSettingsFieldClassName,
            "file:mr-3 file:rounded-md file:border-0 file:bg-neutral-700 file:px-3 file:py-1.5 file:text-sm file:text-white",
            error && "border-red-500",
          )}
        />
        {fieldText(value) && (
          <p className="text-xs text-muted">{fieldText(value)}</p>
        )}
        <FieldError testId={testId} error={error} />
        {help}
      </div>
    );
  }

  if (field.type === "textarea") {
    return (
      <label className="flex w-full flex-col gap-2.5">
        <FieldLabelText field={field} />
        <textarea
          data-testid={testId}
          name={name}
          rows={4}
          value={fieldText(value)}
          placeholder={field.placeholder}
          disabled={disabled}
          aria-invalid={!!error}
          onChange={(event) => onChange(event.target.value)}
          onBlur={onBlur}
          className={cn(
            formControlMultilineFieldClassName,
            error && "border-red-500",
          )}
        />
        <FieldError testId={testId} error={error} />
        {help}
      </label>
    );
  }

  // `text`, `cron`, an unresolved `timezone` and a repository that cannot be
  // browsed are all single-line strings to the host; only the manifest and the
  // service know what a cron expression or a repository name means. A manifest
  // states the format of everything it declares except the repository, whose
  // shape the host derives, so that one hint is host copy.
  const placeholder =
    field.type === "repo-picker" ? repositoryPlaceholder : field.placeholder;

  return (
    <div className="flex w-full flex-col gap-2.5">
      <SettingsInput
        testId={testId}
        name={name}
        type={field.type === "number" ? "number" : "text"}
        label={field.label}
        value={fieldText(value)}
        placeholder={placeholder}
        isDisabled={disabled}
        min={field.constraints?.min}
        max={field.constraints?.max}
        showRequiredTag={field.required}
        error={error}
        onChange={onChange}
        onBlur={onBlur}
      />
      {help}
    </div>
  );
}

function FieldLabelText({ field }: { field: SetupFormFieldDefinition }) {
  return (
    <span className="flex items-center gap-2 text-sm">
      {field.label}
      {field.required && (
        <span className="text-sm leading-none text-red-400" aria-hidden>
          *
        </span>
      )}
    </span>
  );
}

function FieldLabel({ field }: { field: SetupFormFieldDefinition }) {
  return (
    <div className="flex items-center gap-2">
      <FieldLabelText field={field} />
    </div>
  );
}

function FieldError({ testId, error }: { testId: string; error?: string }) {
  if (!error) return null;
  return (
    <p
      role="alert"
      data-testid={`${testId}-error`}
      className="-mt-1 text-xs text-red-400"
    >
      {error}
    </p>
  );
}

import { AutomationAgentProfileSelector } from "#/components/features/automations/agent-profile-selector";
import { useEffect, useMemo, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router";
import { ModalBackdrop } from "#/components/shared/modals/modal-backdrop";
import { ModalCloseButton } from "#/components/shared/modals/modal-close-button";
import { BrandButton } from "#/components/features/settings/brand-button";
import { SettingsDropdownInput } from "#/components/features/settings/settings-dropdown-input";
import { LoadingSpinner } from "#/components/shared/loading-spinner";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import { modalTitleLgClassName } from "#/utils/modal-classes";
import { getApiErrorBody } from "#/utils/api-error-message";
import { useTracking } from "#/hooks/use-tracking";
import { notifySuperAdminSetupStep } from "#/components/features/setup-guide/super-admin-setup-step-event";
import { useSetupCapabilities } from "#/hooks/query/use-manifest-capabilities";
import { useSetupPrerequisites } from "#/hooks/query/use-manifest-prerequisites";
import { useLlmProfiles } from "#/hooks/query/use-llm-profiles";
import { useSetupPreflight } from "#/hooks/use-manifest-preflight";
import { useSetupAction } from "#/manifests/manifest-actions";
import {
  supportedActionKinds,
  supportedTriggerKinds,
} from "#/manifests/manifest-capabilities";
import {
  buildCreatePayload,
  deriveErrorMap,
  missingCreateEndpoints,
  supportsAgentProfile,
} from "#/manifests/automation-setup";
import {
  actionKinds,
  collectFields,
  getFieldOptions,
  getInitialFormValues,
  initialActionKind,
  initialTriggerKind,
  resolveFieldOverrides,
  triggerKinds,
  validateFormValues,
  type SetupFieldError,
  type SetupFieldErrors,
} from "#/manifests/manifest-local-validation";
import {
  mapServiceErrors,
  normalizeServiceErrors,
  type MappedManifestErrors,
} from "#/manifests/manifest-error-map";
import { automationDetailPath } from "#/manifests/automation-interface";
import { findAutomationCommand } from "#/utils/automation-catalog";
import type { GitRepository } from "#/types/git";
import type {
  SetupEntry,
  SetupFormValue,
  SetupFormValues,
  SetupMode,
  SetupRequestBody,
} from "#/manifests/types";
import { SetupFormField } from "./manifest-form-field";
import { SetupPrerequisitesStep } from "./manifest-prerequisites-step";
import { SetupReviewStep } from "./manifest-review-step";

type SetupStep = "prerequisites" | "form" | "review";

/** How long a field rests after a blur before the draft is sent for checking. */
const PREFLIGHT_DEBOUNCE_MS = 400;

const NO_SERVICE_ERRORS: MappedManifestErrors = {
  fieldErrors: {},
  formErrors: [],
};

function hasAnyError(errors: MappedManifestErrors): boolean {
  return (
    errors.formErrors.length > 0 || Object.keys(errors.fieldErrors).length > 0
  );
}

/** Where a completed setup lands: the new automation, or the conversation. */
function getDestination(response: Record<string, unknown>): string | null {
  if (typeof response.conversation_id === "string") {
    return `/conversations/${response.conversation_id}`;
  }
  if (typeof response.id === "string") return automationDetailPath(response.id);
  return null;
}

export interface SetupDialogProps {
  entry: SetupEntry;
  onClose: () => void;
}

/**
 * The setup host: capabilities check, prerequisites, form, review, and the
 * action the manifest's mode selects, rendered as a dialog.
 *
 * The host runs the stages and owns everything the same for every entry; the
 * manifest supplies only what varies. Any string the user reads here is either
 * manifest-authored or host chrome.
 */
export function SetupDialog({ entry, onClose }: SetupDialogProps) {
  const { t } = useTranslation("openhands");
  const navigate = useNavigate();

  const capabilities = useSetupCapabilities(entry);
  const prerequisites = useSetupPrerequisites(entry);
  const runPreflight = useSetupPreflight(entry);
  const runAction = useSetupAction();
  const {
    trackAutomationSetupOpened,
    trackAutomationSetupValidated,
    trackAutomationSetupCreated,
    trackAutomationSetupFailed,
  } = useTracking();

  const [step, setStep] = useState<SetupStep>("prerequisites");
  const allTriggerOptions = useMemo(() => triggerKinds(entry.setup), [entry]);
  const triggerOptions = useMemo(() => {
    if (allTriggerOptions.length === 0) return [];
    return capabilities.capabilities
      ? supportedTriggerKinds(entry, capabilities.capabilities)
      : allTriggerOptions;
  }, [allTriggerOptions, capabilities.capabilities, entry]);
  const allActionOptions = useMemo(() => actionKinds(entry.setup), [entry]);
  const [selectedTrigger, setSelectedTrigger] = useState<string | null>(() =>
    initialTriggerKind(entry.setup),
  );
  const [selectedAction, setSelectedAction] = useState<string | null>(() =>
    initialActionKind(entry.setup),
  );
  const [values, setValues] = useState<SetupFormValues>(() =>
    getInitialFormValues(
      entry.setup,
      initialTriggerKind(entry.setup),
      initialActionKind(entry.setup),
    ),
  );
  const [repositories, setRepositories] = useState<
    Record<string, GitRepository | null>
  >({});
  const [localErrors, setLocalErrors] = useState<SetupFieldErrors>({});
  const [serviceErrors, setServiceErrors] =
    useState<MappedManifestErrors>(NO_SERVICE_ERRORS);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Blur-triggered preflight reads the values as they are when the field is
  // left, which can be the same tick as the change that caused it.
  const valuesRef = useRef(values);
  const blurTimerRef = useRef<number | null>(null);
  useEffect(
    () => () => {
      if (blurTimerRef.current) window.clearTimeout(blurTimerRef.current);
    },
    [],
  );

  const actionOptions = useMemo(() => {
    if (allActionOptions.length === 0) return [];
    const supported = capabilities.capabilities
      ? supportedActionKinds(entry, capabilities.capabilities)
      : allActionOptions;
    return supported.filter(
      (kind) => missingCreateEndpoints(entry, kind).length === 0,
    );
  }, [allActionOptions, capabilities.capabilities, entry]);

  const fields = useMemo(
    () => collectFields(entry.setup, selectedTrigger, selectedAction),
    [entry, selectedTrigger, selectedAction],
  );
  const visibleFields = values.agent_profile_id
    ? Object.fromEntries(
        Object.entries(fields).filter(
          ([, field]) => field.type !== "llm-profile",
        ),
      )
    : fields;
  const canSelectAgentProfile =
    capabilities.capabilities?.features.includes("agentProfiles") === true &&
    supportsAgentProfile(entry, selectedAction);
  const hasLlmProfileField = useMemo(
    () => Object.values(fields).some((field) => field.type === "llm-profile"),
    [fields],
  );
  const { data: profilesData, isLoading: isLoadingProfiles } = useLlmProfiles({
    enabled: hasLlmProfileField,
  });
  const llmProfileOptions = useMemo(
    () =>
      (profilesData?.profiles ?? []).map((profile) => ({
        value: profile.name,
        label: profile.name,
      })),
    [profilesData?.profiles],
  );
  const overrides = useMemo(() => {
    const base = resolveFieldOverrides(
      entry.setup,
      capabilities.capabilities,
      selectedTrigger,
      selectedAction,
    );
    if (!hasLlmProfileField || isLoadingProfiles) return base;

    return Object.entries(fields).reduce(
      (next, [fieldName, field]) =>
        field.type === "llm-profile"
          ? { ...next, [fieldName]: { options: llmProfileOptions } }
          : next,
      base,
    );
  }, [
    entry.setup,
    capabilities.capabilities,
    selectedTrigger,
    selectedAction,
    hasLlmProfileField,
    isLoadingProfiles,
    fields,
    llmProfileOptions,
  ]);
  const payload = useMemo(
    () =>
      buildCreatePayload(
        entry,
        values,
        undefined,
        selectedTrigger,
        selectedAction,
      ),
    [entry, values, selectedTrigger, selectedAction],
  );
  const errorMap = useMemo(
    () => deriveErrorMap(entry, selectedTrigger, selectedAction),
    [entry, selectedTrigger, selectedAction],
  );

  const emittedOpenRef = useRef(false);
  useEffect(() => {
    if (emittedOpenRef.current) return;
    emittedOpenRef.current = true;
    trackAutomationSetupOpened({ automationId: entry.id });
  }, [entry.id, trackAutomationSetupOpened]);

  // An entry the published interface cannot create is refused here rather than
  // at the moment of creating: a bundle needs two endpoints a manifest from
  // before bundles does not declare, and no answer the user gives supplies
  // them. Named alongside the deployment's own unmet requirements, because
  // "which one" is the only thing that makes either diagnosable.
  const missingEndpoints = useMemo(
    () => missingCreateEndpoints(entry, selectedAction),
    [entry, selectedAction],
  );
  const isUnsupported =
    capabilities.supported === false || missingEndpoints.length > 0;
  const unmet = [...capabilities.unmet, ...missingEndpoints];
  const showPrerequisites =
    prerequisites.blockingIntegrations.length > 0 ||
    prerequisites.warningIntegrations.length > 0;
  // Prerequisites resolve asynchronously; deriving the step keeps an entry with
  // nothing to check from flashing an empty first screen.
  const currentStep: SetupStep =
    step === "prerequisites" && !showPrerequisites ? "form" : step;

  const setTriggerValue = (kind: string) => {
    setSelectedTrigger(kind);
    const defaults = getInitialFormValues(entry.setup, kind, selectedAction);
    valuesRef.current = { ...defaults, ...valuesRef.current };
    setValues(valuesRef.current);
    setLocalErrors({});
    setServiceErrors(NO_SERVICE_ERRORS);
  };

  const setActionValue = (kind: string) => {
    setSelectedAction(kind);
    const defaults = getInitialFormValues(entry.setup, selectedTrigger, kind);
    valuesRef.current = {
      ...defaults,
      ...valuesRef.current,
      ...(supportsAgentProfile(entry, kind) ? {} : { agent_profile_id: "" }),
    };
    setValues(valuesRef.current);
    setLocalErrors({});
    setServiceErrors(NO_SERVICE_ERRORS);
  };

  useEffect(() => {
    if (allTriggerOptions.length === 0 || capabilities.isLoading) return;
    if (selectedTrigger && triggerOptions.includes(selectedTrigger)) return;
    if (triggerOptions.length > 0) setTriggerValue(triggerOptions[0]);
  }, [
    triggerOptions,
    allTriggerOptions.length,
    capabilities.isLoading,
    selectedTrigger,
  ]);

  useEffect(() => {
    if (allActionOptions.length === 0 || capabilities.isLoading) return;
    if (
      selectedAction &&
      actionOptions.includes(selectedAction as (typeof actionOptions)[number])
    ) {
      return;
    }
    if (actionOptions.length > 0) setActionValue(actionOptions[0]);
  }, [
    actionOptions,
    allActionOptions.length,
    capabilities.isLoading,
    selectedAction,
  ]);

  const setFieldValue = (name: string, value: SetupFormValue) => {
    valuesRef.current = { ...valuesRef.current, [name]: value };
    setValues(valuesRef.current);
    setLocalErrors(({ [name]: _removed, ...rest }) => rest);
    setServiceErrors((current) => {
      if (!(name in current.fieldErrors)) return current;
      const { [name]: _cleared, ...fieldErrors } = current.fieldErrors;
      return { ...current, fieldErrors };
    });
  };

  const handleFieldBlur = () => {
    if (blurTimerRef.current) window.clearTimeout(blurTimerRef.current);
    blurTimerRef.current = window.setTimeout(() => {
      void runPreflight(
        valuesRef.current,
        selectedTrigger,
        selectedAction,
      ).then((result) => {
        if (result) setServiceErrors(result);
      });
    }, PREFLIGHT_DEBOUNCE_MS);
  };

  const handleContinue = async () => {
    if (currentStep === "prerequisites") {
      setStep("form");
      return;
    }

    const failures = validateFormValues(
      entry.setup,
      values,
      overrides,
      selectedTrigger,
      selectedAction,
    );
    if (Object.keys(failures).length > 0) {
      setLocalErrors(failures);
      return;
    }
    setLocalErrors({});

    const result = await runPreflight(values, selectedTrigger, selectedAction);
    if (result && hasAnyError(result)) {
      setServiceErrors(result);
      return;
    }

    setServiceErrors(NO_SERVICE_ERRORS);
    trackAutomationSetupValidated({ automationId: entry.id });
    setStep("review");
  };

  const submitAction = async (
    actionPayload: SetupRequestBody | null,
    setupMode: SetupMode,
  ) => {
    setIsSubmitting(true);
    try {
      const { response } = await runAction(
        entry,
        values,
        actionPayload,
        selectedTrigger,
        selectedAction,
      );
      trackAutomationSetupCreated({
        automationId: entry.id,
        setupMode,
      });
      // An assisted setup only starts the conversation that creates it.
      if (setupMode === "direct") notifySuperAdminSetupStep("first-automation");
      const destination = getDestination(response);
      if (destination) navigate(destination, { replace: true });
      else onClose();
    } catch (error) {
      trackAutomationSetupFailed({
        automationId: entry.id,
        setupMode,
      });
      const mapped = mapServiceErrors(
        normalizeServiceErrors(getApiErrorBody(error), actionPayload),
        errorMap,
      );
      setServiceErrors(
        hasAnyError(mapped)
          ? mapped
          : {
              fieldErrors: {},
              formErrors: [t(I18nKey.SETUP$SUBMIT_FAILED)],
            },
      );
      setStep("form");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleConfirm = () => submitAction(payload, entry.setup.mode);

  // A direct entry whose deployment cannot run the direct path degrades to the
  // assisted outcome: the skill command and the entry's fallback message seed
  // a conversation that finishes setup instead.
  const handleFallbackConversation = () => submitAction(null, "assisted");
  const canFallBackToConversation =
    entry.setup.mode === "direct" &&
    (findAutomationCommand(entry) !== null ||
      entry.setup.message !== undefined);

  const resolveFieldError = (name: string): string | undefined => {
    const local = localErrors[name];
    return local ? formatFieldError(local, t) : serviceErrors.fieldErrors[name];
  };

  const isLoading = capabilities.isLoading || prerequisites.isLoading;
  const isLoadingLlmProfileOptions = hasLlmProfileField && isLoadingProfiles;

  const title = (() => {
    if (isUnsupported) return t(I18nKey.SETUP$UNAVAILABLE_TITLE);
    if (currentStep === "prerequisites")
      return t(I18nKey.SETUP$PREREQUISITES_TITLE);
    if (currentStep === "review") return t(I18nKey.SETUP$REVIEW_TITLE);
    return entry.name;
  })();

  return (
    <ModalBackdrop onClose={onClose} aria-label={entry.name}>
      <div
        data-testid="setup-dialog"
        className="relative flex max-h-[85vh] w-[92vw] max-w-lg flex-col rounded-xl border border-border bg-base-secondary"
      >
        <ModalCloseButton
          onClose={onClose}
          testId="setup-dialog-close"
          disabled={isSubmitting}
        />
        <header className="flex-shrink-0 px-6 pb-4 pt-6">
          <h2 className={cn("pr-6", modalTitleLgClassName)}>{title}</h2>
        </header>

        <div className="min-h-0 flex-1 overflow-y-auto px-6">
          {isLoading && (
            <div className="flex justify-center py-6">
              <LoadingSpinner size="small" />
            </div>
          )}

          {!isLoading && isUnsupported && (
            <div className="flex flex-col gap-2">
              <p className="text-sm text-muted">
                {t(I18nKey.SETUP$UNSUPPORTED_MESSAGE)}
              </p>
              {/* The unmet requirements are the names both sides of the
                  contract already use, so they are printed rather than
                  translated. Without them the block is undiagnosable: the
                  deployment answered, and the host would be discarding the
                  one thing it learned. */}
              {unmet.length > 0 && (
                <p
                  data-testid="setup-unmet-requirements"
                  className="text-sm text-muted"
                >
                  {unmet.join(", ")}
                </p>
              )}
            </div>
          )}

          {!isLoading && !isUnsupported && currentStep === "prerequisites" && (
            <SetupPrerequisitesStep prerequisites={prerequisites} />
          )}

          {!isLoading && !isUnsupported && currentStep === "form" && (
            <div className="flex flex-col gap-5">
              <p className="text-sm text-muted">{entry.description}</p>
              {entry.setup.form.note && (
                <p className="text-sm text-muted">{entry.setup.form.note}</p>
              )}
              {allActionOptions.length > 1 && actionOptions.length > 1 && (
                <div className="flex w-full flex-col gap-2.5">
                  <SettingsDropdownInput
                    testId="setup-action-kind"
                    name="actionKind"
                    label={t(I18nKey.SETUP$ACTION_LABEL)}
                    items={actionOptions.map((kind) => {
                      const action = entry.setup.actions?.[kind];
                      return {
                        key: kind,
                        label: action?.label ?? kind,
                      };
                    })}
                    selectedKey={selectedAction ?? undefined}
                    isDisabled={isSubmitting}
                    required
                    onSelectionChange={(key) => {
                      if (key !== null) setActionValue(String(key));
                    }}
                  />
                  {selectedAction &&
                    entry.setup.actions?.[
                      selectedAction as keyof typeof entry.setup.actions
                    ] && (
                      <p className="text-xs text-muted">
                        {
                          entry.setup.actions[
                            selectedAction as keyof typeof entry.setup.actions
                          ]?.help
                        }
                      </p>
                    )}
                </div>
              )}
              {triggerOptions.length > 1 && (
                <div className="flex w-full flex-col gap-2.5">
                  <SettingsDropdownInput
                    testId="setup-trigger-kind"
                    name="triggerKind"
                    label={t(I18nKey.SETUP$TRIGGER_LABEL)}
                    items={triggerOptions.map((kind) => ({
                      key: kind,
                      label: kind === "cron" ? "Scheduled" : "Event",
                    }))}
                    selectedKey={selectedTrigger ?? undefined}
                    isDisabled={isSubmitting}
                    required
                    onSelectionChange={(key) => {
                      if (key !== null) setTriggerValue(String(key));
                    }}
                  />
                  <p className="text-xs text-muted">
                    {t(I18nKey.SETUP$TRIGGER_HELP)}
                  </p>
                </div>
              )}
              {canSelectAgentProfile && (
                <AutomationAgentProfileSelector
                  // The form stores "no profile" as "", but the selector only
                  // reads null/undefined as Default; "" would render it blank.
                  value={
                    typeof values.agent_profile_id === "string" &&
                    values.agent_profile_id !== ""
                      ? values.agent_profile_id
                      : null
                  }
                  onChange={(value) =>
                    setFieldValue("agent_profile_id", value ?? "")
                  }
                />
              )}
              {Object.entries(visibleFields).map(([name, field]) => (
                <SetupFormField
                  key={name}
                  name={name}
                  field={field}
                  value={values[name] ?? ""}
                  error={resolveFieldError(name)}
                  options={getFieldOptions(name, field, overrides)}
                  repository={repositories[name] ?? null}
                  disabled={isSubmitting}
                  isOptionsLoading={
                    field.type === "llm-profile" && isLoadingLlmProfileOptions
                  }
                  onChange={(value) => setFieldValue(name, value)}
                  onRepositoryChange={(repository) =>
                    setRepositories((current) => ({
                      ...current,
                      [name]: repository,
                    }))
                  }
                  onBlur={handleFieldBlur}
                />
              ))}
            </div>
          )}

          {!isLoading && !isUnsupported && currentStep === "review" && (
            <SetupReviewStep
              setup={entry.setup}
              values={values}
              selectedTrigger={selectedTrigger}
              selectedAction={selectedAction}
            />
          )}

          {serviceErrors.formErrors.map((message) => (
            <p
              key={message}
              role="alert"
              data-testid="setup-form-error"
              className="pt-4 text-sm text-red-400"
            >
              {message}
            </p>
          ))}
        </div>

        <footer className="flex flex-shrink-0 justify-end gap-2 px-6 pb-6 pt-4">
          {currentStep === "review" && (
            <BrandButton
              testId="setup-back-button"
              type="button"
              variant="secondary"
              isDisabled={isSubmitting}
              onClick={() => setStep("form")}
            >
              {t(I18nKey.BUTTON$BACK)}
            </BrandButton>
          )}

          {isUnsupported ? (
            <>
              <BrandButton
                type="button"
                variant="secondary"
                isDisabled={isSubmitting}
                onClick={onClose}
              >
                {t(I18nKey.BUTTON$CLOSE)}
              </BrandButton>
              {canFallBackToConversation && (
                <BrandButton
                  testId="setup-fallback-conversation"
                  type="button"
                  variant="primary"
                  isDisabled={isSubmitting}
                  onClick={handleFallbackConversation}
                >
                  {t(I18nKey.SETUP$FALLBACK_CONVERSATION)}
                </BrandButton>
              )}
            </>
          ) : (
            <BrandButton
              testId="setup-continue-button"
              type="button"
              variant="primary"
              isDisabled={
                isLoading ||
                isLoadingLlmProfileOptions ||
                isSubmitting ||
                (currentStep === "prerequisites" && prerequisites.isBlocked)
              }
              onClick={
                currentStep === "review" ? handleConfirm : handleContinue
              }
            >
              {currentStep === "review"
                ? t(I18nKey.SETUP$CONFIRM)
                : t(I18nKey.BUTTON$CONTINUE)}
            </BrandButton>
          )}
        </footer>
      </div>
    </ModalBackdrop>
  );
}

function formatFieldError(
  error: SetupFieldError,
  t: (key: I18nKey, options?: Record<string, unknown>) => string,
): string {
  switch (error.code) {
    case "required":
      return t(I18nKey.SETUP$VALIDATION_REQUIRED);
    case "minLength":
      return t(I18nKey.SETUP$VALIDATION_MIN_LENGTH, { length: error.length });
    case "maxLength":
      return t(I18nKey.SETUP$VALIDATION_MAX_LENGTH, { length: error.length });
    case "min":
      return `Must be at least ${error.value}.`;
    case "max":
      return `Must be at most ${error.value}.`;
    case "invalidOption":
      return t(I18nKey.SETUP$VALIDATION_INVALID_OPTION);
    case "unsafeExpressionLiteral":
      return t(I18nKey.SETUP$VALIDATION_UNSAFE_VALUE);
    default: {
      // A code added to `SetupFieldError` without a message here is a compile
      // error rather than a field that silently reads "this field is required".
      const exhaustive: never = error;
      return exhaustive;
    }
  }
}

