/**
 * Renders a helperText string as React nodes, converting any `[text](url)`
 * markdown links into real `<a>` elements. Plain text segments are left as-is.
 * Only `http:` and `https:` URLs are rendered as links; anything else falls
 * back to `#` to guard against `javascript:` / `data:` XSS vectors.
 */
function renderHelperText(text: string): React.ReactNode {
  const linkPattern = /\[([^\]]+)\]\(([^)]+)\)/g;
  const parts: React.ReactNode[] = [];
  let lastIndex = 0;
  for (const match of text.matchAll(linkPattern)) {
    if (match.index > lastIndex) {
      parts.push(text.slice(lastIndex, match.index));
    }
    parts.push(
      <a
        key={match.index}
        href={/^https?:\/\//i.test(match[2]) ? match[2] : "#"}
        target="_blank"
        rel="noreferrer"
        className="underline hover:text-contrast transition-colors"
      >
        {match[1]}
      </a>,
    );
    lastIndex = match.index + match[0].length;
  }
  if (lastIndex < text.length) {
    parts.push(text.slice(lastIndex));
  }
  return parts;
}

interface InstallServerModalProps {
  entry: MarketplaceEntry;
  /** Servers installed before this modal opened — guards health seeding. */
  existingServers: MCPServerConfig[];
  onClose: () => void;
  onSuccess?: (entry: MarketplaceEntry) => void;
  /**
   * When true, an entry that has an MCP option opens on its MCP form without
   * offering the instance's native integration. Defaults to false.
   */
  mcpOnly?: boolean;
}

interface FieldState {
  values: Record<string, string>;
  errors: Record<string, string | null>;
  savedAsSecret: Record<string, boolean>;
}

function optionNeedsCredentialField(
  option: McpMarketplaceConnectionOption | undefined,
): boolean {
  if (option?.transport.kind !== "shttp" && option?.transport.kind !== "sse") {
    return false;
  }
  return ["api_key", "bearer"].includes(option.auth.strategy);
}

function isOAuthOption(
  option: McpMarketplaceConnectionOption | undefined,
): boolean {
  return !!option && option.auth.strategy === "oauth2";
}

function isCredentialOptional(option: McpMarketplaceConnectionOption): boolean {
  if (option.transport.kind === "stdio") {
    return option.auth.apiKeyOptional ?? false;
  }
  return option.auth.apiKeyOptional ?? option.transport.apiKeyOptional ?? false;
}

function getRemoteHeaderFields(
  option: McpMarketplaceConnectionOption | undefined,
): MarketplaceField[] {
  if (option?.transport.kind !== "shttp" && option?.transport.kind !== "sse") {
    return [];
  }
  return option.transport.headerFields ?? [];
}

function makeInitialState(entry: MarketplaceEntry): FieldState {
  const values: Record<string, string> = {};
  const savedAsSecret: Record<string, boolean> = {};
  const option = getInstallableMcpConnectionOption(entry);
  const template = option?.transport;
  if (template?.kind === "stdio") {
    for (const field of template.envFields ?? []) {
      values[field.key] = "";
      // Pre-check password fields; non-password fields default to off.
      savedAsSecret[field.key] = field.type === "password";
    }
    for (const field of template.argFields ?? []) {
      values[field.key] = "";
    }
  } else if (template?.kind === "shttp" || template?.kind === "sse") {
    values.url = template.url;
    for (const field of getRemoteHeaderFields(option)) {
      values[field.key] = "";
      savedAsSecret[field.key] = field.type === "password";
    }
    if (optionNeedsCredentialField(option)) {
      values.api_key = "";
      if (option?.auth.credentialSecretName) {
        savedAsSecret.api_key =
          option.auth.saveCredentialAsSecretByDefault ?? false;
      }
    }
  }
  return { values, errors: {}, savedAsSecret };
}

// The marketplace install modal is intentionally add-only: clicking
// a catalog tile always appends a new server (the user might want
// two Slack workspaces, two Postgres connections, etc.) even when
// one of the same template kind is already installed. Editing an
// existing server is reached via the installed-server-card's edit
// button, which opens `CustomServerEditor` instead.
export function InstallServerModal({
  entry,
  existingServers,
  onClose,
  onSuccess,
  mcpOnly = false,
}: InstallServerModalProps) {
  const { t } = useTranslation("openhands");
  const { mutate: addMcpServer, isPending: isAdding } = useAddMcpServer();
  const { mutate: testMcpServer, isPending: isTesting } = useTestMcpServer();
  const saveFieldsAsSecrets = useSaveFieldsAsSecrets();
  const { backend } = useActiveBackend();
  const isCloudBackend = backend.kind === "cloud";

  const [state, setState] = React.useState<FieldState>(() =>
    makeInitialState(entry),
  );
  // Always holds the latest state so async callbacks (onSuccess) never read
  // stale closure values, even under React concurrent-mode scheduling.
  const stateRef = React.useRef(state);
  stateRef.current = state;

  const [globalError, setGlobalError] = React.useState<string | null>(null);
  const [isFinalizingInstall, setIsFinalizingInstall] = React.useState(false);
  const [isAuthorizingOAuth, setIsAuthorizingOAuth] = React.useState(false);
  const option = getInstallableMcpConnectionOption(entry);
  const template = option?.transport;
  // stdio servers on cloud backends get a synthetic test success (they only
  // run inside the sandbox); never seed card health from it.
  const isSyntheticTest = isCloudBackend && template?.kind === "stdio";

  // A git entry the cloud instance can also connect natively offers that as
  // the recommended option next to the MCP server; an entry with no MCP
  // option (Bitbucket) offers only the native one. A caller that asked for the
  // MCP server alone skips the native option whenever the entry has an MCP one.
  const { getNativeIntegration, isLoading: isNativeIntegrationsLoading } =
    useNativeGitIntegrations();
  const skipNative = mcpOnly && !!option;
  const native = skipNative ? null : getNativeIntegration(entry.id);
  // Until the instance's providers are known, a git entry cannot say whether
  // it leads with the native option; showing the MCP form meanwhile would swap
  // it out from under the user once the answer arrives.
  const isResolvingNative =
    !skipNative &&
    isNativeIntegrationsLoading &&
    isNativeGitCandidate(entry.id);
  const [selectedConnection, setSelectedConnection] = React.useState<
    "native" | "mcp"
  >("native");
  const showConnectionTabs = !!native && !!option;
  const isNativeSelected =
    !!native && (!option || selectedConnection === "native");

  const isPending =
    isTesting || isAuthorizingOAuth || isAdding || isFinalizingInstall;

  const setValue = (key: string, value: string) => {
    setState((prev) => ({
      ...prev,
      values: { ...prev.values, [key]: value },
      errors: { ...prev.errors, [key]: null },
    }));
    setGlobalError(null);
  };

  const toggleSecret = (key: string, value: boolean) => {
    setState((prev) => ({
      ...prev,
      savedAsSecret: { ...prev.savedAsSecret, [key]: value },
    }));
  };

  const saveHostedCredentialAsSecret = (): Promise<void> => {
    const secretName = option?.auth.credentialSecretName;
    const apiKey = stateRef.current.values.api_key?.trim();
    if (!secretName || !apiKey || !stateRef.current.savedAsSecret.api_key) {
      return Promise.resolve();
    }

    const field: MarketplaceField = {
      key: secretName,
      label: option.auth.credentialLabel ?? secretName,
      type: "password",
      required: true,
    };
    return saveFieldsAsSecrets(
      [field],
      { [secretName]: apiKey },
      { [secretName]: true },
    );
  };

  const saveSelectedSecrets = (): Promise<void> => {
    if (template?.kind === "stdio") {
      return saveFieldsAsSecrets(
        template.envFields ?? [],
        stateRef.current.values,
        stateRef.current.savedAsSecret,
      );
    }
    if (template?.kind === "shttp" || template?.kind === "sse") {
      return Promise.all([
        saveHostedCredentialAsSecret(),
        saveFieldsAsSecrets(
          getRemoteHeaderFields(option),
          stateRef.current.values,
          stateRef.current.savedAsSecret,
        ),
      ]).then(() => undefined);
    }
    return Promise.resolve();
  };

  const submitServer = (payload: MCPServerConfig) => {
    if (payload.auth?.strategy === "oauth2") {
      setIsAuthorizingOAuth(true);
      void McpService.authorizeOAuth(payload)
        .then((result) => {
          if (!result.ok) {
            setGlobalError(
              makeMcpTestErrorMessage(
                t,
                result.error_kind,
                result.error,
                payload.type,
              ),
            );
            return;
          }
          const serverToSave = result.oauth_state
            ? {
                ...payload,
                auth: { ...payload.auth!, state: result.oauth_state },
              }
            : payload;
          addMcpServer(serverToSave, {
            onSuccess: () => {
              if (!isSyntheticTest) {
                seedMcpServerHealth(serverToSave, result, existingServers);
              }
              displaySuccessToast(t(I18nKey.MCP$INSTALL_SUCCESS));
              setIsFinalizingInstall(true);
              void (async () => {
                try {
                  await saveSelectedSecrets();
                } finally {
                  onSuccess?.(entry);
                  onClose();
                }
              })();
            },
            onError: (err: unknown) => {
              const message = retrieveAxiosErrorMessage(err as AxiosError);
              setGlobalError(message || t(I18nKey.ERROR$GENERIC));
            },
          });
        })
        .catch((err: unknown) => {
          const message = retrieveAxiosErrorMessage(err as AxiosError);
          setGlobalError(message || t(I18nKey.ERROR$GENERIC));
        })
        .finally(() => setIsAuthorizingOAuth(false));
      return;
    }
    testMcpServer(payload, {
      onSuccess: (result) => {
        if (!result.ok) {
          setGlobalError(
            makeMcpTestErrorMessage(
              t,
              result.error_kind,
              result.error,
              payload.type,
            ),
          );
          // Modal stays open — do NOT call onClose.
          return;
        }
        const serverToSave =
          result.oauth_state && payload.auth?.strategy === "oauth2"
            ? {
                ...payload,
                auth: { ...payload.auth, state: result.oauth_state },
              }
            : payload;
        addMcpServer(serverToSave, {
          onSuccess: () => {
            if (!isSyntheticTest) {
              seedMcpServerHealth(serverToSave, result, existingServers);
            }
            displaySuccessToast(t(I18nKey.MCP$INSTALL_SUCCESS));
            setIsFinalizingInstall(true);
            void (async () => {
              try {
                await saveSelectedSecrets();
              } finally {
                onSuccess?.(entry);
                onClose();
              }
            })();
          },
          onError: (err: unknown) => {
            const message = retrieveAxiosErrorMessage(err as AxiosError);
            setGlobalError(message || t(I18nKey.ERROR$GENERIC));
          },
        });
      },
      onError: (err: unknown) => {
        const message = retrieveAxiosErrorMessage(err as AxiosError);
        setGlobalError(message || t(I18nKey.ERROR$GENERIC));
      },
    });
  };

  // ------------------------------------------------------------------
  // Per-template submit handlers. Each is small and self-contained:
  // validate user input, build the payload, then hand off to
  // submitServer.
  // ------------------------------------------------------------------
  const handleHttpServerSubmit = () => {
    // TS narrows this branch to shttp|sse; the equality guard is a
    // runtime/defensive belt to make the helper safe in isolation.
    if (template?.kind !== "shttp" && template?.kind !== "sse") {
      return;
    }
    if (!option) return;
    const apiKey = state.values.api_key?.trim() ?? "";
    const url = template.urlEditable
      ? (state.values.url?.trim() ?? "")
      : template.url;
    const oauthMode = isOAuthOption(option);
    const needsCredential = optionNeedsCredentialField(option);
    const headerFields = getRemoteHeaderFields(option);
    const headerErrors: Record<string, string | null> = {};
    if (!url) {
      headerErrors.url = t(I18nKey.SETTINGS$MCP_ERROR_URL_REQUIRED);
    } else {
      try {
        const parsedUrl = new URL(url);
        if (!["http:", "https:"].includes(parsedUrl.protocol)) {
          headerErrors.url = t(I18nKey.SETTINGS$MCP_ERROR_URL_INVALID_PROTOCOL);
        }
      } catch {
        headerErrors.url = t(I18nKey.SETTINGS$MCP_ERROR_URL_INVALID);
      }
    }
    for (const field of headerFields) {
      if (field.required && !(state.values[field.key] ?? "").trim()) {
        headerErrors[field.key] = t(I18nKey.MCP$ERROR_FIELD_REQUIRED);
      }
    }
    if (
      !oauthMode &&
      needsCredential &&
      !isCredentialOptional(option) &&
      !apiKey
    ) {
      headerErrors.api_key = t(I18nKey.MCP$ERROR_FIELD_REQUIRED);
    }
    if (Object.values(headerErrors).some(Boolean)) {
      setState((prev) => ({ ...prev, errors: headerErrors }));
      return;
    }
    const oauthAuthentication = oauthMode
      ? getMcpOAuthAuthenticationConfig(option)
      : undefined;
    const fieldHeaders = Object.fromEntries(
      headerFields
        .map((field) => [field.key, state.values[field.key]?.trim() ?? ""])
        .filter(([, value]) => value),
    );
    const hasFieldHeaders = Object.keys(fieldHeaders).length > 0;
    let auth: MCPAuthCredential | undefined;
    if (oauthMode) {
      auth = {
        strategy: "oauth2",
        ...(oauthAuthentication && { authentication: oauthAuthentication }),
      };
    } else if (needsCredential && apiKey) {
      auth =
        option.auth.strategy === "api_key"
          ? {
              strategy: "api_key",
              value: apiKey,
              ...(option.auth.apiKeyHeaderName && {
                header_name: option.auth.apiKeyHeaderName,
              }),
            }
          : { strategy: "bearer", value: apiKey };
    } else if (hasFieldHeaders) {
      auth = { strategy: "header", headers: fieldHeaders };
    }
    const payload: MCPServerConfig = {
      id: "",
      type: template.kind,
      // Name remote servers after the catalog slug (e.g. "github") so they
      // get a referenceable, LLM-tool-safe mcp_config key instead of the
      // auto-generated "sse"/"shttp" fallback. Stdio installs already carry
      // serverName from the catalog.
      name: toMcpServerName(entry.id),
      url,
      ...(auth && { auth }),
      ...(hasFieldHeaders &&
        auth?.strategy !== "header" && { headers: fieldHeaders }),
    };
    submitServer(payload);
  };

  const handleStdioSubmit = () => {
    if (template?.kind !== "stdio") return;
    const stdio = template;
    const errors: Record<string, string | null> = {};

    for (const field of stdio.envFields ?? []) {
      if (field.required && !(state.values[field.key] ?? "").trim()) {
        errors[field.key] = t(I18nKey.MCP$ERROR_FIELD_REQUIRED);
      }
    }
    for (const field of stdio.argFields ?? []) {
      if (field.required && !(state.values[field.key] ?? "").trim()) {
        errors[field.key] = t(I18nKey.MCP$ERROR_FIELD_REQUIRED);
      }
    }
    if (Object.values(errors).some(Boolean)) {
      setState((prev) => ({ ...prev, errors }));
      return;
    }

    const env: Record<string, string> = {};
    for (const field of stdio.envFields ?? []) {
      const v = state.values[field.key]?.trim();
      if (v) env[field.key] = v;
    }
    const extraArgs: string[] = [];
    for (const field of stdio.argFields ?? []) {
      const v = state.values[field.key]?.trim();
      if (v) {
        // Filesystem-style multi-token input: split on whitespace.
        for (const token of v.split(/\s+/)) {
          if (token) extraArgs.push(token);
        }
      }
    }

    const payload: MCPServerConfig = {
      id: "",
      type: "stdio",
      name: stdio.serverName,
      command: stdio.command,
      args: [...stdio.args, ...extraArgs],
      ...(Object.keys(env).length > 0 && { env }),
    };
    submitServer(payload);
  };

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setGlobalError(null);
    if (template?.kind === "shttp" || template?.kind === "sse") {
      return handleHttpServerSubmit();
    }
    return handleStdioSubmit();
  };

  // @spec MCP-004 — Form feedback follows readable theme text roles
  const renderFields = () => {
    if (template?.kind === "shttp" || template?.kind === "sse") {
      const oauthMode = isOAuthOption(option);
      const shouldRenderCredential = optionNeedsCredentialField(option);
      const apiKeyOptional = option ? isCredentialOptional(option) : false;
      const credentialSecretName = option?.auth.credentialSecretName;
      const headerFields = getRemoteHeaderFields(option);
      return (
        <>
          <SettingsInput
            testId="mcp-install-field-url"
            name="url"
            type="url"
            label={t(I18nKey.SETTINGS$MCP_URL)}
            value={state.values.url ?? template.url}
            onChange={(value) => setValue("url", value)}
            isDisabled={!template.urlEditable}
            className="w-full"
          />
          {state.errors.url && (
            <p className="text-xs text-feedback-error">{state.errors.url}</p>
          )}
          {headerFields.map((field) => (
            <div key={field.key} className="flex flex-col gap-1">
              <SettingsInput
                testId={`mcp-install-field-${field.key}`}
                name={field.key}
                type={field.type === "password" ? "password" : "text"}
                label={field.label}
                value={state.values[field.key] ?? ""}
                onChange={(v) => setValue(field.key, v)}
                placeholder={field.placeholder}
                required={field.required}
                showOptionalTag={!field.required}
                className="w-full"
              />
              {field.helperText && (
                <p className="text-xs text-tertiary-alt">
                  {renderHelperText(field.helperText)}
                </p>
              )}
              {state.errors[field.key] && (
                <p className="text-xs text-feedback-error">
                  {state.errors[field.key]}
                </p>
              )}
              {field.key in state.savedAsSecret && (
                <SaveAsSecretToggle
                  fieldKey={field.key}
                  checked={state.savedAsSecret[field.key] ?? false}
                  onToggle={(v) => toggleSecret(field.key, v)}
                />
              )}
            </div>
          ))}
          {oauthMode ? (
            <div
              data-testid="mcp-install-oauth-info"
              className="flex flex-col gap-2 p-3 rounded-lg border border-border bg-tertiary"
            >
              <p className="text-sm text-text-secondary">
                {t(I18nKey.MCP$OAUTH_CONNECT_INFO)}
              </p>
              <p className="text-xs text-tertiary-alt">
                {t(I18nKey.MCP$OAUTH_CONNECT_HINT)}
              </p>
            </div>
          ) : shouldRenderCredential ? (
            <div className="flex flex-col gap-1">
              <SettingsInput
                testId="mcp-install-field-api_key"
                name="api_key"
                type="password"
                label={
                  option?.auth.credentialLabel ??
                  t(I18nKey.SETTINGS$MCP_API_KEY)
                }
                value={state.values.api_key ?? ""}
                onChange={(v) => setValue("api_key", v)}
                placeholder={
                  option?.auth.credentialPlaceholder ??
                  t(I18nKey.SETTINGS$MCP_API_KEY_PLACEHOLDER)
                }
                showOptionalTag={apiKeyOptional}
                required={!apiKeyOptional}
                className="w-full"
              />
              {option?.auth.credentialHelp && (
                <p className="text-xs text-tertiary-alt">
                  {renderHelperText(option.auth.credentialHelp)}
                </p>
              )}
              {state.errors.api_key && (
                <p className="text-xs text-feedback-error">
                  {state.errors.api_key}
                </p>
              )}
              {credentialSecretName && (
                <SaveAsSecretToggle
                  fieldKey={credentialSecretName}
                  checked={state.savedAsSecret.api_key ?? false}
                  onToggle={(v) => toggleSecret("api_key", v)}
                />
              )}
            </div>
          ) : null}
        </>
      );
    }

    if (template?.kind !== "stdio") return null;
    const stdio = template;
    return (
      <>
        <SettingsInput
          testId="mcp-install-field-command-readonly"
          name="command-readonly"
          type="text"
          label={t(I18nKey.MCP$COMMAND_LABEL)}
          value={`${stdio.command} ${stdio.args.join(" ")}`.trim()}
          onChange={() => {}}
          isDisabled
          className="w-full"
        />
        {(stdio.envFields ?? []).map((field) => (
          <div key={field.key} className="flex flex-col gap-1">
            <SettingsInput
              testId={`mcp-install-field-${field.key}`}
              name={field.key}
              type={field.type === "password" ? "password" : "text"}
              label={field.label}
              value={state.values[field.key] ?? ""}
              onChange={(v) => setValue(field.key, v)}
              placeholder={field.placeholder}
              required={field.required}
              showOptionalTag={!field.required}
              className="w-full"
            />
            {field.helperText && (
              <p className="text-xs text-tertiary-alt">
                {renderHelperText(field.helperText)}
              </p>
            )}
            {state.errors[field.key] && (
              <p className="text-xs text-feedback-error">
                {state.errors[field.key]}
              </p>
            )}
            {field.key in state.savedAsSecret && (
              <SaveAsSecretToggle
                fieldKey={field.key}
                checked={state.savedAsSecret[field.key]}
                onToggle={(v) => toggleSecret(field.key, v)}
              />
            )}
          </div>
        ))}
        {/* argFields are CLI arguments, not credentials — they don't need
            a "save as secret" toggle and are excluded from savedAsSecret. */}
        {(stdio.argFields ?? []).map((field) => (
          <div key={field.key} className="flex flex-col gap-1">
            <SettingsInput
              testId={`mcp-install-field-${field.key}`}
              name={field.key}
              type={field.type === "password" ? "password" : "text"}
              label={field.label}
              value={state.values[field.key] ?? ""}
              onChange={(v) => setValue(field.key, v)}
              placeholder={field.placeholder}
              required={field.required}
              showOptionalTag={!field.required}
              className="w-full"
            />
            {field.helperText && (
              <p className="text-xs text-tertiary-alt">
                {renderHelperText(field.helperText)}
              </p>
            )}
            {state.errors[field.key] && (
              <p className="text-xs text-feedback-error">
                {state.errors[field.key]}
              </p>
            )}
          </div>
        ))}
      </>
    );
  };

  return (
    <ModalBackdrop onClose={onClose} aria-label={entry.name}>
      <form
        data-testid="mcp-install-modal"
        data-marketplace-id={entry.id}
        onSubmit={handleSubmit}
        className="relative bg-base-secondary p-6 rounded-xl flex flex-col gap-4 border border-border w-130 max-w-[90vw] max-h-[85vh] overflow-y-auto custom-scrollbar"
      >
        <ModalCloseButton
          onClose={onClose}
          testId="mcp-install-modal-close"
          disabled={isPending}
        />
        <div className="flex items-start gap-3 pr-6">
          <McpLogoBadge entry={entry} />
          <div className="flex flex-col flex-1">
            <h2 className={modalTitleLgClassName}>{entry.name}</h2>
            <p className="text-xs text-tertiary-light">{entry.description}</p>
          </div>
        </div>

        {isResolvingNative && (
          <p
            data-testid="mcp-install-resolving"
            className="text-xs text-tertiary-light"
          >
            {t(I18nKey.HOME$LOADING)}
          </p>
        )}

        {showConnectionTabs && (
          <div role="tablist" className="flex border-b border-border">
            <TabButton
              isActive={selectedConnection === "native"}
              onClick={() => setSelectedConnection("native")}
              disabled={isPending}
              className="flex items-center gap-2"
            >
              <span data-testid="mcp-install-tab-native">
                {t(I18nKey.MCP$NATIVE_TAB, { name: entry.name })}
              </span>
              <BrandBadge className="shrink-0 whitespace-nowrap px-2.5 py-1 text-xs">
                {t(I18nKey.SETTINGS$SKILLS_RECOMMENDED)}
              </BrandBadge>
            </TabButton>
            <TabButton
              isActive={selectedConnection === "mcp"}
              onClick={() => setSelectedConnection("mcp")}
            >
              <span data-testid="mcp-install-tab-mcp">
                {t(I18nKey.MCP$MCP_TAB, { name: entry.name })}
              </span>
            </TabButton>
          </div>
        )}

        {!isResolvingNative &&
          (isNativeSelected && native ? (
            <NativeIntegrationPanel
              entry={entry}
              native={native}
              onConnected={() => {
                onSuccess?.(entry);
                onClose();
              }}
            />
          ) : (
            <>
              {showConnectionTabs && (
                <div className="flex flex-col gap-1">
                  <h3 className="text-sm font-semibold text-contrast">
                    {t(I18nKey.MCP$MCP_TAB, { name: entry.name })}
                  </h3>
                  <p className="text-xs text-tertiary-light">
                    {t(I18nKey.MCP$MCP_DESCRIPTION, { name: entry.name })}
                  </p>
                </div>
              )}

              {/* The entry's hint and documentation describe its MCP server, so
                they belong to the MCP option rather than above both. */}
              {entry.installHint && (
                <p className="text-xs text-tertiary-light">
                  {entry.installHint}
                </p>
              )}

              {entry.docsUrl && (
                <a
                  href={entry.docsUrl}
                  target="_blank"
                  rel="noreferrer"
                  className="text-xs text-muted hover:text-contrast hover:underline self-start transition-colors"
                >
                  {t(I18nKey.MCP$VIEW_DOCS)}
                </a>
              )}

              <div className="flex flex-col gap-3">{renderFields()}</div>

              {/* @spec MCP-004 — Form feedback follows readable theme text roles */}
              {globalError && (
                <p
                  data-testid="mcp-install-modal-error"
                  className="text-sm text-feedback-error whitespace-pre-wrap"
                >
                  {globalError}
                </p>
              )}

              <div className="flex justify-end gap-2 mt-2">
                <BrandButton
                  type="button"
                  variant="secondary"
                  onClick={onClose}
                  testId="mcp-install-cancel"
                  isDisabled={isPending}
                >
                  {t(I18nKey.BUTTON$CANCEL)}
                </BrandButton>
                <BrandButton
                  type="submit"
                  variant="primary"
                  isDisabled={isPending}
                  testId="mcp-install-submit"
                >
                  {isTesting || isAuthorizingOAuth
                    ? t(I18nKey.MCP$VERIFYING)
                    : isAdding || isFinalizingInstall
                      ? t(I18nKey.SETTINGS$SAVING)
                      : t(I18nKey.MCP$INSTALL_BUTTON)}
                </BrandButton>
              </div>
            </>
          ))}
      </form>
    </ModalBackdrop>
  );
}

import {
  McpLogoBadge,
  type McpLogoEntry,
} from "#/components/features/mcp-logo-badge";
import { cn } from "#/utils/utils";

const STACK_CONTAINER_CLASS_NAME =
  "inline-flex h-10 w-10 shrink-0 overflow-hidden rounded-lg border border-contrast/10 bg-surface-raised shadow-[inset_0_1px_0_color-mix(in_srgb,var(--oh-contrast)_18%,transparent)]";

interface McpLogoStackBadgeProps {
  entries: McpLogoEntry[];
  className?: string;
  testId?: string;
}

function toLogoEntries(
  entries: McpLogoStackBadgeProps["entries"],
): McpLogoEntry[] {
  return entries.slice(0, 4);
}

export function McpLogoStackBadge({
  entries,
  className,
  testId,
}: McpLogoStackBadgeProps) {
  const visibleEntries = toLogoEntries(entries);

  if (visibleEntries.length === 0) {
    return (
      <McpLogoBadge
        entry={null}
        size="md"
        className={className}
        testId={testId}
      />
    );
  }

  if (visibleEntries.length === 1) {
    return (
      <McpLogoBadge
        entry={visibleEntries[0]}
        size="md"
        className={className}
        testId={testId}
      />
    );
  }

  if (visibleEntries.length === 2) {
    return (
      <span
        aria-hidden="true"
        data-testid={testId}
        data-layout="overlap"
        className={cn(
          STACK_CONTAINER_CLASS_NAME,
          "items-center justify-center",
          className,
        )}
      >
        <span className="flex items-center justify-center -space-x-2">
          {visibleEntries.map((entry) => (
            <McpLogoBadge
              key={entry.id}
              entry={entry}
              size="sm"
              className="ring-2 ring-surface-raised"
            />
          ))}
        </span>
      </span>
    );
  }

  const quadrantSlots: Array<McpLogoEntry | null> = [
    visibleEntries[0] ?? null,
    visibleEntries[1] ?? null,
    visibleEntries[2] ?? null,
    visibleEntries[3] ?? null,
  ];

  return (
    <span
      aria-hidden="true"
      data-testid={testId}
      data-layout="quadrants"
      className={cn(
        STACK_CONTAINER_CLASS_NAME,
        "grid grid-cols-2 grid-rows-2 gap-0.5 p-1",
        className,
      )}
    >
      {quadrantSlots.map((entry, index) =>
        entry ? (
          <span key={entry.id} className="flex items-center justify-center">
            <McpLogoBadge entry={entry} size="xs" />
          </span>
        ) : (
          <span key={`empty-${index}`} aria-hidden="true" />
        ),
      )}
    </span>
  );
}

import React from "react";
import { AxiosError } from "axios";
import { useTranslation } from "react-i18next";
import type { TFunction } from "i18next";
import { I18nKey } from "#/i18n/declaration";
import { seedMcpServerHealth } from "#/api/mcp-health/probe-mcp-server-health";
import { useActiveBackend } from "#/contexts/active-backend-context";
import { useUpdateMcpServer } from "#/hooks/mutation/use-update-mcp-server";
import { useMcpServerHealth } from "#/hooks/use-mcp-server-health";
import type { McpServerHealth } from "#/types/mcp-health";
import { MCPServerConfig } from "#/types/mcp-server";
import { displayErrorToast } from "#/utils/custom-toast-handlers";
import type { MarketplaceEntry } from "#/utils/mcp-marketplace-utils";
import { makeMcpTestErrorMessage } from "#/utils/mcp-test-error-message";
import { retrieveAxiosErrorMessage } from "#/utils/retrieve-axios-error-message";
import { cn } from "#/utils/utils";

interface McpServerHealthSectionProps {
  server: MCPServerConfig;
  catalog: MarketplaceEntry | undefined;
  onEdit: () => void;
}

const DOT_CLASS_BY_STATUS: Record<McpServerHealth["status"], string> = {
  unchecked: "bg-text-tertiary",
  checking: "bg-interactive-selected animate-pulse",
  healthy: "bg-status-success",
  failed: "bg-red-500",
};

const actionClassName =
  "text-xs text-muted underline transition-colors hover:text-contrast disabled:cursor-not-allowed disabled:opacity-60";

function getDotStatus(health: McpServerHealth): string {
  if (health.status === "healthy") {
    return health.verification === "verified"
      ? "healthy"
      : "healthy-connectivity";
  }
  return health.status;
}

function getStatusLabel(
  t: TFunction<"openhands">,
  health: McpServerHealth,
  serverType: MCPServerConfig["type"],
): string {
  switch (health.status) {
    case "checking":
      return t(I18nKey.MCP$HEALTH_STATUS_CHECKING);
    case "healthy":
      return health.verification === "verified"
        ? t(I18nKey.MCP$HEALTH_STATUS_VERIFIED, { count: health.toolCount })
        : t(I18nKey.MCP$HEALTH_STATUS_CONNECTIVITY_ONLY);
    case "failed":
      return makeMcpTestErrorMessage(t, health.kind, health.error, serverType);
    default:
      return t(I18nKey.MCP$HEALTH_STATUS_UNCHECKED);
  }
}

/**
 * Connection-health row for an installed server card: status dot + label,
 * a Test connection / Retry action, and — on failure — the relevant
 * recovery actions (fix credentials, re-run OAuth, open the docs).
 *
 * Renders nothing for stdio servers on cloud backends: those spawn inside
 * the cloud sandbox, so `McpService.testServer` short-circuits them with a
 * synthetic success that must not be presented as a health verdict. Remote
 * servers on cloud backends are probed through the app server.
 */
export function McpServerHealthSection({
  server,
  catalog,
  onEdit,
}: McpServerHealthSectionProps) {
  const { t } = useTranslation("openhands");
  const { backend } = useActiveBackend();
  const { health, probe, reauthorize } = useMcpServerHealth(server);
  const { mutate: updateMcpServer } = useUpdateMcpServer();

  if (backend.kind === "cloud" && server.type === "stdio") return null;

  const isChecking = health.status === "checking";
  const isFailed = health.status === "failed";
  const label = getStatusLabel(t, health, server.type);

  const handleReauthorize = async () => {
    const result = await reauthorize();
    if (
      !result?.ok ||
      !result.oauth_state ||
      server.auth?.strategy !== "oauth2"
    ) {
      return;
    }
    // Persist the refreshed tokens, mirroring the editor's OAuth save path.
    const serverToSave: MCPServerConfig = {
      ...server,
      auth: { ...server.auth, state: result.oauth_state },
    };
    updateMcpServer(
      { serverId: server.id, server: serverToSave },
      {
        // The update mutation clears this server's health entry; re-seed it
        // from the probe that just succeeded so the verdict survives the save.
        onSuccess: () => seedMcpServerHealth(serverToSave, result, []),
        onError: (err: unknown) =>
          displayErrorToast(
            retrieveAxiosErrorMessage(err as AxiosError) ||
              t(I18nKey.ERROR$GENERIC),
          ),
      },
    );
  };

  return (
    // Propagation stopper: the card root is a role="button" that opens the
    // editor on click/Enter; interactions inside the health row must not
    // double as "edit server".
    <div
      data-testid={`mcp-server-health-${server.id}`}
      role="presentation"
      className="flex flex-col gap-1.5"
      onClick={(event) => event.stopPropagation()}
      onKeyDown={(event) => event.stopPropagation()}
    >
      <div className="flex items-center gap-2">
        <span
          data-testid="mcp-health-dot"
          data-status={getDotStatus(health)}
          aria-hidden="true"
          className={cn(
            "inline-block h-2 w-2 shrink-0 rounded-full",
            DOT_CLASS_BY_STATUS[health.status],
          )}
        />
        <p
          data-testid={`mcp-health-label-${server.id}`}
          className={cn(
            "line-clamp-2 break-words text-xs",
            isFailed ? "text-red-500" : "text-tertiary-alt",
          )}
          title={label}
        >
          {label}
        </p>
      </div>

      {health.status === "healthy" &&
      health.verification === "connectivity-only" ? (
        <p className="text-xs text-tertiary-light">
          {t(I18nKey.MCP$HEALTH_CONNECTIVITY_ONLY_HINT)}
        </p>
      ) : null}

      <div className="flex flex-wrap items-center gap-3">
        <button
          type="button"
          data-testid={`mcp-health-probe-${server.id}`}
          className={actionClassName}
          onClick={() => void probe()}
          disabled={isChecking}
        >
          {isFailed ? t(I18nKey.MCP$HEALTH_RETRY) : t(I18nKey.MCP$TEST_BUTTON)}
        </button>
        {isFailed && health.kind === "credentials" ? (
          <button
            type="button"
            data-testid={`mcp-health-update-credentials-${server.id}`}
            className={actionClassName}
            onClick={onEdit}
          >
            {t(I18nKey.MCP$HEALTH_UPDATE_CREDENTIALS)}
          </button>
        ) : null}
        {isFailed && server.auth?.strategy === "oauth2" ? (
          <button
            type="button"
            data-testid={`mcp-health-reauthorize-${server.id}`}
            className={actionClassName}
            onClick={() => void handleReauthorize()}
          >
            {t(I18nKey.MCP$HEALTH_REAUTHORIZE)}
          </button>
        ) : null}
        {isFailed && catalog?.docsUrl ? (
          <a
            href={catalog.docsUrl}
            target="_blank"
            rel="noreferrer"
            className={actionClassName}
          >
            {t(I18nKey.MCP$VIEW_DOCS)}
          </a>
        ) : null}
      </div>
    </div>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";
import { CircleCheck } from "lucide-react";
import type { IntegrationCatalogEntry as MarketplaceEntry } from "@openhands/extensions/integrations";
import { BrandButton } from "#/components/features/settings/brand-button";
import { BrandBadge } from "#/components/shared/badge";
import { useActiveBackend } from "#/contexts/active-backend-context";
import { useSettings } from "#/hooks/query/use-settings";
import type { NativeGitIntegration } from "#/hooks/query/use-native-git-integrations";
import { I18nKey } from "#/i18n/declaration";
import { cloudIntegrationsUrl } from "#/utils/cloud-integrations-url";
import { convertRawProvidersToList } from "#/utils/convert-raw-providers-to-list";

interface NativeIntegrationPanelProps {
  entry: MarketplaceEntry;
  native: NativeGitIntegration;
  /** Fired once the native integration is connected and the user continues. */
  onConnected: () => void;
}

/**
 * The "Native" option for a git integration on a cloud backend. Connecting
 * happens on the instance's Settings > Integrations page (an OAuth flow the
 * canvas cannot host), so Install opens it in a new tab and Continue re-reads
 * the user's connected providers.
 */
export function NativeIntegrationPanel({
  entry,
  native,
  onConnected,
}: NativeIntegrationPanelProps) {
  const { t } = useTranslation("openhands");
  const { backend, orgId } = useActiveBackend();
  const { refetch: refetchSettings } = useSettings();
  const [hasOpenedIntegrations, setHasOpenedIntegrations] =
    React.useState(false);
  const [isChecking, setIsChecking] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  const features = [t(I18nKey.MCP$NATIVE_FEATURE_REPOS, { name: entry.name })];
  if (native.provider === "github") {
    features.push(t(I18nKey.MCP$NATIVE_FEATURE_MENTIONS_GITHUB));
  } else if (native.provider === "gitlab") {
    features.push(t(I18nKey.MCP$NATIVE_FEATURE_MENTIONS_GITLAB));
  }

  const openIntegrations = () => {
    window.open(
      cloudIntegrationsUrl(backend, orgId),
      "_blank",
      "noopener,noreferrer",
    );
    setHasOpenedIntegrations(true);
  };

  const confirmConnection = async () => {
    setError(null);
    setIsChecking(true);
    const { data } = await refetchSettings();
    setIsChecking(false);
    if (
      convertRawProvidersToList(data?.provider_tokens_set).includes(
        native.provider,
      )
    ) {
      onConnected();
      return;
    }
    setError(t(I18nKey.MCP$NATIVE_NOT_CONNECTED_YET, { name: entry.name }));
  };

  return (
    <div
      data-testid="mcp-native-panel"
      className="flex flex-col gap-4 rounded-xl border border-border p-4"
    >
      <div className="flex flex-col gap-1">
        <div className="flex items-center gap-2">
          <h3 className="text-sm font-semibold text-contrast">
            {t(I18nKey.MCP$NATIVE_TAB, { name: entry.name })}
          </h3>
          <BrandBadge className="shrink-0 whitespace-nowrap px-2.5 py-1 text-xs">
            {t(I18nKey.SETTINGS$SKILLS_RECOMMENDED)}
          </BrandBadge>
        </div>
        <p className="text-xs text-tertiary-light">
          {t(I18nKey.MCP$NATIVE_DESCRIPTION, { name: entry.name })}
        </p>
      </div>

      <ul className="flex flex-col gap-2">
        {features.map((feature) => (
          <li
            key={feature}
            className="flex items-center gap-2 text-sm text-contrast"
          >
            <CircleCheck className="size-4 shrink-0 text-success" aria-hidden />
            {feature}
          </li>
        ))}
      </ul>

      <div className="flex items-center justify-between gap-3 border-t border-border pt-4">
        <p className="text-xs text-tertiary-light">
          {native.isConnected
            ? t(I18nKey.MCP$NATIVE_CONNECTED, { name: entry.name })
            : t(I18nKey.MCP$NATIVE_CONNECT_HINT, { name: entry.name })}
        </p>
        <div className="flex shrink-0 gap-2">
          {!native.isConnected && (
            <BrandButton
              type="button"
              variant={hasOpenedIntegrations ? "secondary" : "primary"}
              onClick={openIntegrations}
              testId="mcp-native-install"
            >
              {t(I18nKey.MCP$INSTALL_BUTTON)}
            </BrandButton>
          )}
          {(native.isConnected || hasOpenedIntegrations) && (
            <BrandButton
              type="button"
              variant="primary"
              onClick={native.isConnected ? onConnected : confirmConnection}
              isDisabled={isChecking}
              testId="mcp-native-continue"
            >
              {t(I18nKey.BUTTON$CONTINUE)}
            </BrandButton>
          )}
        </div>
      </div>

      {error && (
        <p data-testid="mcp-native-error" className="text-sm text-red-500">
          {error}
        </p>
      )}
    </div>
  );
}

