import React from "react";
import { useTranslation } from "react-i18next";
import { isNoBackend } from "#/api/backend-registry/active-store";
import { getLockedCloudHost, isSameCloudHost } from "#/api/agent-server-config";
import {
  readSidebarOnboardingChecklistDismissed,
  writeSidebarOnboardingChecklistDismissed,
} from "#/components/features/sidebar/sidebar-onboarding-checklist-storage";
import { ModalBackdrop } from "#/components/shared/modals/modal-backdrop";
import {
  MODAL_MAX_WIDTH_VIEWPORT,
  modalWidthClassName,
} from "#/components/shared/modals/modal-body";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import { useActiveBackendContext } from "#/contexts/active-backend-context";
import { useBackendsHealth } from "#/hooks/query/use-backends-health";
import { useSettings } from "#/hooks/query/use-settings";
import { useTracking } from "#/hooks/use-tracking";
import { OnboardingProgressBar } from "./onboarding-progress-bar";
import {
  ChooseAgentStep,
  type OnboardingAgentId,
} from "./steps/choose-agent-step";
import { CheckBackendStep } from "./steps/check-backend-step";
import { SetupLlmStep } from "./steps/setup-llm-step";
import { SetupAcpSecretsStep } from "./steps/setup-acp-secrets-step";
import { SayHelloStep } from "./steps/say-hello-step";

/**
 * Logical onboarding phases.
 *
 * State is tracked as a phase (not a numeric step) so that the slide
 * indices renumbering when ``skipBackendStep`` flips — e.g. a returning
 * Cloud user finishes the backend slide and the carousel collapses from
 * 4 slides to 3 — cannot accidentally drag the user from "agent" onto
 * the slide that used to live at the agent index ("setup"). See the
 * regression test `onboarding-modal` covering this transition.
 */
type OnboardingPhase = "backend" | "agent" | "setup" | "hello";

const PHASE_ORDER_WITH_BACKEND: readonly OnboardingPhase[] = [
  "backend",
  "agent",
  "setup",
  "hello",
];
const PHASE_ORDER_WITHOUT_BACKEND: readonly OnboardingPhase[] = [
  "agent",
  "setup",
  "hello",
];

/**
 * sessionStorage flag marking that the one-time "onboarding started" analytics
 * event has already been captured for this browser session. It survives
 * rerenders, remounts and the lazy/Suspense flip so the event fires at most
 * once per onboarding session.
 */
const ONBOARDING_STARTED_TRACKED_KEY = "openhands-onboarding-started";

interface SlideProps {
  /** Index of this slide in the step sequence. */
  index: number;
  /** Index of the currently visible step. */
  currentStep: number;
  children: React.ReactNode;
}

/**
 * One step panel inside the slide rail.
 *
 * Only the active slide is in normal flow — it drives the surrounding
 * container's height. Inactive slides are absolutely positioned so
 * they don't add their height to the modal box (which previously made
 * the modal "overhang" with empty space sized to the tallest step).
 *
 * Each slide is translated horizontally by `(index - currentStep) *
 * 100%` so the active step sits at offset 0, with prior steps off to
 * the left and upcoming steps off to the right. Changes to
 * `currentStep` smoothly animate the transform.
 */
function Slide({ index, currentStep, children }: SlideProps) {
  const isActive = index === currentStep;
  const offsetPct = (index - currentStep) * 100;
  return (
    <div
      data-testid={`onboarding-slide-${index}`}
      data-active={isActive}
      aria-hidden={!isActive}
      // slide offset computed from step index at runtime
      style={{ transform: `translateX(${offsetPct}%)` }}
      className={cn(
        "w-full transition-transform duration-300 ease-out",
        // Inactive slides are taken out of flow so the rail's height
        // tracks just the active step; they stay overlaid via inset-0
        // so they slide in/out of view across the same horizontal box.
        !isActive && "pointer-events-none absolute inset-0",
      )}
    >
      {children}
    </div>
  );
}

interface OnboardingModalProps {
  /** Called when the user dismisses the modal (skip / X / launch). */
  onClose: () => void;
  /** Optional slide index for dev preview (`?previewOnboardingStep=`). */
  initialStep?: number;
  /** When true, skip/close does not persist onboarding completion. */
  isPreview?: boolean;
}

/**
 * Top-level onboarding modal for first-time users.
 *
 * The flow starts with backend setup only when the active backend is missing
 * or cannot be reached. If an already configured backend is healthy, the user
 * starts directly on agent selection:
 *   0. Check/add backend (only when needed)
 *   1. Choose agent
 *   2. Set up LLM
 *   3. Say hello (creates a fresh conversation, then closes)
 *
 * Internally we track the user's *phase* — "backend" | "agent" | "setup" |
 * "hello" — rather than a numeric step, because the slide indices renumber
 * when the backend slide is skipped and we must never accidentally drop the
 * user onto whatever slide *used to* live at their numeric position.
 *
 * Each visible step lives in its own slide and the rail is translated
 * horizontally by step index, so transitioning between steps animates the new
 * step in from the right.
 */
export function OnboardingModal({
  onClose,
  initialStep = 0,
  isPreview = false,
}: OnboardingModalProps) {
  const { t } = useTranslation("openhands");
  const { data: settings } = useSettings();
  const analyticsEnabled = settings?.user_consents_to_analytics === true;
  const {
    trackOnboardingStarted,
    trackOnboardingStepViewed,
    trackOnboardingCompleted,
    trackOnboardingSkipped,
  } = useTracking();
  const { active } = useActiveBackendContext();
  const { backend } = active;
  const noBackendSelected = isNoBackend(backend);
  const healthByBackendId = useBackendsHealth(
    noBackendSelected ? [] : [backend],
  );
  // In locked-to-Cloud mode the backend slide may only be skipped when the
  // active backend IS the configured locked Cloud host. A reachable stale
  // Local backend (or a Cloud backend on a different host) must keep
  // `CheckBackendStep` visible so the user can log into Cloud and replace
  // the stale backend — otherwise they would continue as Local despite
  // `VITE_LOCK_TO_CLOUD`. Outside locked mode the existing behavior
  // (skip once the active backend is healthy) is unchanged.
  const lockedCloudHost = getLockedCloudHost();
  const isActiveLockedCloudBackend =
    lockedCloudHost !== null &&
    backend.kind === "cloud" &&
    isSameCloudHost(backend.host, lockedCloudHost);
  const skipBackendStep =
    !noBackendSelected &&
    healthByBackendId[backend.id]?.isConnected === true &&
    (lockedCloudHost === null || isActiveLockedCloudBackend);

  const slideOrder = skipBackendStep
    ? PHASE_ORDER_WITHOUT_BACKEND
    : PHASE_ORDER_WITH_BACKEND;

  const [phase, setPhase] = React.useState<OnboardingPhase>(
    () =>
      PHASE_ORDER_WITH_BACKEND[
        Math.min(Math.max(initialStep, 0), PHASE_ORDER_WITH_BACKEND.length - 1)
      ],
  );
  const [selectedAgentId, setSelectedAgentId] =
    React.useState<OnboardingAgentId>("openhands");
  const [skipGettingStartedChecklist, setSkipGettingStartedChecklist] =
    React.useState(() => readSidebarOnboardingChecklistDismissed());

  // When the backend slide drops out of the flow (skipBackendStep flips
  // true), a user still parked on "backend" must be moved forward to the
  // first remaining phase. Doing this with the *phase* rather than a numeric
  // step keeps every other phase pinned to itself, so the user never lands
  // on the slide that used to live at the next index ("setup").
  React.useEffect(() => {
    if (!slideOrder.includes(phase)) setPhase(slideOrder[0]);
  }, [phase, slideOrder]);

  const totalSteps = slideOrder.length;
  const currentPhase = slideOrder.includes(phase) ? phase : slideOrder[0];
  const currentStep = slideOrder.indexOf(currentPhase);

  const handleSkipGettingStartedChange = (
    event: React.ChangeEvent<HTMLInputElement>,
  ) => {
    const skip = event.target.checked;
    setSkipGettingStartedChecklist(skip);
    writeSidebarOnboardingChecklistDismissed(skip);
  };

  // Backend connectivity is "settled" once we know whether the active backend
  // is reachable (or no backend is selected). Until then `skipBackendStep` may
  // still flip true and renumber the slides, briefly showing the backend slide
  // for an already-healthy backend. Gate Step Viewed on this so we never emit a
  // phantom "backend" view that immediately auto-skips to "agent".
  const backendHealthSettled =
    noBackendSelected ||
    healthByBackendId[backend.id]?.isConnected !== undefined;

  const isOpenHands = selectedAgentId === "openhands";
  const hideSkip = currentStep === 0 && getLockedCloudHost() !== null;
  const goNext = React.useCallback(() => {
    setPhase((prev) => {
      const order = slideOrder;
      const idx = order.indexOf(prev);
      // If `prev` isn't in the current order (e.g. "backend" after the
      // backend slide just collapsed), start from the first slot.
      const safeIdx = idx === -1 ? 0 : idx;
      return order[Math.min(safeIdx + 1, order.length - 1)];
    });
  }, [slideOrder]);
  const goBack = React.useCallback(() => {
    setPhase((prev) => {
      const order = slideOrder;
      const idx = order.indexOf(prev);
      const safeIdx = idx === -1 ? 0 : idx;
      return order[Math.max(safeIdx - 1, 0)];
    });
  }, [slideOrder]);

  // --- Onboarding analytics -------------------------------------------------
  // Every event is routed through `useTracking`, which drops captures unless
  // the user has consented; the design-preview harness (`isPreview`) emits
  // nothing.

  // Onboarding Started — fire at most once per browser session. The
  // sessionStorage flag survives rerenders, remounts and the lazy/Suspense
  // flip; the consent gate means we only arm the guard once a capture can
  // actually happen, so a user who consents partway through onboarding still
  // gets the event instead of having it latched away during the no-consent
  // window.
  const startedTrackedRef = React.useRef(false);
  React.useEffect(() => {
    if (isPreview || !analyticsEnabled || startedTrackedRef.current) return;
    if (window.sessionStorage.getItem(ONBOARDING_STARTED_TRACKED_KEY)) return;
    startedTrackedRef.current = true;
    window.sessionStorage.setItem(ONBOARDING_STARTED_TRACKED_KEY, "1");
    trackOnboardingStarted();
  }, [isPreview, analyticsEnabled]);

  // Onboarding Step Viewed — fire once per phase entry. The phase string is the
  // stable identity (slide indices renumber), so dedupe on it: this absorbs
  // StrictMode's double-invoke and the index renumber, while re-entering a step
  // via Back counts as a genuine new view.
  const lastViewedPhaseRef = React.useRef<OnboardingPhase | null>(null);
  React.useEffect(() => {
    if (isPreview || !analyticsEnabled || !backendHealthSettled) return;
    if (lastViewedPhaseRef.current === currentPhase) return;
    lastViewedPhaseRef.current = currentPhase;
    trackOnboardingStepViewed({
      step: currentPhase,
      stepIndex: currentStep,
      totalSteps,
      agent: selectedAgentId,
    });
  }, [
    isPreview,
    analyticsEnabled,
    backendHealthSettled,
    currentPhase,
    currentStep,
    totalSteps,
    selectedAgentId,
  ]);

  // Onboarding Completed — `onLaunched` runs only once the user has committed
  // to a launch: a created conversation for the hello message or a recommended
  // automation, or the setup form for an automation that ships one. Wrapping it
  // captures completion exactly once before the modal closes.
  const handleCompleted = () => {
    trackOnboardingCompleted({ agent: selectedAgentId });
    onClose();
  };

  // Onboarding Skipped/Dismissed — the user exited before completing, via the
  // skip button (non-final steps) or the final-step Close button. `currentPhase`
  // records where they left, which also distinguishes the two affordances.
  const handleSkipOrDismiss = () => {
    trackOnboardingSkipped({
      step: currentPhase,
      stepIndex: currentStep,
      totalSteps,
      agent: selectedAgentId,
    });
    onClose();
  };

  return (
    // No `onClose`: the flow must only be dismissed via explicit actions
    // (the skip button or launching), never by an errant backdrop click or
    // Escape press — see https://github.com/OpenHands/agent-canvas/issues/1085.
    <ModalBackdrop aria-label={t(I18nKey.ONBOARDING$TITLE)}>
      <div className="relative flex flex-col items-center gap-4">
        <section
          data-testid="onboarding-modal"
          data-current-step={currentStep}
          data-preview={isPreview ? "true" : undefined}
          className={cn(
            "flex flex-col gap-6 overflow-hidden rounded-2xl border border-contrast/10 bg-base-secondary shadow-2xl",
            modalWidthClassName("lg"),
            MODAL_MAX_WIDTH_VIEWPORT,
            "max-h-[90vh]",
          )}
        >
          <header className="flex flex-col gap-3 px-7 pt-7 shrink-0">
            <OnboardingProgressBar
              currentStep={currentStep}
              totalSteps={totalSteps}
            />
          </header>

          <div
            data-testid="onboarding-scroll-area"
            className="min-h-0 overflow-y-auto custom-scrollbar-always px-7 pb-7"
          >
            <div
              data-testid="onboarding-slide-rail"
              data-current-step={currentStep}
              className="relative overflow-clip"
            >
              {skipBackendStep ? null : (
                <Slide
                  index={slideOrder.indexOf("backend")}
                  currentStep={currentStep}
                >
                  <CheckBackendStep onNext={goNext} onClose={onClose} />
                </Slide>
              )}
              <Slide
                index={slideOrder.indexOf("agent")}
                currentStep={currentStep}
              >
                <ChooseAgentStep
                  selectedAgentId={selectedAgentId}
                  onSelect={setSelectedAgentId}
                  onBack={skipBackendStep ? undefined : goBack}
                  onNext={goNext}
                />
              </Slide>
              <Slide
                index={slideOrder.indexOf("setup")}
                currentStep={currentStep}
              >
                {isOpenHands ? (
                  <SetupLlmStep onBack={goBack} onNext={goNext} />
                ) : (
                  <SetupAcpSecretsStep
                    providerKey={selectedAgentId}
                    isActive={currentPhase === "setup"}
                    onBack={goBack}
                    onNext={goNext}
                  />
                )}
              </Slide>
              <Slide
                index={slideOrder.indexOf("hello")}
                currentStep={currentStep}
              >
                <SayHelloStep
                  onBack={goBack}
                  onClose={handleSkipOrDismiss}
                  onLaunched={handleCompleted}
                />
              </Slide>
            </div>
          </div>
        </section>

        {currentStep < totalSteps - 1 && !hideSkip ? (
          <button
            type="button"
            data-testid="onboarding-skip"
            onClick={handleSkipOrDismiss}
            className="rounded-md px-3 py-2 text-sm text-muted transition-colors hover:bg-contrast/5 hover:text-contrast cursor-pointer"
          >
            {t(I18nKey.ONBOARDING$SKIP)}
          </button>
        ) : null}

        {currentPhase === "hello" ? (
          <label className="flex cursor-pointer items-center justify-center gap-2 text-sm text-muted">
            <input
              data-testid="onboarding-skip-getting-started-checklist"
              type="checkbox"
              checked={skipGettingStartedChecklist}
              onChange={handleSkipGettingStartedChange}
              className="size-4 cursor-pointer"
            />
            {t(I18nKey.ONBOARDING$SKIP_GETTING_STARTED_CHECKLIST)}
          </label>
        ) : null}
      </div>
    </ModalBackdrop>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";
import { CheckCircle2, Loader2, AlertCircle } from "lucide-react";
import { isNoBackend } from "#/api/backend-registry/active-store";
import type { Backend } from "#/api/backend-registry/types";
import {
  getAgentServerFormDefaults,
  getLockedCloudHost,
  isAuthRequired,
  isSameCloudHost,
} from "#/api/agent-server-config";
import { DEFAULT_LOCAL_BACKEND_NAME } from "#/api/backend-registry/default-backend";
import {
  BackendConnectionOptions,
  type BackendConnectionMethod,
  type BackendFormSubmitPayload,
} from "#/components/features/backends/backend-form-modal";
import { BrandButton } from "#/components/features/settings/brand-button";
import { useActiveBackendContext } from "#/contexts/active-backend-context";
import { useBackendsHealth } from "#/hooks/query/use-backends-health";
import { useTracking } from "#/hooks/use-tracking";
import { I18nKey } from "#/i18n/declaration";
import ChevronDownSmallIcon from "#/icons/chevron-down-small.svg?react";
import { cn } from "#/utils/utils";
import { getBackendStatusLabel } from "#/components/features/backends/backend-status-label";

interface CheckBackendStepProps {
  onBack?: () => void;
  onNext: () => void;
  /**
   * Dismisses the entire onboarding modal. Called when Cloud login succeeds
   * in locked-to-Cloud mode: there the Cloud login IS the onboarding
   * completion, so the modal must disappear immediately rather than
   * advancing to the next slide (which previously flickered — the next
   * slide flashed before the root gate tore the modal down). Standard mode
   * still walks the user through agent/LLM setup via `onNext`.
   */
  onClose?: () => void;
}

function ConnectionBanner({
  backend,
  isConnected,
  lastError,
}: {
  backend: Backend;
  isConnected: boolean | null;
  lastError: string | null;
}) {
  const { t } = useTranslation("openhands");

  if (isConnected === true) {
    return (
      <div
        role="status"
        data-testid="onboarding-backend-connected"
        className={cn(
          "flex items-start gap-3 rounded-xl border border-green-500/40 bg-green-500/10 px-4 py-3",
        )}
      >
        <CheckCircle2 className="mt-0.5 size-5 shrink-0 text-green-400" />
        <div className="flex flex-col gap-1">
          <span className="text-sm font-medium text-green-200">
            {t(I18nKey.ONBOARDING$BACKEND_CONNECTED_TITLE)}
          </span>
          <span className="text-xs text-green-200/80">
            {t(I18nKey.ONBOARDING$BACKEND_CONNECTED_BODY)}
          </span>
        </div>
      </div>
    );
  }

  if (isConnected === false) {
    const statusLabel = getBackendStatusLabel(t, backend, {
      isConnected,
      lastError,
    });
    return (
      <div
        role="alert"
        data-testid="onboarding-backend-disconnected"
        className="flex items-start gap-3 rounded-xl border border-red-500/40 bg-red-500/10 px-4 py-3"
      >
        <AlertCircle className="mt-0.5 size-5 shrink-0 text-red-400" />
        <div className="flex flex-col gap-1">
          <span className="text-sm font-medium text-red-200">
            {statusLabel}
          </span>
          <span className="text-xs text-red-200/80">
            {t(I18nKey.ONBOARDING$BACKEND_DISCONNECTED_BODY)}
          </span>
        </div>
      </div>
    );
  }

  return (
    <div
      role="status"
      data-testid="onboarding-backend-checking"
      className="flex items-start gap-3 rounded-xl border border-contrast/10 bg-contrast/5 px-4 py-3"
    >
      <Loader2 className="mt-0.5 size-5 shrink-0 animate-spin text-text-tertiary" />
      <span className="text-sm text-text-tertiary">
        {t(I18nKey.ONBOARDING$BACKEND_CHECKING)}
      </span>
    </div>
  );
}

/**
 * First onboarding step: add the initial backend when none is selected,
 * or edit/check the active backend with a contextual health banner.
 */
export function CheckBackendStep({
  onBack,
  onNext,
  onClose,
}: CheckBackendStepProps) {
  const { t } = useTranslation("openhands");
  const { active, addBackend, setActive, updateBackend } =
    useActiveBackendContext();
  const { trackBackendAdded } = useTracking();
  const { backend } = active;
  const noBackendSelected = isNoBackend(backend);
  const lockedCloudHost = getLockedCloudHost();

  // In locked-Cloud mode, a reachable backend that is NOT the locked
  // Cloud host (e.g. a stale Local backend from localStorage) must be
  // forced through Cloud login replacement. Treat it as if no backend
  // were selected for render purposes so the Cloud login UI shows and
  // the connected-backend "Next" shortcut is suppressed. The real
  // `noBackendSelected` still controls whether handleConnected calls
  // `addBackend` or `updateBackend`, so the stale backend gets replaced.
  const lockedCloudHostMismatch =
    lockedCloudHost !== null &&
    !noBackendSelected &&
    !(
      backend.kind === "cloud" && isSameCloudHost(backend.host, lockedCloudHost)
    );
  const treatAsNoBackend = noBackendSelected || lockedCloudHostMismatch;

  const defaults = React.useMemo(() => getAgentServerFormDefaults(), []);
  const backendForForm = treatAsNoBackend
    ? {
        id: "onboarding-local-backend-draft",
        name: DEFAULT_LOCAL_BACKEND_NAME,
        host: defaults.baseUrl,
        apiKey: defaults.sessionApiKey,
        kind: "local" as const,
      }
    : backend;
  const healthByBackendId = useBackendsHealth(
    noBackendSelected ? [] : [backend],
  );
  const isConnected = treatAsNoBackend
    ? null
    : (healthByBackendId[backend.id]?.isConnected ?? null);
  const lastError = treatAsNoBackend
    ? null
    : (healthByBackendId[backend.id]?.lastError ?? null);
  const [configurationOpen, setConfigurationOpen] = React.useState(false);

  React.useEffect(() => {
    if (isConnected === true) {
      setConfigurationOpen(false);
    }
  }, [isConnected]);

  const hideConfigurationFields = isConnected === true && !configurationOpen;

  const handleConnected = React.useCallback(
    (
      payload: BackendFormSubmitPayload,
      connectionMethod: BackendConnectionMethod,
    ) => {
      if (noBackendSelected) {
        addBackend(payload);
      } else {
        // When the host changes (e.g. replacing a stale Cloud backend
        // with the locked Cloud host), the persisted active org_id is
        // keyed to the OLD host's org list and would be sent as an
        // invalid X-Org-Id to the new host. Clear it so the new
        // backend starts org-less; the user picks an org on the new
        // host. (Local-only edits are no-ops here since active.orgId
        // is already null for Local backends.)
        const hostChanged = payload.host !== backend.host;
        updateBackend(backend.id, payload);
        if (hostChanged && active.orgId !== null) {
          setActive(backend.id, null);
        }
      }
      trackBackendAdded({
        backendKind: payload.kind,
        connectionMethod,
        hasApiKey: Boolean(payload.apiKey),
        source: "onboarding",
      });
      // In locked-to-Cloud mode, Cloud login IS the onboarding
      // completion: dismiss the modal immediately so the user never
      // sees the next slide (Choose Agent) flash before the root gate
      // tears the modal down — the flicker reported on PR #1389.
      // Standard mode still walks the user through agent/LLM setup.
      if (lockedCloudHost !== null && payload.kind === "cloud" && onClose) {
        onClose();
      } else {
        onNext();
      }
    },
    [
      active.orgId,
      addBackend,
      backend.host,
      backend.id,
      lockedCloudHost,
      noBackendSelected,
      onClose,
      onNext,
      setActive,
      trackBackendAdded,
      updateBackend,
    ],
  );

  const actionRowClassName = cn(
    "sticky bottom-0 mt-2 flex items-center gap-2 bg-base-secondary pt-4 pb-7",
    onBack ? "justify-between" : "justify-end",
  );
  const titleKey = treatAsNoBackend
    ? lockedCloudHost
      ? I18nKey.ONBOARDING$LOGIN_TO_CLOUD_TITLE
      : I18nKey.BACKEND$ADD_TITLE
    : I18nKey.ONBOARDING$BACKEND_TITLE;

  return (
    <div
      data-testid="onboarding-step-check-backend"
      className="flex flex-col gap-6"
    >
      <header className="flex flex-col gap-2">
        <h2 className="text-2xl font-medium text-contrast">{t(titleKey)}</h2>
        {treatAsNoBackend ? null : (
          <p
            data-testid="onboarding-backend-subtitle"
            className="text-sm text-muted"
          >
            {t(I18nKey.ONBOARDING$BACKEND_SUBTITLE)}
          </p>
        )}
      </header>

      {treatAsNoBackend ? null : (
        <ConnectionBanner
          backend={backendForForm}
          isConnected={isConnected}
          lastError={lastError}
        />
      )}

      {isConnected === true ? (
        <button
          type="button"
          onClick={() => setConfigurationOpen((open) => !open)}
          aria-expanded={configurationOpen}
          data-testid="onboarding-backend-show-configuration"
          className="flex w-full cursor-pointer items-center justify-center gap-1 text-center text-xs text-muted transition-colors hover:text-content-2"
        >
          <span>
            {configurationOpen
              ? t(I18nKey.ONBOARDING$BACKEND_HIDE_CONFIGURATION)
              : t(I18nKey.ONBOARDING$BACKEND_SHOW_CONFIGURATION)}
          </span>
          <ChevronDownSmallIcon
            className={cn(
              "h-4 w-4 shrink-0 text-muted transition-transform",
              configurationOpen && "rotate-180",
            )}
            aria-hidden
          />
        </button>
      ) : null}

      <div data-testid="onboarding-backend-configuration-fields">
        {!hideConfigurationFields ? (
          <BackendConnectionOptions
            onConnected={handleConnected}
            testIdRoot="onboarding-backend"
            initialManualBackend={backendForForm}
            requireManualApiKey={isAuthRequired()}
            manualSubmitLabel={t(I18nKey.ONBOARDING$NEXT)}
            manualSubmittingLabel={t(I18nKey.SETTINGS$SAVING)}
            manualSubmitTestId="onboarding-backend-next"
            analyticsSource="onboarding"
          />
        ) : null}
      </div>

      {hideConfigurationFields ? (
        <div className={actionRowClassName}>
          {onBack ? (
            <BrandButton
              testId="onboarding-backend-back"
              type="button"
              variant="secondary"
              onClick={onBack}
            >
              {t(I18nKey.ONBOARDING$BACK)}
            </BrandButton>
          ) : null}
          <BrandButton
            testId="onboarding-backend-next"
            type="button"
            variant="primary"
            onClick={onNext}
          >
            {t(I18nKey.ONBOARDING$NEXT)}
          </BrandButton>
        </div>
      ) : null}
    </div>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";
import { ChatSendButton } from "#/components/features/chat/chat-send-button";
import { RecommendedAutomationsLauncher } from "#/components/features/automations/recommended-automations-launcher";
import { BrandButton } from "#/components/features/settings/brand-button";
import { useNavigation } from "#/context/navigation-context";
import { useCreateConversation } from "#/hooks/mutation/use-create-conversation";
import { useIsCreatingConversation } from "#/hooks/use-is-creating-conversation";
import { I18nKey } from "#/i18n/declaration";

interface SayHelloStepProps {
  onBack: () => void;
  /** Dismisses onboarding without launching a conversation. */
  onClose: () => void;
  /** Called once the conversation has been created — used by the parent
   * modal to mark the onboarding as complete before unmounting. */
  onLaunched: () => void;
}

/**
 * Step 3: a simple text input pre-filled with "hello OpenHands!" that
 * launches a brand-new conversation with no workspace and navigates
 * to it. Completing this step finishes the onboarding flow.
 */
export function SayHelloStep({
  onBack,
  onClose,
  onLaunched,
}: SayHelloStepProps) {
  const { t } = useTranslation("openhands");
  const { navigate } = useNavigation();
  const defaultMessage = t(I18nKey.ONBOARDING$HELLO_DEFAULT_MESSAGE);
  const [message, setMessage] = React.useState(defaultMessage);

  const {
    mutate: createConversation,
    isPending,
    isSuccess,
  } = useCreateConversation();
  const isCreatingElsewhere = useIsCreatingConversation();
  const [launchStatus, setLaunchStatus] = React.useState<
    "idle" | "pending" | "error"
  >("idle");
  const isPendingLaunch =
    launchStatus === "pending" || isPending || isCreatingElsewhere;
  const isLaunching = isPendingLaunch || isSuccess;
  const launchInFlightRef = React.useRef(false);

  const canSubmit =
    message.trim().length > 0 && !isLaunching && !launchInFlightRef.current;

  const launchConversation = () => {
    if (!canSubmit || launchInFlightRef.current) return;
    launchInFlightRef.current = true;
    setLaunchStatus("pending");

    // Explicitly omit `repository` and `workingDir` so the
    // conversation starts with no workspace, per the spec.
    createConversation(
      { query: message.trim(), entryPoint: "onboarding_say_hello" },
      {
        onSuccess: (data) => {
          navigate(`/conversations/${data.conversation_id}`);
          onLaunched();
        },
        onError: () => {
          launchInFlightRef.current = false;
          setLaunchStatus("error");
        },
      },
    );
  };

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    launchConversation();
  };

  return (
    <div
      data-testid="onboarding-step-say-hello"
      className="flex max-h-[calc(90vh-7rem)] flex-col"
    >
      <header className="flex shrink-0 flex-col gap-2">
        <h2 className="text-2xl font-medium text-contrast">
          {t(I18nKey.ONBOARDING$HELLO_TITLE)}
        </h2>
        <p className="text-sm text-muted">
          {t(I18nKey.ONBOARDING$HELLO_SUBTITLE)}
        </p>
      </header>

      <form
        onSubmit={handleSubmit}
        data-testid="onboarding-hello-input-form"
        className="mt-6 box-border flex w-full shrink-0 flex-col items-start justify-center rounded-[15px] border border-border bg-surface-raised p-4"
      >
        <div className="relative w-full">
          <div className="box-border flex w-full shrink-0 flex-row items-end justify-between gap-2 p-0 pb-4.5">
            <input
              data-testid="onboarding-hello-input"
              aria-label={t(I18nKey.ONBOARDING$HELLO_TITLE)}
              type="text"
              value={message}
              onChange={(event) => setMessage(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Enter" && !event.shiftKey) {
                  event.preventDefault();
                  launchConversation();
                }
              }}
              placeholder={defaultMessage}
              disabled={isLaunching}
              // Keep a fixed 16px input size; text-base scales with the host root font size.
              // eslint-disable-next-line shadcn/no-arbitrary-values
              className="min-h-5 w-full flex-1 bg-transparent text-[16px] font-normal leading-5 text-contrast outline-none placeholder:text-text-tertiary disabled:cursor-not-allowed disabled:opacity-50"
            />
          </div>
        </div>
        <div className="flex w-full min-w-0 items-center justify-end gap-2">
          <ChatSendButton
            buttonClassName=""
            handleSubmit={launchConversation}
            disabled={!canSubmit}
            isPending={isPendingLaunch}
          />
        </div>
      </form>

      {isPendingLaunch ? (
        <p
          role="status"
          aria-live="polite"
          className="mt-3 text-sm text-[var(--oh-muted)]"
        >
          {t(I18nKey.ONBOARDING$HELLO_LAUNCHING)}
        </p>
      ) : null}
      {launchStatus === "error" ? (
        <div
          role="alert"
          className="mt-3 flex items-center gap-2 text-sm text-danger"
        >
          <span>{t(I18nKey.ERROR$GENERIC)}</span>
          <button
            type="button"
            className="underline underline-offset-2"
            onClick={launchConversation}
          >
            {t(I18nKey.LAUNCH$TRY_AGAIN)}
          </button>
        </div>
      ) : null}

      <div
        data-testid="onboarding-hello-or-separator"
        className="mt-6 flex w-full items-center gap-3"
      >
        <div className="h-px flex-1 bg-border" />
        <span className="text-xs uppercase text-muted">
          {t(I18nKey.LANDING$OR)}
        </span>
        <div className="h-px flex-1 bg-border" />
      </div>

      <div
        data-testid="onboarding-recommended-automations"
        className="flex min-h-0 flex-1 flex-col"
      >
        <RecommendedAutomationsLauncher
          onLaunched={onLaunched}
          scrollableGrid
        />
      </div>

      <div className="flex shrink-0 items-center justify-between gap-2 bg-base-secondary pt-7 pb-7">
        <BrandButton
          testId="onboarding-hello-back"
          type="button"
          variant="secondary"
          onClick={onBack}
          isDisabled={isLaunching}
        >
          {t(I18nKey.ONBOARDING$BACK)}
        </BrandButton>
        <BrandButton
          testId="onboarding-hello-close"
          type="button"
          variant="secondary"
          onClick={onClose}
          isDisabled={isLaunching}
        >
          {t(I18nKey.BUTTON$CLOSE)}
        </BrandButton>
      </div>
    </div>
  );
}

import React from "react";
import { useQuery } from "@tanstack/react-query";
import { useTranslation } from "react-i18next";
import { BrandButton } from "#/components/features/settings/brand-button";
import { I18nKey } from "#/i18n/declaration";
import { LlmSettingsScreen } from "#/routes/llm-settings";
import type { SdkSectionSaveControl } from "#/components/features/settings/sdk-settings/sdk-section-page";
import {
  buildProfileLlmConfig,
  profileConfigToFormValues,
} from "#/components/features/settings/llm-profiles/llm-profile-form";
import { isNoBackend } from "#/api/backend-registry/active-store";
import AgentProfilesService, {
  WELL_KNOWN_DEFAULT_AGENT_PROFILE_NAME,
} from "#/api/agent-profiles-service/agent-profiles-service.api";
import { useActiveBackend } from "#/contexts/active-backend-context";
import { useSaveLlmProfile } from "#/hooks/mutation/use-save-llm-profile";
import { useActivateLlmProfile } from "#/hooks/mutation/use-activate-llm-profile";
import { useApplyOnboardingAgentProfile } from "#/hooks/mutation/use-apply-onboarding-agent-profile";
import {
  useDefaultModel,
  useDefaultModelReady,
} from "#/hooks/query/use-free-models";
import { LLM_PROFILES_QUERY_KEYS } from "#/hooks/query/use-llm-profiles";
import { useOpenAISubscriptionModels } from "#/hooks/query/use-llm-subscription-models";
import { useSettings } from "#/hooks/query/use-settings";
import { useAgentSettingsSchema } from "#/hooks/query/use-agent-settings-schema";
import { useBackendsHealth } from "#/hooks/query/use-backends-health";
import { LlmSettingsInputsSkeleton } from "#/components/features/settings/llm-settings/llm-settings-inputs-skeleton";
import { deriveProfileNameFromModel } from "#/utils/derive-profile-name";
import ProfilesService, {
  type SaveProfileRequest,
} from "#/api/profiles-service/profiles-service.api";
import { displayErrorToast } from "#/utils/custom-toast-handlers";
import type { SettingsFormValues } from "#/utils/sdk-settings-schema";
import {
  LLM_AUTH_TYPE_KEY,
  LLM_AUTH_TYPE_SUBSCRIPTION,
  resolveLlmAuthType,
} from "#/constants/llm-subscription";

interface SetupLlmStepProps {
  onBack: () => void;
  onNext: () => void;
}

/**
 * Fallback when the backend has not exposed a DB-selected OpenHands default.
 * A fresh profile starts with this model, and Next saves it even when the user
 * leaves it as is. An existing profile keeps its own model.
 */
export const ONBOARDING_DEFAULT_LLM_MODEL = "openai/gpt-5.6-sol";

interface ProfileSeed {
  /** The existing LLM profile the form shows, or `null` for a fresh profile. */
  profileName: string | null;
  /** That profile's config (secrets encrypted), or `{}` for a fresh profile. */
  baseConfig: Record<string, unknown>;
  /** The form values that show that profile. */
  initialValues: SettingsFormValues;
}

/**
 * The LLM profile onboarding edits: the active LLM profile, else the one the
 * `default` agent profile points at, else none (a fresh profile). Listing the
 * agent profiles first also runs the Agent Server's one-time backfill, which
 * turns an older install's raw LLM settings into an LLM profile named
 * `default` and points the `default` agent profile at it, without activating
 * it. The active profile comes first because a home launch runs it. The agent
 * profiles are best-effort, as in `useApplyOnboardingAgentProfile`: an older
 * backend without them still gets its active profile.
 */
async function loadOnboardingProfile(): Promise<{
  profileName: string | null;
  config: Record<string, unknown>;
}> {
  const agentProfiles = await AgentProfilesService.listProfiles().catch(
    () => null,
  );
  const llmProfiles = await ProfilesService.listProfiles();
  const existing = new Set(llmProfiles.profiles.map((profile) => profile.name));
  const defaultAgentRef = agentProfiles?.profiles.find(
    (profile) => profile.name === WELL_KNOWN_DEFAULT_AGENT_PROFILE_NAME,
  )?.llm_profile_ref;
  const profileName =
    [llmProfiles.active_profile, defaultAgentRef].find(
      (name): name is string => !!name && existing.has(name),
    ) ?? null;
  if (!profileName) return { profileName: null, config: {} };
  const detail = await ProfilesService.getProfile(profileName, "encrypted");
  return {
    profileName,
    config: (detail.config ?? {}) as Record<string, unknown>,
  };
}

/**
 * The profile the local LLM step edits (see `loadOnboardingProfile`). Raw LLM
 * settings are never the source. The seed is taken once per backend, because
 * the embedded form reads its initial values only when it mounts. Onboarding
 * mounts this step before a public-mode user adds the backend, and often while
 * a local Agent Server is still starting, so there is no seed until a backend
 * exists and answers. A failed read is an error to retry, not a fresh profile:
 * a fresh form would drop an endpoint the Basic view hides.
 */
function useOnboardingProfileSeed(isLocalBackend: boolean): {
  seed: ProfileSeed | null;
  isError: boolean;
  retry: () => void;
} {
  const { backend, orgId } = useActiveBackend();
  const hasBackend = isLocalBackend && !isNoBackend(backend);
  const healthByBackendId = useBackendsHealth(hasBackend ? [backend] : []);
  const enabled =
    hasBackend && healthByBackendId[backend.id]?.isConnected === true;
  const [seedState, setSeedState] = React.useState<{
    backendId: string;
    seed: ProfileSeed;
  } | null>(null);
  const seed = seedState?.backendId === backend.id ? seedState.seed : null;
  const profile = useQuery({
    queryKey: [
      ...LLM_PROFILES_QUERY_KEYS.all,
      "onboarding-seed",
      backend.id,
      orgId,
    ],
    queryFn: loadOnboardingProfile,
    // Read once: the seed never changes, and saving or activating the new
    // profile would otherwise refetch the secrets for nothing.
    enabled: enabled && !seed,
    // Keep the encrypted secrets out of the cache once the step unmounts.
    gcTime: 0,
    retry: 1,
    meta: { disableToast: true },
  });
  const { data: settings } = useSettings();
  const { data: schema, error: schemaError } = useAgentSettingsSchema(
    settings?.agent_settings_schema,
  );
  const isSchemaSettled = !!schema || !!schemaError;

  React.useEffect(() => {
    if (!enabled || seed || !profile.data || !isSchemaSettled) return;
    setSeedState({
      backendId: backend.id,
      seed: {
        profileName: profile.data.profileName,
        baseConfig: profile.data.config,
        initialValues: profileConfigToFormValues(schema, profile.data.config),
      },
    });
  }, [enabled, seed, backend.id, profile.data, isSchemaSettled, schema]);

  const { refetch } = profile;
  const retry = React.useCallback(() => {
    void refetch();
  }, [refetch]);

  return {
    seed,
    isError: enabled && !seed && profile.isError && !profile.isFetching,
    retry,
  };
}

/**
 * Step 2: embed the LLM settings form. The screen runs in `embedded`
 * mode (so it doesn't render its own sticky Save bar) and with
 * `hideSaveButton` set, surfacing its save state via
 * `onSaveControlChange`. We then render a single Next button at the
 * modal footer level matching the other onboarding steps.
 *
 * On a local backend the step edits an LLM profile, like the profile editor
 * in Settings: the form shows the profile `loadOnboardingProfile` picks, or a
 * fresh one with the default model. If the user changes nothing, Next keeps
 * that profile; otherwise it saves the form as a profile named after the
 * model. Either way it activates the profile and points the `default` agent
 * profile at it. Activation applies the profile to `agent_settings.llm` on the
 * server, so the step never reads or writes raw LLM settings.
 *
 * On Cloud, Next saves the form to the settings and `onSaveSuccess` advances.
 * The agent-profile ↔ LLM wiring is resolved server-side from those settings,
 * and there is no client-writable cloud agent-profile ref to repoint here. If
 * the form is untouched, Next advances without a save call.
 *
 * Note: returning Cloud users who already have an LLM configured are
 * intercepted upstream by `OnboardingHost`, so they never reach this
 * step. Users who do reach it are first-time installs (Cloud or Local)
 * who want the OpenHands default pre-filled.
 */
export function SetupLlmStep({ onBack, onNext }: SetupLlmStepProps) {
  const { t } = useTranslation("openhands");
  const { backend } = useActiveBackend();
  const isLocalBackend = backend.kind === "local";
  const saveProfile = useSaveLlmProfile();
  const activateProfile = useActivateLlmProfile();
  const applyAgentProfile = useApplyOnboardingAgentProfile();
  const dbDefaultLlmModel = useDefaultModel();
  const isDefaultModelReady = useDefaultModelReady();
  const defaultLlmModel = dbDefaultLlmModel ?? ONBOARDING_DEFAULT_LLM_MODEL;
  const {
    seed: profileSeed,
    isError: isProfileSeedError,
    retry: retryProfileSeed,
  } = useOnboardingProfileSeed(isLocalBackend);
  const [saveControl, setSaveControl] =
    React.useState<SdkSectionSaveControl | null>(null);
  const [isFinalizing, setIsFinalizing] = React.useState(false);
  const isSubscriptionAuth =
    resolveLlmAuthType(saveControl?.values[LLM_AUTH_TYPE_KEY]) ===
    LLM_AUTH_TYPE_SUBSCRIPTION;
  // Shares the form's query, so this reads the list its picker shows.
  const { data: subscriptionModels } = useOpenAISubscriptionModels({
    enabled: isLocalBackend && isSubscriptionAuth,
  });

  // An existing profile keeps its own model; only a fresh one gets the
  // onboarding default, so the form never pairs the default model with
  // another profile's key and endpoint.
  const initialValueOverrides = React.useMemo(() => {
    if (profileSeed?.profileName) return profileSeed.initialValues;
    return {
      ...(profileSeed?.initialValues ?? {}),
      "llm.model": defaultLlmModel,
    };
  }, [profileSeed, defaultLlmModel]);

  const activateForOnboarding = React.useCallback(
    async (profileName: string) => {
      await activateProfile.mutateAsync(profileName);
      // Conversations launch from the active AGENT profile, so point it at the
      // LLM the user just set up or kept (this also clears the "LLM not set
      // up" banner). Otherwise it keeps its seeded llm_profile_ref, which may
      // have no key.
      await applyAgentProfile({
        agent_kind: "openhands",
        llm_profile_ref: profileName,
      });
      onNext();
    },
    [activateProfile, applyAgentProfile, onNext],
  );

  const persistProfile = React.useCallback(async () => {
    if (!saveControl || !profileSeed) return;

    // Unchanged existing profile: keep it as it is rather than saving a copy
    // under the name derived from its model.
    if (profileSeed.profileName && !saveControl.isDirty) {
      setIsFinalizing(true);
      try {
        await activateForOnboarding(profileSeed.profileName);
      } catch {
        displayErrorToast(t(I18nKey.ERROR$GENERIC));
      } finally {
        setIsFinalizing(false);
      }
      return;
    }

    let dirtyLlm: Record<string, unknown>;
    try {
      dirtyLlm = {
        ...((saveControl.getDirtyPayload().llm ?? {}) as Record<
          string,
          unknown
        >),
      };
    } catch (error) {
      displayErrorToast(
        error instanceof Error ? error.message : t(I18nKey.ERROR$GENERIC),
      );
      return;
    }
    // The form shows its model even when the user keeps it (a fresh profile's
    // is the onboarding default), so the profile gets that model whether or
    // not the field was edited.
    if (!Object.prototype.hasOwnProperty.call(dirtyLlm, "model")) {
      dirtyLlm.model = String(saveControl.values["llm.model"] ?? "");
    }
    if (isSubscriptionAuth && !subscriptionModels?.length) {
      displayErrorToast(t(I18nKey.SETTINGS$SUBSCRIPTION_MODELS_NOT_LOADED));
      return;
    }
    const { llmConfig } = buildProfileLlmConfig({
      baseConfig: profileSeed.baseConfig,
      dirtyLlm,
      values: saveControl.values,
      view: saveControl.view,
      supportsConnections: true,
      isCloud: false,
      subscriptionModels,
    });
    const model = typeof llmConfig.model === "string" ? llmConfig.model : "";
    if (!model) {
      displayErrorToast(t(I18nKey.SETTINGS$MODEL_REQUIRED));
      return;
    }
    const profileName = deriveProfileNameFromModel(model);

    setIsFinalizing(true);
    try {
      await saveProfile.mutateAsync({
        name: profileName,
        request: {
          llm: llmConfig as SaveProfileRequest["llm"],
          include_secrets: true,
        },
      });
      await activateForOnboarding(profileName);
    } catch {
      // Nothing advanced, so Next retries the whole save.
      displayErrorToast(t(I18nKey.ERROR$GENERIC));
    } finally {
      setIsFinalizing(false);
    }
  }, [
    saveControl,
    profileSeed,
    isSubscriptionAuth,
    subscriptionModels,
    saveProfile,
    activateForOnboarding,
    t,
  ]);

  const handleNext = () => {
    if (isLocalBackend) {
      void persistProfile();
      return;
    }
    if (saveControl?.isDirty) {
      // `onSaveSuccess` advances once the settings save resolves.
      saveControl.save();
      return;
    }
    onNext();
  };

  return (
    <div
      data-testid="onboarding-step-setup-llm"
      className="flex flex-col gap-6 max-h-[calc(90vh-7rem)]"
    >
      <header className="flex flex-col gap-2">
        <h2 className="text-2xl font-medium text-contrast">
          {t(I18nKey.ONBOARDING$LLM_TITLE)}
        </h2>
        <p className="text-sm text-muted">
          {t(
            profileSeed?.profileName
              ? I18nKey.ONBOARDING$LLM_SUBTITLE_CURRENT_PROFILE
              : I18nKey.ONBOARDING$LLM_SUBTITLE,
          )}
        </p>
      </header>

      <div
        data-testid="onboarding-llm-settings"
        className="flex min-h-0 flex-1 flex-col overflow-y-auto custom-scrollbar-always"
      >
        {isProfileSeedError ? (
          <div
            data-testid="onboarding-llm-load-error"
            className="flex flex-col items-start gap-3"
          >
            <p className="text-sm text-muted">
              {t(I18nKey.ERROR$FAILED_TO_LOAD_PROFILE_TRY_AGAIN)}
            </p>
            <BrandButton
              testId="onboarding-llm-load-retry"
              type="button"
              variant="secondary"
              onClick={retryProfileSeed}
            >
              {t(I18nKey.AUTOMATIONS$ERROR_RETRY)}
            </BrandButton>
          </div>
        ) : isDefaultModelReady && (!isLocalBackend || profileSeed) ? (
          <LlmSettingsScreen
            embedded
            hideSaveButton
            suppressSuccessToast
            initialValueOverrides={initialValueOverrides}
            // Local edits a profile, so like the profile editor only real
            // changes are dirty. Cloud saves the model override to settings,
            // so the override starts dirty there.
            markInitialOverridesDirty={!isLocalBackend}
            onSaveSuccess={isLocalBackend ? undefined : onNext}
            onSaveControlChange={setSaveControl}
          />
        ) : (
          <LlmSettingsInputsSkeleton />
        )}
      </div>

      <div className="sticky bottom-0 flex items-center justify-between gap-2 bg-base-secondary pt-4 pb-7">
        <BrandButton
          testId="onboarding-llm-back"
          type="button"
          variant="secondary"
          onClick={onBack}
        >
          {t(I18nKey.ONBOARDING$BACK)}
        </BrandButton>
        <BrandButton
          testId="onboarding-llm-next"
          type="button"
          variant="primary"
          isDisabled={
            !isDefaultModelReady ||
            (isLocalBackend && (!profileSeed || !saveControl)) ||
            (saveControl?.isSaving ?? false) ||
            isFinalizing
          }
          onClick={handleNext}
        >
          {t(I18nKey.ONBOARDING$NEXT)}
        </BrandButton>
      </div>
    </div>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";
import { ModalBackdrop } from "#/components/shared/modals/modal-backdrop";
import { ModalCloseButton } from "#/components/shared/modals/modal-close-button";
import { BrandButton } from "#/components/features/settings/brand-button";
import { SettingsInput } from "#/components/features/settings/settings-input";
import { useInstallPlugin } from "#/hooks/mutation/use-install-plugin";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import { modalTitleLgClassName } from "#/utils/modal-classes";

interface AddPluginModalProps {
  onClose: () => void;
  onInstalled?: () => void;
}

export function AddPluginModal({ onClose, onInstalled }: AddPluginModalProps) {
  const { t } = useTranslation("openhands");
  const installPlugin = useInstallPlugin();

  const [source, setSource] = React.useState("");
  const [ref, setRef] = React.useState("");
  const [repoPath, setRepoPath] = React.useState("");

  const trimmedSource = source.trim();
  const canSubmit = trimmedSource.length > 0 && !installPlugin.isPending;

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!canSubmit) return;

    installPlugin.mutate(
      {
        source: trimmedSource,
        ref: ref.trim() || null,
        repo_path: repoPath.trim() || null,
      },
      {
        onSuccess: () => {
          onInstalled?.();
          onClose();
        },
      },
    );
  };

  return (
    <ModalBackdrop
      onClose={onClose}
      aria-label={t(I18nKey.SETTINGS$PLUGINS_ADD_MODAL_TITLE)}
    >
      <form
        onSubmit={handleSubmit}
        data-testid="add-plugin-modal"
        className="relative flex w-130 max-w-[90vw] max-h-[85vh] flex-col rounded-xl border border-border bg-base-secondary"
      >
        <ModalCloseButton onClose={onClose} testId="add-plugin-modal-close" />

        <header className="flex-shrink-0 px-6 pb-4 pt-6">
          <h2 className={cn("pr-6", modalTitleLgClassName)}>
            {t(I18nKey.SETTINGS$PLUGINS_ADD_MODAL_TITLE)}
          </h2>
          <p className="mt-4 text-sm text-tertiary-light">
            {t(I18nKey.SETTINGS$PLUGINS_ADD_MODAL_INTRO)}
          </p>
        </header>

        <div className="flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-6 custom-scrollbar">
          <SettingsInput
            testId="add-plugin-source-input"
            label={t(I18nKey.SETTINGS$PLUGINS_SOURCE_LABEL)}
            type="text"
            value={source}
            onChange={setSource}
            placeholder={t(I18nKey.SETTINGS$PLUGINS_SOURCE_PLACEHOLDER)}
            showRequiredTag
          />
          <SettingsInput
            testId="add-plugin-ref-input"
            label={t(I18nKey.SETTINGS$PLUGINS_REF_LABEL)}
            type="text"
            value={ref}
            onChange={setRef}
            showOptionalTag
          />
          <SettingsInput
            testId="add-plugin-repo-path-input"
            label={t(I18nKey.SETTINGS$PLUGINS_REPO_PATH_LABEL)}
            type="text"
            value={repoPath}
            onChange={setRepoPath}
            showOptionalTag
          />
        </div>

        <footer className="flex flex-shrink-0 justify-end gap-2 px-6 pb-6 pt-4">
          <BrandButton
            type="button"
            variant="secondary"
            onClick={onClose}
            testId="add-plugin-modal-dismiss"
          >
            {t(I18nKey.BUTTON$CLOSE)}
          </BrandButton>
          <BrandButton
            type="submit"
            variant="primary"
            testId="add-plugin-submit"
            isDisabled={!canSubmit}
          >
            {t(
              installPlugin.isPending
                ? I18nKey.SETTINGS$PLUGINS_INSTALLING
                : I18nKey.SETTINGS$PLUGINS_INSTALL,
            )}
          </BrandButton>
        </footer>
      </form>
    </ModalBackdrop>
  );
}

