interface AgentProfileActionsMenuProps {
  onEdit: () => void;
  onSetActive: () => void;
  onDelete: () => void;
  isActive: boolean;
  isActivating: boolean;
  onClose: () => void;
  /**
   * Element the menu anchors against. When provided, the menu renders into a
   * body portal with fixed positioning so it isn't clipped by scroll
   * containers (matches the LLM-profiles menu behavior).
   */
  anchorRef?: React.RefObject<HTMLElement | null>;
}

export function AgentProfileActionsMenu({
  onEdit,
  onSetActive,
  onDelete,
  isActive,
  isActivating,
  onClose,
  anchorRef,
}: AgentProfileActionsMenuProps) {
  const { t } = useTranslation("openhands");
  const menuRef = useRef<HTMLDivElement>(null);
  const menuItemsRef = useRef<(HTMLButtonElement | null)[]>([]);

  const anchorElement = anchorRef?.current ?? null;
  const [portalStyle, setPortalStyle] = useState<React.CSSProperties>();

  useLayoutEffect(() => {
    if (!anchorElement) return undefined;

    const updatePosition = () => {
      const rect = anchorElement.getBoundingClientRect();
      if (!rect) return;
      const gap = 8;
      setPortalStyle({
        position: "fixed",
        zIndex: 9999,
        top: rect.bottom + gap,
        right: window.innerWidth - rect.right,
        width: "max-content",
      });
    };

    updatePosition();
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [anchorElement]);

  // The anchored menu renders nothing until its position is measured, so wait
  // for the items to exist before focusing the first enabled one.
  const isMenuRendered = !anchorElement || portalStyle !== undefined;
  useEffect(() => {
    if (isMenuRendered) getEnabledItems(menuItemsRef.current)[0]?.focus();
  }, [isMenuRendered]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node;
      if (menuRef.current?.contains(target)) return;
      if (anchorElement?.contains(target)) return;
      onClose();
    };
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        if (menuRef.current?.contains(document.activeElement)) {
          anchorElement?.focus();
        }
        onClose();
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("keydown", handleEscape);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("keydown", handleEscape);
    };
  }, [anchorElement, onClose]);

  const handleAction = (action: () => void) => {
    action();
    onClose();
  };

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent, currentIndex: number) => {
      if (e.key === "Tab") {
        // The anchored menu is portaled to the end of <body>; move focus back
        // to its trigger so Tab continues from the row, not the page end.
        anchorElement?.focus();
        onClose();
        return;
      }
      if (e.key !== "ArrowDown" && e.key !== "ArrowUp") return;
      e.preventDefault();
      const enabledItems = getEnabledItems(menuItemsRef.current);
      const position = enabledItems.findIndex(
        (item) => item === menuItemsRef.current[currentIndex],
      );
      const step = e.key === "ArrowDown" ? 1 : -1;
      const target =
        (position + step + enabledItems.length) % enabledItems.length;
      enabledItems[target]?.focus();
    },
    [anchorElement, onClose],
  );

  const setActiveDisabled = isActive || isActivating;
  const isPortaled = Boolean(anchorElement);

  const menu = (
    <div
      ref={menuRef}
      className={cn(
        "absolute right-0 top-full z-10 mt-2 w-40 rounded-md border border-border-subtle bg-tertiary px-1 py-1 shadow-lg",
        dropdownMenuListClassName,
        isPortaled &&
          "!static !top-auto !bottom-auto !left-auto !right-auto !mt-0",
      )}
      role="menu"
      aria-orientation="vertical"
      data-testid="agent-profile-actions-menu"
    >
      <MenuItem
        index={0}
        icon={<EditIcon width={16} height={16} />}
        label={t(I18nKey.SETTINGS$PROFILE_EDIT)}
        onClick={() => handleAction(onEdit)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        testId="agent-profile-edit"
      />
      <MenuItem
        index={1}
        icon={<CheckCircleIcon width={16} height={16} />}
        label={t(I18nKey.SETTINGS$PROFILE_SET_ACTIVE)}
        onClick={() => handleAction(onSetActive)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        disabled={setActiveDisabled}
        testId="agent-profile-set-active"
      />
      <MenuItem
        index={2}
        icon={<DeleteIcon width={16} height={16} />}
        label={t(I18nKey.BUTTON$DELETE)}
        onClick={() => handleAction(onDelete)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        testId="agent-profile-delete"
      />
    </div>
  );

  if (isPortaled) {
    if (typeof document === "undefined" || !portalStyle) {
      return null;
    }
    return ReactDOM.createPortal(
      <div style={portalStyle}>{menu}</div>,
      document.body,
    );
  }

  return menu;
}

import { useTranslation } from "react-i18next";
import { LoadingSpinner } from "#/components/shared/loading-spinner";
import { AgentProfileRow } from "./agent-profile-row";
import { type AgentProfileSummary } from "#/api/agent-profiles-service/agent-profiles-service.api";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import {
  settingsListContainerClassName,
  settingsListDividerClassName,
} from "#/utils/settings-list-classes";
import { extensionModuleEmptyStateClassName } from "#/utils/extension-module-card-classes";

interface AgentProfilesBodyProps {
  isLoading: boolean;
  loadError: Error | null;
  profiles: AgentProfileSummary[];
  activeId: string | null;
  /** When false, rows are read-only and the actions menu is hidden. */
  canManage: boolean;
  onActivate: (profile: AgentProfileSummary) => void;
  onEdit: (profile: AgentProfileSummary) => void;
  onDelete: (profile: AgentProfileSummary) => void;
  isActivating: boolean;
}

export function AgentProfilesBody({
  isLoading,
  loadError,
  profiles,
  activeId,
  canManage,
  onActivate,
  onEdit,
  onDelete,
  isActivating,
}: AgentProfilesBodyProps) {
  const { t } = useTranslation("openhands");

  if (isLoading) {
    return (
      <div className="flex justify-center p-4">
        <LoadingSpinner size="large" />
      </div>
    );
  }

  if (loadError) {
    return (
      <div
        data-testid="agent-profiles-load-error"
        className={extensionModuleEmptyStateClassName}
      >
        <p className="text-sm text-red-400">
          {t(I18nKey.SETTINGS$PROFILES_LOAD_ERROR)}
        </p>
      </div>
    );
  }

  if (profiles.length === 0) {
    return (
      <div
        data-testid="agent-profiles-empty"
        className={extensionModuleEmptyStateClassName}
      >
        <p className="text-sm text-muted">
          {t(I18nKey.SETTINGS$PROFILES_EMPTY)}
        </p>
      </div>
    );
  }

  return (
    <div
      className={cn(
        settingsListContainerClassName,
        settingsListDividerClassName,
      )}
    >
      {profiles.map((profile) => (
        <AgentProfileRow
          key={profile.name}
          profile={profile}
          isActive={!!profile.id && profile.id === activeId}
          canManage={canManage}
          onActivate={onActivate}
          onEdit={onEdit}
          onDelete={onDelete}
          isActivating={isActivating}
        />
      ))}
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { AgentProfilesManager } from "./agent-profiles-manager";
import { GlobalToolsNotice } from "./global-tools-notice";
import { mergeAgentProfileSaveInput } from "./merge-agent-profile-save-input";
import { ProfileNameInput } from "#/components/features/settings/llm-profiles/profile-name-input";
import { BrandButton } from "#/components/features/settings/brand-button";
import { SettingsDropdownInput } from "#/components/features/settings/settings-dropdown-input";
import {
  AgentSettingsScreen,
  type AgentSettingsSaveControl,
} from "#/routes/agent-settings";
import AgentProfilesService, {
  WELL_KNOWN_DEFAULT_AGENT_PROFILE_NAME,
  type AgentProfile,
  type AgentProfileSummary,
  type AgentProfileSaveInput,
} from "#/api/agent-profiles-service/agent-profiles-service.api";
import { useSaveAgentProfile } from "#/hooks/mutation/use-save-agent-profile";
import { useRenameAgentProfile } from "#/hooks/mutation/use-rename-agent-profile";
import { useAgentProfiles } from "#/hooks/query/use-agent-profiles";
import { useLlmProfiles } from "#/hooks/query/use-llm-profiles";
import {
  displayErrorToast,
  displaySuccessToast,
} from "#/utils/custom-toast-handlers";
import { I18nKey } from "#/i18n/declaration";
import { isProfileNameValid } from "#/utils/derive-profile-name";
import { retrieveAxiosErrorMessage } from "#/utils/retrieve-axios-error-message";
import { SettingsValue } from "#/types/settings";
import { BackNavButton } from "#/components/shared/buttons/back-nav-button";
import { Typography } from "#/ui/typography";
import { useSettingsSectionHeader } from "#/contexts/settings-section-header-context";
import { parseCommand } from "#/utils/acp-command";

type ViewMode = "list" | "create" | "edit";

/**
 * Build the `agent_settings`-shaped seed the embedded {@link AgentSettingsScreen}
 * consumes for an existing profile. The stored ACP command is a shell string;
 * the form's init logic expects a token array, so split it here.
 */
function toAgentSettingsOverride(
  profile: AgentProfile,
): Record<string, SettingsValue> {
  const secretRefs = profile.secret_refs ?? null;
  if (profile.agent_kind === "acp") {
    return {
      agent_kind: "acp",
      mcp_server_refs: profile.mcp_server_refs ?? null,
      secret_refs: secretRefs,
      acp_server: profile.acp_server,
      acp_command: profile.acp_command ? parseCommand(profile.acp_command) : [],
      acp_args: profile.acp_args ?? [],
      acp_model: profile.acp_model ?? "",
    };
  }
  return {
    agent_kind: "openhands",
    mcp_server_refs: profile.mcp_server_refs ?? null,
    tools: (profile.tools as SettingsValue) ?? null,
    tool_concurrency_limit: profile.tool_concurrency_limit,
    secret_refs: secretRefs,
    persona: profile.persona ?? null,
    system_message_suffix: profile.system_message_suffix ?? null,
  };
}

/**
 * AgentProfilesLocalView mirrors {@link LlmSettingsLocalView}: a list of the
 * user's Agent profiles, with a create/edit view that reuses the existing Agent
 * settings form (embedded) plus a profile name and — for OpenHands profiles —
 * an LLM-profile picker. Available on local backends only.
 */
export function AgentProfilesLocalView() {
  const { t } = useTranslation("openhands");
  const { setHideSectionHeader } = useSettingsSectionHeader();
  const saveProfile = useSaveAgentProfile();
  const renameProfile = useRenameAgentProfile();
  const { data: profilesData } = useAgentProfiles();
  const { data: llmProfilesData, isLoading: isLlmProfilesLoading } =
    useLlmProfiles();

  const [viewMode, setViewMode] = useState<ViewMode>("list");
  const [profileName, setProfileName] = useState("");
  const [editingProfile, setEditingProfile] = useState<AgentProfile | null>(
    null,
  );
  const [override, setOverride] = useState<Record<
    string,
    SettingsValue
  > | null>(null);
  const [llmProfileRef, setLlmProfileRef] = useState("");
  const [saveControl, setSaveControl] =
    useState<AgentSettingsSaveControl | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    setHideSectionHeader(viewMode !== "list");
    return () => setHideSectionHeader(false);
  }, [viewMode, setHideSectionHeader]);

  const llmProfiles = llmProfilesData?.profiles ?? [];
  const defaultLlmProfileRef =
    llmProfilesData?.active_profile ?? llmProfiles[0]?.name ?? "";

  const existingNames = useMemo(
    () => new Set(profilesData?.profiles?.map((p) => p.name) ?? []),
    [profilesData],
  );

  // The shared validator rejects whitespace, so the duplicate check compares raw.
  const isNameFormatValid = isProfileNameValid(profileName, {
    isRequired: true,
  });
  const isDuplicateName =
    isNameFormatValid &&
    existingNames.has(profileName) &&
    (viewMode === "create" ||
      (viewMode === "edit" && profileName !== editingProfile?.name));
  const isNameValid = isNameFormatValid && !isDuplicateName;

  const handleAddProfile = useCallback(() => {
    setProfileName("");
    setEditingProfile(null);
    setOverride({ agent_kind: "openhands" });
    setLlmProfileRef(defaultLlmProfileRef);
    setSaveControl(null);
    setViewMode("create");
  }, [defaultLlmProfileRef]);

  const handleEditProfile = useCallback(
    async (summary: AgentProfileSummary) => {
      try {
        // Fetch with encrypted secret exposure so any `skills[].mcp_tools`
        // values arrive as Fernet tokens rather than masks — the save below
        // round-trips the stored profile, and posting back a mask would
        // persist it literally (the local save only decrypts tokens).
        const detail = await AgentProfilesService.getProfile(
          summary.name,
          "encrypted",
        );
        const profile = detail.profile;
        setEditingProfile(profile);
        setOverride(toAgentSettingsOverride(profile));
        if (profile.agent_kind === "openhands") {
          // A profile can reference an LLM profile that's since been deleted
          // (or renamed): the dropdown would render nothing selected while
          // `llmProfileRef` still holds the stale name and saves it straight
          // back. Validate against the live list and fall back to the default
          // so a dangling ref self-heals on load (#1571 review). Skip the
          // check while the list is still loading rather than treating an
          // unloaded cache as "not found".
          const refIsLive =
            isLlmProfilesLoading ||
            llmProfiles.some((p) => p.name === profile.llm_profile_ref);
          setLlmProfileRef(
            refIsLive ? profile.llm_profile_ref : defaultLlmProfileRef,
          );
        } else {
          setLlmProfileRef("");
        }
        setProfileName(profile.name);
        setSaveControl(null);
        setViewMode("edit");
      } catch (error) {
        console.error("Failed to fetch agent profile:", error);
        displayErrorToast(t(I18nKey.ERROR$GENERIC));
      }
    },
    [t, llmProfiles, isLlmProfilesLoading, defaultLlmProfileRef],
  );

  const handleBackToList = useCallback(() => {
    setViewMode("list");
    setEditingProfile(null);
    setProfileName("");
    setOverride(null);
    setSaveControl(null);
  }, []);

  const handleSave = useCallback(async () => {
    if (!saveControl || !isNameValid) return;

    // Build the variant-specific fields from the embedded form (may throw on
    // invalid input, e.g. a bad concurrency value).
    let input: AgentProfileSaveInput;
    try {
      const fields = saveControl.buildAgentProfileFields();
      if (fields.agent_kind === "openhands") {
        if (!llmProfileRef) {
          displayErrorToast(t(I18nKey.SETTINGS$AGENT_PROFILE_LLM_REQUIRED));
          return;
        }
        input = { ...fields, llm_profile_ref: llmProfileRef };
      } else {
        input = fields as AgentProfileSaveInput;
      }
    } catch (error) {
      displayErrorToast(
        error instanceof Error ? error.message : t(I18nKey.ERROR$GENERIC),
      );
      return;
    }

    const trimmedName = profileName.trim();
    const originalName = editingProfile?.name;
    const isRename =
      viewMode === "edit" && originalName && originalName !== trimmedName;

    setIsSaving(true);
    try {
      // Persist ACP credentials (global secrets) before the profile spec.
      if (saveControl.credentials.isDirty) {
        const ok = await saveControl.credentials.save({ silent: true });
        if (!ok) return;
        saveControl.credentials.reset();
      }

      // Rename first (preserves the profile's stable id / active pointer);
      // saving to a new name would otherwise mint a fresh profile.
      if (isRename) {
        await renameProfile.mutateAsync({
          name: originalName,
          newName: trimmedName,
        });
      }

      // Save is a whole-profile overwrite: spread the stored profile under
      // the edited fields so the fields this editor doesn't model survive an
      // edit (kind-aware — a kind switch stays a clean variant replacement).
      const profile = mergeAgentProfileSaveInput(
        viewMode === "edit" ? editingProfile : null,
        input,
      );
      await saveProfile.mutateAsync({ name: trimmedName, profile });

      displaySuccessToast(
        viewMode === "create"
          ? t(I18nKey.SETTINGS$PROFILE_CREATED, { name: trimmedName })
          : t(I18nKey.SETTINGS$PROFILE_UPDATED, { name: trimmedName }),
      );
      handleBackToList();
    } catch (error) {
      const message = retrieveAxiosErrorMessage(error as never);
      displayErrorToast(message || t(I18nKey.ERROR$GENERIC));
    } finally {
      setIsSaving(false);
    }
  }, [
    saveControl,
    isNameValid,
    llmProfileRef,
    profileName,
    viewMode,
    editingProfile,
    saveProfile,
    renameProfile,
    t,
    handleBackToList,
  ]);

  if (viewMode === "list") {
    return (
      <div className="flex flex-col gap-4">
        <GlobalToolsNotice />
        <AgentProfilesManager
          onAddProfile={handleAddProfile}
          onEditProfile={handleEditProfile}
        />
      </div>
    );
  }

  const editorTitle =
    viewMode === "edit"
      ? t(I18nKey.SETTINGS$EDIT_AGENT_PROFILE)
      : t(I18nKey.SETTINGS$ADD_AGENT_PROFILE);
  const editorDescription =
    viewMode === "edit" && editingProfile
      ? t(I18nKey.SETTINGS$PROFILE_LOADED, { name: editingProfile.name })
      : t(I18nKey.SETTINGS$AGENT_PROFILE_SAVE_HINT);
  const isOpenHands = saveControl?.agentType !== "acp";
  const nameDirty = viewMode === "edit" && profileName !== editingProfile?.name;
  const loadedLlmRef =
    editingProfile?.agent_kind === "openhands"
      ? editingProfile.llm_profile_ref
      : "";
  const llmRefDirty =
    viewMode === "edit" && isOpenHands && llmProfileRef !== loadedLlmRef;
  const hasUnsavedChanges =
    viewMode === "create" ||
    Boolean(saveControl?.isDirty) ||
    nameDirty ||
    llmRefDirty;

  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-col gap-2">
        <BackNavButton
          testId="back-to-agent-profiles"
          onClick={handleBackToList}
        >
          {t(I18nKey.BUTTON$BACK)}
        </BackNavButton>
        <Typography.H2 testId="agent-profile-editor-title">
          {editorTitle}
        </Typography.H2>
        <p
          data-testid="agent-profile-editor-description"
          className="text-sm leading-5 text-tertiary-light"
        >
          {editorDescription}
        </p>
      </div>

      <ProfileNameInput
        testId="agent-profile-name-input"
        value={profileName}
        onChange={setProfileName}
        isRequired
        error={
          isDuplicateName
            ? t(I18nKey.SETTINGS$META_PROFILE_NAME_TAKEN)
            : undefined
        }
      />

      {/* Reuse the existing Agent settings form to define the agent. */}
      <AgentSettingsScreen
        key={viewMode === "edit" ? `edit-${editingProfile?.id}` : "new-profile"}
        agentSettingsOverride={override}
        onSaveControlChange={setSaveControl}
        isDefaultProfile={
          profileName.trim() === WELL_KNOWN_DEFAULT_AGENT_PROFILE_NAME
        }
      />

      {/* OpenHands profiles reference an LLM profile (required). */}
      {isOpenHands &&
        (llmProfiles.length > 0 ? (
          <SettingsDropdownInput
            testId="agent-profile-llm-selector"
            name="agent-profile-llm"
            label={t(I18nKey.SETTINGS$AGENT_PROFILE_LLM_LABEL)}
            items={llmProfiles.map((p) => ({
              key: p.name,
              label: p.model ? `${p.name} (${p.model})` : p.name,
            }))}
            selectedKey={llmProfileRef}
            onSelectionChange={(key) => key && setLlmProfileRef(String(key))}
          />
        ) : (
          <p
            data-testid="agent-profile-no-llm"
            className="text-sm text-red-400"
          >
            {t(I18nKey.SETTINGS$AGENT_PROFILE_NO_LLM)}
          </p>
        ))}

      <div className="flex justify-start gap-3 pt-4">
        <BrandButton
          testId="cancel-agent-profile-btn"
          type="button"
          variant="secondary"
          onClick={handleBackToList}
        >
          {t(I18nKey.BUTTON$CANCEL)}
        </BrandButton>
        <BrandButton
          testId="save-agent-profile-btn"
          type="button"
          variant="primary"
          onClick={handleSave}
          isDisabled={
            !isNameValid ||
            isSaving ||
            !saveControl?.isValid ||
            !hasUnsavedChanges
          }
          aria-busy={isSaving}
        >
          {isSaving ? t(I18nKey.SETTINGS$SAVING) : t(I18nKey.BUTTON$SAVE)}
        </BrandButton>
      </div>
    </div>
  );
}

import { useTranslation } from "react-i18next";
import { Typography } from "#/ui/typography";
import { I18nKey } from "#/i18n/declaration";
import { useActiveBackend } from "#/contexts/active-backend-context";
import { useAllCloudOrganizations } from "#/hooks/query/use-cloud-organizations";
import { useCloudCurrentUserId } from "#/hooks/query/use-cloud-current-user-id";

function useActiveBackendDisplayName(): string {
  const { t } = useTranslation();
  const active = useActiveBackend();
  const cloudOrgs = useAllCloudOrganizations();
  const userIds = useCloudCurrentUserId();

  if (active.backend.kind !== "cloud" || !active.orgId) {
    return active.backend.name;
  }

  const entry = cloudOrgs[active.backend.id];
  const org = entry?.orgs.find((o) => o.id === active.orgId);
  if (!org) return active.backend.name;

  const userId = userIds[active.backend.id]?.userId ?? null;
  const isPersonal = !!userId && org.id === userId;
  const orgLabel = isPersonal
    ? t(I18nKey.BACKEND$PERSONAL_WORKSPACE)
    : org.name;
  return `${active.backend.name} – ${orgLabel}`;
}

export function BackendSyncedSettingsBadge() {
  const { t } = useTranslation();
  const active = useActiveBackend();
  const name = useActiveBackendDisplayName();

  return (
    <div
      data-testid="backend-synced-settings-badge"
      className="flex items-center"
    >
      <Typography.Text className="text-[11px] font-medium text-text-secondary leading-5">
        {t(I18nKey.SETTINGS$BACKEND_SYNCED_BADGE, {
          name,
          host: active.backend.host,
          interpolation: { escapeValue: false },
        })}
      </Typography.Text>
    </div>
  );
}

import { forwardRef } from "react";
import { cn } from "#/utils/utils";
import { formControlButtonClassName } from "#/utils/form-control-classes";

interface BrandButtonProps {
  testId?: string;
  name?: string;
  variant: "primary" | "secondary" | "tertiary" | "danger" | "ghost-danger";
  type: React.ButtonHTMLAttributes<HTMLButtonElement>["type"];
  isDisabled?: boolean;
  className?: string;
  onClick?: (event?: React.MouseEvent<HTMLButtonElement>) => void;
  startContent?: React.ReactNode;
  /** Accessible label for icon-only buttons */
  ariaLabel?: string;
  /** Indicates busy/loading state for screen readers */
  "aria-busy"?: boolean;
  "aria-haspopup"?: React.AriaAttributes["aria-haspopup"];
  "aria-expanded"?: boolean;
}

export const BrandButton = forwardRef<
  HTMLButtonElement,
  React.PropsWithChildren<BrandButtonProps>
>(function BrandButton(
  {
    testId,
    name,
    children,
    variant,
    type,
    isDisabled,
    className,
    onClick,
    startContent,
    ariaLabel,
    "aria-busy": ariaBusy,
    "aria-haspopup": ariaHasPopup,
    "aria-expanded": ariaExpanded,
  },
  ref,
) {
  return (
    <button
      ref={ref}
      name={name}
      data-testid={testId}
      disabled={isDisabled}
      // The type is already passed as a prop to the button component

      type={type}
      onClick={onClick}
      aria-label={ariaLabel}
      aria-busy={ariaBusy}
      aria-haspopup={ariaHasPopup}
      aria-expanded={ariaExpanded}
      className={cn(
        formControlButtonClassName,
        variant === "primary" &&
          "bg-primary text-[var(--oh-accent-foreground)] hover:opacity-80 disabled:bg-interactive-hover disabled:text-muted disabled:opacity-100",
        variant === "secondary" &&
          "border border-border bg-base-secondary text-contrast hover:bg-surface-raised",
        variant === "tertiary" &&
          "bg-interactive-hover text-contrast hover:opacity-80",
        variant === "danger" && "bg-red-600 text-white hover:bg-red-700",
        variant === "ghost-danger" &&
          "h-auto min-h-0 bg-transparent px-0 text-red-600 underline hover:text-red-700 hover:no-underline font-normal",
        startContent && "flex items-center justify-center gap-2",
        className,
      )}
    >
      {startContent}
      {children}
    </button>
  );
});

import { useEffect, useMemo, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { BrandButton } from "#/components/features/settings/brand-button";
import { LoadingSpinner } from "#/components/shared/loading-spinner";
import { ApiKeyModalBase } from "#/components/features/settings/api-key-modal-base";
import { useProviderModels } from "#/hooks/query/use-provider-models";
import { useSearchProviders } from "#/hooks/query/use-search-providers";
import { useSaveLlmProfile } from "#/hooks/mutation/use-save-llm-profile";
import type { SaveProfileRequest } from "#/api/profiles-service/profiles-service.api";
import type { ProviderConnection } from "#/api/provider-connections-service/provider-connections-service.api";
import { mapProvider } from "#/utils/map-provider";
import { deriveProfileNameFromModel } from "#/utils/derive-profile-name";
import {
  displayErrorToast,
  displaySuccessToast,
} from "#/utils/custom-toast-handlers";
import { I18nKey } from "#/i18n/declaration";
import { isSdkHttpStatusError } from "#/api/agent-server-compatibility";
/** Pull the server's own explanation out of an error, when it sent one. */
function getServerDetail(error: unknown): string | null {
  const detail = (error as { response?: { detail?: unknown } })?.response
    ?.detail;
  return typeof detail === "string" && detail.trim() ? detail : null;
}

interface AddModelsModalProps {
  isOpen: boolean;
  existingNames: string[];
  /**
   * Provider connections the user can bulk-add from. When the selected
   * provider has a matching connection, the modal binds it (created profiles
   * inherit the connection's credential). When it does not — or the user
   * chooses "No connection" — profiles are created keyless, preserving the
   * pre-connection bulk-add behavior.
   */
  connections: ProviderConnection[];
  /**
   * A connection id to preselect when the modal opens (launched from a
   * connection row's "…"). Omit/leave null for the chooser entry point
   * (the top "Add from provider connections" button), where the user picks a
   * provider. In preselect mode the provider combobox opens on that
   * connection's provider, the connection is bound, and its models load
   * already selected.
   */
  initialConnectionId?: string | null;
  onClose: () => void;
}

type RowStatus = "idle" | "saving" | "saved" | "failed";

interface ModelRow {
  /** Full model id, e.g. "openhands/deepseek-v4-flash". */
  model: string;
  /** Derived profile name (not user-editable). */
  name: string;
  selected: boolean;
  status: RowStatus;
}

/** Sentinel for the "no connection" (keyless) option in the connection box. */
const KEYLESS_CONNECTION_VALUE = "";

function filterModelsByConnectionAvailability(
  models: NonNullable<ReturnType<typeof useProviderModels>["data"]>,
  availableModels: string[] | undefined,
  provider: string | null,
) {
  if (!availableModels) return models;

  const available = new Set(availableModels);
  return models.filter((model) => {
    const fullName =
      model.provider && !model.name.startsWith(`${model.provider}/`)
        ? `${model.provider}/${model.name}`
        : model.name;
    const providerName = provider ?? model.provider;
    const bareName =
      providerName && fullName.startsWith(`${providerName}/`)
        ? fullName.slice(providerName.length + 1)
        : model.name;
    return available.has(fullName) || available.has(bareName);
  });
}

/**
 * Bulk-add models as LLM profiles. One modal serves two entry points: the top
 * "Add from provider connections" button (chooser mode — pick a provider) and
 * a connection row's "…" (preselect mode — opens on that connection's
 * provider with the connection bound and models already selected).
 *
 * The selected provider drives the model list. When a matching provider
 * connection exists it is bound by default, so created profiles inherit the
 * connection's shared credential via `provider_connection_id` (mirroring the
 * link flow in `llm-settings-local-view.tsx`) and no key needs to be added
 * afterward. When no connection matches — or the user chooses "No connection"
 * — `provider_connection_id` is null and profiles are created keyless, the
 * same behavior bulk-add had before provider connections existed.
 */
export function AddModelsModal({
  isOpen,
  existingNames,
  connections,
  initialConnectionId = null,
  onClose,
}: AddModelsModalProps) {
  const { t } = useTranslation("openhands");
  const [selectedProvider, setSelectedProvider] = useState<string | null>(null);
  const [selectedConnectionId, setSelectedConnectionId] = useState<
    string | null
  >(null);
  const [rows, setRows] = useState<ModelRow[]>([]);
  const [submitting, setSubmitting] = useState(false);

  const { data: providers } = useSearchProviders();
  const models = useProviderModels(selectedProvider);
  const saveProfile = useSaveLlmProfile();

  // Connections whose provider matches the selected provider. These are the
  // only ones the connection box offers: a connection is only usable as a
  // credential source for its own provider's models.
  const matchingConnections = useMemo(
    () =>
      selectedProvider
        ? connections.filter((c) => c.provider === selectedProvider)
        : [],
    [connections, selectedProvider],
  );

  // The bound connection id drives the submit payload. Null means keyless.
  const connectionId = useMemo(() => {
    if (!selectedConnectionId) return null;
    return matchingConnections.some((c) => c.id === selectedConnectionId)
      ? selectedConnectionId
      : null;
  }, [matchingConnections, selectedConnectionId]);

  const selectedConnection = useMemo(
    () =>
      matchingConnections.find((connection) => connection.id === connectionId),
    [connectionId, matchingConnections],
  );
  const availableModels = useMemo(
    () =>
      filterModelsByConnectionAvailability(
        models.data ?? [],
        selectedConnection?.available_models,
        selectedProvider,
      ),
    [models.data, selectedConnection?.available_models, selectedProvider],
  );

  // Rows follow the model list, and only the model list. Already-added models
  // are hidden at render rather than rebuilding the rows, because a rebuild
  // discards the selections and per-row statuses the user has accumulated. A
  // row already on screen keeps its state when the list refreshes.
  // `autoSelectRef` is set when the modal opens from a connection row ("…"):
  // that entry point is an explicit intent to bulk-add from that connection,
  // so the loaded rows are selected for the user instead of forcing per-row
  // clicking. It fires once per open (on the first model list that arrives)
  // and is cleared, so a later connection change in the combobox does not
  // re-select rows the user has already curated.
  const autoSelectRef = useRef(false);
  useEffect(() => {
    const items = availableModels;
    const selectNew = autoSelectRef.current;
    setRows((prev) => {
      const prior = new Map(prev.map((row) => [row.model, row]));
      // Dedupe by canonical model id: a provider's catalog can list the same
      // model twice (e.g. once in the verified set and once in the raw list
      // when the two disagree on prefixing). Without dedup each copy becomes
      // its own row with the same derived name, and the two flag each other as
      // conflicts — surfacing bogus "Name already exists" on a fresh account.
      const seen = new Set<string>();
      const built: ModelRow[] = [];
      for (const m of items) {
        const full =
          m.provider && !m.name.startsWith(`${m.provider}/`)
            ? `${m.provider}/${m.name}`
            : m.name;
        if (seen.has(full)) continue;
        seen.add(full);
        const carried = prior.get(full);
        built.push(
          carried
            ? carried
            : {
                model: full,
                name: deriveProfileNameFromModel(full),
                // Chooser mode leaves rows unselected: the server caps how
                // many profiles an account may hold, so defaulting to "all"
                // invites a submission that is mostly refusals. Preselect mode
                // (autoSelectRef) selects them — see the comment above.
                selected: selectNew,
                status: "idle" as RowStatus,
              },
        );
      }
      return built;
    });
    if (items.length > 0) autoSelectRef.current = false;
  }, [availableModels]);

  // The manager keeps this component mounted and drives it with `isOpen`, so
  // without an explicit reset a reopened modal still shows the last session's
  // provider, connection, selections, and Saved/Failed marks. On open, seed
  // the provider/connection from `initialConnectionId` (preselect mode) or
  // leave both unset (chooser mode). On close, clear everything.
  useEffect(() => {
    if (isOpen) {
      const initial =
        initialConnectionId &&
        connections.find((c) => c.id === initialConnectionId);
      if (initial) {
        setSelectedProvider(initial.provider);
        setSelectedConnectionId(initial.id);
        autoSelectRef.current = true;
      } else {
        setSelectedProvider(null);
        setSelectedConnectionId(null);
      }
    } else {
      // Clear the provider/connection too, not just the rows. The modal stays
      // mounted between openings, and `useProviderModels` serves a cached
      // `models.data` for the same provider — so if `selectedProvider` is left
      // set, reopening in preselect mode reseeds the same provider string, the
      // cached list reference is unchanged, and the `[models.data]` effect
      // never re-runs to rebuild `rows`. Resetting to null makes that effect
      // see undefined -> cached-list on reopen, so the model list reloads.
      setSelectedProvider(null);
      setSelectedConnectionId(null);
      setRows([]);
      setSubmitting(false);
      autoSelectRef.current = false;
    }
  }, [isOpen, initialConnectionId, connections]);

  const existing = useMemo(() => new Set(existingNames), [existingNames]);

  if (!isOpen) return null;

  // Already-added models are hidden, not disabled: a row whose name matches an
  // existing profile can't be re-created, so showing it (flagged or greyed)
  // just clutters the list. A saved row is exempt — it was added from this
  // very session, so it stays visible with its "Saved" mark.
  const visibleRows = rows.filter(
    (row) => row.status === "saved" || !existing.has(row.name),
  );

  // Saved rows stay visible (so the user sees the "Saved" mark) but are not
  // selectable: a saved row is finished work, so it must not count toward the
  // footer's "Add N", drive select-all, or be re-POSTed on a retry. Without
  // this exclusion a partial submit leaves the saved rows selected, and a
  // second Submit re-creates them — the create now 409s (the name exists) and
  // is reported as a fresh failure for work that already succeeded.
  const selectable = visibleRows.filter((row) => row.status !== "saved");
  const selectedRows = selectable.filter((row) => row.selected);

  const setRow = (model: string, patch: Partial<ModelRow>) =>
    setRows((prev) =>
      prev.map((row) => (row.model === model ? { ...row, ...patch } : row)),
    );

  const allSelected =
    selectable.length > 0 && selectedRows.length === selectable.length;

  const toggleAll = () => {
    const next = !allSelected;
    const reachable = new Set(selectable.map((row) => row.model));
    setRows((prev) =>
      prev.map((row) =>
        reachable.has(row.model) ? { ...row, selected: next } : row,
      ),
    );
  };

  // When the user picks a provider, bind a matching connection by default so
  // created profiles are usable out of the box (this modal's reason for
  // existing). If there is no matching connection, leave it keyless. The user
  // can still switch the connection box to "No connection" to opt out.
  const handleProviderChange = (value: string) => {
    setSelectedProvider(value || null);
    const first = connections.find((c) => c.provider === value);
    setSelectedConnectionId(first?.id ?? null);
  };

  const handleSubmit = async () => {
    setSubmitting(true);
    const targets = selectedRows;
    for (const row of targets) setRow(row.model, { status: "saving" });

    // Sequential, not a parallel fan-out: the server enforces a profile limit,
    // and firing every create at once turns one refusal into a wall of
    // identical failures.
    //
    // A 409 is ambiguous. It means the profile ceiling, which every remaining
    // create would hit too — or a name taken since this list loaded, which
    // says nothing about the rows behind it. Stopping on the first one halts
    // a run that would have succeeded; ignoring it spends the whole selection
    // against a wall. So one 409 fails its own row and the run continues, and
    // a second confirms the wall at a cost of exactly one extra request.
    let added = 0;
    let failed = 0;
    let conflicts = 0;
    let blocked = false;
    let blockedReason: string | null = null;

    for (const [i, row] of targets.entries()) {
      try {
        await saveProfile.mutateAsync({
          name: row.name,
          request: {
            // A bound connection sources the credential, so it replaces any
            // inline api_key/base_url — mirrored on the normal save flow in
            // `llm-settings-local-view.tsx`. `include_secrets: false` because
            // no secret is being sent; the link is by id. When no connection
            // is bound (`connectionId` is null) the profile is keyless, the
            // same as bulk-add before provider connections existed.
            llm: {
              model: row.model,
              provider_connection_id: connectionId,
            } as SaveProfileRequest["llm"],
            include_secrets: false,
          },
        });
        setRow(row.model, { status: "saved" });
        added += 1;
      } catch (error) {
        // Surface the server's reason — a silent "failed" row is undebuggable.
        console.error(`profile create failed for ${row.model}:`, error);
        setRow(row.model, { status: "failed" });
        failed += 1;
        if (isSdkHttpStatusError(error, 409)) {
          conflicts += 1;
          if (conflicts >= 2) {
            blocked = true;
            // Read the reason off the refusal that actually stopped the run.
            // Carrying an earlier 409's detail forward would report a raced
            // duplicate name as the cause of a halt it had nothing to do with.
            blockedReason = getServerDetail(error);
            // Rows past this one were marked "saving" up front and are now
            // never attempted; leave them idle rather than spinning forever.
            for (const skipped of targets.slice(i + 1)) {
              setRow(skipped.model, { status: "idle" });
            }
            break;
          }
        }
      }
    }

    setSubmitting(false);
    if (blocked) {
      // Quote the server when it explained itself. When it did not, say so
      // plainly: the partial-count wording below counts only the rows that
      // were attempted, so it reads as a smaller failure than it was.
      displayErrorToast(
        blockedReason ??
          t(I18nKey.SETTINGS$MODELS_ADD_BLOCKED, { added: String(added) }),
      );
    } else if (failed === 0) {
      displaySuccessToast(
        t(I18nKey.SETTINGS$MODELS_ADDED, { count: String(added) }),
      );
      onClose();
    } else {
      displayErrorToast(
        t(I18nKey.SETTINGS$MODELS_ADDED_PARTIAL, {
          added: String(added),
          failed: String(failed),
        }),
      );
    }
  };

  const handleClose = () => {
    if (!submitting) onClose();
  };

  const isLoadingModels = selectedProvider !== null && models.isLoading;
  // Only flag "empty" once a provider is chosen and its (non-loading) model
  // list came back bare. In chooser mode with nothing picked yet, the
  // provider box is the prompt — there's no list to call empty.
  const showEmpty =
    selectedProvider !== null && !isLoadingModels && visibleRows.length === 0;
  const emptyMessage = I18nKey.SETTINGS$ADD_MODELS_EMPTY;

  const footer = (
    <>
      <BrandButton
        type="button"
        variant="tertiary"
        onClick={handleClose}
        isDisabled={submitting}
      >
        {t(I18nKey.BUTTON$CANCEL)}
      </BrandButton>
      <BrandButton
        testId="add-models-submit"
        type="button"
        variant="primary"
        onClick={handleSubmit}
        isDisabled={submitting || selectedRows.length === 0}
      >
        {submitting ? (
          <LoadingSpinner size="small" />
        ) : (
          t(I18nKey.SETTINGS$ADD_N_PROFILES, {
            count: String(selectedRows.length),
          })
        )}
      </BrandButton>
    </>
  );

  return (
    <ApiKeyModalBase
      isOpen
      title={t(I18nKey.SETTINGS$ADD_MODELS_TITLE)}
      footer={footer}
      onClose={handleClose}
    >
      <div data-testid="add-models-modal" className="flex flex-col gap-3">
        <label
          className="flex flex-col gap-2 text-sm text-white"
          data-testid="add-models-provider-field"
        >
          {t(I18nKey.SETTINGS$ADD_MODELS_PROVIDER_LABEL)}
          <select
            data-testid="add-models-provider"
            className="rounded-md border border-[var(--oh-border)] bg-[var(--oh-background)] px-3 py-2 text-sm text-white"
            value={selectedProvider ?? ""}
            onChange={(e) => handleProviderChange(e.target.value)}
            disabled={submitting}
          >
            <option value="" disabled>
              {t(I18nKey.SETTINGS$ADD_MODELS_PROVIDER_PLACEHOLDER)}
            </option>
            {providers?.map((p) => (
              <option key={p.name} value={p.name}>
                {mapProvider(p.name)}
              </option>
            ))}
          </select>
        </label>

        {/* Only offer a connection binding when the selected provider has a
            matching connection. With none, the run is keyless and there is
            nothing to choose, so the box is omitted rather than showing a
            lone "No connection" option. */}
        {matchingConnections.length > 0 && (
          <label
            className="flex flex-col gap-2 text-sm text-white"
            data-testid="add-models-connection-field"
          >
            {t(I18nKey.SETTINGS$ADD_MODELS_CONNECTION_LABEL)}
            <select
              data-testid="add-models-connection"
              className="rounded-md border border-[var(--oh-border)] bg-[var(--oh-background)] px-3 py-2 text-sm text-white"
              value={selectedConnectionId ?? KEYLESS_CONNECTION_VALUE}
              onChange={(e) => setSelectedConnectionId(e.target.value || null)}
              disabled={submitting}
            >
              <option value={KEYLESS_CONNECTION_VALUE}>
                {t(I18nKey.SETTINGS$ADD_MODELS_NO_CONNECTION)}
              </option>
              {matchingConnections.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.display_name}
                </option>
              ))}
            </select>
          </label>
        )}

        {selectedProvider && connectionId && (
          <span className="min-w-0 max-w-full truncate text-xs text-[var(--oh-muted)]">
            {t(I18nKey.SETTINGS$ADD_MODELS_CONNECTION_BOUND, {
              provider: selectedProvider,
            })}
          </span>
        )}
        {selectedProvider && !connectionId && (
          <span
            data-testid="add-models-keyless-note"
            className="min-w-0 max-w-full truncate text-xs text-[var(--oh-muted)]"
          >
            {t(I18nKey.SETTINGS$ADD_MODELS_KEYLESS_NOTE)}
          </span>
        )}

        {isLoadingModels && (
          <div data-testid="add-models-loading" className="py-4 text-center">
            <LoadingSpinner size="small" />
          </div>
        )}

        {showEmpty && (
          <p
            data-testid="add-models-empty"
            className="text-sm text-[var(--oh-muted)]"
          >
            {t(emptyMessage)}
          </p>
        )}

        {visibleRows.length > 0 && (
          <>
            <label className="flex items-center gap-2 text-sm text-white">
              <input
                data-testid="add-models-select-all"
                type="checkbox"
                checked={allSelected}
                onChange={toggleAll}
                disabled={submitting || selectable.length === 0}
              />
              {t(I18nKey.SETTINGS$ADD_MODELS_SELECT_ALL)}
            </label>
            <ul className="flex max-h-64 flex-col gap-2 overflow-y-auto">
              {visibleRows.map((row) => {
                const disabled = submitting || row.status === "saved";
                // Show the model name without the provider prefix — the
                // prefix is implied by the selected connection and just adds
                // visual noise to every row.
                const shortName = row.model.split("/").pop() ?? row.model;
                return (
                  <li
                    key={row.model}
                    data-testid={`add-models-row-${row.model}`}
                    className="flex items-center gap-2"
                  >
                    <input
                      data-testid={`add-models-check-${row.model}`}
                      type="checkbox"
                      checked={row.selected}
                      onChange={(e) =>
                        setRow(row.model, { selected: e.target.checked })
                      }
                      disabled={disabled}
                    />
                    <span
                      className="min-w-0 flex-1 truncate text-sm text-white"
                      title={row.model}
                    >
                      {shortName}
                    </span>
                    {row.status === "saving" && <LoadingSpinner size="small" />}
                    {row.status === "saved" && (
                      <span className="text-xs text-green-400">
                        {t(I18nKey.SETTINGS$MODEL_ROW_SAVED)}
                      </span>
                    )}
                    {row.status === "failed" && (
                      <span className="text-xs text-red-400">
                        {t(I18nKey.SETTINGS$MODEL_ROW_FAILED)}
                      </span>
                    )}
                  </li>
                );
              })}
            </ul>
          </>
        )}
      </div>
    </ApiKeyModalBase>
  );
}

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useCallback,
  useState,
} from "react";
import ReactDOM from "react-dom";
import { useTranslation } from "react-i18next";
import { TextCursor, Copy } from "lucide-react";
import { cn } from "#/utils/utils";
import { dropdownMenuListClassName } from "#/utils/dropdown-classes";
import { I18nKey } from "#/i18n/declaration";
import EditIcon from "#/icons/u-edit.svg?react";
import CheckCircleIcon from "#/icons/u-check-circle.svg?react";
import DeleteIcon from "#/icons/u-delete.svg?react";
import { MenuItem } from "./profile-actions-menu-item";

interface ProfileActionsMenuProps {
  onEdit: () => void;
  onRename: () => void;
  onDuplicate: () => void;
  onSetActive: () => void;
  onDelete: () => void;
  isActive: boolean;
  isActivating: boolean;
  onClose: () => void;
  /**
   * Element the menu should anchor against. When provided, the menu renders
   * into a portal at the document body using fixed positioning so it cannot be
   * clipped by ancestors with `overflow: auto/hidden` (e.g. the settings
   * `<main>` scroll container).
   */
  anchorRef?: React.RefObject<HTMLElement | null>;
}

// A natively disabled button ignores focus(), so keyboard navigation has to
// skip it rather than stop on it.
const getEnabledItems = (items: (HTMLButtonElement | null)[]) =>
  items.filter((item): item is HTMLButtonElement =>
    Boolean(item && !item.disabled),
  );

export function ProfileActionsMenu({
  onEdit,
  onRename,
  onDuplicate,
  onSetActive,
  onDelete,
  isActive,
  isActivating,
  onClose,
  anchorRef,
}: ProfileActionsMenuProps) {
  const { t } = useTranslation("openhands");
  const menuRef = useRef<HTMLDivElement>(null);
  const menuItemsRef = useRef<(HTMLButtonElement | null)[]>([]);

  const anchorElement = anchorRef?.current ?? null;
  const [portalStyle, setPortalStyle] = useState<React.CSSProperties>();

  useLayoutEffect(() => {
    if (!anchorElement) return undefined;

    const updatePosition = () => {
      const rect = anchorElement.getBoundingClientRect();
      if (!rect) return;
      const gap = 8;
      setPortalStyle({
        position: "fixed",
        zIndex: 9999,
        top: rect.bottom + gap,
        right: window.innerWidth - rect.right,
        width: "max-content",
      });
    };

    updatePosition();
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [anchorElement]);

  // The anchored menu renders nothing until its position is measured, so wait
  // for the items to exist before focusing the first enabled one.
  const isMenuRendered = !anchorElement || portalStyle !== undefined;
  useEffect(() => {
    if (isMenuRendered) getEnabledItems(menuItemsRef.current)[0]?.focus();
  }, [isMenuRendered]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node;
      if (menuRef.current?.contains(target)) return;
      if (anchorElement?.contains(target)) return;
      onClose();
    };

    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        if (menuRef.current?.contains(document.activeElement)) {
          anchorElement?.focus();
        }
        onClose();
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("keydown", handleEscape);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("keydown", handleEscape);
    };
  }, [anchorElement, onClose]);

  const handleAction = (action: () => void) => {
    action();
    onClose();
  };

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent, currentIndex: number) => {
      if (e.key === "Tab") {
        // The anchored menu is portaled to the end of <body>; move focus back
        // to its trigger so Tab continues from the row, not the page end.
        anchorElement?.focus();
        onClose();
        return;
      }
      if (e.key !== "ArrowDown" && e.key !== "ArrowUp") return;
      e.preventDefault();
      const enabledItems = getEnabledItems(menuItemsRef.current);
      const position = enabledItems.findIndex(
        (item) => item === menuItemsRef.current[currentIndex],
      );
      const step = e.key === "ArrowDown" ? 1 : -1;
      const target =
        (position + step + enabledItems.length) % enabledItems.length;
      enabledItems[target]?.focus();
    },
    [anchorElement, onClose],
  );

  const setActiveDisabled = isActive || isActivating;
  const isPortaled = Boolean(anchorElement);

  const menu = (
    <div
      ref={menuRef}
      className={cn(
        "absolute right-0 top-full z-10 mt-2 w-40 rounded-md border border-border-subtle bg-tertiary px-1 py-1 shadow-lg",
        dropdownMenuListClassName,
        isPortaled &&
          "!static !top-auto !bottom-auto !left-auto !right-auto !mt-0",
      )}
      role="menu"
      aria-orientation="vertical"
      data-testid="profile-actions-menu"
    >
      <MenuItem
        index={0}
        icon={<EditIcon width={16} height={16} />}
        label={t(I18nKey.SETTINGS$PROFILE_EDIT)}
        onClick={() => handleAction(onEdit)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        testId="profile-edit"
      />
      <MenuItem
        index={1}
        icon={<TextCursor aria-hidden className="size-4" strokeWidth={2} />}
        label={t(I18nKey.BUTTON$RENAME)}
        onClick={() => handleAction(onRename)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        testId="profile-rename"
      />
      <MenuItem
        index={2}
        icon={<Copy aria-hidden className="size-4" strokeWidth={2} />}
        label={t(I18nKey.BUTTON$DUPLICATE)}
        onClick={() => handleAction(onDuplicate)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        testId="profile-duplicate"
      />
      <MenuItem
        index={3}
        icon={<CheckCircleIcon width={16} height={16} />}
        label={t(I18nKey.SETTINGS$PROFILE_SET_DEFAULT)}
        onClick={() => handleAction(onSetActive)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        disabled={setActiveDisabled}
        testId="profile-set-active"
      />
      {/* The active profile can be deleted: useEnsureActiveProfile then promotes
          another remaining profile so a profile is always active in local mode. */}
      <MenuItem
        index={4}
        icon={<DeleteIcon width={16} height={16} />}
        label={t(I18nKey.BUTTON$DELETE)}
        onClick={() => handleAction(onDelete)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        testId="profile-delete"
      />
    </div>
  );

  if (isPortaled) {
    if (typeof document === "undefined" || !portalStyle) {
      return null;
    }
    return ReactDOM.createPortal(
      // portal position computed from DOM bounding rect at runtime
      <div style={portalStyle}>{menu}</div>,
      document.body,
    );
  }

  return menu;
}

import { useTranslation } from "react-i18next";
import { LoadingSpinner } from "#/components/shared/loading-spinner";
import { ProfileRow } from "./profile-row";
import { ProfileInfo } from "#/api/profiles-service/profiles-service.api";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import {
  settingsListContainerClassName,
  settingsListDividerClassName,
} from "#/utils/settings-list-classes";
import { extensionModuleEmptyStateClassName } from "#/utils/extension-module-card-classes";

interface ProfilesBodyProps {
  isLoading: boolean;
  loadError: Error | null;
  profiles: ProfileInfo[];
  active: string | null;
  /** When false, rows render read-only (no actions menu) — cloud members. */
  canManage: boolean;
  /**
   * Display name per provider-connection id. When non-empty, profiles are
   * grouped under their connection's name so models sharing a provider are
   * visually clustered. Empty (the default, e.g. a cloud backend with no org
   * bound) renders a flat list identical to before.
   */
  connectionNamesById?: Record<string, string>;
  onActivate: (name: string) => void;
  onEdit: (profile: ProfileInfo) => void;
  onRename: (profile: ProfileInfo) => void;
  onDuplicate: (profile: ProfileInfo) => void;
  onDelete: (profile: ProfileInfo) => void;
  isActivating: boolean;
  isModelUnlisted?: (model: string | null | undefined) => boolean;
}

interface ProfileGroup {
  /** Connection id, or null for profiles with no provider connection. */
  connectionId: string | null;
  label: string | null;
  profiles: ProfileInfo[];
}

/**
 * Bucket profiles by their `provider_connection_id`, preserving input order
 * within each group and ordering groups by first appearance. Unlinked profiles
 * collect under a trailing `null` group.
 */
export function groupProfilesByConnection(
  profiles: ProfileInfo[],
  connectionNamesById: Record<string, string>,
): ProfileGroup[] {
  const groups = new Map<string, ProfileGroup>();
  const unlinked: ProfileGroup = {
    connectionId: null,
    label: null,
    profiles: [],
  };

  for (const profile of profiles) {
    const connectionId = profile.provider_connection_id ?? null;
    if (!connectionId) {
      unlinked.profiles.push(profile);
      continue;
    }
    let group = groups.get(connectionId);
    if (!group) {
      group = {
        connectionId,
        label: connectionNamesById[connectionId] ?? connectionId,
        profiles: [],
      };
      groups.set(connectionId, group);
    }
    group.profiles.push(profile);
  }

  const linkedGroups = [...groups.values()];
  return unlinked.profiles.length > 0
    ? [...linkedGroups, unlinked]
    : linkedGroups;
}

export function ProfilesBody({
  isLoading,
  loadError,
  profiles,
  active,
  canManage,
  connectionNamesById = {},
  onActivate,
  onEdit,
  onRename,
  onDuplicate,
  onDelete,
  isActivating,
  isModelUnlisted,
}: ProfilesBodyProps) {
  const { t } = useTranslation("openhands");

  const renderRow = (profile: ProfileInfo) => (
    <ProfileRow
      key={profile.name}
      profile={profile}
      isActive={profile.name === active}
      canManage={canManage}
      onActivate={onActivate}
      onEdit={onEdit}
      onRename={onRename}
      onDuplicate={onDuplicate}
      onDelete={onDelete}
      isActivating={isActivating}
      isModelUnlisted={isModelUnlisted?.(profile.model)}
    />
  );

  const listClassName = cn(
    settingsListContainerClassName,
    settingsListDividerClassName,
  );

  if (isLoading) {
    return (
      <div className="flex justify-center p-4">
        <LoadingSpinner size="large" />
      </div>
    );
  }

  if (loadError) {
    return (
      <div
        data-testid="profiles-load-error"
        className={extensionModuleEmptyStateClassName}
      >
        <p className="text-sm text-red-400">
          {t(I18nKey.SETTINGS$PROFILES_LOAD_ERROR)}
        </p>
      </div>
    );
  }

  if (profiles.length === 0) {
    return (
      <div
        data-testid="profiles-empty"
        className={extensionModuleEmptyStateClassName}
      >
        <p className="text-sm text-muted">
          {t(I18nKey.SETTINGS$PROFILES_EMPTY)}
        </p>
      </div>
    );
  }

  // Group only when there is at least one linked connection to show; otherwise
  // (no profile links to a connection) render the flat list unchanged.
  const hasLinkedProfiles = profiles.some((p) => p.provider_connection_id);
  if (!hasLinkedProfiles) {
    return <div className={listClassName}>{profiles.map(renderRow)}</div>;
  }

  const groups = groupProfilesByConnection(profiles, connectionNamesById);
  return (
    <div className="flex flex-col gap-4">
      {groups.map((group) => (
        <div
          key={group.connectionId ?? "__unlinked__"}
          className="flex flex-col gap-2"
        >
          <h3
            data-testid="profile-group-header"
            className="text-xs font-medium uppercase tracking-wide text-muted"
          >
            {group.label ?? t(I18nKey.SETTINGS$PROFILES_UNGROUPED)}
          </h3>
          <div className={listClassName}>{group.profiles.map(renderRow)}</div>
        </div>
      ))}
    </div>
  );
}

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useCallback,
  useState,
} from "react";
import ReactDOM from "react-dom";
import { useTranslation } from "react-i18next";
import { cn } from "#/utils/utils";
import { dropdownMenuListClassName } from "#/utils/dropdown-classes";
import { I18nKey } from "#/i18n/declaration";
import EditIcon from "#/icons/u-edit.svg?react";
import DeleteIcon from "#/icons/u-delete.svg?react";
import AddModelsIcon from "#/icons/u-plus.svg?react";
import { MenuItem } from "./profile-actions-menu-item";

interface ProviderConnectionActionsMenuProps {
  onAddModels: () => void;
  onEdit: () => void;
  onDelete: () => void;
  onClose: () => void;
  /**
   * Element the menu should anchor against. When provided, the menu renders
   * into a portal at the document body using fixed positioning so it cannot be
   * clipped by ancestors with `overflow: auto/hidden` (e.g. the settings
   * `<main>` scroll container).
   */
  anchorRef?: React.RefObject<HTMLElement | null>;
}

export function ProviderConnectionActionsMenu({
  onAddModels,
  onEdit,
  onDelete,
  onClose,
  anchorRef,
}: ProviderConnectionActionsMenuProps) {
  const { t } = useTranslation("openhands");
  const menuRef = useRef<HTMLDivElement>(null);
  const menuItemsRef = useRef<(HTMLButtonElement | null)[]>([]);

  const anchorElement = anchorRef?.current ?? null;
  const [portalStyle, setPortalStyle] = useState<React.CSSProperties>();

  useLayoutEffect(() => {
    if (!anchorElement) return undefined;

    const updatePosition = () => {
      const rect = anchorElement.getBoundingClientRect();
      if (!rect) return;
      const gap = 8;
      setPortalStyle({
        position: "fixed",
        zIndex: 9999,
        top: rect.bottom + gap,
        right: window.innerWidth - rect.right,
        width: "max-content",
      });
    };

    updatePosition();
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [anchorElement]);

  useEffect(() => {
    menuItemsRef.current[0]?.focus();
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node;
      if (menuRef.current?.contains(target)) return;
      if (anchorElement?.contains(target)) return;
      onClose();
    };

    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        onClose();
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("keydown", handleEscape);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("keydown", handleEscape);
    };
  }, [anchorElement, onClose]);

  const handleAction = (action: () => void) => {
    action();
    onClose();
  };

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent, currentIndex: number) => {
      if (e.key === "Tab") {
        onClose();
        return;
      }
      const itemCount = menuItemsRef.current.filter(Boolean).length;
      if (e.key === "ArrowDown") {
        e.preventDefault();
        const nextIndex = (currentIndex + 1) % itemCount;
        menuItemsRef.current[nextIndex]?.focus();
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        const prevIndex = (currentIndex - 1 + itemCount) % itemCount;
        menuItemsRef.current[prevIndex]?.focus();
      }
    },
    [onClose],
  );

  const isPortaled = Boolean(anchorElement);

  const menu = (
    <div
      ref={menuRef}
      className={cn(
        "absolute right-0 top-full z-10 mt-2 w-40 rounded-md border border-border-subtle bg-tertiary px-1 py-1 shadow-lg",
        dropdownMenuListClassName,
        isPortaled &&
          "!static !top-auto !bottom-auto !left-auto !right-auto !mt-0",
      )}
      role="menu"
      aria-orientation="vertical"
      data-testid="provider-connection-actions-menu"
    >
      <MenuItem
        index={0}
        icon={<AddModelsIcon width={16} height={16} />}
        label={t(I18nKey.SETTINGS$PROVIDER_CONNECTION_BULK_ADD)}
        onClick={() => handleAction(onAddModels)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        testId="provider-connection-add-models"
      />
      <MenuItem
        index={1}
        icon={<EditIcon width={16} height={16} />}
        label={t(I18nKey.BUTTON$EDIT)}
        onClick={() => handleAction(onEdit)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        testId="provider-connection-edit"
      />
      <MenuItem
        index={2}
        icon={<DeleteIcon width={16} height={16} />}
        label={t(I18nKey.BUTTON$DELETE)}
        onClick={() => handleAction(onDelete)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        testId="provider-connection-delete"
      />
    </div>
  );

  if (isPortaled) {
    if (typeof document === "undefined" || !portalStyle) {
      return null;
    }
    return ReactDOM.createPortal(
      // portal position computed from DOM bounding rect at runtime
      <div style={portalStyle}>{menu}</div>,
      document.body,
    );
  }

  return menu;
}

import { useState } from "react";
import { useTranslation } from "react-i18next";
import { BrandButton } from "#/components/features/settings/brand-button";
import { ProviderConnectionRow } from "./provider-connection-row";
import { ProviderConnectionModal } from "./provider-connection-modal";
import { DeleteProviderConnectionModal } from "./delete-provider-connection-modal";
import type { ProviderConnection } from "#/api/provider-connections-service/provider-connections-service.api";
import { cn } from "#/utils/utils";
import {
  settingsListContainerClassName,
  settingsListDividerClassName,
} from "#/utils/settings-list-classes";
import { extensionModuleEmptyStateClassName } from "#/utils/extension-module-card-classes";
import { I18nKey } from "#/i18n/declaration";

interface ProviderConnectionsManagerProps {
  connections: ProviderConnection[];
  /** Number of LLM profiles linked to each connection id. */
  linkedCountById: Record<string, number>;
  isLoading: boolean;
  loadError: Error | null;
  /**
   * Called when a connection's "..." bulk-add action is clicked. The parent
   * owns the single shared AddModelsModal and opens it preselected to this
   * connection, so there is one modal for both entry points.
   */
  onAddModels: (connection: ProviderConnection) => void;
}

/**
 * Manages shared provider connections: a shared API key + optional base URL
 * that LLM profiles reference by id. Rendered only for the local agent-server,
 * which is the only backend exposing the endpoints. Each connection row carries
 * its own "add models" action that bulk-creates profiles linked to it.
 */
export function ProviderConnectionsManager({
  connections,
  linkedCountById,
  isLoading,
  loadError,
  onAddModels,
}: ProviderConnectionsManagerProps) {
  const { t } = useTranslation("openhands");
  const [isCreating, setIsCreating] = useState(false);
  const [connectionToEdit, setConnectionToEdit] =
    useState<ProviderConnection | null>(null);
  const [connectionToDelete, setConnectionToDelete] =
    useState<ProviderConnection | null>(null);

  const renderBody = () => {
    if (isLoading) return null;

    if (loadError) {
      return (
        <div
          data-testid="provider-connections-load-error"
          className={extensionModuleEmptyStateClassName}
        >
          <p className="text-sm text-red-400">
            {t(I18nKey.SETTINGS$PROVIDER_CONNECTIONS_LOAD_ERROR)}
          </p>
        </div>
      );
    }

    if (connections.length === 0) {
      return (
        <div
          data-testid="provider-connections-empty"
          className={extensionModuleEmptyStateClassName}
        >
          <p className="text-sm text-muted">
            {t(I18nKey.SETTINGS$PROVIDER_CONNECTIONS_EMPTY)}
          </p>
        </div>
      );
    }

    return (
      <div
        className={cn(
          settingsListContainerClassName,
          settingsListDividerClassName,
        )}
      >
        {connections.map((connection) => (
          <ProviderConnectionRow
            key={connection.id}
            connection={connection}
            linkedProfileCount={linkedCountById[connection.id] ?? 0}
            onAddModels={onAddModels}
            onEdit={setConnectionToEdit}
            onDelete={setConnectionToDelete}
          />
        ))}
      </div>
    );
  };

  return (
    <>
      <div className="flex flex-col gap-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex flex-col gap-1">
            <h2 className="text-base font-medium text-contrast">
              {t(I18nKey.SETTINGS$PROVIDER_CONNECTIONS_TITLE)}
            </h2>
            <p className="text-sm text-muted">
              {t(I18nKey.SETTINGS$PROVIDER_CONNECTIONS_SUBLINE)}
            </p>
          </div>
          <BrandButton
            testId="add-provider-connection"
            type="button"
            variant="secondary"
            className="ml-auto"
            onClick={() => setIsCreating(true)}
          >
            {t(I18nKey.SETTINGS$PROVIDER_CONNECTION_ADD)}
          </BrandButton>
        </div>

        {renderBody()}
      </div>

      {isCreating && (
        <ProviderConnectionModal
          isCreate
          onClose={() => setIsCreating(false)}
        />
      )}
      <ProviderConnectionModal
        isCreate={false}
        connection={connectionToEdit}
        onClose={() => setConnectionToEdit(null)}
      />
      <DeleteProviderConnectionModal
        connection={connectionToDelete}
        onClose={() => setConnectionToDelete(null)}
      />
    </>
  );
}

