import {
  useEffect,
  useLayoutEffect,
  useRef,
  useCallback,
  useState,
} from "react";
import ReactDOM from "react-dom";
import { useTranslation } from "react-i18next";
import { cn } from "#/utils/utils";
import { dropdownMenuListClassName } from "#/utils/dropdown-classes";
import { I18nKey } from "#/i18n/declaration";
import { ConversationNameContextMenuIconText } from "#/components/features/conversation/conversation-name-context-menu-icon-text";
import EditIcon from "#/icons/u-edit.svg?react";
import CheckCircleIcon from "#/icons/u-check-circle.svg?react";
import DeleteIcon from "#/icons/u-delete.svg?react";

interface MenuItemProps {
  index: number;
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  onKeyDown: (e: React.KeyboardEvent, index: number) => void;
  menuItemsRef: React.MutableRefObject<(HTMLButtonElement | null)[]>;
  disabled?: boolean;
  testId: string;
}

function MenuItem({
  index,
  icon,
  label,
  onClick,
  onKeyDown,
  menuItemsRef,
  disabled,
  testId,
}: MenuItemProps) {
  return (
    <button
      ref={(el) => {
        // eslint-disable-next-line no-param-reassign
        menuItemsRef.current[index] = el;
      }}
      type="button"
      onClick={onClick}
      onKeyDown={(e) => onKeyDown(e, index)}
      disabled={disabled}
      className={cn(
        "group w-full cursor-pointer rounded px-2 py-2 text-start text-nowrap text-sm font-normal",
        "text-[var(--oh-foreground)] hover:bg-[var(--oh-interactive-hover)]",
        "disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:bg-transparent",
      )}
      role="menuitem"
      data-testid={testId}
    >
      <ConversationNameContextMenuIconText icon={icon} text={label} />
    </button>
  );
}

interface MetaProfileActionsMenuProps {
  onEdit: () => void;
  onSetActive: () => void;
  onDelete: () => void;
  isActive: boolean;
  isActivating: boolean;
  onClose: () => void;
  /**
   * Element the menu should anchor against. When provided, the menu renders
   * into a portal at the document body using fixed positioning so it cannot be
   * clipped by ancestors with `overflow: auto/hidden` (e.g. the settings
   * `<main>` scroll container).
   */
  anchorRef?: React.RefObject<HTMLElement | null>;
}

export function MetaProfileActionsMenu({
  onEdit,
  onSetActive,
  onDelete,
  isActive,
  isActivating,
  onClose,
  anchorRef,
}: MetaProfileActionsMenuProps) {
  const { t } = useTranslation("openhands");
  const menuRef = useRef<HTMLDivElement>(null);
  const menuItemsRef = useRef<(HTMLButtonElement | null)[]>([]);

  const anchorElement = anchorRef?.current ?? null;
  const [portalStyle, setPortalStyle] = useState<React.CSSProperties>();

  useLayoutEffect(() => {
    if (!anchorElement) return undefined;

    const updatePosition = () => {
      const rect = anchorElement.getBoundingClientRect();
      if (!rect) return;
      const gap = 8;
      setPortalStyle({
        position: "fixed",
        zIndex: 9999,
        top: rect.bottom + gap,
        right: window.innerWidth - rect.right,
        width: "max-content",
      });
    };

    updatePosition();
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [anchorElement]);

  // Focus first item when menu opens
  useEffect(() => {
    menuItemsRef.current[0]?.focus();
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node;
      if (menuRef.current && !menuRef.current.contains(target)) {
        onClose();
      }
    };

    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        onClose();
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("keydown", handleEscape);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("keydown", handleEscape);
    };
  }, [onClose]);

  const handleAction = (action: () => void) => {
    action();
    onClose();
  };

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent, currentIndex: number) => {
      if (e.key === "Tab") {
        onClose();
        return;
      }
      const itemCount = menuItemsRef.current.filter(Boolean).length;
      if (e.key === "ArrowDown") {
        e.preventDefault();
        const nextIndex = (currentIndex + 1) % itemCount;
        menuItemsRef.current[nextIndex]?.focus();
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        const prevIndex = (currentIndex - 1 + itemCount) % itemCount;
        menuItemsRef.current[prevIndex]?.focus();
      }
    },
    [onClose],
  );

  const setActiveDisabled = isActive || isActivating;
  const isPortaled = Boolean(anchorElement);

  const menu = (
    <div
      ref={menuRef}
      className={cn(
        "absolute right-0 top-full z-10 mt-2 w-[160px] rounded-md border border-[var(--oh-border-subtle)] bg-tertiary px-1 py-1 shadow-lg",
        dropdownMenuListClassName,
        isPortaled &&
          "!static !top-auto !bottom-auto !left-auto !right-auto !mt-0",
      )}
      role="menu"
      aria-orientation="vertical"
      data-testid="meta-profile-actions-menu"
    >
      <MenuItem
        index={0}
        icon={<EditIcon width={16} height={16} />}
        label={t(I18nKey.BUTTON$EDIT)}
        onClick={() => handleAction(onEdit)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        testId="meta-profile-edit"
      />
      <MenuItem
        index={1}
        icon={<CheckCircleIcon width={16} height={16} />}
        label={t(I18nKey.SETTINGS$META_PROFILE_ACTIVATE)}
        onClick={() => handleAction(onSetActive)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        disabled={setActiveDisabled}
        testId="meta-profile-set-active"
      />
      <MenuItem
        index={2}
        icon={<DeleteIcon width={16} height={16} />}
        label={t(I18nKey.BUTTON$DELETE)}
        onClick={() => handleAction(onDelete)}
        onKeyDown={handleKeyDown}
        menuItemsRef={menuItemsRef}
        testId="meta-profile-delete"
      />
    </div>
  );

  if (isPortaled) {
    if (typeof document === "undefined" || !portalStyle) {
      return null;
    }
    return ReactDOM.createPortal(
      // portal position computed from DOM bounding rect at runtime
      <div style={portalStyle}>{menu}</div>,
      document.body,
    );
  }

  return menu;
}

import { useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { BrandButton } from "#/components/features/settings/brand-button";
import { SettingsDropdownInput } from "#/components/features/settings/settings-dropdown-input";
import { ProfileNameInput } from "#/components/features/settings/llm-profiles/profile-name-input";
import { ProviderConnectionModal } from "#/components/features/settings/llm-profiles/provider-connection-modal";
import { Typography } from "#/ui/typography";
import { isProfileNameValid } from "#/utils/derive-profile-name";
import { cn } from "#/utils/utils";
import { formControlMultilineFieldClassName } from "#/utils/form-control-classes";
import { I18nKey } from "#/i18n/declaration";
import type { MetaProfile } from "#/api/meta-profiles-service/meta-profiles-service.api";
import type { ProviderConnection } from "#/api/provider-connections-service/provider-connections-service.api";
import {
  DEFAULT_ROUTER_PRO_META_PROFILE_DEFAULT,
  DEFAULT_ROUTER_PRO_META_PROFILE_NAME,
} from "./default-meta-profile";

// Dropdown key that means "don't create any router profiles" (i.e. all the
// referenced LLM profiles already exist or the user will create them manually).
const NO_ROUTER_CONNECTION_KEY = "";

interface MetaProfileEditorProps {
  mode: "create" | "edit";
  initialName?: string;
  initialConfig?: MetaProfile;
  /**
   * When true (create mode, built-in templates), the first provider connection
   * is pre-selected so the router's LLM profiles are created on save.
   */
  selectRouterConnectionByDefault?: boolean;
  /**
   * Provider connections offered for populating the router's LLM profiles.
   * Empty on cloud / older backends, where the picker is hidden.
   */
  providerConnections?: ProviderConnection[];
  /** Names of saved LLM profiles, offered as dropdown options. */
  availableProfiles: string[];
  /**
   * Names of existing meta-profiles. In create mode a name already present
   * here is rejected, so "Add" cannot silently overwrite an existing profile
   * (the backend save contract is create-or-overwrite).
   */
  existingNames?: string[];
  isSaving: boolean;
  onSave: (
    name: string,
    config: MetaProfile,
    providerConnectionId: string | null,
  ) => void;
  onCancel: () => void;
  onProviderConnectionCreated?: (connection: ProviderConnection) => void;
}

const EMPTY_CONFIG: MetaProfile = {
  classifier_model: "",
  prompt_template: "",
  model_table: "",
};

const INSTANCE_TEXT_PLACEHOLDER = /{{\s*instance_text\s*}}/;
const INSTANCE_TEXT_PLACEHOLDER_TEXT = "{{ instance_text }}";
const MODEL_TABLE_PLACEHOLDER_TEXT = "{{ model_table }}";
const PROMPT_TEMPLATE_PLACEHOLDER = `Return JSON with the best model for this task.
${MODEL_TABLE_PLACEHOLDER_TEXT}

Task:
${INSTANCE_TEXT_PLACEHOLDER_TEXT}`;

const normalizeConfig = (config?: MetaProfile): MetaProfile => ({
  classifier_model: config?.classifier_model ?? "",
  classes: [],
  prompt_template: config?.prompt_template ?? "",
  model_table: config?.model_table ?? "",
});

export function MetaProfileEditor({
  mode,
  initialName,
  initialConfig,
  selectRouterConnectionByDefault,
  providerConnections = [],
  availableProfiles,
  existingNames = [],
  isSaving,
  onSave,
  onCancel,
  onProviderConnectionCreated,
}: MetaProfileEditorProps) {
  const { t } = useTranslation("openhands");
  const isEdit = mode === "edit";
  const startingConfig = normalizeConfig(
    initialConfig ??
      (isEdit ? EMPTY_CONFIG : DEFAULT_ROUTER_PRO_META_PROFILE_DEFAULT),
  );
  const [name, setName] = useState(
    initialName ?? (isEdit ? "" : DEFAULT_ROUTER_PRO_META_PROFILE_NAME),
  );
  const [config, setConfig] = useState<MetaProfile>(() => startingConfig);
  const [createdProviderConnections, setCreatedProviderConnections] = useState<
    ProviderConnection[]
  >([]);
  const [isProviderConnectionModalOpen, setIsProviderConnectionModalOpen] =
    useState(false);
  const connectionOptions = useMemo(() => {
    const byId = new Map<string, ProviderConnection>();
    for (const connection of providerConnections)
      byId.set(connection.id, connection);
    for (const connection of createdProviderConnections) {
      byId.set(connection.id, connection);
    }
    return [...byId.values()];
  }, [providerConnections, createdProviderConnections]);
  const showRouterConnectionPicker = !isEdit;
  // `null` until the user picks a connection. "Don't create profiles" is the
  // empty key, so the template default must not be stored in the same state
  // or it would overwrite that choice.
  const [chosenRouterConnectionId, setChosenRouterConnectionId] = useState<
    string | null
  >(null);
  const routerConnectionId =
    chosenRouterConnectionId ??
    (selectRouterConnectionByDefault && connectionOptions.length > 0
      ? connectionOptions[0].id
      : NO_ROUTER_CONNECTION_KEY);

  // The classifier dropdown is driven by saved LLM profile names, but a router
  // template can name a classifier (e.g. ``minimax-m3``) before any profiles
  // exist. Without the value in the list, the Autocomplete's
  // ``defaultSelectedKey`` finds no match and renders an empty input — which
  // ``allowsCustomValue`` then syncs back as ``""``, dropping the classifier
  // from the saved config (so it never gets created). Surface the chosen
  // classifier as an item so it is genuinely preselected.
  const profileItems = useMemo(() => {
    const items = availableProfiles.map((p) => ({ key: p, label: p }));
    const classifier = config.classifier_model.trim();
    if (
      classifier &&
      !availableProfiles.some(
        (p) => p.toLowerCase() === classifier.toLowerCase(),
      )
    ) {
      items.push({ key: classifier, label: classifier });
    }
    return items;
  }, [availableProfiles, config.classifier_model]);
  const routerConnectionItems = useMemo(
    () => [
      {
        key: NO_ROUTER_CONNECTION_KEY,
        label: t(I18nKey.SETTINGS$META_PROFILE_ROUTER_CONNECTION_NONE),
      },
      ...connectionOptions.map((connection) => ({
        key: connection.id,
        label: `${connection.display_name} (${connection.provider})`,
      })),
    ],
    [connectionOptions, t],
  );

  const nameValid = isProfileNameValid(name, { isRequired: true });
  // In create mode, a name that already exists would overwrite that profile
  // (the backend save is create-or-overwrite), so reject it here.
  const isDuplicateName = !isEdit && existingNames.includes(name.trim());
  const canSave =
    nameValid &&
    !isDuplicateName &&
    config.classifier_model.trim().length > 0 &&
    INSTANCE_TEXT_PLACEHOLDER.test(config.prompt_template ?? "");

  const handleProviderConnectionSaved = (connection: ProviderConnection) => {
    setCreatedProviderConnections((existing) => [
      connection,
      ...existing.filter((item) => item.id !== connection.id),
    ]);
    onProviderConnectionCreated?.(connection);
    setChosenRouterConnectionId(connection.id);
  };

  const handleSave = () => {
    if (!canSave || isSaving) return;
    onSave(
      name.trim(),
      {
        classifier_model: config.classifier_model.trim(),
        classes: [],
        prompt_template: (config.prompt_template ?? "").trim(),
        model_table: config.model_table?.trim() || null,
      },
      showRouterConnectionPicker && routerConnectionId
        ? routerConnectionId
        : null,
    );
  };

  return (
    <div className="flex flex-col gap-6" data-testid="meta-profile-editor">
      <Typography.H3>
        {t(
          isEdit
            ? I18nKey.SETTINGS$EDIT_META_PROFILE
            : I18nKey.SETTINGS$NEW_META_PROFILE,
        )}
      </Typography.H3>

      <div className="flex flex-col gap-1">
        <ProfileNameInput
          testId="meta-profile-name-input"
          value={name}
          onChange={setName}
          isDisabled={isEdit || isSaving}
          isRequired
        />
        {isDuplicateName ? (
          <p
            data-testid="meta-profile-name-taken"
            className="text-xs text-red-400"
          >
            {t(I18nKey.SETTINGS$META_PROFILE_NAME_TAKEN)}
          </p>
        ) : null}
      </div>

      <div className="flex flex-col gap-2">
        <SettingsDropdownInput
          testId="meta-profile-classifier-input"
          name="classifier_model"
          label={t(I18nKey.SETTINGS$META_PROFILE_CLASSIFIER)}
          items={profileItems}
          selectedKey={config.classifier_model || undefined}
          allowsCustomValue
          isDisabled={isSaving}
          onInputChange={(value) =>
            setConfig((prev) => ({ ...prev, classifier_model: value }))
          }
          onSelectionChange={(key) =>
            setConfig((prev) => ({
              ...prev,
              classifier_model: key ? String(key) : "",
            }))
          }
        />
        <p className="text-xs text-[var(--oh-muted)]">
          {t(I18nKey.SETTINGS$META_PROFILE_CLASSIFIER_HELP)}
        </p>
      </div>

      <div className="flex flex-col gap-2">
        <label className="flex flex-col gap-2.5">
          <span className="text-sm">
            {t(I18nKey.SETTINGS$META_PROFILE_PROMPT_TEMPLATE)}
          </span>
          <textarea
            data-testid="meta-profile-prompt-template"
            rows={8}
            spellCheck={false}
            value={config.prompt_template ?? ""}
            placeholder={PROMPT_TEMPLATE_PLACEHOLDER}
            onChange={(event) =>
              setConfig((prev) => ({
                ...prev,
                prompt_template: event.target.value,
              }))
            }
            disabled={isSaving}
            className={cn(
              formControlMultilineFieldClassName,
              "font-mono text-xs",
            )}
          />
        </label>
        <p className="text-xs text-[var(--oh-muted)]">
          {t(I18nKey.SETTINGS$META_PROFILE_PROMPT_TEMPLATE_HELP, {
            instance_text: INSTANCE_TEXT_PLACEHOLDER_TEXT,
            model_table: MODEL_TABLE_PLACEHOLDER_TEXT,
          })}
        </p>
      </div>

      <div className="flex flex-col gap-2">
        <label className="flex flex-col gap-2.5">
          <span className="text-sm">
            {t(I18nKey.SETTINGS$META_PROFILE_MODEL_TABLE)}
          </span>
          <textarea
            data-testid="meta-profile-model-table"
            rows={5}
            spellCheck={false}
            value={config.model_table ?? ""}
            placeholder={t(
              I18nKey.SETTINGS$META_PROFILE_MODEL_TABLE_PLACEHOLDER,
            )}
            onChange={(event) =>
              setConfig((prev) => ({
                ...prev,
                model_table: event.target.value,
              }))
            }
            disabled={isSaving}
            className={cn(
              formControlMultilineFieldClassName,
              "font-mono text-xs",
            )}
          />
        </label>
        <p className="text-xs text-[var(--oh-muted)]">
          {t(I18nKey.SETTINGS$META_PROFILE_MODEL_TABLE_HELP, {
            model_table: MODEL_TABLE_PLACEHOLDER_TEXT,
          })}
        </p>
      </div>

      {showRouterConnectionPicker ? (
        <div className="flex flex-col gap-2">
          <SettingsDropdownInput
            testId="meta-profile-router-connection"
            name="router_connection"
            label={t(I18nKey.SETTINGS$META_PROFILE_CREATE_ROUTER_PROFILES)}
            items={routerConnectionItems}
            selectedKey={routerConnectionId}
            isDisabled={isSaving}
            onSelectionChange={(key) =>
              setChosenRouterConnectionId(
                key ? String(key) : NO_ROUTER_CONNECTION_KEY,
              )
            }
          />
          <div className="flex flex-wrap items-center gap-3">
            <p className="text-xs text-[var(--oh-muted)]">
              {t(I18nKey.SETTINGS$META_PROFILE_CREATE_ROUTER_PROFILES_HELP)}
            </p>
            <BrandButton
              testId="meta-profile-add-provider-connection"
              type="button"
              variant="secondary"
              onClick={() => setIsProviderConnectionModalOpen(true)}
              isDisabled={isSaving}
            >
              {t(I18nKey.SETTINGS$PROVIDER_CONNECTION_ADD)}
            </BrandButton>
          </div>
        </div>
      ) : null}

      {isProviderConnectionModalOpen ? (
        <ProviderConnectionModal
          isCreate
          onClose={() => setIsProviderConnectionModalOpen(false)}
          onSaved={handleProviderConnectionSaved}
        />
      ) : null}

      <div className="flex items-center gap-3">
        <BrandButton
          testId="meta-profile-save"
          type="button"
          variant="primary"
          onClick={handleSave}
          isDisabled={!canSave || isSaving}
        >
          {t(I18nKey.BUTTON$SAVE)}
        </BrandButton>
        <BrandButton
          testId="meta-profile-cancel"
          type="button"
          variant="tertiary"
          onClick={onCancel}
          isDisabled={isSaving}
        >
          {t(I18nKey.BUTTON$CANCEL)}
        </BrandButton>
      </div>
    </div>
  );
}

import { useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { MetaProfileActionsMenu } from "./meta-profile-actions-menu";
import { MetaProfileInfo } from "#/api/meta-profiles-service/meta-profiles-service.api";
import { I18nKey } from "#/i18n/declaration";
import { EllipsisButton } from "#/components/features/conversation-panel/ellipsis-button";
import { BrandBadge } from "#/components/shared/badge";
