          className="min-w-0 max-w-full truncate text-sm font-medium text-contrast"
          title={info.name}
        >
          {info.name}
        </span>
        <span
          className="min-w-0 max-w-full truncate text-sm text-[var(--oh-muted)]"
          title={summary}
