import React from "react";
import { createPortal } from "react-dom";
import { useTranslation } from "react-i18next";
import { I18nKey } from "#/i18n/declaration";
import { cn } from "#/utils/utils";
import { extensionModuleCardPillClassName } from "#/utils/extension-module-card-classes";

/** @deprecated Use {@link extensionModuleCardPillClassName} from `#/utils/extension-module-card-classes`. */
export const SKILL_CARD_PILL_CLASS = extensionModuleCardPillClassName;

const PILL_GAP_PX = 6;
const OVERFLOW_PILL_WIDTH_PX = 40;
const OVERFLOW_POPOVER_GUTTER_PX = 8;
const OVERFLOW_POPOVER_OFFSET_PX = 4;

function placePopoverByTrigger(
  trigger: DOMRect,
  popoverWidth: number,
): { top: number; left: number } {
  const maxLeft = window.innerWidth - OVERFLOW_POPOVER_GUTTER_PX - popoverWidth;
  let left = trigger.left;
  if (left > maxLeft) {
    left = trigger.right - popoverWidth;
  }
  left = Math.min(
    Math.max(OVERFLOW_POPOVER_GUTTER_PX, left),
    Math.max(OVERFLOW_POPOVER_GUTTER_PX, maxLeft),
  );
  return { top: trigger.bottom + OVERFLOW_POPOVER_OFFSET_PX, left };
}

export interface SkillCardPill {
  id: string;
  node: React.ReactNode;
}

function computeVisiblePillCount(
  widths: number[],
  containerWidth: number,
): number {
  if (widths.length === 0 || containerWidth <= 0) return 0;

  let used = 0;
  for (let i = 0; i < widths.length; i += 1) {
    const width = widths[i]!;
    const gap = i > 0 ? PILL_GAP_PX : 0;
    const remaining = widths.length - i - 1;
    const reserve = remaining > 0 ? OVERFLOW_PILL_WIDTH_PX + PILL_GAP_PX : 0;
    if (used + gap + width + reserve > containerWidth) {
      return Math.max(1, i);
    }
    used += gap + width;
  }
  return widths.length;
}

interface SkillCardPillRowProps {
  pills: SkillCardPill[];
  testId: string;
}

export function SkillCardPillRow({ pills, testId }: SkillCardPillRowProps) {
  const { t } = useTranslation("openhands");
  const containerRef = React.useRef<HTMLDivElement>(null);
  const measureRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const popoverRef = React.useRef<HTMLDivElement>(null);
  const [visibleCount, setVisibleCount] = React.useState(pills.length);
  const [isOverflowOpen, setIsOverflowOpen] = React.useState(false);
  const [popoverBox, setPopoverBox] = React.useState<{
    top: number;
    left: number;
  } | null>(null);

  const recomputeVisibleCount = React.useCallback(() => {
    const container = containerRef.current;
    const measure = measureRef.current;
    if (!container || !measure) return;

    const widths = Array.from(measure.children).map(
      (child) => (child as HTMLElement).offsetWidth,
    );
    setVisibleCount(computeVisiblePillCount(widths, container.clientWidth));
  }, []);

  // Recommended cards rebuild the pills array every render; compare ids so an
  // open +N popover is not slammed shut under the cursor.
  const pillsKey = pills.map((pill) => pill.id).join("\u001f");
  const lastPillsKeyRef = React.useRef<string | null>(null);

  React.useLayoutEffect(() => {
    if (lastPillsKeyRef.current === pillsKey) {
      return;
    }
    lastPillsKeyRef.current = pillsKey;
    setIsOverflowOpen(false);
    recomputeVisibleCount();
  }, [pillsKey, recomputeVisibleCount]);

  React.useEffect(() => {
    const container = containerRef.current;
    if (!container || typeof ResizeObserver === "undefined") return undefined;

    const observer = new ResizeObserver(() => recomputeVisibleCount());
    observer.observe(container);
    return () => observer.disconnect();
  }, [recomputeVisibleCount]);

  const measurePopover = React.useCallback(() => {
    const trigger = triggerRef.current;
    if (!trigger) {
      return;
    }
    const next = placePopoverByTrigger(
      trigger.getBoundingClientRect(),
      popoverRef.current?.offsetWidth ?? trigger.offsetWidth,
    );
    setPopoverBox((prev) =>
      prev?.top === next.top && prev?.left === next.left ? prev : next,
    );
  }, []);

  React.useLayoutEffect(() => {
    if (!isOverflowOpen) {
      setPopoverBox(null);
      return undefined;
    }
    measurePopover();
    window.addEventListener("resize", measurePopover);
    window.addEventListener("scroll", measurePopover, true);
    return () => {
      window.removeEventListener("resize", measurePopover);
      window.removeEventListener("scroll", measurePopover, true);
    };
  }, [isOverflowOpen, measurePopover]);

  React.useLayoutEffect(() => {
    if (isOverflowOpen && popoverBox && popoverRef.current) {
      measurePopover();
    }
  }, [isOverflowOpen, measurePopover, popoverBox]);

  React.useEffect(() => {
    if (!isOverflowOpen) {
      return undefined;
    }
    const onPointerDown = (event: MouseEvent) => {
      const target = event.target as Node;
      if (triggerRef.current?.contains(target)) {
        return;
      }
      if (popoverRef.current?.contains(target)) {
        return;
      }
      setIsOverflowOpen(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        // The modal also listens for Escape on window. Keep this key press
        // scoped to the open popover so it does not close both at once.
        event.stopPropagation();
        setIsOverflowOpen(false);
      }
    };
    // mousedown (not click) so the opening click cannot race-close the panel,
    // and so wrapping card/link activation is easier to cancel on the trigger.
    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [isOverflowOpen]);

  if (pills.length === 0) return null;

  const hiddenCount = Math.max(0, pills.length - visibleCount);
  const overflowPills = pills.slice(visibleCount);

  const stopCardActivation = (event: React.SyntheticEvent) => {
    event.stopPropagation();
  };

  const stopCardActivationForKeyboard = (
    event: React.KeyboardEvent<HTMLButtonElement>,
  ) => {
    if (event.key === "Enter" || event.key === " ") {
      event.stopPropagation();
    }
  };

  const activateOverflow = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    setIsOverflowOpen((open) => !open);
  };

  return (
    <div data-testid={`${testId}-wrap`} className="min-w-0 overflow-hidden">
      <div
        ref={measureRef}
        aria-hidden
        className="pointer-events-none fixed top-0 -left-2500 z-[-1] flex flex-nowrap items-center gap-1.5 opacity-0"
      >
        {pills.map((pill) => (
          <span key={pill.id} className="inline-flex shrink-0">
            {pill.node}
          </span>
        ))}
      </div>
      <div
        ref={containerRef}
        data-testid={testId}
        className="flex w-full min-w-0 max-w-full flex-nowrap items-center gap-1.5 overflow-hidden"
      >
        {pills.slice(0, visibleCount).map((pill) => (
          <span key={pill.id} className="inline-flex shrink-0">
            {pill.node}
          </span>
        ))}
        {hiddenCount > 0 ? (
          <button
            ref={triggerRef}
            type="button"
            data-testid={`${testId}-overflow`}
            aria-expanded={isOverflowOpen}
            aria-haspopup="dialog"
            aria-label={t(I18nKey.SETTINGS$SKILLS_PILLS_OVERFLOW_ARIA, {
              count: hiddenCount,
            })}
            onMouseDown={stopCardActivation}
            onClick={activateOverflow}
            onKeyDown={stopCardActivationForKeyboard}
            className={cn(
              extensionModuleCardPillClassName,
              "cursor-pointer font-medium text-tertiary-alt hover:text-contrast",
            )}
          >
            {t(I18nKey.SETTINGS$SKILLS_PILLS_MORE, { count: hiddenCount })}
          </button>
        ) : null}
      </div>

      {isOverflowOpen &&
        popoverBox &&
        typeof document !== "undefined" &&
        createPortal(
          // Stop card-level click activation when interacting with the list.
          // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- dialog surface must swallow clicks
          <div
            ref={popoverRef}
            role="dialog"
            data-testid={`${testId}-overflow-popover`}
            className={cn(
              "z-[9999] flex w-max max-w-[20rem] flex-col gap-1.5",
              "rounded-md border border-border-subtle",
              "bg-surface p-2 shadow-lg",
            )}
            style={{
              position: "fixed",
              top: popoverBox.top,
              left: popoverBox.left,
            }}
            onMouseDown={stopCardActivation}
            onClick={(event) => {
              event.preventDefault();
              event.stopPropagation();
            }}
          >
            {overflowPills.map((pill) => (
              <div
                key={pill.id}
                data-testid={`${testId}-overflow-item`}
                className="min-w-0"
              >
                {pill.node}
              </div>
            ))}
          </div>,
          document.body,
        )}
    </div>
  );
}

import React from "react";
import { useTranslation } from "react-i18next";
import { ModalBackdrop } from "#/components/shared/modals/modal-backdrop";
import { ModalCloseButton } from "#/components/shared/modals/modal-close-button";
import { BrandButton } from "#/components/features/settings/brand-button";
import { SettingsSwitch } from "#/components/features/settings/settings-switch";
import { I18nKey } from "#/i18n/declaration";
import type { SkillInfo } from "#/types/settings";
import { cn } from "#/utils/utils";
import { modalTitleLgClassName } from "#/utils/modal-classes";
import CopyIcon from "#/icons/copy.svg?react";
import CheckmarkIcon from "#/icons/checkmark.svg?react";
import MessageSquareShareIcon from "#/icons/message-square-share.svg?react";
import { SkillIconBadge } from "./skill-icon-badge";
import { getSkillCardDescription } from "./get-skill-card-description";
import { buildSkillPills } from "./build-skill-pills";
import { isCopyableSkillSource } from "./is-copyable-skill-source";
import { SkillCardPillRow } from "./skill-card-pill-row";
import { getSkillChatLaunchMessage } from "./get-skill-chat-launch-message";
import { useLaunchSkillInChat } from "#/hooks/use-launch-skill-in-chat";

interface SkillDetailModalProps {
  skill: SkillInfo;
  enabled: boolean;
  onToggle: (enabled: boolean) => void;
  onClose: () => void;
}

function ReadonlyTextArea({
  testId,
  label,
  value,
}: {
  testId: string;
  label: string;
  value: string;
}) {
  return (
    <label className="flex min-w-0 w-full flex-col gap-2.5">
      <span className="text-sm">{label}</span>
      <textarea
        data-testid={testId}
        readOnly
        value={value}
        rows={Math.min(12, Math.max(4, value.split("\n").length))}
        className={cn(
          "bg-surface-raised border border-border-subtle w-full min-w-0 rounded-sm p-2 text-sm",
          "cursor-not-allowed resize-none custom-scrollbar",
        )}
      />
    </label>
  );
}

export function SkillDetailModal({
  skill,
  enabled,
  onToggle,
  onClose,
}: SkillDetailModalProps) {
  const { t } = useTranslation("openhands");
  const launchSkillInChat = useLaunchSkillInChat();
  const [sourceCopied, setSourceCopied] = React.useState(false);
  const chatLaunchMessage = React.useMemo(
    () => getSkillChatLaunchMessage(skill),
    [skill],
  );

  const description = getSkillCardDescription(skill);
  const pills = React.useMemo(
    () =>
      buildSkillPills(skill, t, {
        variant: "detail",
        testIdPrefix: "skill-modal-pill",
      }),
    [skill, t],
  );
  const showCopySource = isCopyableSkillSource(skill.source);

  const handleCopySource = async () => {
    if (!skill.source) {
      return;
    }

    await navigator.clipboard.writeText(skill.source);
    setSourceCopied(true);
  };

  React.useEffect(() => {
    if (!sourceCopied) {
      return undefined;
    }

    const timeout = setTimeout(() => setSourceCopied(false), 2000);
    return () => clearTimeout(timeout);
  }, [sourceCopied]);

  return (
    <ModalBackdrop onClose={onClose} aria-label={skill.name}>
      <div
        data-testid="skill-detail-modal"
        data-skill-name={skill.name}
        className="relative flex w-130 max-w-[90vw] max-h-[85vh] flex-col overflow-hidden rounded-xl border border-border bg-base-secondary"
      >
        <ModalCloseButton onClose={onClose} testId="skill-detail-modal-close" />
        <header className="flex flex-shrink-0 items-start gap-3 pb-4 pl-6 pr-12 pt-6">
          <SkillIconBadge skillName={skill.name} />
          <div className="min-w-0 flex-1">
            <h2
              data-testid={`skill-modal-name-${skill.name}`}
              className={modalTitleLgClassName}
            >
              {skill.name}
            </h2>
            {skill.source ? (
              <div className="mt-0.5 flex min-w-0 items-center gap-1">
                <p
                  data-testid={`skill-modal-source-${skill.name}`}
                  className="min-w-0 flex-1 truncate text-xs text-tertiary-alt"
                  title={skill.source}
                >
                  {skill.source}
                </p>
                {showCopySource ? (
                  <button
                    type="button"
                    data-testid={`skill-modal-copy-source-${skill.name}`}
                    aria-label={t(
                      sourceCopied
                        ? I18nKey.BUTTON$COPIED
                        : I18nKey.SETTINGS$SKILLS_COPY_PATH,
                    )}
                    disabled={sourceCopied}
                    onClick={handleCopySource}
                    className="shrink-0 cursor-pointer border-0 bg-transparent p-0.5 text-tertiary-alt hover:text-contrast disabled:cursor-default [&_path]:fill-current"
                  >
                    {sourceCopied ? (
                      <CheckmarkIcon width={12} height={12} />
                    ) : (
                      <CopyIcon width={12} height={12} />
                    )}
                  </button>
                ) : null}
              </div>
            ) : null}
          </div>
        </header>

        <div
          data-testid="skill-detail-modal-content"
          className="flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto overscroll-contain px-6 custom-scrollbar-always"
        >
          <div
            data-testid={`skill-modal-enable-row-${skill.name}`}
            className="flex w-full items-center rounded-lg border border-border bg-contrast/[0.04] px-3 py-2.5"
          >
            <SettingsSwitch
              testId={`skill-modal-toggle-${skill.name}`}
              isToggled={enabled}
              onToggle={onToggle}
              togglePosition="right"
            >
              {t(
                enabled
                  ? I18nKey.SETTINGS$SKILLS_ENABLED
                  : I18nKey.SETTINGS$SKILLS_DISABLED,
              )}
            </SettingsSwitch>
          </div>

          {description ? (
