import React from "react";
import { useTranslation } from "react-i18next";
import { isHookExecutionEvent } from "#/types/agent-server/type-guards";
import { OpenHandsEvent } from "#/types/agent-server/core";
import { GenericEventMessage } from "#/components/features/chat/generic-event-message";
import { cn } from "#/utils/utils";
import { I18nKey } from "#/i18n/declaration";

interface HookExecutionEventMessageProps {
  event: OpenHandsEvent;
}

function getHookIcon(hookType: string, blocked: boolean): string {
  if (blocked) {
    return "🚫";
  }

  switch (hookType) {
    case "PreToolUse":
      return "⏳";
    case "PostToolUse":
      return "✅";
    case "UserPromptSubmit":
      return "📝";
    case "SessionStart":
      return "🚀";
    case "SessionEnd":
      return "🏁";
    case "Stop":
      return "⏹️";
    default:
      return "🔗";
  }
}

function formatHookCommand(command: string): string {
  // Truncate long commands for display
  if (command.length > 80) {
    return `${command.slice(0, 77)}...`;
  }
  return command;
}

function getStatusText(blocked: boolean, success: boolean): string {
  if (blocked) return "blocked";
  if (success) return "ok";
  return "failed";
}

function getStatusClassName(blocked: boolean, success: boolean): string {
  if (blocked) return "bg-amber-900/50 text-amber-300";
  if (success) return "bg-green-900/50 text-green-300";
  return "bg-red-900/50 text-red-300";
}

export function HookExecutionEventMessage({
  event,
}: HookExecutionEventMessageProps) {
  const { t } = useTranslation("openhands");

  if (!isHookExecutionEvent(event)) {
    return null;
  }

  const icon = getHookIcon(event.hook_event_type, event.blocked);
  const statusText = getStatusText(event.blocked, event.success);
  const statusClassName = getStatusClassName(event.blocked, event.success);

  // Determine the overall success indicator for GenericEventMessage.
  // When blocked, suppress the success indicator entirely — the amber "blocked"
  // badge in the title is the authoritative status signal.
  const getSuccessStatus = (): "success" | "error" | undefined => {
    if (event.blocked) return undefined;
    return event.success ? "success" : "error";
  };
  const successStatus = getSuccessStatus();

  const title = (
    <span>
      {icon} {t(I18nKey.HOOK$HOOK_LABEL)}: {event.hook_event_type}
      {event.tool_name && (
        <span className="text-muted ml-2">({event.tool_name})</span>
      )}
      <span className={cn("ml-2 px-1 py-0.5 rounded text-xs", statusClassName)}>
        {statusText}
      </span>
    </span>
  );

  const details = (
    <div className="flex flex-col gap-2 text-muted">
      <div>
        <span className="text-text-subtle">{t(I18nKey.HOOK$COMMAND)}:</span>{" "}
        <code className="text-xs bg-surface px-1 py-0.5 rounded">
          {formatHookCommand(event.hook_command)}
        </code>
      </div>

      {event.exit_code !== null && (
        <div>
          <span className="text-text-subtle">{t(I18nKey.HOOK$EXIT_CODE)}:</span>{" "}
          {event.exit_code}
        </div>
      )}

      {event.blocked && event.reason && (
        <div className="text-amber-400">
          <span className="text-text-subtle">
            {t(I18nKey.HOOK$BLOCKED_REASON)}:
          </span>{" "}
          {event.reason}
        </div>
      )}

      {event.additional_context && (
        <div>
          <span className="text-text-subtle">{t(I18nKey.HOOK$CONTEXT)}:</span>{" "}
          {event.additional_context}
        </div>
      )}

      {event.error && (
        <div className="text-red-400">
          <span className="text-text-subtle">{t(I18nKey.HOOK$ERROR)}:</span>{" "}
          {event.error}
        </div>
      )}

      {event.stdout && (
        <div>
          <span className="text-text-subtle">{t(I18nKey.HOOK$OUTPUT)}:</span>
          <pre className="text-xs bg-surface p-2 rounded mt-1 overflow-x-auto max-h-40 overflow-y-auto">
            {event.stdout}
          </pre>
        </div>
      )}

      {event.stderr && (
        <div>
          <span className="text-text-subtle">{t(I18nKey.HOOK$STDERR)}:</span>
          <pre className="text-xs bg-surface p-2 rounded mt-1 overflow-x-auto max-h-40 overflow-y-auto text-amber-300">
            {event.stderr}
          </pre>
        </div>
      )}
    </div>
  );

  return (
    <GenericEventMessage
      title={title}
      details={details}
      success={successStatus}
    />
  );
}

import React from "react";
import { createPortal } from "react-dom";

interface ModalBackdropProps {
  children: React.ReactNode;
  onClose?: () => void;
  /** When false, pressing Escape does not close the modal. Defaults to true. */
  closeOnEscape?: boolean;
  /** When false, clicking the backdrop does not close the modal. Defaults to true. */
  closeOnBackdropClick?: boolean;
  /** When true, renders above the default modal layer so it stacks over other
   *  modals (used by the telemetry consent banner over the onboarding modal).
   *  Defaults to false. */
  elevated?: boolean;
  "aria-label"?: string;
}

export function ModalBackdrop({
  children,
  onClose,
  closeOnEscape = true,
  closeOnBackdropClick = true,
  elevated = false,
  "aria-label": ariaLabel,
}: ModalBackdropProps) {
  React.useEffect(() => {
    if (!closeOnEscape) return undefined;
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose?.();
    };

    window.addEventListener("keydown", handleEscape);
    return () => window.removeEventListener("keydown", handleEscape);
  }, [closeOnEscape, onClose]);

  const handleClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!closeOnBackdropClick) return;
    if (e.target === e.currentTarget) onClose?.(); // only close if the click was on the backdrop
  };

  if (typeof document === "undefined") return null;

  // Portal to document.body so the modal's `position: fixed` resolves
  // against the viewport. Otherwise a transformed ancestor (e.g. the
  // onboarding slide rail) would become the containing block and the
  // modal would render trapped inside it instead of overlapping its
  // parent modal.
  return createPortal(
    <div
      role="dialog"
      aria-modal="true"
      aria-label={ariaLabel}
      className={`fixed inset-0 flex items-center justify-center ${
        elevated ? "z-[70]" : "z-60"
      }`}
    >
      <div
        onClick={handleClick}
        className="fixed inset-0 bg-black opacity-60"
      />
      <div className="relative">{children}</div>
    </div>,
    document.body,
  );
}

