      ) : null}

      {isAcp && (
        <>
          <SettingsDropdownInput
            testId="agent-preset-selector"
            name="agent-preset"
            label={t(I18nKey.SETTINGS$AGENT_PRESET)}
            items={[
              ...acpProviders.map((provider) => ({
                key: provider.key,
                label: provider.display_name,
              })),
              {
                key: ACP_CUSTOM_PRESET_KEY,
                label: t(I18nKey.SETTINGS$AGENT_PRESET_CUSTOM),
              },
            ]}
            selectedKey={selectedPreset}
            onSelectionChange={(key) => {
              if (!key) return;
              const preset = String(key);
              const provider = getAcpProvider(preset);
              if (provider) {
                setCommandText(formatCommand(provider.default_command));
                setAcpModel(getAcpPreferredDefaultModel(preset) ?? "");
                setIsCustomAcpModel(false);
                if (secretsMode === "custom" && preset !== selectedPreset) {
                  addProviderSecrets(preset);
                }
              } else if (preset === ACP_CUSTOM_PRESET_KEY) {
                // Clear command + model: the previous provider's default
                // command would otherwise make detectPreset(commandText)
                // re-match it on the next render and snap the dropdown back
                // off "Custom". Clearing model also prevents leaking e.g.
                // ``claude-opus-4-7`` into ``acp_model`` for an unrelated
                // wrapper.
                setCommandText("");
                setAcpModel("");
                setIsCustomAcpModel(true);
              }
            }}
          />

          <div className="flex flex-col gap-2.5">
            <Typography.Text className="text-sm">
              {t(I18nKey.SETTINGS$AGENT_COMMAND)}
            </Typography.Text>
            <textarea
              data-testid="agent-command-input"
              className="bg-tertiary border border-[#717888] rounded-sm p-2 text-sm font-mono text-contrast placeholder:text-[#717888] min-h-15 resize-y focus:outline-none focus:border-contrast"
              value={commandText}
              placeholder={commandPlaceholder}
              onChange={(e) => {
                const nextCommandText = e.target.value;
                // Keep the model selector in sync with the command being
                // typed. Editing the command into a *different* provider — or
                // into a custom command — must drop the previous provider's
                // model, or Save would silently persist e.g.
                // ``claude-opus-4-7`` against a Codex / custom wrapper. The
                // preset dropdown already does this; the textarea is the other
                // way a user changes provider, so it needs the same
                // reconciliation. Gated on the *detected preset* actually
                // changing, so it never clobbers a model the user is editing
                // within the same provider.
                const prevPreset = detectPreset(commandText, acpProviders);
                const nextPreset = detectPreset(nextCommandText, acpProviders);
                if (nextPreset !== prevPreset) {
                  setAcpModel(getAcpPreferredDefaultModel(nextPreset) ?? "");
                  setIsCustomAcpModel(false);
                  if (secretsMode === "custom") addProviderSecrets(nextPreset);
                }
                setCommandText(nextCommandText);
              }}
            />
            <Typography.Text className="text-xs text-[#717888]">
              {t(I18nKey.SETTINGS$AGENT_COMMAND_HINT)}
            </Typography.Text>
          </div>
        </>
      )}

      {isAcp && selectedPreset !== ACP_CUSTOM_PRESET_KEY && (
        <>
          <hr className="border-[#3D4046]" />
          <AcpCredentialsSection
            form={acpCredentialForm}
            providerKey={selectedPreset}
            loginRejected={
              liveModels.discovery?.error?.code === "ACPAuthRequired"
            }
          />
          <hr className="border-[#3D4046]" />
        </>
      )}

      {isAcp && (
        <div className="flex flex-col gap-1.5">
          {showModelSelector && (
            <SettingsDropdownInput
              testId="agent-model-selector"
              name="agent-model"
              label={t(I18nKey.SETTINGS$AGENT_MODEL)}
              items={[
                ...(offersAgentDefault
                  ? [
                      {
                        key: ACP_AGENT_DEFAULT_MODEL_KEY,
                        label: agentDefaultModelLabel
                          ? t(I18nKey.SETTINGS$AGENT_MODEL_AGENT_DEFAULT_IS, {
                              model: agentDefaultModelLabel,
                            })
                          : t(I18nKey.SETTINGS$AGENT_MODEL_AGENT_DEFAULT),
                      },
                    ]
                  : []),
                ...modelSuggestions.map((model) => ({
                  key: model.id,
                  label:
                    !offersAgentDefault &&
                    model.id === liveModels.defaultModelId
                      ? t(I18nKey.SETTINGS$AGENT_MODEL_IS_AGENT_DEFAULT, {
                          model: model.label,
                        })
                      : model.label,
                })),
                {
                  key: ACP_CUSTOM_MODEL_KEY,
                  label: t(I18nKey.SETTINGS$AGENT_PRESET_CUSTOM),
                },
              ]}
              selectedKey={selectedModelKey}
              onSelectionChange={(key) => {
                if (!key) return;
                const modelKey = String(key);
                if (modelKey === ACP_CUSTOM_MODEL_KEY) {
                  setIsCustomAcpModel(true);
                  setAcpModel("");
                } else if (modelKey === ACP_AGENT_DEFAULT_MODEL_KEY) {
                  setIsCustomAcpModel(false);
                  setAcpModel("");
                } else {
                  setIsCustomAcpModel(false);
                  setAcpModel(modelKey);
                }
              }}
            />
          )}
          {selectedModelKey === ACP_CUSTOM_MODEL_KEY && (
            <SettingsInput
              testId="agent-model-input"
              label={
                showModelSelector
                  ? t(I18nKey.SETTINGS$AGENT_CUSTOM_MODEL)
                  : t(I18nKey.SETTINGS$AGENT_MODEL)
              }
              type="text"
              className="w-full"
              value={acpModel}
              showOptionalTag
              onChange={(value) => {
                setAcpModel(value);
              }}
            />
          )}
          {liveModels.isDiscovering && selectedProvider && (
            <Typography.Text
              testId="agent-model-discovering"
              className="text-xs text-[#717888]"
            >
              {t(I18nKey.SETTINGS$AGENT_MODEL_DISCOVERING, {
                agent: selectedProvider.display_name,
              })}
            </Typography.Text>
          )}
          {liveModels.discovery?.error?.code === "ACPAuthRequired" &&
            selectedProvider && (
              <Typography.Text
                testId="agent-model-discovery-needs-auth"
                className="text-xs text-[#717888]"
              >
                {t(I18nKey.SETTINGS$AGENT_MODEL_DISCOVERY_NEEDS_AUTH, {
                  agent: selectedProvider.display_name,
                })}
              </Typography.Text>
            )}
          {modelListHint && selectedProvider && (
            <Typography.Text
              testId={modelListHint.testId}
              className="text-xs text-[#717888]"
            >
              {t(modelListHint.key, { agent: selectedProvider.display_name })}
            </Typography.Text>
          )}
          <Typography.Text className="text-xs text-[#717888]">
            {t(I18nKey.SETTINGS$AGENT_MODEL_HINT)}
          </Typography.Text>
        </div>
      )}
    </div>
  );
}

/**
 * Legacy `/settings/agent` route. Settings → Agent is now the Agent Profile
 * library (`/settings/agents`), whose editor reuses the named
 * `AgentSettingsScreen` export below; this global-agent-form route is retired
 * and redirects there so old links/bookmarks keep working.
 *
 * Note: This is a route file; only the router should import the default export.
 * React Router's Vite plugin wraps a route's default export with
 * `withComponentProps`, which invokes it with route props and drops any props
 * passed by a parent — so the Agent-profile editor MUST import the named
 * `AgentSettingsScreen` export instead, or `agentSettingsOverride` /
 * `onSaveControlChange` never arrive. Mirrors `LlmSettingsRoute`.
 */
export default function AgentSettingsRoute() {
  return <Navigate to="/settings/agents" replace />;
}

import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { useTranslation } from "react-i18next";
import { useSearchParams } from "react-router";
import AutomationService from "#/api/automation-service/automation-service.api";
import {
  PENDING_AUTOMATION_SETUP_ID,
  getAutomationFormSession,
  initializeAutomationFormSession,
  subscribeAutomationFormSession,
} from "#/api/automation-form-session";
import type { AutomationSetupDraft } from "#/api/automation-setup-types";
import { setupDraftFromServerDraft } from "#/components/features/automations/setup/automation-setup-draft-service";
import { AutomationSetupPanel } from "#/components/features/automations/setup/automation-setup-panel";
import { InteractiveChatBox } from "#/components/features/chat/interactive-chat-box";
import { ComposerDockedProvider } from "#/context/composer-docked-context";
import { useStartAutomationSetup } from "#/hooks/use-start-automation-setup";
import { I18nKey } from "#/i18n/declaration";
import { buildAutomationDraftTags } from "#/utils/automation-draft-tags";
import { setupDraftFromAutomation } from "#/utils/automation-edit-draft";
import { displayErrorToast } from "#/utils/custom-toast-handlers";

const BLANK_DRAFT: AutomationSetupDraft = { prompt: "", kind: "prompt" };

/**
 * New automation form before any conversation exists.
 *
 * The agent drawer stays hidden. Sending the docked prompt is what creates
 * the conversation and reveals the agent.
 */
export default function AutomationSetupNew() {
  const { t } = useTranslation("openhands");
  const [searchParams] = useSearchParams();
  const automationId = searchParams.get("automationId")?.trim() ?? "";
  const draftId = searchParams.get("draftId")?.trim() ?? "";
  const { startConversationFromPrompt, isPending } = useStartAutomationSetup();
  const [toolbarElement, setToolbarElement] = useState<HTMLDivElement | null>(
    null,
  );
  const [composerTarget, setComposerTarget] = useState<HTMLDivElement | null>(
    null,
  );
  const [draft, setDraft] = useState<AutomationSetupDraft | null>(() => {
    const existing = getAutomationFormSession(PENDING_AUTOMATION_SETUP_ID);
    return existing ?? (automationId || draftId ? null : BLANK_DRAFT);
  });

  useEffect(
    () =>
      subscribeAutomationFormSession(PENDING_AUTOMATION_SETUP_ID, (next) => {
        setDraft(next ?? (automationId || draftId ? null : BLANK_DRAFT));
      }),
    [automationId, draftId],
  );

  useEffect(() => {
    const existing = getAutomationFormSession(PENDING_AUTOMATION_SETUP_ID);
    if (existing) {
      setDraft(existing);
      return undefined;
    }

    let cancelled = false;
    const loadDraft = async () => {
      try {
        if (automationId) {
          const automation =
            await AutomationService.getAutomation(automationId);
          const next = setupDraftFromAutomation(automation);
          initializeAutomationFormSession(PENDING_AUTOMATION_SETUP_ID, next);
          if (!cancelled) setDraft(next);
          return;
        }
        if (draftId) {
          const savedDraft = await AutomationService.getServerDraft(draftId);
          const next = setupDraftFromServerDraft(savedDraft);
          initializeAutomationFormSession(PENDING_AUTOMATION_SETUP_ID, next);
          if (!cancelled) setDraft(next);
          return;
        }
        if (!cancelled) setDraft(BLANK_DRAFT);
      } catch (error) {
        if (!cancelled) {
          displayErrorToast(error instanceof Error ? error.message : null);
          setDraft(BLANK_DRAFT);
        }
      }
    };

    void loadDraft();
    return () => {
      cancelled = true;
    };
  }, [automationId, draftId]);

  const title = draft?.form?.name?.trim() || t(I18nKey.AUTOMATION_SETUP$TITLE);
  const conversationTags = draft?.serverDraftId
    ? buildAutomationDraftTags(
        null,
        draft.serverDraftId,
        draft.materializedAutomationId,
      )
    : null;

  return (
    <div className="flex h-full min-h-0 flex-col overflow-hidden bg-canvas-base">
      <header
        data-testid="automation-setup-topbar"
        className="flex h-10 min-h-10 shrink-0 items-center justify-between gap-2 border-b border-[var(--oh-border)] bg-canvas-base px-3"
      >
        <h2 className="min-w-0 truncate text-sm font-medium text-content">
          {title}
        </h2>
        <div
          ref={setToolbarElement}
          data-testid="automation-setup-toolbar"
          className="flex min-w-0 shrink-0 items-center gap-1.5"
        />
      </header>
      <div className="relative flex min-h-0 flex-1 flex-col overflow-hidden">
        {draft ? (
          <AutomationSetupPanel
            draft={draft}
            conversationId={PENDING_AUTOMATION_SETUP_ID}
            conversationTags={conversationTags}
            toolbarPortal={toolbarElement}
            showInlineHeader={false}
            reserveComposerSpace
          />
        ) : (
          <div
            role="status"
            className="flex flex-1 items-center justify-center text-sm text-[var(--oh-muted)]"
          >
            {t(I18nKey.AUTOMATION_SETUP$LOADING_DRAFT)}
          </div>
        )}
        <div className="custom-scrollbar-always pointer-events-none absolute inset-0 z-20 overflow-y-scroll px-5 [scrollbar-gutter:stable] [&::-webkit-scrollbar-thumb]:bg-transparent">
          <div className="relative mx-auto h-full w-full min-w-0 max-w-[800px]">
            <div
              ref={setComposerTarget}
              data-testid="automation-setup-docked-composer"
              className="pointer-events-auto absolute inset-x-0 bottom-5 overflow-visible rounded-[15px] shadow-[0_12px_40px_rgba(0,0,0,0.55)]"
            />
          </div>
        </div>
        {composerTarget
          ? createPortal(
              <ComposerDockedProvider enabled minimal>
                <InteractiveChatBox
                  onSubmit={(content) => startConversationFromPrompt(content)}
                  disabled={isPending || !draft}
                  showGitControlBar={false}
                  placeholder={t(
                    I18nKey.AUTOMATION_SETUP$DOCKED_COMPOSER_PLACEHOLDER,
                  )}
                />
              </ComposerDockedProvider>,
              composerTarget,
            )
          : null}
      </div>
    </div>
  );
}

import React, { useState } from "react";
import { useSearchParams } from "react-router";
import { useTranslation } from "react-i18next";
import { useIsAuthed } from "#/hooks/query/use-is-authed";
import { I18nKey } from "#/i18n/declaration";
import { H1 } from "#/ui/typography";
import { cn } from "#/utils/utils";

export default function DeviceVerify() {
  const { t } = useTranslation("openhands");
  const [searchParams] = useSearchParams();
  const { data: isAuthed, isLoading: isAuthLoading } = useIsAuthed();
  const [verificationResult, setVerificationResult] = useState<{
    success: boolean;
    messageKey: I18nKey;
  } | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const userCode = searchParams.get("user_code");

  const processDeviceVerification = async (code: string) => {
    try {
      setIsProcessing(true);

      const response = await fetch("/oauth/device/verify-authenticated", {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: `user_code=${encodeURIComponent(code)}`,
        credentials: "include",
      });

      if (response.ok) {
        setVerificationResult({
          success: true,
          messageKey: I18nKey.DEVICE$SUCCESS_MESSAGE,
        });
      } else {
        setVerificationResult({
          success: false,
          messageKey: I18nKey.DEVICE$ERROR_FAILED,
        });
      }
    } catch {
      setVerificationResult({
        success: false,
        messageKey: I18nKey.DEVICE$ERROR_OCCURRED,
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleManualSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const code = formData.get("user_code") as string;
    if (code && isAuthed) {
      processDeviceVerification(code);
    }
  };

  if (verificationResult) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="max-w-md w-full mx-auto p-6 bg-surface-raised rounded-lg shadow-lg">
          <div className="text-center">
            <div
              className={cn(
                "mb-4",
                verificationResult.success ? "text-green-600" : "text-red-600",
              )}
            >
              {verificationResult.success ? (
                <svg
                  className="w-12 h-12 mx-auto"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M5 13l4 4L19 7"
                  />
                </svg>
              ) : (
                <svg
                  className="w-12 h-12 mx-auto"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              )}
            </div>
            <h2 className="text-xl font-medium mb-2">
              {verificationResult.success
                ? t(I18nKey.DEVICE$SUCCESS_TITLE)
                : t(I18nKey.DEVICE$ERROR_TITLE)}
            </h2>
            <p className="text-muted mb-4">
              {t(verificationResult.messageKey)}
            </p>
            {!verificationResult.success && (
              <button
                type="button"
                onClick={() => window.location.reload()}
                className="px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90"
              >
                {t(I18nKey.DEVICE$TRY_AGAIN)}
              </button>
            )}
          </div>
        </div>
      </div>
    );
  }

  if (isProcessing) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="max-w-md w-full mx-auto p-6 bg-surface-raised rounded-lg shadow-lg">
          <div className="text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-contrast mx-auto mb-4" />
            <p className="text-muted">{t(I18nKey.DEVICE$PROCESSING)}</p>
          </div>
        </div>
      </div>
    );
  }

  if (isAuthed && userCode) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background p-4">
        <div className="flex flex-col items-center gap-6 w-full max-w-md">
          <div className="flex-1 min-w-0 max-w-md w-full mx-auto p-6 bg-surface-raised rounded-2xl shadow-lg border border-border-subtle">
            <H1 className="text-2xl mb-4 text-center">
              {t(I18nKey.DEVICE$AUTHORIZATION_REQUEST)}
            </H1>
            <div className="mb-6 p-4 bg-canvas-base rounded-lg border border-border-subtle">
              <p className="text-xs text-text-subtle mb-2 text-center uppercase tracking-wider">
                {t(I18nKey.DEVICE$CODE_LABEL)}
              </p>
              <p className="text-xl font-mono font-semibold text-center tracking-[0.3em]">
                {userCode}
              </p>
            </div>
            <div className="mb-6 p-4 bg-amber-950/50 border-l-2 border-amber-500 rounded-r-lg">
              <p className="text-sm font-medium text-amber-500 mb-1">
                {t(I18nKey.DEVICE$SECURITY_NOTICE)}
              </p>
              <p className="text-sm text-muted">
                {t(I18nKey.DEVICE$SECURITY_WARNING)}
              </p>
            </div>
            <p className="text-muted mb-6 text-center">
              {t(I18nKey.DEVICE$CONFIRM_PROMPT)}
            </p>
            <div className="flex gap-3">
              <button
                type="button"
                onClick={() => window.close()}
                className="flex-1 px-4 py-2 border border-border rounded-md hover:bg-muted text-text-tertiary"
              >
                {t(I18nKey.DEVICE$CANCEL)}
              </button>
              <button
                type="button"
                onClick={() => processDeviceVerification(userCode)}
                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700"
              >
                {t(I18nKey.DEVICE$AUTHORIZE)}
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (isAuthed && !userCode) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="max-w-md w-full mx-auto p-6 bg-surface-raised rounded-lg shadow-lg">
          <H1 className="text-2xl mb-4 text-center">
            {t(I18nKey.DEVICE$AUTHORIZATION_TITLE)}
          </H1>
          <p className="text-muted mb-6 text-center">
            {t(I18nKey.DEVICE$ENTER_CODE_PROMPT)}
          </p>
          <form onSubmit={handleManualSubmit}>
            <div className="mb-4">
              <label
                htmlFor="user_code"
                className="block text-sm font-medium mb-2"
              >
                {t(I18nKey.DEVICE$CODE_INPUT_LABEL)}
              </label>
              <input
                type="text"
                id="user_code"
                name="user_code"
                required
                className="w-full px-3 py-2 border border-border-input rounded-md focus:outline-none focus:ring-2 focus:ring-focus"
                placeholder={t(I18nKey.DEVICE$CODE_PLACEHOLDER)}
              />
            </div>
            <button
              type="submit"
              className="w-full px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90"
            >
              {t(I18nKey.DEVICE$CONTINUE)}
            </button>
          </form>
        </div>
      </div>
    );
  }

  if (isAuthLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="text-center">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-contrast mx-auto mb-4" />
          <p className="text-muted">{t(I18nKey.DEVICE$PROCESSING)}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-background">
      <div className="max-w-md w-full mx-auto p-6 bg-surface-raised rounded-lg shadow-lg text-center">
        <H1 className="text-2xl mb-4">{t(I18nKey.DEVICE$AUTH_REQUIRED)}</H1>
        <p className="text-muted">{t(I18nKey.DEVICE$SIGN_IN_PROMPT)}</p>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { useQueryClient } from "@tanstack/react-query";

import { NoFileSelectedMessage } from "#/components/features/files-tab/no-file-selected-message";
import { I18nKey } from "#/i18n/declaration";
import { useFilesTabStore } from "#/stores/files-tab-store";
import { useWorkspaceFiles } from "#/hooks/query/use-workspace-files";
import { useWorkspaceFileContent } from "#/hooks/query/use-workspace-file-content";
import { useAutoRefreshFilesOnEdit } from "#/hooks/use-auto-refresh-files-on-edit";
import { useOptionalConversationId } from "#/hooks/use-conversation-id";
import { useResizableDrawerWidth } from "#/hooks/use-resizable-drawer-width";
import {
  getConversationState,
  useConversationLocalStorageState,
} from "#/utils/conversation-local-storage";
import {
  useWorkspaceMutationCounter,
  withWorkspaceCacheBuster,
} from "#/stores/use-workspace-mutation-counter";
import { FileQuickRow } from "#/components/features/files-tab/file-quick-row";
import { FileTreeView } from "#/components/features/files-tab/file-tree-view";
import { FileContentViewer } from "#/components/features/files-tab/file-content-viewer";
import { SegmentedToggle } from "#/components/features/files-tab/segmented-toggle";
import { WorkspacePath } from "#/components/features/files-tab/workspace-path";
import { WorkspaceFileDiscoverySettings } from "#/components/features/files-tab/workspace-file-discovery-settings";
import type { ViewMode } from "#/components/features/files-tab/view-mode";
import {
  FILES_TAB_TREE_DEFAULT_WIDTH_PX,
  FILES_TAB_TREE_MAX_WIDTH_PX,
  FILES_TAB_TREE_MIN_WIDTH_PX,
  FILES_TAB_TREE_RESIZE_HANDLE_TEST_ID,
  FILES_TAB_TREE_WIDTH_STORAGE_KEY,
} from "#/components/features/files-tab/files-tab-tree.constants";
import { ResizeHandle } from "#/components/ui/resize-handle";
import RefreshIcon from "#/icons/u-refresh.svg?react";
import LinkExternalIcon from "#/icons/link-external.svg?react";
import { useActiveConversation } from "#/hooks/query/use-active-conversation";

/**
 * Workspace file browser. Diff/Commits live in the sibling Commits
 * conversation tab — this surface is only the file tree / content viewer.
 */
function FilesTab() {
  const { t } = useTranslation("openhands");

  // Keep the list / content caches fresh as the agent writes files.
  useAutoRefreshFilesOnEdit();

  const { data: activeConversation } = useActiveConversation();
  const workspacePath = activeConversation?.workspace?.working_dir;

  const { conversationId } = useOptionalConversationId();
  const {
    state: persistedState,
    setFilesTabContentViewMode,
    setFilesTabTreeVisible,
  } = useConversationLocalStorageState(conversationId ?? "");
  const contentViewMode = persistedState.filesTabContentViewMode;
  const isTreeVisible = persistedState.filesTabTreeVisible ?? true;
  const toggleTreeVisible = useCallback(() => {
    setFilesTabTreeVisible?.(!isTreeVisible);
  }, [isTreeVisible, setFilesTabTreeVisible]);

  const treeLayoutRef = useRef<HTMLDivElement>(null);
  const {
    drawerWidth: treeWidth,
    isDragging: isTreeResizing,
    handleMouseDown: handleTreeResizeMouseDown,
  } = useResizableDrawerWidth({
    containerRef: treeLayoutRef,
    defaultWidth: FILES_TAB_TREE_DEFAULT_WIDTH_PX,
    minWidth: FILES_TAB_TREE_MIN_WIDTH_PX,
    maxWidth: FILES_TAB_TREE_MAX_WIDTH_PX,
    storageKey: FILES_TAB_TREE_WIDTH_STORAGE_KEY,
    enabled: isTreeVisible,
    edge: "left",
  });

  const filesQuery = useWorkspaceFiles();
  const paths = useMemo(() => filesQuery.data ?? [], [filesQuery.data]);

  const storedSelectedPath = useFilesTabStore((s) => s.selectedPath);
  const selectedConversationId = useFilesTabStore(
    (s) => s.selectedConversationId,
  );
  const openPaths = useFilesTabStore((s) => s.openPaths);
  const setSelectedPath = useFilesTabStore((s) => s.setSelectedPath);
  const closeOpenPath = useFilesTabStore((s) => s.closeOpenPath);
  const hydrateForConversation = useFilesTabStore(
    (s) => s.hydrateForConversation,
  );

  // A selection is scoped to the conversation it was made in. Ignore a path
  // that belongs to a different conversation so we never try to open a file
  // that only exists in the previous conversation's workspace (issue #1350).
  const selectedPath =
    selectedConversationId === conversationId ? storedSelectedPath : null;
  const conversationOpenPaths =
    selectedConversationId === conversationId ? openPaths : [];

  // Tag every selection with the active conversation so it can't leak into
  // the next one. Opening a path also appends it to the tab strip.
  const handleSelectFile = useCallback(
    (path: string) => setSelectedPath(path, conversationId),
    [conversationId, setSelectedPath],
  );

  // Pre-fetch the selected file's content here too so the toolbar's
  // "open in new window" link can reach for its `staticUrl`. react-query
  // dedupes against `FileContentViewer`'s identical call, so this costs
  // nothing extra.
  const selectedFileContent = useWorkspaceFileContent(selectedPath);
  const mutationCounter = useWorkspaceMutationCounter((state) => state.count);
  const bumpWorkspaceMutationCounter = useWorkspaceMutationCounter(
    (state) => state.bump,
  );
  const selectedFileStaticUrl = withWorkspaceCacheBuster(
    selectedFileContent.data?.staticUrl ?? null,
    mutationCounter,
  );

  // Restore open tabs / selection from conversation-scoped localStorage on
  // mount and when switching conversations (survives a full page refresh).
  // Read localStorage directly — the React hook mirror can briefly hold the
  // previous conversation's state until its sync effect runs.
  useEffect(() => {
    if (!conversationId) return;
    if (selectedConversationId === conversationId) return;
    const persisted = getConversationState(conversationId);
    hydrateForConversation(
      conversationId,
      persisted.filesTabOpenPaths ?? [],
      persisted.filesTabSelectedPath ?? null,
    );
  }, [conversationId, selectedConversationId, hydrateForConversation]);

  const queryClient = useQueryClient();
  const [isRefreshing, setIsRefreshing] = useState(false);
  const refreshFiles = async () => {
    setIsRefreshing(true);
    // Bumping the counter re-keys every `workspace-file-content` query, so
    // the open file refetches, and gives the rich preview's <iframe>/<img> a
    // new `?v=` URL: the only way to make them skip a cached response.
    bumpWorkspaceMutationCounter();
    try {
      await queryClient.invalidateQueries({ queryKey: ["workspace-files"] });
    } finally {
      setIsRefreshing(false);
    }
  };

  const quickRowActions = (
    <>
      <WorkspaceFileDiscoverySettings workingDir={workspacePath?.trim()} />
      <button
        type="button"
        onClick={refreshFiles}
        disabled={isRefreshing}
        aria-label={t(I18nKey.FILES$REFRESH)}
        title={t(I18nKey.FILES$REFRESH)}
        data-testid="files-tab-refresh"
        className="flex items-center justify-center w-6.5 py-1 rounded-[7px] hover:enabled:bg-interactive-hover cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
      >
        <RefreshIcon
          width={12.75}
          height={15}
          color="#ffffff"
          className={isRefreshing ? "animate-spin" : ""}
        />
      </button>
    </>
  );

  return (
    <main
      className="h-full w-full flex flex-col items-stretch"
      data-testid="files-tab"
    >
      <WorkspacePath path={workspacePath} />
      {filesQuery.isTruncated && (
        <p
          role="status"
          className="border-b border-border px-3 py-2 text-xs text-muted"
        >
          {t(I18nKey.FILES$DISCOVERY_TRUNCATED, { count: paths.length })}
        </p>
      )}
      {filesQuery.isLoading ? (
        <div className="flex flex-1 items-center justify-center text-sm text-muted">
          {t(I18nKey.FILES$LOADING_FILES)}
        </div>
      ) : (
        <>
          <FileQuickRow
            openPaths={conversationOpenPaths}
            selectedPath={selectedPath}
            onSelectFile={handleSelectFile}
            onCloseFile={closeOpenPath}
            isTreeVisible={isTreeVisible}
            onToggleTree={toggleTreeVisible}
            actions={quickRowActions}
          />
          <div ref={treeLayoutRef} className="flex h-full min-h-0 flex-1">
            {isTreeVisible && (
              <>
                <aside
                  className="shrink-0 border-r border-border overflow-y-auto custom-scrollbar-always"
                  data-testid="files-tab-tree"
                  style={{ width: `${treeWidth}px` }}
                >
                  <FileTreeView
                    paths={paths}
                    selectedPath={selectedPath}
                    onSelectFile={handleSelectFile}
                  />
                </aside>
                <ResizeHandle
                  testId={FILES_TAB_TREE_RESIZE_HANDLE_TEST_ID}
                  onMouseDown={handleTreeResizeMouseDown}
                  isDragging={isTreeResizing}
                />
              </>
            )}
            <section
              className="flex h-full min-h-0 min-w-0 flex-1 flex-col"
              data-testid="files-tab-content"
            >
              {selectedPath ? (
                <>
                  <div className="flex items-center gap-3 px-3 py-1.5 border-b border-border">
                    <SegmentedToggle<ViewMode>
                      ariaLabel={t(I18nKey.FILES$RICH)}
                      testId="files-tab-content-mode-toggle"
                      value={contentViewMode}
                      options={[
                        { value: "rich", label: t(I18nKey.FILES$RICH) },
                        { value: "plain", label: t(I18nKey.FILES$PLAIN) },
                      ]}
                      onChange={setFilesTabContentViewMode}
                    />
                    {selectedFileStaticUrl ? (
                      <a
                        href={selectedFileStaticUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        aria-label={t(I18nKey.FILES$OPEN_IN_NEW_WINDOW)}
                        title={t(I18nKey.FILES$OPEN_IN_NEW_WINDOW)}
                        data-testid="files-tab-open-in-new-window"
                        className="ml-auto flex items-center justify-center w-6.5 py-1 rounded-[7px] hover:bg-interactive-hover cursor-pointer text-contrast"
                      >
                        <LinkExternalIcon width={14} height={14} />
                      </a>
                    ) : null}
                  </div>
                  <FileContentViewer
                    path={selectedPath}
                    viewMode={contentViewMode}
                  />
                </>
              ) : (
                <NoFileSelectedMessage />
              )}
            </section>
          </div>
        </>
      )}
    </main>
  );
}

export default FilesTab;

import React from "react";
import { useNavigate, useSearchParams } from "react-router";
import { useTranslation } from "react-i18next";
import { PluginLaunchModal } from "#/components/features/launch/plugin-launch-modal";
import { PluginSpec } from "#/api/conversation-service/agent-server-conversation-service.types";
import { useCreateConversation } from "#/hooks/mutation/use-create-conversation";
import { I18nKey } from "#/i18n/declaration";

type ErrorType = "no_plugins" | "invalid_format" | "creation_failed";

interface ParseResult {
  plugins: PluginSpec[];
  message?: string;
  error?: ErrorType;
}

function sanitizeMessage(message: string | null): string | undefined {
  if (!message) return undefined;
  // Strip ALL HTML tags for plain text display
  const stripped = message.replace(/<[^>]*>/g, "").slice(0, 500);
  return stripped || undefined;
}

function parsePluginsFromUrl(searchParams: URLSearchParams): ParseResult {
  // Try base64 encoded plugins parameter first (production format)
  const pluginsParam = searchParams.get("plugins");
  if (pluginsParam) {
    try {
      const decoded = atob(pluginsParam);
      const parsed = JSON.parse(decoded);

      if (!Array.isArray(parsed)) {
        return { plugins: [], error: "invalid_format" };
      }

      // Validate each plugin has at least a source
      const validPlugins: PluginSpec[] = [];
      for (const item of parsed) {
        if (
          typeof item !== "object" ||
          !item ||
          typeof item.source !== "string"
        ) {
          return { plugins: [], error: "invalid_format" };
        }
        validPlugins.push({
          source: item.source,
          ref: item.ref ?? null,
          repo_path: item.repo_path ?? null,
          parameters: item.parameters ?? null,
        });
      }

      if (validPlugins.length === 0) {
        return { plugins: [], error: "no_plugins" };
      }

      return {
        plugins: validPlugins,
        message: sanitizeMessage(searchParams.get("message")),
      };
    } catch {
      return { plugins: [], error: "invalid_format" };
    }
  }

  // Fallback: simple params format for dev/testing
  const pluginSource = searchParams.get("plugin_source");
  if (pluginSource) {
    const plugin: PluginSpec = {
      source: pluginSource,
      ref: searchParams.get("plugin_ref") ?? null,
      repo_path: searchParams.get("plugin_repo_path") ?? null,
      parameters: null,
    };
    return {
      plugins: [plugin],
      message: sanitizeMessage(searchParams.get("message")),
    };
  }

  return { plugins: [], error: "no_plugins" };
}

function ErrorDisplay({
  errorType,
  onGoHome,
  onTryAgain,
}: {
  errorType: ErrorType;
  onGoHome: () => void;
  onTryAgain?: () => void;
}) {
  const { t } = useTranslation("openhands");

  const errorMessages: Record<ErrorType, string> = {
    no_plugins: t(I18nKey.LAUNCH$ERROR_NO_PLUGINS),
    invalid_format: t(I18nKey.LAUNCH$ERROR_INVALID_FORMAT),
    creation_failed: t(I18nKey.LAUNCH$ERROR_CREATION_FAILED),
  };

  return (
    <div
      className="flex h-full items-center justify-center"
      data-testid="launch-error"
    >
      <div className="max-w-md rounded-lg bg-surface p-6 text-center">
        <h2 className="mb-4 text-xl font-medium text-red-400">
          {t(I18nKey.LAUNCH$ERROR_TITLE)}
        </h2>
        <p className="mb-6 text-text-tertiary">{errorMessages[errorType]}</p>
        <div className="flex justify-center gap-3">
          <button
            type="button"
            onClick={onGoHome}
            className="rounded-md bg-tertiary px-4 py-2 text-sm text-foreground hover:bg-interactive-hover"
            data-testid="go-home-button"
          >
            {t(I18nKey.LAUNCH$GO_HOME)}
          </button>
          {onTryAgain && (
            <button
              type="button"
              onClick={onTryAgain}
              className="rounded-md bg-blue-600 px-4 py-2 text-sm text-white hover:bg-blue-700"
              data-testid="try-again-button"
            >
              {t(I18nKey.LAUNCH$TRY_AGAIN)}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

export default function LaunchRoute() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { t } = useTranslation("openhands");
  const createConversation = useCreateConversation();

  const [creationError, setCreationError] = React.useState<string | null>(null);

  const parseResult = React.useMemo(
    () => parsePluginsFromUrl(searchParams),
    [searchParams],
  );

  const handleStartConversation = async (
    plugins: PluginSpec[],
    initialMessage?: string,
  ) => {
    setCreationError(null);
    try {
      const result = await createConversation.mutateAsync({
        plugins,
        query: initialMessage,
        entryPoint: "launch_deeplink",
      });
      navigate(`/conversations/${result.conversation_id}`);
    } catch {
      setCreationError(t(I18nKey.LAUNCH$ERROR_CREATION_UNKNOWN));
    }
  };

  const handleGoHome = () => {
    navigate("/conversations");
  };

  const handleTryAgain = () => {
    setCreationError(null);
    window.location.reload();
  };

  // Show error if parsing failed
  if (parseResult.error) {
    return (
      <ErrorDisplay errorType={parseResult.error} onGoHome={handleGoHome} />
    );
  }

  // Show error if conversation creation failed
  if (creationError) {
    return (
      <ErrorDisplay
        errorType="creation_failed"
        onGoHome={handleGoHome}
        onTryAgain={handleTryAgain}
      />
    );
  }

  return (
    <div className="h-full" data-testid="launch-route">
      <PluginLaunchModal
        plugins={parseResult.plugins}
        message={parseResult.message}
        isLoading={createConversation.isPending}
        onStartConversation={handleStartConversation}
        onClose={handleGoHome}
      />
    </div>
  );
}

