import { useTranslation } from "react-i18next";
import { MetaLlmSettingsView } from "#/components/features/settings/meta-llm-profiles";
import { useActiveBackend } from "#/contexts/active-backend-context";
import { I18nKey } from "#/i18n/declaration";

/**
 * Settings route for managing *meta-profiles* — declarative model-routing
 * configurations consumed by the agent's ``route_task_to_model`` tool.
 *
 * Local backends store meta-profiles on the agent-server. Organization-bound
 * cloud backends store them in the SaaS control plane and pass the active
 * configuration inline to ephemeral runtimes.
 *
 * Note: This is a route file, only the router should import the default export.
 */
export default function MetaLlmSettingsRoute() {
  const { t } = useTranslation("openhands");
  const { backend, orgId } = useActiveBackend();

  if (backend.kind === "cloud" && !orgId) {
    return (
      <p
        data-testid="meta-profile-cloud-unsupported"
        className="text-sm text-[var(--oh-muted)]"
      >
        {t(I18nKey.SETTINGS$META_PROFILE_CLOUD_UNSUPPORTED)}
      </p>
    );
  }

  return <MetaLlmSettingsView />;
}

import React, { useState } from "react";
import { useCombobox } from "downshift";
import { cn } from "#/utils/utils";
import { DropdownOption } from "./types";
import { dropdownTriggerShellClassName } from "#/utils/dropdown-classes";
import { LoadingSpinner } from "./loading-spinner";
import { ClearButton } from "./clear-button";
import { ToggleButton } from "./toggle-button";
import { DropdownMenu } from "./dropdown-menu";
import { DropdownInput } from "./dropdown-input";

// Equivalent to Tailwind's `sr-only`, inlined so we don't depend on the
// utility class being preserved by the host project's CSS pipeline.
const visuallyHiddenStyle: React.CSSProperties = {
  position: "absolute",
  width: 1,
  height: 1,
  padding: 0,
  margin: -1,
  overflow: "hidden",
  clip: "rect(0, 0, 0, 0)",
  whiteSpace: "nowrap",
  border: 0,
};

interface DropdownProps {
  options: DropdownOption[];
  emptyMessage?: string;
  clearable?: boolean;
  loading?: boolean;
  disabled?: boolean;
  placeholder?: string;
  defaultValue?: DropdownOption;
  onChange?: (item: DropdownOption | null) => void;
  testId?: string;
  className?: string;
  footer?: React.ReactNode;
  openUpward?: boolean;
  hideTrigger?: boolean;
  defaultOpen?: boolean;
  /** Open the dropdown menu on hover instead of requiring a click. */
  openOnHover?: boolean;
  /** When false, the combobox placeholder uses normal (non-italic) type. */
  italicPlaceholder?: boolean;
  /** Size the trigger to its label instead of stretching to the container width. */
  fitContent?: boolean;
}

export function Dropdown({
  options,
  emptyMessage = "No options",
  clearable = false,
  loading = false,
  disabled = false,
  placeholder,
  defaultValue,
  onChange,
  testId,
  className,
  footer,
  openUpward = false,
  hideTrigger = false,
  defaultOpen = false,
  openOnHover = false,
  italicPlaceholder = true,
  fitContent = false,
}: DropdownProps) {
  const closeTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(
    null,
  );
  const [inputValue, setInputValue] = useState(defaultValue?.label ?? "");
  const [searchTerm, setSearchTerm] = useState("");

  React.useEffect(
    () => () => {
      if (closeTimerRef.current) {
        clearTimeout(closeTimerRef.current);
        closeTimerRef.current = null;
      }
    },
    [],
  );

  const filteredOptions = options.filter((option) =>
    option.label.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  const {
    isOpen,
    selectedItem,
    selectItem,
    openMenu,
    closeMenu,
    getToggleButtonProps,
    getMenuProps,
    getItemProps,
    getInputProps,
  } = useCombobox({
    items: filteredOptions,
    itemToString: (item) => item?.label ?? "",
    inputValue,
    stateReducer: (state, actionAndChanges) =>
      actionAndChanges.type === useCombobox.stateChangeTypes.InputClick &&
      state.isOpen
        ? { ...actionAndChanges.changes, isOpen: true }
        : actionAndChanges.changes,
    initialIsOpen: defaultOpen,
    onInputValueChange: ({ inputValue: newValue }) => {
      setInputValue(newValue ?? "");
      setSearchTerm(newValue ?? "");
    },
    defaultSelectedItem: defaultValue,
    onSelectedItemChange: ({ selectedItem: newSelectedItem }) => {
      onChange?.(newSelectedItem ?? null);
    },
    onIsOpenChange: ({
      isOpen: newIsOpen,
      selectedItem: currentSelectedItem,
    }) => {
      if (newIsOpen) {
        // Clear the input on open so the user sees an empty search box
        // (with the placeholder reminding them of the current value)
        // and the full options list. Otherwise the active label would
        // appear both in the trigger AND as the highlighted menu row.
        setInputValue("");
        setSearchTerm("");
      } else {
        setInputValue(currentSelectedItem?.label ?? "");
        setSearchTerm("");
      }
    },
  });

  const isDisabled = loading || disabled;

  // `selectedItem` is downshift's internal state, frozen to whatever
  // initialized it. Resolve the currently selected option against the
  // live `options` array so per-option fields like `prefix` (e.g. a
  // status indicator that re-renders on a timer) update on the trigger
  // without remounting the dropdown.
  const liveSelectedOption = selectedItem
    ? (options.find((o) => o.value === selectedItem.value) ?? selectedItem)
    : null;

  // Wrap getInputProps to inject a direct onChange handler that preserves
  // cursor position. Downshift's default onInputValueChange resets cursor
  // to end of input on every keystroke; reading from e.target.value keeps
  // the browser's native cursor position intact.
  const getInputPropsWithCursorFix = (props?: object) =>
    getInputProps({
      ...props,
      onChange: (e: React.ChangeEvent<HTMLInputElement>) => {
        setInputValue(e.target.value);
        setSearchTerm(e.target.value);
      },
    });

  return (
    <div
      className={cn("relative", fitContent ? "inline-block w-auto" : "w-full")}
      data-testid={testId}
      onMouseEnter={
        openOnHover
          ? () => {
              if (closeTimerRef.current) {
                clearTimeout(closeTimerRef.current);
                closeTimerRef.current = null;
              }
              openMenu();
            }
          : undefined
      }
      onMouseLeave={
        openOnHover
          ? () => {
              if (closeTimerRef.current) {
                clearTimeout(closeTimerRef.current);
              }
              closeTimerRef.current = setTimeout(() => closeMenu(), 150);
            }
          : undefined
      }
    >
      {!hideTrigger ? (
        <div
          className={cn(
            dropdownTriggerShellClassName,
            fitContent ? "w-auto" : "w-full",
            isDisabled && "cursor-not-allowed opacity-60",
            className,
          )}
        >
          {liveSelectedOption?.prefix ? (
            <span className="flex items-center shrink-0">
              {liveSelectedOption.prefix}
            </span>
          ) : null}
          <DropdownInput
            placeholder={placeholder}
            isDisabled={isDisabled}
            getInputProps={getInputPropsWithCursorFix}
            italicPlaceholder={italicPlaceholder}
            fitContent={fitContent}
          />
          {loading && <LoadingSpinner />}
          {clearable && selectedItem && (
            <ClearButton onClear={() => selectItem(null)} />
          )}
          <ToggleButton
            isOpen={isOpen}
            isDisabled={isDisabled}
            getToggleButtonProps={getToggleButtonProps}
          />
        </div>
      ) : (
        // downshift's useCombobox always expects getInputProps() (and the
        // toggle button) to be wired up. When the trigger is hidden (e.g.
        // collapsed-sidebar popover) we still need to mount a real input
        // so it stops warning every render. Keep it visually hidden but
        // present in the DOM for accessibility.
        <>
          <input
            {...getInputPropsWithCursorFix({
              // eslint-disable-next-line i18next/no-literal-string -- i18n-free UI primitive; callers supply translated labels
              "aria-label": placeholder ?? "Filter options",
              tabIndex: -1,
            })}
            style={visuallyHiddenStyle}
          />
          <button
            type="button"
            {...getToggleButtonProps({ tabIndex: -1 })}
            style={visuallyHiddenStyle}
            aria-hidden
          />
        </>
      )}
      <DropdownMenu
        isOpen={isOpen}
        filteredOptions={filteredOptions}
        selectedItem={selectedItem}
        emptyMessage={emptyMessage}
        getMenuProps={getMenuProps}
        getItemProps={getItemProps}
        footer={footer}
        openUpward={openUpward}
        fitContent={fitContent}
      />
    </div>
  );
}

import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "#/utils/utils";

const preVariants = cva("whitespace-pre-wrap", {
  variants: {
    size: {
      default: "text-sm",
      small: "text-xs",
    },
    font: {
      default: "",
      mono: "font-mono",
    },
    lineHeight: {
      default: "",
      relaxed: "leading-relaxed",
    },
    background: {
      default: "",
      dark: "bg-canvas-base",
    },
    textColor: {
      default: "",
      light: "text-text-tertiary",
    },
    padding: {
      default: "",
      medium: "p-3",
      large: "px-5",
    },
    borderRadius: {
      default: "",
      medium: "rounded-md",
    },
    shadow: {
      default: "",
      inner: "shadow-inner",
    },
    maxHeight: {
      default: "",
      small: "max-h-100",
      large: "max-h-[60vh]",
    },
    overflow: {
      default: "",
      auto: "overflow-auto",
    },
  },
  defaultVariants: {
    size: "default",
    font: "default",
    lineHeight: "default",
    background: "default",
    textColor: "default",
    padding: "default",
    borderRadius: "default",
    shadow: "default",
    maxHeight: "default",
    overflow: "default",
  },
});

interface PreProps extends VariantProps<typeof preVariants> {
  className?: string;
  testId?: string;
  children: React.ReactNode;
}

export function Pre({
  size,
  font,
  lineHeight,
  background,
  textColor,
  padding,
  borderRadius,
  shadow,
  maxHeight,
  overflow,
  className,
  testId,
  children,
}: PreProps) {
  return (
    <pre
      data-testid={testId}
      className={cn(
        preVariants({
          size,
          font,
          lineHeight,
          background,
          textColor,
          padding,
          borderRadius,
          shadow,
          maxHeight,
          overflow,
        }),
        className,
      )}
    >
      {children}
    </pre>
  );
}

import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "#/utils/utils";

const typographyVariants = cva("", {
  variants: {
    variant: {
      h1: "text-[32px] text-contrast font-medium leading-5",
      h2: "text-xl font-medium leading-6 -tracking-[0.02em] text-contrast",
      h3: "text-sm font-medium text-text-tertiary",
      span: "text-sm font-normal text-contrast leading-5.5",
      p: "text-sm font-normal text-contrast leading-5.5",
      codeBlock:
        "font-mono text-sm leading-relaxed text-text-tertiary whitespace-pre-wrap",
    },
  },
  defaultVariants: {
    variant: "h1",
  },
});

interface TypographyProps extends VariantProps<typeof typographyVariants> {
  className?: string;
  testId?: string;
  children: React.ReactNode;
}

export function Typography({
  variant,
  className,
  testId,
  children,
}: TypographyProps) {
  const Tag = variant as keyof React.JSX.IntrinsicElements;

  return (
    <Tag
      data-testid={testId}
      className={cn(typographyVariants({ variant }), className)}
    >
      {children}
    </Tag>
  );
}

// Export individual heading components for convenience
export function H1({
  className,
  testId,
  children,
}: Omit<TypographyProps, "variant">) {
  return (
    <Typography variant="h1" className={className} testId={testId}>
      {children}
    </Typography>
  );
}

export function H2({
  className,
  testId,
  children,
}: Omit<TypographyProps, "variant">) {
  return (
    <Typography variant="h2" className={className} testId={testId}>
      {children}
    </Typography>
  );
}

export function H3({
  className,
  testId,
  children,
}: Omit<TypographyProps, "variant">) {
  return (
    <Typography variant="h3" className={className} testId={testId}>
      {children}
    </Typography>
  );
}

export function Text({
  className,
  testId,
  children,
}: Omit<TypographyProps, "variant">) {
  return (
    <Typography variant="span" className={className} testId={testId}>
      {children}
    </Typography>
  );
}

export function CodeBlock({
  className,
  testId,
  children,
}: Omit<TypographyProps, "variant">) {
  return (
    <Typography variant="codeBlock" className={className} testId={testId}>
      {children}
    </Typography>
  );
}

export function Paragraph({
  className,
  testId,
  children,
}: Omit<TypographyProps, "variant">) {
  return (
    <Typography variant="p" className={className} testId={testId}>
      {children}
    </Typography>
  );
}

// Attach components to Typography for the expected API
Typography.H1 = H1;
Typography.H2 = H2;
Typography.H3 = H3;
Typography.Text = Text;
Typography.CodeBlock = CodeBlock;
Typography.Paragraph = Paragraph;

import React, { CSSProperties, ReactNode } from "react";
import { CircleX } from "lucide-react";
import toast, { ToastOptions } from "react-hot-toast";
import { OH_STATUS_ERROR_COLOR } from "#/constants/status-colors";
import { calculateToastDuration } from "./toast-duration";
import { cn } from "#/utils/utils";
import i18n from "#/i18n";
import { I18nKey } from "#/i18n/declaration";
import {
  isBackendRequestTimeoutMessage,
  isCorsOrNetworkErrorMessage,
} from "./user-facing-error";
import { buildAgentCanvasPath } from "#/utils/base-path";
import {
  getApiOrConnectionErrorMessage,
  hasApiErrorResponse,
} from "./api-error-message";

// react-hot-toast accepts only CSSProperties via the style option — cannot use className
const TOAST_STYLE: CSSProperties = {
  background: "var(--oh-color-tertiary)",
  border: "1px solid var(--oh-border-input)",
  color: "#fff",
  borderRadius: "var(--oh-radius)",
  maxWidth: "400px",
  wordBreak: "break-word",
  overflowWrap: "anywhere",
  whiteSpace: "pre-wrap",
};

export const TOAST_OPTIONS: ToastOptions = {
  position: "top-right",
  style: TOAST_STYLE,
};

const ERROR_TOAST_STYLE: CSSProperties = {
  ...TOAST_STYLE,
  color: "var(--oh-muted)",
};

/** Icon + message row; center icon for single-line text, top-align when wrapped. */
export function ErrorToastContent({ message }: { message: ReactNode }) {
  const contentRef = React.useRef<HTMLSpanElement>(null);
  const [isMultiLine, setIsMultiLine] = React.useState(false);

  React.useLayoutEffect(() => {
    const content = contentRef.current;
    if (!content) {
      return undefined;
    }

    const updateIsMultiLine = () => {
      const lineHeight = Number.parseFloat(
        getComputedStyle(content).lineHeight,
      );
      if (!Number.isFinite(lineHeight) || lineHeight <= 0) {
        setIsMultiLine(false);
        return;
      }

      setIsMultiLine(content.getBoundingClientRect().height > lineHeight * 1.5);
    };

    updateIsMultiLine();

    const observer = new ResizeObserver(updateIsMultiLine);
    observer.observe(content);

    return () => observer.disconnect();
  }, [message]);

  return (
    <div
      className={cn(
        "flex min-w-0 gap-2",
        isMultiLine ? "items-start" : "items-center",
      )}
    >
      <CircleX
        aria-hidden
        className="h-4 w-4 shrink-0"
        strokeWidth={2}
        style={{ color: OH_STATUS_ERROR_COLOR }}
      />
      <span
        ref={contentRef}
        className="min-w-0 flex-1 text-sm leading-5 [word-break:break-word] [overflow-wrap:anywhere]"
      >
        {message}
      </span>
    </div>
  );
}

export const ERROR_TOAST_OPTIONS: ToastOptions = {
  ...TOAST_OPTIONS,
  icon: null,
  style: ERROR_TOAST_STYLE,
};

function showErrorToast(message: string) {
  const duration = calculateToastDuration(message, 4000);
  toast(<ErrorToastContent message={message} />, {
    ...ERROR_TOAST_OPTIONS,
    duration,
  });
}

export const displayErrorToast = (error: string | null | undefined) => {
  let errorMessage = error || i18n.t(I18nKey.STATUS$ERROR);
  if (isCorsOrNetworkErrorMessage(errorMessage)) {
    errorMessage = i18n.t(I18nKey.ERROR$CORS_OR_NETWORK);
  } else if (isBackendRequestTimeoutMessage(errorMessage)) {
    errorMessage = i18n.t(I18nKey.ERROR$BACKEND_REQUEST_TIMEOUT);
  }
  showErrorToast(errorMessage);
};

/**
 * Toast a failed API call. When the server answered, its own reason (see
 * `getApiErrorMessage`) is shown as sent, even if it happens to mention
 * "Failed to fetch"; only a failure with no response (network, CORS, timeout)
 * gets the shared "Disconnected" wording.
 */
export const displayApiErrorToast = (error: unknown, fallback: string) => {
  const message = getApiOrConnectionErrorMessage(error, fallback);
  if (hasApiErrorResponse(error)) {
    showErrorToast(message);
  } else {
    displayErrorToast(message);
  }
};

export const displaySuccessToast = (message: string) => {
  const duration = calculateToastDuration(message, 5000);
  toast.success(
    <span className="[word-break:break-word] [overflow-wrap:anywhere]">
      {message}
    </span>,
    { ...TOAST_OPTIONS, duration },
  );
};

export const displaySuccessToastWithLink = (
  message: string,
  linkLabel: string,
  href: string,
) => {
  const duration = calculateToastDuration(`${message} ${linkLabel}`, 5000);
  toast.success(
    <span className="[word-break:break-word] [overflow-wrap:anywhere]">
      {message}{" "}
      <a
        className="underline hover:no-underline"
        href={buildAgentCanvasPath(href)}
      >
        {linkLabel}
      </a>
    </span>,
    { ...TOAST_OPTIONS, duration },
  );
};

/**
 * Neutral, non-success notice — used when an action completed but the outcome
 * is qualified (e.g. a secret was saved but the active backend can't consume it
 * yet). Renders without the success checkmark so it doesn't read as "all good".
 */
export const displayWarningToast = (message: string) => {
  const duration = calculateToastDuration(message, 6000);
  toast(
    <span className="[word-break:break-word] [overflow-wrap:anywhere]">
      {message}
    </span>,
    { ...TOAST_OPTIONS, icon: "⚠️", duration },
  );
};

import { cn } from "#/utils/utils";
import { formControlShellClassName } from "#/utils/form-control-classes";

/** Snap hover colors instantly — no transition-colors delay on menus/dropdowns. */
export const dropdownInstantColorClassName = "transition-none";

/** 2px vertical gap between rows in a dropdown/context menu list. */
export const dropdownMenuListGapClassName = "gap-0.5";

/** Standard horizontal gap between a row icon and its label. */
export const dropdownMenuRowGapClassName = "gap-2";

/** Flex column shell for a dropdown menu item list. */
export const dropdownMenuListClassName = cn(
  "flex flex-col",
  dropdownMenuListGapClassName,
);

/** Combobox/select trigger shell with instant hover colors. */
export const dropdownTriggerShellClassName = cn(
  "bg-tertiary border border-border-input rounded p-2",
  "flex items-center gap-2",
  formControlShellClassName,
  dropdownInstantColorClassName,
  "group w-full gap-2 px-3 text-muted hover:text-contrast",
);

/** Standard white-label menu row. */
export const dropdownMenuRowClassName = cn(
  "group flex w-full cursor-pointer items-center rounded px-2 py-2 text-left text-sm font-normal text-contrast",
  dropdownMenuRowGapClassName,
  "hover:bg-interactive-hover disabled:cursor-not-allowed disabled:opacity-60",
  dropdownInstantColorClassName,
);

/** Menu row using foreground token (context menus). */
export const dropdownMenuRowForegroundClassName = cn(
  "group flex w-full cursor-pointer items-center rounded px-2 py-2 text-start text-sm font-normal",
  dropdownMenuRowGapClassName,
  "text-foreground hover:bg-interactive-hover",
  "disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:bg-transparent",
  dropdownInstantColorClassName,
);

/** Icon inside a menu row — muted until row hover/focus. */
export const dropdownMenuRowIconClassName = cn(
  "shrink-0 text-muted group-hover:text-contrast group-focus-visible:text-contrast",
  dropdownInstantColorClassName,
);

/** Wrapper for SVG/React icon nodes inside a menu row. */
export const dropdownMenuRowIconWrapperClassName = cn(
  "flex size-4 shrink-0 items-center justify-center [&_svg]:text-current",
  dropdownMenuRowIconClassName,
);

/** Enum/filter dropdown trigger chip. */
export const dropdownFilterTriggerClassName = cn(
  "inline-flex cursor-pointer items-center gap-1.5 rounded-lg border px-3 py-2 text-sm font-medium",
  "border-border bg-base-secondary text-contrast",
  "focus-visible:border-contrast/40 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-contrast/20",
  dropdownInstantColorClassName,
);

/**
 * Scroll cap for the switch-profile menu: four two-line rows
 * (p-2 + leading-5 title + gap-0.5 + leading-4 subtitle) plus list gaps.
 */
export const switchProfileMenuListScrollClassName = cn(
  dropdownMenuListClassName,
  "overflow-y-auto custom-scrollbar-always",
  "max-h-[13.875rem]",
);

/**
 * Tall sidebar/context menus: cap height to the viewport and scroll with the
 * custom scrollbar when content overflows (no scrollbar when everything fits).
 */
export const dropdownMenuViewportScrollClassName = cn(
  "overflow-y-auto custom-scrollbar",
  "max-h-[min(60vh,calc(100dvh-5rem))]",
);

/** Footer action row inside a dropdown panel. */
export const dropdownFooterActionClassName = cn(
  "group flex w-full items-center rounded-md px-2 py-2 text-sm font-normal text-contrast",
  dropdownMenuRowGapClassName,
  "hover:bg-interactive-hover",
  dropdownInstantColorClassName,
);

import { cn } from "#/utils/utils";

/** 36px control height — shared by fields, dropdowns, and buttons. */
export const formControlHeightClassName = "h-9 min-h-9";

export const formControlRadiusClassName = "rounded-lg";

export const formControlBorderClassName = "border border-border";

export const formControlSurfaceClassName = "bg-base-secondary";

/** Shared transition duration for form controls and chrome buttons. */
export const formControlTransitionDurationClassName = "duration-75";

export const formControlHeroUiTransitionDurationClassName = "!duration-75";

export const formControlMotionReduceClassName = "motion-reduce:transition-none";

/** Shell properties that animate on hover/focus; foreground color snaps instantly. */
export const formControlTransitionPropertiesClassName =
  "transition-[background-color,border-color,box-shadow,opacity]";

/** Animate shell chrome on hover/focus; foreground color snaps instantly. */
export const formControlTransitionClassName = cn(
  formControlTransitionPropertiesClassName,
  formControlTransitionDurationClassName,
  formControlMotionReduceClassName,
);

/** HeroUI input wrappers ship `transition-colors`; override so caret/text hover is instant. */
export const formControlHeroUiWrapperTransitionClassName = cn(
  "!transition-[background-color,border-color,box-shadow,opacity]",
  formControlHeroUiTransitionDurationClassName,
  formControlMotionReduceClassName,
);

